INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (284, 'Unity.GridGame', 'US-342', NULL, NULL, 'Production roadmap (owner direction, 2026-10-10)', '§1.2', 'done', '✅', '', 'Power Amplifier (Terra Battle): spawns on a luck-modified random schedule; a pincer attacker aligned with it gets an enhanced attack; enemies cannot use it but can walk through it to shove it away and break amplified combos', '`Amplifier_chance_grows_with_party_luck_and_caps`, `An_attacker_on_the_amplifier_strikes_harder_adds_mana_charge_and_uses_it_up`, `Enemies_cannot_use_the_amplifier_but_stepping_on_it_shoves_it_back`; `tools/uicheck.py` (marker on its tile)', NULL, 'table', 234);
