INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (963, 'Unity.Eve', 'US-019', NULL, NULL, 'Battle core', NULL, 'done', '✅', '', 'The engaged creature stalks or flanks in, rears up (growl, red glow, crouch), charges at a burst of speed, strikes, then retreats and hands the turn on; a charge that never connects gives up', '`Token_holder_stalks_in_rears_up_charges_strikes_then_retreats_and_hands_the_token_back`, `A_charge_that_never_connects_gives_up_the_turn`, `Flanker_works_round_then_charges_from_the_blind_side`, autoplay:`encounter_*_enemy_rears_up`, `encounter_*_enemy_charges`', NULL, 'table', 5);
