INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1011, 'UnityRonin', 'US-001', NULL, NULL, 'Movement', NULL, 'done', '✅', '', 'The on-screen stick ignores small jitter near its center (dead zone)', '`Input_inside_dead_zone_resolves_to_zero`', NULL, 'table', 0);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1012, 'UnityRonin', 'US-002', NULL, NULL, 'Movement', NULL, 'done', '✅', '', 'Dragging past the stick''s travel radius clamps to full deflection, never overshoots', '`Input_beyond_full_deflection_clamps_to_unit_magnitude`', NULL, 'table', 1);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1013, 'UnityRonin', 'US-003', NULL, NULL, 'Movement', NULL, 'done', '✅', '', 'The stick''s output rescales continuously from the dead-zone edge to full deflection', '`Rescaling_is_continuous_from_the_dead_zone_edge_to_full_deflection`', NULL, 'table', 2);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1014, 'UnityRonin', 'US-004', NULL, NULL, 'Movement', NULL, 'done', '✅', '', 'Stick input is interpreted relative to the camera''s facing, not world axes', '`Pushing_up_with_zero_yaw_moves_along_world_forward`, `Pushing_up_with_camera_yawed_90_degrees_moves_along_world_right`', NULL, 'table', 3);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1015, 'UnityRonin', 'US-005', NULL, NULL, 'Movement', NULL, 'partial', '🟡', '', 'The stick covers the bottom half of the screen and appears wherever the thumb lands', 'autoplay drives real `OnPointerDown`/`OnDrag` and the Samurai moves correctly; confirmed rendering on a real Android device (`artifacts/android-playtest/`); needs an owner playtest for how it feels under a real thumb', NULL, 'table', 4);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1016, 'UnityRonin', 'US-006', NULL, NULL, 'Movement', NULL, 'partial', '🟡', '', 'The camera sits slightly above and behind and smart-follows without a second-finger drag', '`SmartFollowCamera` runs every frame of the autoplay pass with no errors; confirmed rendering on a real Android device; needs an owner playtest', NULL, 'table', 5);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1017, 'UnityRonin', 'US-010', NULL, NULL, 'Engagement', NULL, 'done', '✅', '', 'Coming within an enemy''s enter radius starts a duel', '`Engages_once_the_enemy_is_within_enter_radius`', NULL, 'table', 6);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1018, 'UnityRonin', 'US-011', NULL, NULL, 'Engagement', NULL, 'done', '✅', '', 'The duel doesn''t release until the player backs out past a larger exit radius (no flicker at the boundary)', '`Stays_engaged_inside_the_hysteresis_band_so_it_cannot_flicker_at_the_boundary`, `Releases_back_to_exploring_only_past_the_exit_radius`', NULL, 'table', 7);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1019, 'UnityRonin', 'US-012', NULL, NULL, 'Engagement', NULL, 'done', '✅', '', 'An exit radius that isn''t strictly larger than the enter radius is rejected outright', '`Rejects_an_exit_radius_that_would_allow_flicker`', NULL, 'table', 8);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1020, 'UnityRonin', 'US-013', NULL, NULL, 'Engagement', NULL, 'done', '✅', '', 'Entering a duel swaps the live input surface from the stick to full-screen swipes, and movement goes automatic', 'autoplay: joystick zone deactivates and swipe zone activates on engage, for both enemies, in `Logs/autoplay.log`', NULL, 'table', 9);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1021, 'UnityRonin', 'US-020', NULL, NULL, 'Duel (katana combat)', NULL, 'done', '✅', '', 'A drawn path is split into straight strokes at sharp corners only, each classified into one of five shapes', '`GestureClassifierTests`: `A_long_straight_horizontal_drag_classifies_as_horizontal`, `A_sharp_corner_splits_into_two_chained_strokes`, `A_gentle_curve_with_no_sharp_corner_stays_one_stroke`', NULL, 'table', 10);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1022, 'UnityRonin', 'US-021', NULL, NULL, 'Duel (katana combat)', NULL, 'done', '✅', '', 'A path that never clears the minimum stroke length is a Thrust (a tap), not an aborted swipe', '`A_pure_tap_with_no_movement_is_a_thrust`, `A_drag_shorter_than_the_minimum_distance_is_also_a_thrust_not_an_aborted_swipe`', NULL, 'table', 11);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1023, 'UnityRonin', 'US-022', NULL, NULL, 'Duel (katana combat)', NULL, 'done', '✅', '', 'Drawing the perpendicular shape against a cutting enemy attack parries it: no damage, and it opens a riposte', '`Perpendicular_stroke_against_a_cutting_attack_parries`, `Successful_parry_opens_a_riposte_window_instead_of_dealing_immediate_damage`', NULL, 'table', 12);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1024, 'UnityRonin', 'US-023', NULL, NULL, 'Duel (katana combat)', NULL, 'done', '✅', '', 'Drawing the wrong shape, or not in time, against an attack hits the player', '`Matching_stroke_against_a_cutting_attack_hits_the_player`, `Not_responding_to_an_attack_in_time_also_hits_the_player`', NULL, 'table', 13);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1025, 'UnityRonin', 'US-023a', NULL, NULL, 'Duel (katana combat)', NULL, 'done', '✅', '', 'A thrust attack is parried only by a thrust in return — a cross-block has no purchase on a straight point', '`Matching_thrust_against_a_thrust_attack_parries`, `Thrusting_against_a_cutting_attack_does_not_parry_it`, `A_cross_block_does_not_stop_a_thrust_attack`', NULL, 'table', 14);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1026, 'UnityRonin', 'US-024', NULL, NULL, 'Duel (katana combat)', NULL, 'done', '✅', '', 'Matching the open shape against an enemy guard strikes it', '`Matching_the_open_shape_against_a_guard_strikes_the_enemy`, `Matching_a_thrust_guard_opening_strikes_the_enemy`', NULL, 'table', 15);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1027, 'UnityRonin', 'US-025', NULL, NULL, 'Duel (katana combat)', NULL, 'done', '✅', '', 'Drawing the wrong shape, or not in time, against a guard just wastes the beat — no damage either way', '`Wrong_shape_against_a_guard_wastes_the_beat_with_no_damage`, `Not_responding_to_a_guard_wastes_the_beat_with_no_damage`', NULL, 'table', 16);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1028, 'UnityRonin', 'US-025a', NULL, NULL, 'Duel (katana combat)', NULL, 'done', '✅', '', 'Chaining strokes onto a successful guard strike lands a bonus hit each, as long as they keep alternating shape', '`Chained_strokes_alternating_shape_land_a_bonus_hit_each`, `Repeating_the_same_shape_breaks_the_combo_chain`', NULL, 'table', 17);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1029, 'UnityRonin', 'US-026', NULL, NULL, 'Duel (katana combat)', NULL, 'done', '✅', '', 'The duel ends the instant either combatant''s health reaches zero', '`The_duel_ends_as_soon_as_either_side_reaches_zero_health`', NULL, 'table', 18);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1030, 'UnityRonin', 'US-027', NULL, NULL, 'Duel (katana combat)', NULL, 'done', '✅', '', 'The same seed replays the identical sequence of beats, including riposte exchanges', '`The_same_seed_replays_the_same_sequence_of_beats`, `Same_seed_replays_the_identical_sequence` (Rng)', NULL, 'table', 19);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1031, 'UnityRonin', 'US-028', NULL, NULL, 'Duel (katana combat)', NULL, 'partial', '🟡', '', 'The katana is sheathed while exploring and drawn the instant a duel starts, and swings through whatever gesture was just drawn', '`DuelPresenter.Begin/End` calls `SamuraiWeapon.Draw/Sheathe`, and every gesture calls `SamuraiWeapon.Swing`, without error every autoplay duel; needs an owner playtest to confirm it looks right', NULL, 'table', 20);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1032, 'UnityRonin', 'US-029', NULL, NULL, 'Duel (katana combat)', NULL, 'partial', '🟡', '', 'The HUD shows the telegraphed technique as a real calligraphy-brush glyph, colored by attack vs. guard', '`DuelTelegraph.Show/Hide` runs every autoplay beat without error; `-demo` screenshots confirm all five glyphs render correctly (see §Combo for the riposte prompt); needs an owner playtest to confirm it reads clearly', NULL, 'table', 21);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1033, 'UnityRonin', 'US-030', NULL, NULL, 'Duel (katana combat)', NULL, 'done', '✅', '', 'Winning a duel removes that enemy', 'autoplay: both enemies inactive after their duels, in `Logs/autoplay.log`', NULL, 'table', 22);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1034, 'UnityRonin', 'US-031', NULL, NULL, 'Duel (katana combat)', NULL, 'done', '✅', '', 'Losing a duel knocks the Samurai back out of range instead of the duel immediately re-triggering', 'autoplay: `RoninAutopilot` deliberately loses the first duel, then confirms the gate released and the enemy is still alive (`Logs/autoplay.log`: "confirmed a loss retreats the player")', NULL, 'table', 23);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1035, 'UnityRonin', 'US-050', NULL, NULL, 'Combo (parry → riposte)', NULL, 'done', '✅', '', 'A successful parry opens a riposte window instead of immediately dealing the next enemy beat', '`Successful_parry_opens_a_riposte_window_instead_of_dealing_immediate_damage`', NULL, 'table', 24);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1036, 'UnityRonin', 'US-051', NULL, NULL, 'Combo (parry → riposte)', NULL, 'done', '✅', '', 'Not drawing a riposte attack in time wastes the window — no damage either way', '`Riposte_timeout_wastes_the_window_with_no_damage`', NULL, 'table', 25);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1037, 'UnityRonin', 'US-052', NULL, NULL, 'Combo (parry → riposte)', NULL, 'done', '✅', '', 'The enemy may retreat from a riposte attack instead of risking a counter — no damage either way', '`Riposte_retreat_ends_the_window_safely`', NULL, 'table', 26);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1038, 'UnityRonin', 'US-053', NULL, NULL, 'Combo (parry → riposte)', NULL, 'done', '✅', '', 'If the enemy''s counter doesn''t validly answer the riposte attack, it lands — enemy takes damage', '`Riposte_lands_when_the_enemys_counter_fails`', NULL, 'table', 27);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1039, 'UnityRonin', 'US-054', NULL, NULL, 'Combo (parry → riposte)', NULL, 'done', '✅', '', 'If the enemy''s counter does validly answer the riposte attack, the "flash slash" lands on the player instead', '`Riposte_countered_when_the_enemys_counter_matches`', NULL, 'table', 28);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1040, 'UnityRonin', 'US-055', NULL, NULL, 'Combo (parry → riposte)', NULL, 'done', '✅', '', 'A landed riposte reopens the window if the enemy survives, chaining into a real combo with no artificial depth cap', '`A_chained_combo_of_riposte_lands_can_defeat_the_enemy_without_returning_to_enemy_beat`', NULL, 'table', 29);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1041, 'UnityRonin', 'US-056', NULL, NULL, 'Combo (parry → riposte)', NULL, 'done', '✅', '', 'The riposte window visibly slows time and shows a neutral "your turn" cue, not a telegraphed technique', '`-demo` screenshots: the gold "刀" glyph appears after a real parry and persists ≈3× its nominal 0.6s window, confirming `Time.timeScale` slow-motion is genuinely active', NULL, 'table', 30);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1042, 'UnityRonin', 'US-057', NULL, NULL, 'Combo (parry → riposte)', NULL, 'partial', '🟡', '', 'The enemy hops back on a retreat and flashes on a successful counter — primitive-only feedback, no rig', '`EnemyCombatFeedback.HopBack/FlashCounter` wired from `RoninGameController.OnBeatResolved`, runs without error every autoplay duel; needs an owner playtest to confirm it reads clearly', NULL, 'table', 31);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1043, 'UnityRonin', 'US-058', NULL, NULL, 'Combo (parry → riposte)', NULL, 'done', '✅', '', '`-autoplay` proves the riposte wiring fires for real (prompt, slow-motion, timeout) without gambling the pass''s deterministic win on the riposte''s real risk', '`-autoplay` declines every riposte window (always a safe, scored timeout); two consecutive runs both exited 0', NULL, 'table', 32);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1044, 'UnityRonin', 'US-040', NULL, NULL, 'Rendering', NULL, 'done', '✅', '', 'The project has its own real URP pipeline asset, not a dangling reference to another project''s', '`RoninBuild.EnsureRenderPipeline`; confirmed by shader variant counts dropping from ~1.7M to 1–2 per pass in `Logs/build-player.log`', NULL, 'table', 33);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1045, 'UnityRonin', 'US-041', NULL, NULL, 'Rendering', NULL, 'done', '✅', '', 'The ground renders as matte terrain, not a blown-out white specular highlight', 'On-device screenshot `artifacts/android-playtest/03-fixed-ground.png` on a real Pixel 7 emulator, Android 16', NULL, 'table', 34);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1046, 'UnityRonin', 'US-042', NULL, NULL, 'Rendering', NULL, 'done', '✅', '', 'The game boots and renders correctly on real Android hardware (not just Unity''s -nographics batch mode)', 'Installed via `adb install` and launched via `adb shell monkey` on a booted Pixel 7 (API 36) AVD; screenshots in `artifacts/android-playtest/`', NULL, 'table', 35);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1047, 'MindAttic.Tickets', 'M.TIX-US-D1', NULL, 'D', NULL, NULL, 'planned', '⬜', '', 'As a Dev, `workflow db restore` rebuilds data/workflow.db from the committed data/workflow.sql dump and proves it matches (row counts per table, `db check` clean, every view renders unchanged), so a corrupt or merge-conflicted binary is never data loss (M.FLOW-LAW-3). Today nothing reads the dump back.', NULL, NULL, 'bullet', 11);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1048, 'MindAttic.Tickets', 'M.TIX-US-D2', NULL, 'D', NULL, NULL, 'planned', '⬜', '', 'As an Agent, my feature commits never carry data/workflow.db or data/workflow.sql; only `workflow db sync` commits them, and .gitattributes marks the db binary with a merge that keeps the working copy, so merging a worktree branch can''t conflict on the database or roll it back to an older snapshot. Today ordinary commits sweep it in whenever it''s modified.', NULL, NULL, 'bullet', 12);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1049, 'MindAttic.Tickets', 'M.TIX-US-D3', NULL, 'D', NULL, NULL, 'planned', '⬜', '', 'As an Agent running alongside other autopilot agents, `workflow ticket new` from many processes at once hands out distinct IDs with none lost and no ''database is locked'' failure, proved by a test that starts parallel writers against one database (and decides whether WAL beats today''s journal_mode=DELETE with a 15s busy_timeout).', NULL, NULL, 'bullet', 13);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1050, 'MindAttic.Tickets', 'M.TIX-US-E1', NULL, 'E', NULL, NULL, 'planned', '⬜', '', 'As an Agent, workflow output piped or redirected (not a terminal) has no ANSI escape codes and honors NO_COLOR, so scripts and agents read plain text. Today `ticket list | cat` prints raw color codes around ''0 ticket(s)'', and help text keeps its underline codes even with NO_COLOR.', NULL, NULL, 'bullet', 14);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1051, 'MindAttic.Tickets', 'M.TIX-US-E2', NULL, 'E', NULL, NULL, 'planned', '⬜', '', 'As a Dev, `workflow story list` is readable in an 80-column terminal: one line per story with ID, glyph, epic and the text cut to fit, instead of today''s 20-character Story column that wraps each story over seven lines. `--json` is unchanged.', NULL, NULL, 'bullet', 15);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1052, 'MindAttic.Tickets', 'M.TIX-US-E3', NULL, 'E', NULL, NULL, 'planned', '⬜', '', 'As a Dev, `workflow ticket list --search <text>` matches ID, summary and ref (case-insensitive) across the workspace, so finding a ticket doesn''t mean piping --json through grep.', NULL, NULL, 'bullet', 16);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1053, 'MindAttic.Tickets', 'M.TIX-US-E4', NULL, 'E', NULL, NULL, 'planned', '⬜', '', 'As a Dev, the commands agents run that have no CLI test yet are tested through the real `workflow` on a temp workspace: story new/edit/status, epic new, backlog add, ticket link (a refused cycle), ticket correct, db render, and db sync --no-push committing only the database files.', NULL, NULL, 'bullet', 17);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1054, 'MindAttic.Tickets', 'M.TIX-US-F1', NULL, 'F', NULL, NULL, 'planned', '⬜', '', 'As a Dev, `workflow view` shows each ticket''s and story''s links (requires, blocks) and a ticket''s history, and an ID in a summary or ref links to that item, so I can see from the page why something is blocked.', NULL, NULL, 'bullet', 18);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1055, 'MindAttic.Tickets', 'M.TIX-US-F2', NULL, 'F', NULL, NULL, 'planned', '⬜', '', 'As a Dev, the Launcher''s Workflow menu (M.LNCH-US-E6) has an ''Open viewer'' item that runs `workflow view`, scoped to the repo I''m in.', NULL, NULL, 'bullet', 19);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1056, 'MindAttic.Tickets', 'M.TIX-US-F3', NULL, 'F', NULL, NULL, 'planned', '⬜', '', 'As an Agent reading the canon, README.md and docs/BIBLE.md describe the database, not the markdown era: the intro and architecture diagrams say tickets live in SQLite, `ticket new` no longer claims ''only that one line changes'', ''stories are still written by hand'' goes, the glossary''s ''Ticket log'' stops pointing at the ## Tickets table, M.FLOW-LAW-2 stops repeating its trigger sentence, and the codex doctor passes.', NULL, NULL, 'bullet', 20);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1057, 'Prose', 'PRS-US-Q1', NULL, 'Q', NULL, NULL, 'done', '✅', '', 'As the maintainer, I clean up Epics A, B, C and D (canon foundation, writing surface, generation, interconnect: 16 stories) so the backlog matches the novel factory and states only what is true. Rules to apply (sources: docs/rfc/0015-novel-factory.md, the SessionStart forbidden list, SS-LAW-17): (1) THE PLAN IS THE FACTORY — book work is computed by the Hub (prose --factory next / --order list), never stored as story text, so a story that tracks chapters, acts, word counts or beats of a book is restated as a pointer to the factory or marked superseded; (2) THE BOOK IS THE BOOK — no outline, spine, ledger, summary or reconciler; (3) no LLM judges, review panels, votes or review-score thresholds (≥85% etc.); (4) RESULTS NOT TOOLS — a story is done only when its effect is applied and verified, never because a tool exists; (5) every ✅ cites a test or CLI check that exists today. For each story: show it (workflow story show <ID>); grep src/Prose.UnitTests for every cited test and run them (dotnet test --filter); a ✅ whose evidence is missing or failing drops to partial with the gap stated; rewrite (workflow story edit) any text that asks for a forbidden thing; mark a story that the factory now owns as done-superseded with a pointer. Touch no prose, no canon, no DB outside the workflow CLI. Then run workflow db render, commit the regenerated docs/USER_STORIES.md and list each story changed and why in the ticket.', NULL, NULL, 'bullet', 160);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1058, 'Prose', 'PRS-US-Q2', NULL, 'Q', NULL, NULL, 'done', '✅', '', 'As the maintainer, I clean up Epics E, F and I (voice harvest, coverage/observability, feedback loops: 10 stories; check E1/E2 and I-stories for LLM-judge or review-score dependencies) so the backlog matches the novel factory and states only what is true. Rules to apply (sources: docs/rfc/0015-novel-factory.md, the SessionStart forbidden list, SS-LAW-17): (1) THE PLAN IS THE FACTORY — book work is computed by the Hub (prose --factory next / --order list), never stored as story text, so a story that tracks chapters, acts, word counts or beats of a book is restated as a pointer to the factory or marked superseded; (2) THE BOOK IS THE BOOK — no outline, spine, ledger, summary or reconciler; (3) no LLM judges, review panels, votes or review-score thresholds (≥85% etc.); (4) RESULTS NOT TOOLS — a story is done only when its effect is applied and verified, never because a tool exists; (5) every ✅ cites a test or CLI check that exists today. For each story: show it (workflow story show <ID>); grep src/Prose.UnitTests for every cited test and run them (dotnet test --filter); a ✅ whose evidence is missing or failing drops to partial with the gap stated; rewrite (workflow story edit) any text that asks for a forbidden thing; mark a story that the factory now owns as done-superseded with a pointer. Touch no prose, no canon, no DB outside the workflow CLI. Then run workflow db render, commit the regenerated docs/USER_STORIES.md and list each story changed and why in the ticket.', NULL, NULL, 'bullet', 161);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1059, 'Prose', 'PRS-US-Q3', NULL, 'Q', NULL, NULL, 'done', '✅', '', 'As the maintainer, I clean up Epics K, L, M, N and O (service law, architecture, emotional intelligence, voting kill-switch, reader QA: 19 stories; L6 is partial) so the backlog matches the novel factory and states only what is true. Rules to apply (sources: docs/rfc/0015-novel-factory.md, the SessionStart forbidden list, SS-LAW-17): (1) THE PLAN IS THE FACTORY — book work is computed by the Hub (prose --factory next / --order list), never stored as story text, so a story that tracks chapters, acts, word counts or beats of a book is restated as a pointer to the factory or marked superseded; (2) THE BOOK IS THE BOOK — no outline, spine, ledger, summary or reconciler; (3) no LLM judges, review panels, votes or review-score thresholds (≥85% etc.); (4) RESULTS NOT TOOLS — a story is done only when its effect is applied and verified, never because a tool exists; (5) every ✅ cites a test or CLI check that exists today. For each story: show it (workflow story show <ID>); grep src/Prose.UnitTests for every cited test and run them (dotnet test --filter); a ✅ whose evidence is missing or failing drops to partial with the gap stated; rewrite (workflow story edit) any text that asks for a forbidden thing; mark a story that the factory now owns as done-superseded with a pointer. Touch no prose, no canon, no DB outside the workflow CLI. Then run workflow db render, commit the regenerated docs/USER_STORIES.md and list each story changed and why in the ticket.', NULL, NULL, 'bullet', 162);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1060, 'Prose', 'PRS-US-Q4', NULL, 'Q', NULL, NULL, 'done', '✅', '', 'As the maintainer, I clean up Epics U and P (multi-universe and SCRY/Fantasy books: 13 stories) so the backlog matches the novel factory and states only what is true. Rules to apply (sources: docs/rfc/0015-novel-factory.md, the SessionStart forbidden list, SS-LAW-17): (1) THE PLAN IS THE FACTORY — book work is computed by the Hub (prose --factory next / --order list), never stored as story text, so a story that tracks chapters, acts, word counts or beats of a book is restated as a pointer to the factory or marked superseded; (2) THE BOOK IS THE BOOK — no outline, spine, ledger, summary or reconciler; (3) no LLM judges, review panels, votes or review-score thresholds (≥85% etc.); (4) RESULTS NOT TOOLS — a story is done only when its effect is applied and verified, never because a tool exists; (5) every ✅ cites a test or CLI check that exists today. For each story: show it (workflow story show <ID>); grep src/Prose.UnitTests for every cited test and run them (dotnet test --filter); a ✅ whose evidence is missing or failing drops to partial with the gap stated; rewrite (workflow story edit) any text that asks for a forbidden thing; mark a story that the factory now owns as done-superseded with a pointer. Touch no prose, no canon, no DB outside the workflow CLI. Then run workflow db render, commit the regenerated docs/USER_STORIES.md and list each story changed and why in the ticket.', NULL, NULL, 'bullet', 163);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1061, 'Prose', 'PRS-US-Q5', NULL, 'Q', NULL, NULL, 'done', '✅', '', 'As the maintainer, I clean up Epic G (Bushido Coda: PRS-US-G1..G5 and G5a..G5g, 12 stories; G3 asks for an LLM review pass, G4 for a 100-story outline, G5g for a review-score campaign — all forbidden, restate or supersede against BCODA''s factory state) so the backlog matches the novel factory and states only what is true. Rules to apply (sources: docs/rfc/0015-novel-factory.md, the SessionStart forbidden list, SS-LAW-17): (1) THE PLAN IS THE FACTORY — book work is computed by the Hub (prose --factory next / --order list), never stored as story text, so a story that tracks chapters, acts, word counts or beats of a book is restated as a pointer to the factory or marked superseded; (2) THE BOOK IS THE BOOK — no outline, spine, ledger, summary or reconciler; (3) no LLM judges, review panels, votes or review-score thresholds (≥85% etc.); (4) RESULTS NOT TOOLS — a story is done only when its effect is applied and verified, never because a tool exists; (5) every ✅ cites a test or CLI check that exists today. For each story: show it (workflow story show <ID>); grep src/Prose.UnitTests for every cited test and run them (dotnet test --filter); a ✅ whose evidence is missing or failing drops to partial with the gap stated; rewrite (workflow story edit) any text that asks for a forbidden thing; mark a story that the factory now owns as done-superseded with a pointer. Touch no prose, no canon, no DB outside the workflow CLI. Then run workflow db render, commit the regenerated docs/USER_STORIES.md and list each story changed and why in the ticket.', NULL, NULL, 'bullet', 164);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1062, 'Prose', 'PRS-US-Q6', NULL, 'Q', NULL, NULL, 'done', '✅', '', 'As the maintainer, I clean up Epic H stories PRS-US-H1..H4 and their children (H1a..H4e; H1f asks for a review panel ≥85%, restate or supersede against each book''s factory state) so the backlog matches the novel factory and states only what is true. Rules to apply (sources: docs/rfc/0015-novel-factory.md, the SessionStart forbidden list, SS-LAW-17): (1) THE PLAN IS THE FACTORY — book work is computed by the Hub (prose --factory next / --order list), never stored as story text, so a story that tracks chapters, acts, word counts or beats of a book is restated as a pointer to the factory or marked superseded; (2) THE BOOK IS THE BOOK — no outline, spine, ledger, summary or reconciler; (3) no LLM judges, review panels, votes or review-score thresholds (≥85% etc.); (4) RESULTS NOT TOOLS — a story is done only when its effect is applied and verified, never because a tool exists; (5) every ✅ cites a test or CLI check that exists today. For each story: show it (workflow story show <ID>); grep src/Prose.UnitTests for every cited test and run them (dotnet test --filter); a ✅ whose evidence is missing or failing drops to partial with the gap stated; rewrite (workflow story edit) any text that asks for a forbidden thing; mark a story that the factory now owns as done-superseded with a pointer. Touch no prose, no canon, no DB outside the workflow CLI. Then run workflow db render, commit the regenerated docs/USER_STORIES.md and list each story changed and why in the ticket.', NULL, NULL, 'bullet', 165);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1063, 'Prose', 'PRS-US-Q7', NULL, 'Q', NULL, NULL, 'done', '✅', '', 'As the maintainer, I clean up Epic H stories PRS-US-H5..H8 and their children (H5a..H8g) so the backlog matches the novel factory and states only what is true. Rules to apply (sources: docs/rfc/0015-novel-factory.md, the SessionStart forbidden list, SS-LAW-17): (1) THE PLAN IS THE FACTORY — book work is computed by the Hub (prose --factory next / --order list), never stored as story text, so a story that tracks chapters, acts, word counts or beats of a book is restated as a pointer to the factory or marked superseded; (2) THE BOOK IS THE BOOK — no outline, spine, ledger, summary or reconciler; (3) no LLM judges, review panels, votes or review-score thresholds (≥85% etc.); (4) RESULTS NOT TOOLS — a story is done only when its effect is applied and verified, never because a tool exists; (5) every ✅ cites a test or CLI check that exists today. For each story: show it (workflow story show <ID>); grep src/Prose.UnitTests for every cited test and run them (dotnet test --filter); a ✅ whose evidence is missing or failing drops to partial with the gap stated; rewrite (workflow story edit) any text that asks for a forbidden thing; mark a story that the factory now owns as done-superseded with a pointer. Touch no prose, no canon, no DB outside the workflow CLI. Then run workflow db render, commit the regenerated docs/USER_STORIES.md and list each story changed and why in the ticket.', NULL, NULL, 'bullet', 166);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1064, 'Prose', 'PRS-US-Q8', NULL, 'Q', NULL, NULL, 'done', '✅', '', 'As the maintainer, I clean up Epic H stories PRS-US-H9..H12 and their children (H9a..H12g; H9e..H9h are planned) so the backlog matches the novel factory and states only what is true. Rules to apply (sources: docs/rfc/0015-novel-factory.md, the SessionStart forbidden list, SS-LAW-17): (1) THE PLAN IS THE FACTORY — book work is computed by the Hub (prose --factory next / --order list), never stored as story text, so a story that tracks chapters, acts, word counts or beats of a book is restated as a pointer to the factory or marked superseded; (2) THE BOOK IS THE BOOK — no outline, spine, ledger, summary or reconciler; (3) no LLM judges, review panels, votes or review-score thresholds (≥85% etc.); (4) RESULTS NOT TOOLS — a story is done only when its effect is applied and verified, never because a tool exists; (5) every ✅ cites a test or CLI check that exists today. For each story: show it (workflow story show <ID>); grep src/Prose.UnitTests for every cited test and run them (dotnet test --filter); a ✅ whose evidence is missing or failing drops to partial with the gap stated; rewrite (workflow story edit) any text that asks for a forbidden thing; mark a story that the factory now owns as done-superseded with a pointer. Touch no prose, no canon, no DB outside the workflow CLI. Then run workflow db render, commit the regenerated docs/USER_STORIES.md and list each story changed and why in the ticket.', NULL, NULL, 'bullet', 167);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1065, 'Prose', 'PRS-US-Q9', NULL, 'Q', NULL, NULL, 'planned', '⬜', '', 'As the maintainer, every story ID in the Prose backlog is unique. PRS-US-H7 and H7a, H7b, H7c each exist twice in the workflow database. Compare each pair with workflow story show; if they say the same thing, merge into one; if they differ, renumber the later one to the next free ID in epic H. Then workflow db render, check that docs/USER_STORIES.md has no duplicate IDs, and commit. BLOCKED 2026-10-15: the workflow CLI has no command to renumber or delete a story and `db check` does not report duplicate IDs, so this needs a MindAttic.Workflow change first (`story renumber`, duplicate-ID check). After renumbering, give both H7 stories the same factory note as the other epic-H books (PRS-US-Q7): Rook Trilogy = MxG F5 fails 3/3, NxR F5 fails 1/4, CxC F5 fails 3/3 (PRS-T77); Steppin Razor (SRZR) F5 fails 3/3, F1 waiting (PRS-T77); mark both partial and their review-score children historical.', NULL, NULL, 'bullet', 168);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1066, 'Prose', 'PRS-US-Q10', NULL, 'Q', NULL, NULL, 'planned', '⬜', '', 'As the author, every remaining GLMZ book is fully tagged, read and verified: work open tickets PRS-T56..PRS-T68 one book per run, in order, each to its own done criteria (factory F1-F7 green for that book), closing each ticket as it lands. Story is done when all thirteen are closed.', NULL, NULL, 'bullet', 169);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1067, 'Prose', 'PRS-US-Q11', NULL, 'Q', NULL, NULL, 'planned', '⬜', '', 'As the author, every book in the other universes (SCRY, NONFICTION, FICTION, HORROR, EROTICA, GOSPEL, EVE, ANTHOLOGY) is fully tagged, read and verified. PRS-T69..PRS-T76 listed each universe''s books and expanded into one ticket per real book (PRS-T84..PRS-T103; EROTICA has no books, so PRS-T73 closed with nothing to expand); work each per-book ticket to factory F1-F7 green. Done when every non-calibration book''s factory status is green.', NULL, NULL, 'bullet', 170);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1068, 'Prose', 'PRS-US-Q12', NULL, 'Q', NULL, NULL, 'planned', '⬜', '', 'As the author, no pressed book carries un-read beats after later record edits: work ticket PRS-T77 (final re-read, F1 recommit, re-export) after PRS-US-Q10 and PRS-US-Q11 are done.', NULL, NULL, 'bullet', 171);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1069, 'Prose', 'PRS-US-Q13', NULL, 'Q', NULL, NULL, 'planned', '⬜', '', 'As the author, the GLMZ focus wheel''s cycle 2 is a full re-read of every catalog book (the change-tracking dockets select.py needs to do the cheap diff were lost with a prior session''s scratchpad, so this cycle falls back to wheel rule 2: a whole-book read). Each of the 22 books (SCON excluded) gets its own ticket: read the focus book in full against the current text of all 21 others, draft only meaningful rows (cold-reader gaps, consequences, behavior, veracity, belonging), borrow capped at 3 rows/zero normal, reject re-litigated rulings or invented source facts, then archive+splice+tag+capture+re-read the changed beats+F1 verify. Done when every book''s ticket is closed and prose --factory status is clean for all 22.', NULL, NULL, 'bullet', 172);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1070, 'GTFO.EZ.AbsurdWeapons', 'G.AWPN-US-X1', NULL, 'X', NULL, NULL, 'planned', '⬜', '', 'Spike: as a player, I see Mjölnir spelled with its ö in the loadout screen, inventory and HUD - test whether GTFO''s TextMeshPro fonts render non-ASCII weapon names (or show a missing-glyph box), and whether a non-ASCII name survives gear JSON, datablock lookup and multiplayer sync. If it works, rename Mjolnir to Mjölnir (display names only; keep config section and ids ASCII).', NULL, NULL, 'bullet', 0);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1071, 'MindAttic.Tickets', 'M.TIX-US-G1', NULL, 'G', NULL, NULL, 'planned', '⬜', '', 'As a Dev, Workflow Desktop (src/MindAttic.Workflow.Desktop, WPF on net10.0-windows with MindAttic.Components.Wpf, the Orchestrator''s look) opens from a Desktop and Start-menu shortcut that shows assets/logo.ico, which is also the exe and window icon, installed by deploy.ps1 to C:\Apps\MindAttic.Workflow.Desktop.', NULL, NULL, 'bullet', 21);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1072, 'MindAttic.Tickets', 'M.TIX-US-G2', NULL, 'G', NULL, NULL, 'planned', '⬜', '', 'As a Dev or Agent, a ticket''s approval (proposed/approved/rejected) and queue priority live in workflow.db (ticket_queue), recorded in its history, set through the library and ''workflow ticket approve|reject|priority'', so the database stays the only store.', NULL, NULL, 'bullet', 22);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1073, 'MindAttic.Tickets', 'M.TIX-US-G3', NULL, 'G', NULL, NULL, 'planned', '⬜', '', 'As a Dev, Workflow Desktop''s Queue view lists every repo''s open tickets in priority order; I approve, reject (with a reason; it closes wont-do) and reorder them by drag and drop or by keyboard (buttons, Alt+Up/Down), each change announced to screen readers.', NULL, NULL, 'bullet', 23);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1074, 'MindAttic.Tickets', 'M.TIX-US-G4', NULL, 'G', NULL, NULL, 'planned', '⬜', '', 'As a Dev, Workflow Desktop''s Tickets view lists every ticket in every repo, filterable by repo, status, type and approval, searchable by ID, summary and ref, sortable by column, with closed and wont-do tickets hidden until I show archived.', NULL, NULL, 'bullet', 24);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1075, 'MindAttic.Tickets', 'M.TIX-US-G5', NULL, 'G', NULL, NULL, 'planned', '⬜', '', 'As a Dev, selecting a ticket opens a detail pane with its fields, history and links both ways (linked IDs focus that ticket, blocked state shown), where I close it, wont-do it, set its ref, correct its type with a reason and add or remove links.', NULL, NULL, 'bullet', 25);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1076, 'MindAttic.Tickets', 'M.TIX-US-G6', NULL, 'G', NULL, NULL, 'planned', '⬜', '', 'As a Dev, Ctrl+N in Workflow Desktop files a new ticket (repo, type, summary, ref), remembering the last repo and type.', NULL, NULL, 'bullet', 26);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1077, 'MindAttic.Tickets', 'M.TIX-US-G7', NULL, 'G', NULL, NULL, 'done', '✅', '', 'As a Dev, Workflow Desktop shows agents'' ticket changes within seconds without a manual refresh, and a Sync button runs ''workflow db sync'' and shows its result.', NULL, NULL, 'bullet', 27);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1078, 'MindAttic.Tickets', 'M.TIX-US-G8', NULL, 'G', NULL, NULL, 'planned', '⬜', '', 'As a Dev who relies on assistive tech, Workflow Desktop meets WCAG 2.2 AA: contrast, keyboard-only use, visible unobscured focus, names and roles, live regions, 200% zoom, high-contrast mode, 24px targets and a dragging alternative, proved by tests and an Accessibility Insights FastPass.', NULL, NULL, 'bullet', 28);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1079, 'MindAttic.Tickets', 'M.TIX-US-H1', NULL, 'H', NULL, NULL, 'planned', '⬜', '', 'As a Dev or Agent, I add append-only comments to a ticket (author, time, markdown), shown in its history, without rewording the ticket row.', NULL, NULL, 'bullet', 29);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1080, 'MindAttic.Tickets', 'M.TIX-US-H2', NULL, 'H', NULL, NULL, 'planned', '⬜', '', 'As a Dev, a ticket has a markdown description separate from its one-line summary, and rewording the summary is a recorded correction with a reason, like CorrectType.', NULL, NULL, 'bullet', 30);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1081, 'MindAttic.Tickets', 'M.TIX-US-H3', NULL, 'H', NULL, NULL, 'planned', '⬜', '', 'As a Dev, I tag tickets with labels and components and filter by them in the CLI and Workflow Desktop.', NULL, NULL, 'bullet', 31);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1082, 'MindAttic.Tickets', 'M.TIX-US-H4', NULL, 'H', NULL, NULL, 'planned', '⬜', '', 'As a Dev, each ticket carries an effort estimate, seeded from the Orchestrator''s TicketCosts actuals for similar tickets and editable, so the queue can sort by smallest effort from the database.', NULL, NULL, 'bullet', 32);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1083, 'MindAttic.Tickets', 'M.TIX-US-H5', NULL, 'H', NULL, NULL, 'planned', '⬜', '', 'As a Dev, I see which agent, CLI or worktree is working a ticket and since when, from the Orchestrator''s assignments, in the list and detail pane.', NULL, NULL, 'bullet', 33);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1084, 'MindAttic.Tickets', 'M.TIX-US-H6', NULL, 'H', NULL, NULL, 'planned', '⬜', '', 'As a Dev, a Board view shows tickets in columns Proposed, Approved, In progress and Done, and moving a card (drag or keyboard) changes its approval or status.', NULL, NULL, 'bullet', 34);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1085, 'MindAttic.Tickets', 'M.TIX-US-H7', NULL, 'H', NULL, NULL, 'planned', '⬜', '', 'As a Dev, I filter with a query language (repo:M.FLOW type:fix status:open label:ui ''text'') and save named filters for reuse in the CLI and Desktop.', NULL, NULL, 'bullet', 35);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1086, 'MindAttic.Tickets', 'M.TIX-US-H8', NULL, 'H', NULL, NULL, 'planned', '⬜', '', 'As a Dev, I select many tickets and approve, reject, close, label or reprioritize them in one action.', NULL, NULL, 'bullet', 36);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1087, 'MindAttic.Tickets', 'M.TIX-US-H9', NULL, 'H', NULL, NULL, 'planned', '⬜', '', 'As a Dev, Ctrl+Z undoes my last Workflow Desktop action by writing a compensating, recorded change, never by deleting history.', NULL, NULL, 'bullet', 37);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1088, 'MindAttic.Tickets', 'M.TIX-US-H10', NULL, 'H', NULL, NULL, 'planned', '⬜', '', 'As a Dev, Ctrl+K opens a command palette to jump to any ticket or story by ID or text and run any command by name.', NULL, NULL, 'bullet', 38);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1089, 'MindAttic.Tickets', 'M.TIX-US-H11', NULL, 'H', NULL, NULL, 'planned', '⬜', '', 'As a Dev, Workflow Desktop shows and edits a repo''s epics and stories (text, status, acceptance, evidence) and their implements links to tickets.', NULL, NULL, 'bullet', 39);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1090, 'MindAttic.Tickets', 'M.TIX-US-H12', NULL, 'H', NULL, NULL, 'planned', '⬜', '', 'As a Dev, a dependency graph shows a ticket''s requires chain both ways, with what''s blocking it highlighted (and a text list for screen readers).', NULL, NULL, 'bullet', 40);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1091, 'MindAttic.Tickets', 'M.TIX-US-H13', NULL, 'H', NULL, NULL, 'planned', '⬜', '', 'As a Dev, an activity feed shows every ticket change across the workspace as it happens, and a toast tells me when an agent closes a ticket.', NULL, NULL, 'bullet', 41);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1092, 'MindAttic.Tickets', 'M.TIX-US-H14', NULL, 'H', NULL, NULL, 'planned', '⬜', '', 'As a Dev, a ticket lists the commits whose subject names it, in every repo, with links to them on GitHub.', NULL, NULL, 'bullet', 42);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1093, 'MindAttic.Tickets', 'M.TIX-US-H15', NULL, 'H', NULL, NULL, 'planned', '⬜', '', 'As a Dev, a metrics view shows throughput, cycle time (opened to closed), and open tickets by repo and type over time.', NULL, NULL, 'bullet', 43);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1094, 'MindAttic.Tickets', 'M.TIX-US-H16', NULL, 'H', NULL, NULL, 'planned', '⬜', '', 'As a Dev, I export a filtered ticket list to CSV or markdown.', NULL, NULL, 'bullet', 44);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1095, 'MindAttic.Tickets', 'M.TIX-US-H17', NULL, 'H', NULL, NULL, 'planned', '⬜', '', 'As a Dev, filing a ticket offers a template per type (fix: symptom, cause, test; feature: story, acceptance) and warns when a similar open ticket already exists.', NULL, NULL, 'bullet', 45);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1096, 'MindAttic.Tickets', 'M.TIX-US-I1', NULL, 'I', NULL, NULL, 'planned', '⬜', '', 'As a Dev, once the GitHub Issues spike (M.FLOW-T50) reports, I decide whether Issues becomes the ticket store or a mirror of workflow.db, and a two-way sync prototype runs behind the same library API so the CLI, hooks and orchestrator don''t change.', NULL, NULL, 'bullet', 46);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1097, 'MindAttic.Capture', 'M.CAPT-US-T1', NULL, 'T', NULL, NULL, 'partial', '🟡', '', 'As a user, I have a Capture icon in the system tray whose menu offers Record Screen, Record App, Record Area, Screenshot (screen / app / area), my saved regions, Stop and Settings, so I can capture without a terminal.', NULL, NULL, 'bullet', 0);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1098, 'MindAttic.Capture', 'M.CAPT-US-T2', NULL, 'T', NULL, NULL, 'partial', '🟡', '', 'As a user, I can choose Record App and pick a running app''s window from a list, so only that window is recorded (lossless, at its native resolution).', NULL, NULL, 'bullet', 1);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1099, 'MindAttic.Capture', 'M.CAPT-US-T3', NULL, 'T', NULL, NULL, 'partial', '🟡', '', 'As a user, when I choose Record Area the whole screen (every monitor) dims under a gray semi-transparent overlay and I drag out a rectangle that shows as a light-blue outlined, fully clear cut-out, so I can see exactly what will be recorded.', NULL, NULL, 'bullet', 2);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1100, 'MindAttic.Capture', 'M.CAPT-US-T4', NULL, 'T', NULL, NULL, 'partial', '🟡', '', 'As a user, after drawing the area I can move it by dragging its upper-left grab handle and resize it from its edges and corners, so I can fine-tune the region before recording.', NULL, NULL, 'bullet', 3);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1101, 'MindAttic.Capture', 'M.CAPT-US-T5', NULL, 'T', NULL, NULL, 'partial', '🟡', '', 'As a user, buttons beside the selection let me snap it to an aspect ratio (Free, 16:9, 9:16, 1:1, 4:3, 4:5, 21:9, ...), resizing to the rectangle of that ratio closest in size to my current cut-out, so a 1:1 is a square and a 9:16 is a tall vertical frame.', NULL, NULL, 'bullet', 4);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1102, 'MindAttic.Capture', 'M.CAPT-US-T6', NULL, 'T', NULL, NULL, 'partial', '🟡', '', 'As a user, the area toolbar also lets me pick the output format (video: MP4 H.264 / lossless MKV / GIF, screenshot: PNG / JPG) and start Record or take a Screenshot, so I decide what is produced before capturing.', NULL, NULL, 'bullet', 5);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1103, 'MindAttic.Capture', 'M.CAPT-US-T7', NULL, 'T', NULL, NULL, 'partial', '🟡', '', 'As a user, I can save the current region''s size and position under a name like ''YouTube Short'', and later pick it from the tray or the overlay, so I can record the same frame again without redrawing it.', NULL, NULL, 'bullet', 6);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1104, 'MindAttic.Capture', 'M.CAPT-US-T8', NULL, 'T', NULL, NULL, 'partial', '🟡', '', 'As a user, once a region is armed, a global hotkey starts recording it and pressing it again stops, and a separate hotkey takes a screenshot of it; a thin border marks the region while it records and is never in the recording, so I can capture hands-free.', NULL, NULL, 'bullet', 7);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1105, 'MindAttic.Capture', 'M.CAPT-US-T9', NULL, 'T', NULL, NULL, 'partial', '🟡', '', 'As a user, when a recording stops the lossless master is written and a lossy copy is written next to it, so I have both an editing master and a small file ready to upload.', NULL, NULL, 'bullet', 8);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1106, 'MindAttic.Capture', 'M.CAPT-US-T10', NULL, 'T', NULL, NULL, 'partial', '🟡', '', 'As a user, I can open Settings from the tray to assign the record and screenshot hotkeys, choose the output folder and default format, and set Capture to start with Windows, so the tray app fits my setup.', NULL, NULL, 'bullet', 9);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1107, 'Unity.GridGame', 'GG-US-Z1', NULL, 'Z', NULL, NULL, 'planned', '⬜', '', 'As a player, I want my hero''s identity to emerge from the stat and ability choices I actually make rather than a fixed class label, so a Warrior who leans into Agility feels like a different fighter and one who leans into Intelligence can eventually cast a spell like Fireball -- exact mechanism (node tree, shared ring, or pure stat-gated unlocks) is still undecided; parked to focus on core gameplay first.', NULL, NULL, 'bullet', 265);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1108, 'Unity.GridGame', 'GG-US-W1', NULL, 'W', NULL, NULL, 'planned', '⬜', '', 'As a new player, the game introduces one camp system at a time in a natural order -- shop, blacksmith repairs, alchemy potions from looted materials, forging a weapon, then armor, enchanting armor for passive effects, then training a new skill for my bar -- each with a short guided first use, so I learn the whole loop without being dumped into every menu at once.', NULL, NULL, 'bullet', 266);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1109, 'Unity.GridGame', 'GG-US-W2', NULL, 'W', NULL, NULL, 'planned', '⬜', '', 'As a player, there is enough to find, craft and fight to carry a whole campaign: 100 unique weapons, 100 unique armor pieces in named sets, 100 mechanically distinct abilities, 100 distinct enemy groups, recipes that use every material enemies drop, and enchants for armor as well as weapons.', NULL, NULL, 'bullet', 267);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1110, 'Unity.GridGame', 'GG-US-W3', NULL, 'W', NULL, NULL, 'planned', '⬜', '', 'As a player, I can pick how the menus look in Settings: the current blue windows, a slate-gray theme like Chrono Trigger''s default windows, or a modern dark theme like the DocFX docs sites and mindattic.com.', NULL, NULL, 'bullet', 268);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1111, 'Unity.GridGame', 'GG-US-W4', NULL, 'W', NULL, NULL, 'planned', '⬜', '', 'As a new player, starting a game shows an opening crawl, a short (lorem ipsum) conversation, and a tutorial that teaches the battle controls before my first real fight.', NULL, NULL, 'bullet', 269);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1112, 'Unity.Hare', 'U.HARE-US-A1', NULL, 'A', NULL, NULL, 'done', '✅', '', 'As a developer, I have a Unity project scaffolded under Unity.Hare with the folder layout (Scenes/Scripts/Prefabs/Art/Audio) the other MindAttic Unity games use, so the rebuild starts from a consistent baseline', NULL, NULL, 'bullet', 0);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1113, 'Unity.Hare', 'U.HARE-US-A2', NULL, 'A', NULL, NULL, 'done', '✅', '', 'As a developer, I have the reverse-engineering notes from gmlHARE/gmlRabbit (objects, scripts, rooms) captured in docs/ so the GML source of truth survives even if R:\ becomes unavailable', NULL, NULL, 'bullet', 1);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1114, 'Unity.Hare', 'U.HARE-US-A3', NULL, 'A', NULL, NULL, 'done', '✅', '', 'As a developer, I can import the existing Unity HARE proof-of-concept (Assets/Resources, Scripts/Player, Scripts/Weapon, Scripts/Rock) as a starting reference without being blocked by it', NULL, NULL, 'bullet', 2);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1115, 'Unity.Hare', 'U.HARE-US-B1', NULL, 'B', NULL, NULL, 'done', '✅', '', 'As a player, I can fly obj_player''s ship with thrust/rotate controls (boost, brake, leap) matching the original''s alarm-driven state machine', NULL, NULL, 'bullet', 3);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1116, 'Unity.Hare', 'U.HARE-US-B2', NULL, 'B', NULL, NULL, 'done', '✅', '', 'As a player, I can take damage and die/respawn (player_hurt, reset_player) with the same health/lives rules as the GML original', NULL, NULL, 'bullet', 4);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1117, 'Unity.Hare', 'U.HARE-US-B3', NULL, 'B', NULL, NULL, 'done', '✅', '', 'As a player, I can raise a shield (player_shield/obj_shield/obj_shieldwall) that blocks incoming damage for a limited time', NULL, NULL, 'bullet', 5);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1118, 'Unity.Hare', 'U.HARE-US-C1', NULL, 'C', NULL, NULL, 'done', '✅', '', 'As a player, I can fire the primary air weapon (vulcan) with spin-up/spin-down and a looping fire sound', NULL, NULL, 'bullet', 6);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1119, 'Unity.Hare', 'U.HARE-US-C2', NULL, 'C', NULL, NULL, 'planned', '⬜', '', 'As a player, I can fire a secondary air weapon (laser, railgun or rocket) and cycle between unlocked air weapons with next_air_weapon', NULL, NULL, 'bullet', 7);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1120, 'Unity.Hare', 'U.HARE-US-C3', NULL, 'C', NULL, NULL, 'planned', '⬜', '', 'As a player, I can fire the shotgun and flamethrower weapons with their own spread/cone behaviour', NULL, NULL, 'bullet', 8);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1121, 'Unity.Hare', 'U.HARE-US-D1', NULL, 'D', NULL, NULL, 'planned', '⬜', '', 'As a player, I can fire a separate ground weapon loadout (mine, grenade) at surface targets, cycling with next_ground_weapon', NULL, NULL, 'bullet', 9);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1122, 'Unity.Hare', 'U.HARE-US-D2', NULL, 'D', NULL, NULL, 'planned', '⬜', '', 'As a player, ammo cost and resupply (set_ammo_cost, subtract_ground_ammo) work the same as the original for both air and ground loadouts', NULL, NULL, 'bullet', 10);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1123, 'Unity.Hare', 'U.HARE-US-E1', NULL, 'E', NULL, NULL, 'planned', '⬜', '', 'As a player, I fight flying insect-style enemies (butterfly, firefly, fly, dagger) driven by their original ai_* flight patterns', NULL, NULL, 'bullet', 11);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1124, 'Unity.Hare', 'U.HARE-US-E2', NULL, 'E', NULL, NULL, 'planned', '⬜', '', 'As a player, I fight the larger set-piece enemies (hydra, phalanx with phalanx_shield, meatball, wraith, sawblade, worm with segments/gibs, trilobyte, mimic with mimic_illusion)', NULL, NULL, 'bullet', 12);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1125, 'Unity.Hare', 'U.HARE-US-E3', NULL, 'E', NULL, NULL, 'planned', '⬜', '', 'As a player, enemies spawn through the original emitter objects (obj_*_emitter) and generate_enemy_list so spawn pacing matches the source game', NULL, NULL, 'bullet', 13);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1126, 'Unity.Hare', 'U.HARE-US-E4', NULL, 'E', NULL, NULL, 'planned', '⬜', '', 'As a player, enemies die with the right gib/explosion/death-particle effects per enemy type (meatball_gib, worm_gib, rocket_explosion, death_particle)', NULL, NULL, 'bullet', 14);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1127, 'Unity.Hare', 'U.HARE-US-F1', NULL, 'F', NULL, NULL, 'planned', '⬜', '', 'As a player, I navigate around destructible rocks (rock1-5, create_new_rock, move_rocks, rock_destroyed) that behave like the original''s par_rock family', NULL, NULL, 'bullet', 15);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1128, 'Unity.Hare', 'U.HARE-US-F2', NULL, 'F', NULL, NULL, 'planned', '⬜', '', 'As a player, I see weather/ambient environment layers (clouds, rain, snow, sand, fog emitters) matching each room''s backdrop', NULL, NULL, 'bullet', 16);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1129, 'Unity.Hare', 'U.HARE-US-G1', NULL, 'G', NULL, NULL, 'planned', '⬜', '', 'As a player, I can select a level from the overworld map (room_map, obj_map, obj_destination, obj_btn_level01-09) the way the original campaign does', NULL, NULL, 'bullet', 17);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1130, 'Unity.Hare', 'U.HARE-US-G2', NULL, 'G', NULL, NULL, 'planned', '⬜', '', 'As a player, each level (level_01..level_10, level_default, level_composition, level_objective, level_setting) loads its own enemy composition, objective and time limit', NULL, NULL, 'bullet', 18);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1131, 'Unity.Hare', 'U.HARE-US-G3', NULL, 'G', NULL, NULL, 'planned', '⬜', '', 'As a player, I play the side-scroll and shaft stage variants (room_sidescroll, room_shaft) in addition to the open gamescreen arena', NULL, NULL, 'bullet', 19);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1132, 'Unity.Hare', 'U.HARE-US-G4', NULL, 'G', NULL, NULL, 'planned', '⬜', '', 'As a player, finishing a level shows level_results and level-complete state (set_level_complete) before returning to the map', NULL, NULL, 'bullet', 20);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1133, 'Unity.Hare', 'U.HARE-US-H1', NULL, 'H', NULL, NULL, 'planned', '⬜', '', 'As a player, I collect carrots, coins, chips and cartridges dropped by enemies/rocks (random_pickup, spawn_chips, obj_drop*) as the game''s currency/ammo pickups', NULL, NULL, 'bullet', 21);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1134, 'Unity.Hare', 'U.HARE-US-H2', NULL, 'H', NULL, NULL, 'planned', '⬜', '', 'As a player, I spend currency in the upgrade/garage screen (room_upgrade, obj_upgrade, obj_upgrade_vulcan1, obj_upgrade_shotgun1, obj_upgrade_missle1, obj_rabbit_schematic, obj_booster_schematic, obj_brake_schematic) to improve my ship', NULL, NULL, 'bullet', 22);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1135, 'Unity.Hare', 'U.HARE-US-I1', NULL, 'I', NULL, NULL, 'planned', '⬜', '', 'As a player, I see a HUD with health bar, energy bar, weapon GUI and speedometer during gameplay (obj_healthbar, obj_energybar, obj_weapon_gui, obj_speedometer)', NULL, NULL, 'bullet', 23);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1136, 'Unity.Hare', 'U.HARE-US-I2', NULL, 'I', NULL, NULL, 'planned', '⬜', '', 'As a player, I navigate title and quit/confirm menus (obj_title, obj_btn_quickstart, obj_btn_campaign, obj_btn_quit, obj_yesno_dialog) with the same flow as the original', NULL, NULL, 'bullet', 24);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1137, 'Unity.Hare', 'U.HARE-US-I3', NULL, 'I', NULL, NULL, 'planned', '⬜', '', 'As a player, I see floating damage/pickup text and tips (obj_float_text, obj_tip, obj_alert) during play', NULL, NULL, 'bullet', 25);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1138, 'Unity.Hare', 'U.HARE-US-J1', NULL, 'J', NULL, NULL, 'planned', '⬜', '', 'As a player, I read the intro and story scenes (room_intro, room_story, obj_conversation, obj_typewriter_story, load_scenario) with a typewriter-style text reveal', NULL, NULL, 'bullet', 26);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1139, 'Unity.Hare', 'U.HARE-US-K1', NULL, 'K', NULL, NULL, 'planned', '⬜', '', 'As a player, I hear the original''s music tracks with random selection between levels (play_random_music, obj_jukebox)', NULL, NULL, 'bullet', 27);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1140, 'Unity.Hare', 'U.HARE-US-K2', NULL, 'K', NULL, NULL, 'planned', '⬜', '', 'As a player, I hear weapon and UI sound effects ported from the gmlHARE/gmlRabbit sound libraries (102-152 original sound assets)', NULL, NULL, 'bullet', 28);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1141, 'Unity.Hare', 'U.HARE-US-L1', NULL, 'L', NULL, NULL, 'planned', '⬜', '', 'As a player, I see muzzle flashes, explosions (oval_explosion, tinyexplosion, rocket_explosion, grenade_explosion) and trail/swirl effects (rail_swirl) matching each weapon', NULL, NULL, 'bullet', 29);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1142, 'Unity.Hare', 'U.HARE-US-M1', NULL, 'M', NULL, NULL, 'planned', '⬜', '', 'As a player, I fight Scrap Mental, the level 8 boss (obj_scrapmental with its obj_shrapnel_back/piece/harpoon parts) in the open arena, and destroying it completes the level', NULL, NULL, 'bullet', 30);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1143, 'Unity.Ricochet', 'U.RICO-US-CORE1', NULL, 'CORE', NULL, NULL, 'planned', '⬜', '', 'As a player, I aim with an angle and power meter and see my shot''s likely ricochet path off borders and redirectors before I fire, the way the 2013 original''s aim/bounce-preview did.', NULL, NULL, 'bullet', 0);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1144, 'Unity.Ricochet', 'U.RICO-US-CORE2', NULL, 'CORE', NULL, NULL, 'planned', '⬜', '', 'As a host, I set up to 16 players (any mix of human and AI) with names, colours and per-player health, and play proceeds through a visible turn order with a turn timer.', NULL, NULL, 'bullet', 1);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1145, 'Unity.Ricochet', 'U.RICO-US-CORE3', NULL, 'CORE', NULL, NULL, 'planned', '⬜', '', 'As a player, I cycle through a weapon and item loadout, throw fused grenades, and pick up random weapon/item/health drops spawned on the level.', NULL, NULL, 'bullet', 2);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1146, 'Unity.Ricochet', 'U.RICO-US-CORE4', NULL, 'CORE', NULL, NULL, 'planned', '⬜', '', 'As a player, I contend with level hazards carried over from the original: a destructible shield wall, a vortex detonation, electricity and laser obstacles, and destructible borders/foliage.', NULL, NULL, 'bullet', 3);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1147, 'Unity.Ricochet', 'U.RICO-US-CORE5', NULL, 'CORE', NULL, NULL, 'planned', '⬜', '', 'As a player, I can fill empty seats with AI opponents whose count and aim-assist level I control before the match starts.', NULL, NULL, 'bullet', 4);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1148, 'Unity.Ricochet', 'U.RICO-US-CORE6', NULL, 'CORE', NULL, NULL, 'planned', '⬜', '', 'As a player, I see announcer commentary (portrait + name box) between turns and a HUD showing scores, turn time, and the current weapon/item.', NULL, NULL, 'bullet', 5);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1149, 'Unity.Ricochet', 'U.RICO-US-CORE7', NULL, 'CORE', NULL, NULL, 'planned', '⬜', '', 'As a player, I move through title, player setup, map/room select, settings, controls, how-to-play and credits screens, and see an endgame recap, matching the original''s room flow.', NULL, NULL, 'bullet', 6);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1150, 'Unity.Ricochet', 'U.RICO-US-CORE8', NULL, 'CORE', NULL, NULL, 'planned', '⬜', '', 'As a player, my display name, colour and audio settings come from my MindAttic profile (Unity.Shared) instead of being re-entered every session.', NULL, NULL, 'bullet', 7);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1151, 'Unity.Ricochet', 'U.RICO-US-NET1', NULL, 'NET', NULL, NULL, 'planned', '⬜', '', 'As a player, I host a match (listen server or dedicated) or join one by IP or a short join code, through the Unity.Multiplayer drop-in front end and lobby.', NULL, NULL, 'bullet', 8);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1152, 'Unity.Ricochet', 'U.RICO-US-NET2', NULL, 'NET', NULL, NULL, 'planned', '⬜', '', 'As a player, turn order, aiming inputs, shot resolution and damage are server-authoritative and replicated to every client, replacing the original''s single-PC hotseat turn-passing.', NULL, NULL, 'bullet', 9);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1153, 'Unity.Ricochet', 'U.RICO-US-NET3', NULL, 'NET', NULL, NULL, 'planned', '⬜', '', 'As a player who drops mid-match, my seat and health are held for the reconnect grace period and I resume on the same turn if I reconnect in time.', NULL, NULL, 'bullet', 10);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1154, 'Unity.Ricochet', 'U.RICO-US-NET4', NULL, 'NET', NULL, NULL, 'planned', '⬜', '', 'As a player, I can start a restart or kick vote through NetVotes with the same overlay the house front end provides.', NULL, NULL, 'bullet', 11);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1155, 'Unity.Incognito', 'U.INC-US-A1', NULL, 'A', NULL, NULL, 'done', '✅', '', 'As a player, I walk left/right with a gentle triangle-wave vertical bob (ramping between a min/max offset, not a literal sine) that quickens while sprinting, so movement feels alive instead of robotic. *(verified by `PlayerLocomotionStateTests` (Core.Tests: `Bob_oscillates_between_amplitude_bounds_while_walking`, `Sprint_ramps_up_to_double_speed_instead_of_snapping`).)*', NULL, NULL, 'bullet', 0);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1156, 'Unity.Incognito', 'U.INC-US-A2', NULL, 'A', NULL, NULL, 'done', '✅', '', 'As a player, the camera holds my character pinned near the screen edge opposite my facing direction (leading room ahead of me) while panning vertically with the mouse, so the view stays close and intimate instead of centering me. *(verified by `CloseFramingCameraStateTests` (Core.Tests: `Snap_pins_the_player_near_the_trailing_edge`, `Vertical_pan_follows_mouse_height_and_is_bounded`).)*', NULL, NULL, 'bullet', 1);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1157, 'Unity.Incognito', 'U.INC-US-A3', NULL, 'A', NULL, NULL, 'done', '✅', '', 'As a player, my cursor doubles as my character''s visible eye: the pupil tracks the mouse with a parallax offset and blinks on a randomized idle timer, and the on-screen cursor sprite itself changes to reflect look/talk/pointer/aim modes. *(verified by `EyeballStateTests` (Core.Tests: `Pupil_is_damped_parallax_not_one_to_one`, `Blink_rolls_irandom_range_0_to_160_each_idle_step`, `Each_mode_shows_its_own_sprite`).)*', NULL, NULL, 'bullet', 2);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1158, 'Unity.Incognito', 'U.INC-US-A4', NULL, 'A', NULL, NULL, 'done', '✅', '', 'As a player, scrolling the mouse wheel cycles the cursor between look mode (hover an NPC to read a floating description) and talk mode (click an NPC to walk over and start a conversation). *(verified by `CursorModeCyclingTests` (EditMode: `Wheel_either_way_cycles`, `Npc_click_action_follows_the_cursor_mode`).)*', NULL, NULL, 'bullet', 3);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1159, 'Unity.Incognito', 'U.INC-US-A5', NULL, 'A', NULL, NULL, 'done', '✅', '', 'As a player, clicking an NPC in pointer mode opens a hacking/console overlay on that NPC (a Shadowrun-style ''matrix'' panel), separate from the look/talk interactions. *(verified by `HackingOverlayTests` (EditMode: `Pointer_click_hacks_the_npc_and_raises_the_active_program_icon`).)*', NULL, NULL, 'bullet', 4);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1160, 'Unity.Incognito', 'U.INC-US-A6', NULL, 'A', NULL, NULL, 'done', '✅', '', 'As a player, NPCs patrol between waypoints with the same idle bob animation and raise a visible suspicion meter driven by my proximity, whether we''re facing each other, and whether I''m looking down (console/menu open), so stealth has Shadowrun-flavored social detection. *(verified by `NpcPatrolStateTests` and `SuspicionMeterTests` (Core.Tests: `Loops_the_route_turning_at_each_waypoint`, `Bobs_like_the_player_while_walking`, `Close_eye_contact_raises_suspicion_fastest`, `Looking_down_while_facing_bleeds_suspicion_off`).)*', NULL, NULL, 'bullet', 5);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1161, 'Unity.Incognito', 'U.INC-US-A7', NULL, 'A', NULL, NULL, 'done', '✅', '', 'As a player, I can draw/holster a weapon through an equip animation, aim with the arm pivoting toward the mouse, and fire a bullet that travels and can hit an NPC. *(verified by `PlayerWeaponStateTests`, `BulletStateTests` (Core.Tests) and `BulletTests` (EditMode).)*', NULL, NULL, 'bullet', 6);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1162, 'Unity.Incognito', 'U.INC-US-A8', NULL, 'A', NULL, NULL, 'done', '✅', '', 'As a player, I can open a typed command console (help/list/reboot/overwrite/clear) that queries nearby objects by type, echoing the original terminal/hacking mini-game. *(verified by `CommandInterpreterTests` (Core.Tests) and `TerminalRuntimeTests` (EditMode).)*', NULL, NULL, 'bullet', 7);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1163, 'Unity.Incognito', 'U.INC-US-A9', NULL, 'A', NULL, NULL, 'done', '✅', '', 'As a player, the street/shop/title rooms are rebuilt as Unity scenes with the original parallax clouds, rain, and lamplight props, playing the original footstep/whoosh/door/type sound effects and music tracks. *(verified by `RoomTraversalPlayTests` (PlayMode: `Every_room_is_reachable_from_the_title_and_every_exit_lands_where_the_original_put_the_player`) and `RoomSceneBuilderTests` (EditMode).)*', NULL, NULL, 'bullet', 8);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1164, 'Unity.Incognito', 'U.INC-US-A10', NULL, 'A', NULL, NULL, 'done', '✅', '', 'As a player, a pistol icon rises from the bottom-right of the screen (spr_icon_pistol, swapping to spr_icon_pistol_selected while the gun is out) and clicking it draws or holsters the gun exactly like Z, with the original sfx_flick click sound on icon and console clicks, so the HUD gun toggle of the original works. *(verified by `HudPistolIconPlayTests` (PlayMode: `The_pistol_icon_rises_and_a_click_draws_and_holsters_the_gun`, `A_console_click_selects_it_and_flicks`).)*', NULL, NULL, 'bullet', 9);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1165, 'Unity.Incognito', 'U.INC-US-A11', NULL, 'A', NULL, NULL, 'done', '✅', '', 'As a player, every original sound the live game used is present: sfx_flick (HUD clicks) and the whispers ambient loop (imported and kept as room data, unwired exactly as in the original), so no audio the original played is missing. *(verified by `OriginalAudioParityTests` (Core.Tests: `Every_sound_a_live_original_object_plays_is_catalogued_wired_and_on_disk`, `Whispers_is_imported_and_catalogued_but_unwired_as_in_the_original`).)*', NULL, NULL, 'bullet', 10);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1166, 'Unity.Incognito', 'U.INC-US-A12', NULL, 'A', NULL, NULL, 'done', '✅', '', 'As a player, all text is drawn in the original''s fonts (fnt_basic 12pt Arial, fnt_large, fnt_system) with the original''s outlined-text look, as real UI Toolkit/TextMesh text rather than IMGUI, so the prose and labels read as they did. *(verified by `OriginalFontParityTests`, `GmTextTests` (Core.Tests) and `OriginalTextPlayTests` (PlayMode: `Room_npc_console_and_floating_text_use_the_original_fonts_and_outlines`).)*', NULL, NULL, 'bullet', 11);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1167, 'Unity.Incognito', 'U.INC-US-A13', NULL, 'A', NULL, NULL, 'done', '✅', '', 'As a player, the game runs at the original''s 1920x1080 reference with the original''s screen-ratio setup (obj_startup), letterboxed on other aspects, starting fullscreen from the title as the original did. *(verified by `ScreenRatioTests` (Core.Tests) and `GameDisplayTests` (EditMode).)*', NULL, NULL, 'bullet', 12);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1168, 'Unity.Incognito', 'U.INC-US-A14', NULL, 'A', NULL, NULL, 'done', '✅', '', 'As a player, every sprite and background a live original object or room uses is in the rebuild (spr_exit_side, spr_barrier, spr_command_prompt and its selected variant, spr_console, spr_icon_pistol and selected, spr_linewall and the rest of the inventory in RECONSTRUCTION.md section 10), proven by a test that diffs the original''s live asset list against the rebuild''s. *(verified by `OriginalArtParityTests` (Core.Tests: `Every_image_a_live_original_object_or_room_uses_is_catalogued_at_its_origin_and_on_disk`).)*', NULL, NULL, 'bullet', 13);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1169, 'Unity.Incognito', 'U.INC-US-A15', NULL, 'A', NULL, NULL, 'planned', '⬜', '', 'As the owner, the finished game is verified end to end against the reconstruction by a scripted run that plays title to every room and every mechanic and captures screenshots, so the repo can be called a complete proof of concept of the original.', NULL, NULL, 'bullet', 14);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1170, 'Unity.QuickDuel', 'UQD-US-P1', NULL, 'P', NULL, NULL, 'planned', '⬜', '', 'As a player, I see the original Bushido Coda''s own art in the duel, so that the game looks like the game it rebuilds.', NULL, NULL, 'bullet', 0);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1171, 'Unity.Chain', 'U.CHN-US-F1', NULL, 'F', NULL, NULL, 'done', '✅', '', 'As a maintainer, I can read docs/BIBLE.md and the README to learn the game''s rules, the architecture and every deliberate deviation from the original, so that the repo matches the shared standard', NULL, NULL, 'bullet', 0);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1172, 'Unity.Chain', 'U.CHN-US-F2', NULL, 'F', NULL, NULL, 'done', '✅', '', 'As a maintainer, the game rules live in an engine-free Core assembly apart from the MonoBehaviour layer, so that they can be tested without Unity', NULL, NULL, 'bullet', 1);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1173, 'Unity.Chain', 'U.CHN-US-F3', NULL, 'F', NULL, NULL, 'done', '✅', '', 'As a maintainer, I can run the Core tests with dotnet test outside Unity, so that rules are checked in seconds without opening the editor', NULL, NULL, 'bullet', 2);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1174, 'Unity.Chain', 'U.CHN-US-F4', NULL, 'F', NULL, NULL, 'done', '✅', '', 'As a maintainer, game state changes only through commands that produce events, so that presentation only reads state and plays events and local play is the same path an online game will use', NULL, NULL, 'bullet', 3);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1175, 'Unity.Chain', 'U.CHN-US-F5', NULL, 'F', NULL, NULL, 'done', '✅', '', 'As a designer, every tuning number and the level content come from data files validated on load, so that nothing is hard-coded in behaviour', NULL, NULL, 'bullet', 4);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1176, 'Unity.QuickDuel', 'UQD-US-S1', NULL, 'S', NULL, NULL, 'planned', '⬜', '', 'As the maintainer, I want the duel''s tuning (countdown, standoff range, strike timeout, settle window, AI reaction ranges, wins needed, taunt lines, human floor) in a validated settings registry and profile on the shared Unity.Shared package, so that no tuning number is hard-coded in behaviour.', NULL, NULL, 'bullet', 1);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1177, 'Unity.Chain', 'U.CHN-US-F6', NULL, 'F', NULL, NULL, 'done', '✅', '', 'As a player, I steer and act through the Input System with rebindable actions and gamepad support, so that input is not hard-coded to device polling', NULL, NULL, 'bullet', 5);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1178, 'Unity.QuickDuel', 'UQD-US-S2', NULL, 'S', NULL, NULL, 'planned', '⬜', '', 'As the maintainer, I want the game on URP behind a pipeline-agnostic layer, so that it follows the Unity 6 standard the other repos use.', NULL, NULL, 'bullet', 2);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1179, 'Unity.QuickDuel', 'UQD-US-S3', NULL, 'S', NULL, NULL, 'planned', '⬜', '', 'As the maintainer, I want every duel rule, including the match flow and mode selection that live in DuelSession today, in the engine-free Core behind commands that carry a player id and produce events, so that presentation only reads state and plays events and local and online play share one path.', NULL, NULL, 'bullet', 3);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1180, 'Unity.QuickDuel', 'UQD-US-S4', NULL, 'S', NULL, NULL, 'planned', '⬜', '', 'As a player, I want crisp, resolution-independent text and UI, so that the game looks right at any window size.', NULL, NULL, 'bullet', 4);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1181, 'Unity.Ricochet', 'U.RICO-US-STD1', NULL, 'STD', NULL, NULL, 'planned', '⬜', '', 'As a maintainer, every assembly is named for this game and sits behind a hard one-way boundary (Ricochet.Core <- Ricochet.Runtime <- Ricochet.Editor and tests), so nothing is still called MyGame.', NULL, NULL, 'bullet', 12);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1182, 'Unity.Ricochet', 'U.RICO-US-STD2', NULL, 'STD', NULL, NULL, 'planned', '⬜', '', 'As a maintainer, the game''s rules change state only through commands that produce events, and presentation reads state and plays the events, so a networked client, a replay and a test all drive the same path.', NULL, NULL, 'bullet', 13);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1183, 'Unity.QuickDuel', 'UQD-US-P2', NULL, 'P', NULL, NULL, 'done', '✅', '', 'As a player, each duel is set on one of the original''s arenas, so that no two duels feel the same.', NULL, NULL, 'bullet', 5);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1184, 'Unity.Ricochet', 'U.RICO-US-STD3', NULL, 'STD', NULL, NULL, 'planned', '⬜', '', 'As a designer, every tuning number and every piece of content (rules, weapons, items, maps, announcer lines, slides, names) is a data file validated on load, not a constant in behaviour.', NULL, NULL, 'bullet', 14);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1185, 'Unity.QuickDuel', 'UQD-US-P3', NULL, 'P', NULL, NULL, 'planned', '⬜', '', 'As a player, I see two samurai on the field, so that the standoff has someone in it.', NULL, NULL, 'bullet', 6);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1186, 'Unity.Ricochet', 'U.RICO-US-STD4', NULL, 'STD', NULL, NULL, 'planned', '⬜', '', 'As a player, the game reads input through the Unity Input System with rebindable actions, so a controller or a rebind works and nothing depends on the legacy Input Manager.', NULL, NULL, 'bullet', 15);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1187, 'Unity.QuickDuel', 'UQD-US-P4', NULL, 'P', NULL, NULL, 'planned', '⬜', '', 'As a player, I see the duelists charge at the cue, so that the strike feels like a motion and not a flash.', NULL, NULL, 'bullet', 7);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1188, 'Unity.Ricochet', 'U.RICO-US-STD5', NULL, 'STD', NULL, NULL, 'planned', '⬜', '', 'As a player, the game renders through URP with a pipeline-agnostic layer, so quality tiers and platforms work and no code names a render pipeline.', NULL, NULL, 'bullet', 16);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1189, 'Unity.QuickDuel', 'UQD-US-P5', NULL, 'P', NULL, NULL, 'done', '✅', '', 'As a player, I read the original''s own type, so that the text has its character.', NULL, NULL, 'bullet', 8);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1190, 'Unity.Ricochet', 'U.RICO-US-STD6', NULL, 'STD', NULL, NULL, 'planned', '⬜', '', 'As a player, the HUD and every overlay are real UI (UI Toolkit or the shared MindAttic components), so it scales, themes and sits in the right order over menus.', NULL, NULL, 'bullet', 17);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1191, 'Unity.QuickDuel', 'UQD-US-P6', NULL, 'P', NULL, NULL, 'planned', '⬜', '', 'As a player, I see Get Ready and a fading 3-2-1, so that the countdown reads like the original''s.', NULL, NULL, 'bullet', 9);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1192, 'Unity.Ricochet', 'U.RICO-US-STD7', NULL, 'STD', NULL, NULL, 'planned', '⬜', '', 'As a maintainer, the two largest runtime classes are split into small single-purpose components, so each can be read and tested.', NULL, NULL, 'bullet', 18);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1193, 'Unity.Ricochet', 'U.RICO-US-STD8', NULL, 'STD', NULL, NULL, 'planned', '⬜', '', 'As a maintainer, every push builds, runs the Core tests and the EditMode and PlayMode suites in CI, and the Core is covered by tests for every rule.', NULL, NULL, 'bullet', 19);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1194, 'Unity.QuickDuel', 'UQD-US-P7', NULL, 'P', NULL, NULL, 'done', '✅', '', 'As a player, I watch the reaction counter run during the strike, so that I feel the time pass.', NULL, NULL, 'bullet', 10);
