INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1221, 'Unity.Ricochet', 'U.RICO-US-PAR15', NULL, 'PAR', NULL, NULL, 'planned', '⬜', '', 'As a player, the credits roll over the original''s credits image with its font.', NULL, NULL, 'bullet', 34);
