INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1227, 'Unity.Ricochet', 'U.RICO-US-PAR17', NULL, 'PAR', NULL, NULL, 'planned', '⬜', '', 'As a player, the game opens with the original''s studio splash and startup credits, in this project''s own words.', NULL, NULL, 'bullet', 36);
