INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1250, 'Unity.Hare', 'U.HARE-US-P2', NULL, 'P', NULL, NULL, 'planned', '⬜', '', 'As a developer, the original''s sound effects and music are imported into Unity as audio clips with their mixer groups, so every sound can be played by name', NULL, NULL, 'bullet', 41);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1251, 'Unity.Hare', 'U.HARE-US-P3', NULL, 'P', NULL, NULL, 'planned', '⬜', '', 'As a developer, the original''s fonts are available as Unity font assets, so text matches the original''s weight and size', NULL, NULL, 'bullet', 42);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1252, 'Unity.Hare', 'U.HARE-US-O1', NULL, 'O', NULL, NULL, 'planned', '⬜', '', 'As a player, the game remembers my lives, coins, skill points, score, difficulty and place in the campaign through one game-session state, the same way the original''s globals did', NULL, NULL, 'bullet', 43);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1253, 'Unity.Chain', 'U.CHN-US-G1', NULL, 'G', NULL, NULL, 'done', '✅', '', 'As a player, the chain and combat feel the same as the original, with each deliberate deviation recorded and chosen on purpose, so that gameplay is kept exactly', NULL, NULL, 'bullet', 16);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1254, 'Unity.Hare', 'U.HARE-US-O2', NULL, 'O', NULL, NULL, 'planned', '⬜', '', 'As a player, the game moves between its rooms (startup, title, intro, story, map, game, upgrade) with the original''s fade transitions and Esc behaviour, so it flows like the original', NULL, NULL, 'bullet', 44);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1255, 'Unity.Hare', 'U.HARE-US-O3', NULL, 'O', NULL, NULL, 'planned', '⬜', '', 'As a player, I see the startup screen with the circuit-board backdrop and the controller note before the title, the way the original opens', NULL, NULL, 'bullet', 45);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1256, 'Unity.Chain', 'U.CHN-US-G2', NULL, 'G', NULL, NULL, 'done', '✅', '', 'As a player, 14 enemies come at me from the corners of the arena and return on restart, so that the fight matches the original', NULL, NULL, 'bullet', 17);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1257, 'Unity.Overworld', 'U.OVW-US-A1', NULL, 'A', NULL, NULL, 'done', '✅', '', 'As the owner, the project is built on engine-free foundations: Overworld.Core (pure C#, noEngineReferences) holds the rules and changes only through commands that carry a player id and produce events, Overworld.Runtime, Overworld.Editor and the test assemblies reference it one way, and the simulation steps at a fixed 60 Hz so the original''s per-frame speeds behave identically on any machine (RECONSTRUCTION sections 2 and 19).', NULL, NULL, 'bullet', 0);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1258, 'Unity.Hare', 'U.HARE-US-O4', NULL, 'O', NULL, NULL, 'planned', '⬜', '', 'As a player, I play in the original''s open arena with a camera that follows my rabbit, scrolling backgrounds, wrap-around edges and a lost life when I fly out of bounds', NULL, NULL, 'bullet', 46);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1259, 'Unity.Overworld', 'U.OVW-US-A2', NULL, 'A', NULL, NULL, 'planned', '⬜', '', 'As the owner, every number and string the original kept in data or hard-coded in its source lives in validated data files loaded by Core: both world.mdb databases (the engine''s data/world.mdb and the later root world.mdb), hero.mdb, the five books, the 372 original pickups and the restored Nitro Bean, the quests and subquests, the two weapons, the three heroes, and the walls and props, with a test that loads them and cross-checks them against RECONSTRUCTION sections 8, 10 and 16.', NULL, NULL, 'bullet', 1);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1260, 'Unity.Overworld', 'U.OVW-US-A3', NULL, 'A', NULL, NULL, 'done', '✅', '', 'As the owner, all 895 original files (gfx, sfx, data, executable and databases) are catalogued in the repo with a disposition (imported and used, imported and used by the union layer, or recorded and deliberately not shipped), and a test diffs the catalogue against the original''s file list so no asset is silently missing (RECONSTRUCTION section 17).', NULL, NULL, 'bullet', 2);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1261, 'Unity.Hare', 'U.HARE-US-Q1', NULL, 'Q', NULL, NULL, 'planned', '⬜', '', 'As a player, my rabbit lands on rocks and structures, crouches there, aims from the rock and leaps off to the next one, exactly as in the original', NULL, NULL, 'bullet', 47);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1262, 'Unity.Overworld', 'U.OVW-US-A4', NULL, 'A', NULL, NULL, 'done', '✅', '', 'As a player, I see the world as the original drew it: an 11 by 11 grid of 512-pixel area tiles (A1 to F8, one world unit per tile, row A at the top) seen through a 45-degree perspective camera that looks straight down the Z axis from -1 and zooms out to -3.5, everything beyond the render range culled, a magenta-cleared backdrop box behind it, and heroes, tree-trunk props and weapons drawn back to front by Y.', NULL, NULL, 'bullet', 3);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1263, 'Unity.Overworld', 'U.OVW-US-A5', NULL, 'A', NULL, NULL, 'done', '✅', '', 'As a player, I move my hero by holding the right mouse button toward the cursor (walking when the cursor is near, running when it is far or the run key is held and stamina remains, slowing to a stop on arrival), or with the arrow keys, with the original''s 0.003/0.006 walk and run speeds, 0.001 acceleration steps, four-way facing, and the six-frame walk and run cycles of Chrono at 64 pixels.', NULL, NULL, 'bullet', 4);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1264, 'Unity.Chain', 'U.CHN-US-G3', NULL, 'G', NULL, NULL, 'done', '✅', '', 'As a player, enemies that overlap push each other apart instead of stacking into one blob, so that a crowd spreads out as in the original', NULL, NULL, 'bullet', 18);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1265, 'Unity.Overworld', 'U.OVW-US-A6', NULL, 'A', NULL, NULL, 'planned', '⬜', '', 'As a player, the mouse is a world cursor with the original''s arrow, edge-scroll arrows, zoom and eye (examine) sprites: moving it to a screen edge scrolls the camera (three times as fast with Shift) within the original''s limits around the hero, the camera eases back to centre on the hero while I move, the wheel or middle button zooms between -1 and -3.5, and F, the numpad and X/Z give the free-camera and isometric debug moves.', NULL, NULL, 'bullet', 5);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1266, 'Unity.Hare', 'U.HARE-US-Q2', NULL, 'Q', NULL, NULL, 'planned', '⬜', '', 'As a player, I lose a life when I die or leave the arena, drop back in from the top of the screen, and the game restarts when my lives run out, like the original', NULL, NULL, 'bullet', 48);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1267, 'Unity.Overworld', 'U.OVW-US-A7', NULL, 'A', NULL, NULL, 'done', '✅', '', 'As a player, six hard-coded wall segments (the horizontal, vertical and angled runs from (1,0) to (4,2)) stop my heroes from walking through them exactly as the original''s collision pushed them back, and a hero recalled to the party falls into place from Z -1.', NULL, NULL, 'bullet', 6);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1268, 'Unity.Overworld', 'U.OVW-US-A8', NULL, 'A', NULL, NULL, 'done', '✅', '', 'As a player, I lead a party of three (Chrono, Belmont and Flagg, all on Chrono''s sprites) that follows me: followers run when over 0.2 units away, walk when near, stand within 0.05, are recalled beside me beyond 1 unit, separate when they crowd each other, and I switch leader with [ and ] or a left click on a hero, with the Team/Solo button (apostrophe or the panel) turning following off so the others kneel.', NULL, NULL, 'bullet', 7);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1269, 'Unity.Hare', 'U.HARE-US-Q3', NULL, 'Q', NULL, NULL, 'planned', '⬜', '', 'As a player, my rabbit looks and animates like the original: idle, crouch, leap and hurt poses, the weapon held at my aim, smoke and spark trails, and the flashing when invulnerable', NULL, NULL, 'bullet', 49);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1270, 'Unity.Overworld', 'U.OVW-US-A9', NULL, 'A', NULL, NULL, 'done', '✅', '', 'As a player, the game has a clock that runs one in-game minute per real second from 9:00 AM on 1 January of year 64, divides the day into Day (9 to 18), Evening (18 to 21), Night (21 to 6) and Morning (6 to 9) with the original''s ambient tints and fade steps, announces each period on screen, names the months and weekdays with the original''s fantasy calendar, and shows the time and date on the HUD and hero screen.', NULL, NULL, 'bullet', 8);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1271, 'Unity.Chain', 'U.CHN-US-G4', NULL, 'G', NULL, NULL, 'done', '✅', '', 'As a player, a heart floats down the screen and heals me when I touch it, so that I can recover as in the original', NULL, NULL, 'bullet', 19);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1272, 'Unity.Overworld', 'U.OVW-US-A10', NULL, 'A', NULL, NULL, 'done', '✅', '', 'As a player, each hero has health, mana and stamina with the original''s maximums (50, 20 and 60), regenerates and spends stamina as the original does (plus 1 standing, plus 2 kneeling, minus 1 running, every 2 seconds), shows the Exhausted, Angry or Poisoned status animation above them when stamina is under 15 percent, health under 5 percent or poisoned, loses a health point every 2 seconds while poisoned, and sees all of it on the status box and the three bottom-left bars.', NULL, NULL, 'bullet', 9);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1273, 'Unity.Hare', 'U.HARE-US-Q4', NULL, 'Q', NULL, NULL, 'planned', '⬜', '', 'As a player, I find structures with their covers on the rocks of a level (and can land on them), as set by each level''s structure range', NULL, NULL, 'bullet', 50);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1274, 'Unity.Overworld', 'U.OVW-US-A11', NULL, 'A', NULL, NULL, 'done', '✅', '', 'As a player, I can rest: the rest key kneels me, again lays me down, and while laid I set 1 to 24 hours with left/down and right/up and confirm to sleep, which fades the screen out, restores one-eighth of maximum health, mana and stamina per hour for the whole party (stamina not while poisoned), advances the clock and fades back in, and the Moon Berry and Morningstar sleep until 10 PM and 5 AM.', NULL, NULL, 'bullet', 10);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1275, 'Unity.Overworld', 'U.OVW-US-A12', NULL, 'A', NULL, NULL, 'done', '✅', '', 'As a player, I find and pick up the original''s 372 pickups (plus the restored Nitro Bean as a 373rd, per the BIBLE) at their placements (the named herbs, the 45-plant potato and 49-plant turnip fields, the sword, books, rune, cheese, apple, eggs, coffee and nitro beans, and the randomly scattered gold, 5-gold and satchels), with a name label on the nearest one in reach (0.05), comma and period (or the wheel) cycling among those in reach, picking up kneeling the hero, picked-up herbs and crops growing back after their growth time, gold and satchels paying out at once, and the E key opening the examine box for the one under the cursor.', NULL, NULL, 'bullet', 11);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1276, 'Unity.Hare', 'U.HARE-US-O5', NULL, 'O', NULL, NULL, 'planned', '⬜', '', 'As a player, each level starts with its name banner, its objective and its time limit, runs its enemy emitters, and ends when I have met the objective, like the original', NULL, NULL, 'bullet', 51);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1277, 'Unity.Overworld', 'U.OVW-US-A13', NULL, 'A', NULL, NULL, 'done', '✅', '', 'As a player, I carry what I pick up in the inventory panel: stacked by name, ten icons per row with a cursor, weight against the party limit (28.5) kneeling me when over-burdened, swapping items with the run key, dropping them back into the world (and picking the drops up again), using them on a chosen party member or on myself, reusable items surviving use, the Delete key and panel button toggling it, and the 1 to 0 keys using items from the quick bar.', NULL, NULL, 'bullet', 12);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1278, 'Unity.Chain', 'U.CHN-US-G5', NULL, 'G', NULL, NULL, 'done', '✅', '', 'As a player, when I die the light fades and the game restarts by itself, so that game over matches the original', NULL, NULL, 'bullet', 20);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1279, 'Unity.Overworld', 'U.OVW-US-A14', NULL, 'A', NULL, NULL, 'done', '✅', '', 'As a player, I can type the original''s scripting language into the tilde console (CHANGE, MOVE and RUN commands over HERO, CAMERA, TIME, LIGHT, INVENTORY, BOOK, OPTIONS, CURSOR and SCRIPT, compound with '' | '', arithmetic with +/- and assignment otherwise), Insert recalls the last one, and every item''s effect, the Rune''s teleport and the quest end scripts run through it, with errors reported on screen as ''Script failed to execute.'' and exceptions as ''Script failed to run.''', NULL, NULL, 'bullet', 13);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1280, 'Unity.Hare', 'U.HARE-US-Q5', NULL, 'Q', NULL, NULL, 'planned', '⬜', '', 'As a player, I see the original''s backdrop props: the moon surface, floating debris and the water-surface reflection in the side-scroll stage', NULL, NULL, 'bullet', 52);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1281, 'Unity.Overworld', 'U.OVW-US-A15', NULL, 'A', NULL, NULL, 'done', '✅', '', 'As a player, I follow the original''s four main quests (Farmer Brinn''s fields, the centre field, the west-east pair and the far west) and two subquests, walking into each objective''s range to complete it and earn the original''s experience values, with the quest screen on Page Down (main, subquests, finished tabs) and a marker drawn in the world at every incomplete objective.', NULL, NULL, 'bullet', 14);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1282, 'Unity.Overworld', 'U.OVW-US-A16', NULL, 'A', NULL, NULL, 'done', '✅', '', 'As a player, I read the five books (Grimoire de''Alchemiste, Dragon Almanac, Poetry Book, Matt''s Book, Colesium Vol I) in a two-page book view with the original''s covers, fonts and Roman page numbers, turning pages with left/right or the wheel and cycling books with N, opening a book from its inventory item or the B key.', NULL, NULL, 'bullet', 15);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1283, 'Unity.Hare', 'U.HARE-US-O6', NULL, 'O', NULL, NULL, 'planned', '⬜', '', 'As a player, I see my score, the level objective, the elapsed time, my extra lives and my health pips on screen while I play', NULL, NULL, 'bullet', 53);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1284, 'Unity.Overworld', 'U.OVW-US-A17', NULL, 'A', NULL, NULL, 'done', '✅', '', 'As a player, the world has its weather and scenery: 2,501 particles of snow, rain, falling leaves and dust storm, cycled with W (starting in snow), 401 drifting clouds with four balloons, the tent at (-0.7,-0.04) and the four props, all falling, drifting and recycling as the original does.', NULL, NULL, 'bullet', 16);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1285, 'Unity.Overworld', 'U.OVW-US-A18', NULL, 'A', NULL, NULL, 'done', '✅', '', 'As a player, I toggle battle mode with End: heroes draw their weapon with the original''s draw and battle animations (the Steel Sword for Belmont and Flagg, the Fine Axe for Chrono, with their overlay sprites kept in step), the leader''s stamina becomes a turn gauge that recharges kneeling at the original''s 0.18-second rate, a hero reaching full is Ready and draws, and the team enters and leaves battle together.', NULL, NULL, 'bullet', 17);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1286, 'Unity.Chain', 'U.CHN-US-G6', NULL, 'G', NULL, NULL, 'done', '✅', '', 'As a player, the arena light fades and the day cycle tints the scene, so that the lighting matches the original', NULL, NULL, 'bullet', 21);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1287, 'Unity.Hare', 'U.HARE-US-O7', NULL, 'O', NULL, NULL, 'planned', '⬜', '', 'As a player, I can pause, restart the level, toggle the minimap, units, volume and fullscreen with the original''s keys', NULL, NULL, 'bullet', 54);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1288, 'Unity.Overworld', 'U.OVW-US-A19', NULL, 'A', NULL, NULL, 'done', '✅', '', 'As a player, in battle I choose from the ring menu around the active hero (Move, End, Skill, Item, Attack; rotated with left/right or the wheel, pulsed with Up, chosen with Enter or click), Move lets me walk only as far as my stamina allows (agility times 0.05 units, shown as a dotted circle), Attack shows my weapon''s range circle, Item opens the inventory at a 10 percent stamina cost, a pickup costs 5 percent, and End or running out of stamina passes the turn to the next ready hero with the camera following.', NULL, NULL, 'bullet', 18);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1289, 'Unity.Overworld', 'U.OVW-US-A20', NULL, 'A', NULL, NULL, 'planned', '⬜', '', 'As a player, the interface is complete: fading status messages, the tutorial text on start, the F11 options menu (controls list and exit), the PageUp hero screen, the FPS counter, the pause banner, the 12 random loading screens, the team, inventory and turn-bar widgets, and the eye cursor in examine mode.', NULL, NULL, 'bullet', 19);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1290, 'Unity.Hare', 'U.HARE-US-O8', NULL, 'O', NULL, NULL, 'planned', '⬜', '', 'As a player, I aim with the original''s blue reticle in the game and its pointer on menus', NULL, NULL, 'bullet', 55);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1291, 'Unity.Overworld', 'U.OVW-US-A21', NULL, 'A', NULL, NULL, 'planned', '⬜', '', 'As a player, I can play with a gamepad: the left stick moves and the buttons run, pick up, open the inventory, rest, drop and switch hero as in the original''s button map (J toggles it).', NULL, NULL, 'bullet', 20);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1292, 'Unity.Overworld', 'U.OVW-US-A22', NULL, 'A', NULL, NULL, 'planned', '⬜', '', 'As a player, the game has sound: the music track plays and loops (the original constructed it but never played it), and the footsteps, jump, sword draw, swing and hit, defend, charge, regen, death and ambient zombies sounds are wired to the events they were evidently made for, with the original''s music, effect and ambient volumes and the F7/F8 regen test.', NULL, NULL, 'bullet', 21);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1293, 'Unity.Hare', 'U.HARE-US-O9', NULL, 'O', NULL, NULL, 'planned', '⬜', '', 'As a player, the title screen opens with the original''s falling drop, the standing rabbit and the logo before the menu appears', NULL, NULL, 'bullet', 56);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1294, 'Unity.Overworld', 'U.OVW-US-A23', NULL, 'A', NULL, NULL, 'planned', '⬜', '', 'As a player, the game remembers its window, resolution and colour depth between runs as the original did in its registry key, shows the first-run welcome, and F12 toggles between windowed and full screen without losing the game.', NULL, NULL, 'bullet', 22);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1295, 'Unity.Chain', 'U.CHN-US-G7', NULL, 'G', NULL, NULL, 'done', '✅', '', 'As a player, I can toggle the chain''s follow-the-mouse force, so that I can watch it fall free as the original allowed', NULL, NULL, 'bullet', 22);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1296, 'Unity.Overworld', 'U.OVW-US-A24', NULL, 'A', NULL, NULL, 'planned', '⬜', '', 'As a player, when the current hero''s health reaches zero the screen fades to black and the game resets (pickups returned, inventory emptied, the day period set to Morning with the clock unchanged, the camera home) as the original''s GameOver and Reset do, with the original''s never-restored health defect replaced by restoring the party.', NULL, NULL, 'bullet', 23);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1297, 'Unity.Hare', 'U.HARE-US-O10', NULL, 'O', NULL, NULL, 'planned', '⬜', '', 'As a player, the map looks like the original: the spinning earth, the scanner sweep, the USS Warren, mission alerts and the travel dot', NULL, NULL, 'bullet', 57);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1298, 'Unity.Overworld', 'U.OVW-US-A25', NULL, 'A', NULL, NULL, 'planned', '⬜', '', 'As a player, the later world design is playable: the root world.mdb areas Grasslands and Lowlands with their eight landscape scenes, sky strips and mountain layer in parallax, the nine terrain segments the heroes walk over, and the placed orchard trees, Stonehenge and the Gateway from its prop table.', NULL, NULL, 'bullet', 24);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1299, 'Unity.Overworld', 'U.OVW-US-A26', NULL, 'A', NULL, NULL, 'planned', '⬜', '', 'As a player, stepping into a data-defined event box runs its script, so the Poison Box hurts, the Healing Box heals and Entering Dark Woods turns the day to night, at the rate the data gives, and the older database''s three events (Test, Dark Woods, Cinematic) and three scripts are kept as data.', NULL, NULL, 'bullet', 25);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1300, 'Unity.Hare', 'U.HARE-US-O11', NULL, 'O', NULL, NULL, 'planned', '⬜', '', 'As a player, I can start a quick game, the campaign or the enemy generator at a difficulty I choose, like the original''s three game modes', NULL, NULL, 'bullet', 58);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1301, 'Unity.Overworld', 'U.OVW-US-A27', NULL, 'A', NULL, NULL, 'planned', '⬜', '', 'As a player, I meet the Peasant Woman (standing) and the Magitek Armor (pursuing) placed in Grasslands, drawn with their walking, left, right and front sprites at 0.144 by 0.072.', NULL, NULL, 'bullet', 26);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1302, 'Unity.Overworld', 'U.OVW-US-A28', NULL, 'A', NULL, NULL, 'planned', '⬜', '', 'As a player, I meet the data-defined enemies (Werelynx, Botherfly, Blue Slime, Red Slime, Toadie) with their health, speed, sensing range, state (passive, aggressive, afraid, defensive), motion (walking, flying, hopping) and class, drawn with the catman and slime sprites in stand, walk, attack and hurt poses, with the original''s missing art (Botherfly, Toadie) supplied as placeholders flagged for replacement.', NULL, NULL, 'bullet', 27);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1303, 'Unity.Chain', 'U.CHN-US-G8', NULL, 'G', NULL, NULL, 'done', '✅', '', 'As a player, I can reset the game with a key and the music restarts at a random point, so that a new round starts as in the original', NULL, NULL, 'bullet', 23);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1304, 'Unity.Hare', 'U.HARE-US-O12', NULL, 'O', NULL, NULL, 'planned', '⬜', '', 'As a player, my campaign progress, coins, skill points and purchased upgrades are saved to my profile and restored when I return', NULL, NULL, 'bullet', 59);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1305, 'Unity.Overworld', 'U.OVW-US-A29', NULL, 'A', NULL, NULL, 'planned', '⬜', '', 'As a player, attacking and being attacked works: weapon rating, slashing, piercing and blunt values, range and durability (Steel Sword 28 of 30, Fine Axe 41 of 50), enemy health and class, defeat, and the Axe, Steel Sword, Katana and Broad Sword of the hero database, resolved by Core commands and events, with every number a documented decision because the original had no damage code.', NULL, NULL, 'bullet', 28);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1306, 'Unity.Overworld', 'U.OVW-US-A30', NULL, 'A', NULL, NULL, 'planned', '⬜', '', 'As a player, I can equip heroes from the hero database (Alexander, health 50, strength 1, agility 2, speed 2, with the Steel Sword), its four weapons with their sprite sets, and the empty head, body, arms and feet armour and relic slots, on a hero screen.', NULL, NULL, 'bullet', 29);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1307, 'Unity.Hare', 'U.HARE-US-R1', NULL, 'R', NULL, NULL, 'planned', '⬜', '', 'As a player, I can call a helper hawk that flies with me, picks up my drops and dies to a hit, like the original''s obj_helper', NULL, NULL, 'bullet', 60);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1308, 'Unity.Overworld', 'U.OVW-US-A31', NULL, 'A', NULL, NULL, 'planned', '⬜', '', 'As a player, I can choose the Belmont or girl sprite pack for a hero (the original''s unused stand, walk, run, jump, dash, kneel and attack sets), kept as selectable art with the facings the engine uses.', NULL, NULL, 'bullet', 30);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1309, 'Unity.Overworld', 'U.OVW-US-A32', NULL, 'A', NULL, NULL, 'planned', '⬜', '', 'As the owner, the original''s unfinished hooks exist as defined seams so nothing in the original is dropped: the five spell schools and the Flame spell behind the Skill ring entry, the cutscene record, the Mechanical enemy class and the Teleporting, Stationary and Swimming motions, and the Item_Textures table.', NULL, NULL, 'bullet', 31);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1310, 'Unity.Hare', 'U.HARE-US-R2', NULL, 'R', NULL, NULL, 'planned', '⬜', '', 'As a player, I can set off the flashbomb that flashes the screen and blows up the enemies and shots around me, like the original', NULL, NULL, 'bullet', 61);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1311, 'Unity.Overworld', 'U.OVW-US-A33', NULL, 'A', NULL, NULL, 'planned', '⬜', '', 'As the owner, the finished game is verified end to end by a scripted run that plays every mechanic against RECONSTRUCTION.md and captures screenshots, with the Windows build launching, so the repo can be called a complete proof of concept of the original.', NULL, NULL, 'bullet', 32);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1312, 'Unity.Chain', 'U.CHN-US-G9', NULL, 'G', NULL, NULL, 'done', '✅', '', 'As a player, I can shake the screen, so that the original''s shake key works', NULL, NULL, 'bullet', 24);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1313, 'Unity.Hare', 'U.HARE-US-R3', NULL, 'R', NULL, NULL, 'planned', '⬜', '', 'As a player, I fight Scrap Mental, the level 8 boss that shoots, spawns saws and daggers and sheds its hull pieces, and I win the level by destroying it', NULL, NULL, 'bullet', 62);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1314, 'Unity.Hare', 'U.HARE-US-O13', NULL, 'O', NULL, NULL, 'planned', '⬜', '', 'As a player, I can see who made the music and sound effects I hear, as the original''s licences require', NULL, NULL, 'bullet', 63);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1315, 'Unity.Hare', 'U.HARE-US-S1', NULL, 'S', NULL, NULL, 'planned', '⬜', '', 'As a developer, the game is verified by play: PlayMode tests and a scripted run drive the real game and capture screenshots of every room', NULL, NULL, 'bullet', 64);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1316, 'Unity.Chain', 'U.CHN-US-D1', NULL, 'D', NULL, NULL, 'done', '✅', '', 'As a player, the HUD shows what the original showed in the same places, so that the screen reads the same', NULL, NULL, 'bullet', 25);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1317, 'Unity.Hare', 'U.HARE-US-S2', NULL, 'S', NULL, NULL, 'planned', '⬜', '', 'As a player, I can install and launch a polished Windows build with the right name, icon, resolution and settings, so the proof of concept is complete', NULL, NULL, 'bullet', 65);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1318, 'Unity.Chain', 'U.CHN-US-D2', NULL, 'D', NULL, NULL, 'done', '✅', '', 'As a player, I can tune resistance, gravity and spring live and see them, so that the chain''s feel can be changed as the original allowed', NULL, NULL, 'bullet', 26);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1319, 'Unity.Chain', 'U.CHN-US-D3', NULL, 'D', NULL, NULL, 'done', '✅', '', 'As a player, I can speed up and slow down the game, so that the original''s speed keys work', NULL, NULL, 'bullet', 27);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1320, 'Unity.Chain', 'U.CHN-US-D4', NULL, 'D', NULL, NULL, 'done', '✅', '', 'As a player, the screen shows how long this round has lasted, so that the original''s clock is there', NULL, NULL, 'bullet', 28);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1321, 'Unity.Chain', 'U.CHN-US-D5', NULL, 'D', NULL, NULL, 'done', '✅', '', 'As a player, pause and quit work as in the original', NULL, NULL, 'bullet', 29);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1322, 'Unity.Chain', 'U.CHN-US-D6', NULL, 'D', NULL, NULL, 'done', '✅', '', 'As a player, Tab opens the in-game menu panel, so that the original''s menu is there', NULL, NULL, 'bullet', 30);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1323, 'Unity.Chain', 'U.CHN-US-D7', NULL, 'D', NULL, NULL, 'done', '✅', '', 'As a developer, I can show the hit boxes and the render debug toggles, so that the original''s debug views exist', NULL, NULL, 'bullet', 31);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1324, 'Unity.Chain', 'U.CHN-US-D8', NULL, 'D', NULL, NULL, 'done', '✅', '', 'As a developer, I can move the camera with the numpad, so that the original''s debug camera works', NULL, NULL, 'bullet', 32);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1325, 'Unity.Chain', 'U.CHN-US-D9', NULL, 'D', NULL, NULL, 'done', '✅', '', 'As a player, a random loading picture shows while the game starts, so that start-up matches the original', NULL, NULL, 'bullet', 33);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1326, 'Unity.Chain', 'U.CHN-US-D10', NULL, 'D', NULL, NULL, 'done', '✅', '', 'As a player, I can change resolution, window mode and the volumes in a settings screen, so that the original''s configuration window exists', NULL, NULL, 'bullet', 34);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1327, 'Unity.Chain', 'U.CHN-US-C1', NULL, 'C', NULL, NULL, 'done', '✅', '', 'As a player, I can type scripts that change the game, so that the original''s scripting language exists', NULL, NULL, 'bullet', 35);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1328, 'Unity.Chain', 'U.CHN-US-C2', NULL, 'C', NULL, NULL, 'done', '✅', '', 'As a player, I can open the scripter console and type commands into it, so that scripts can be entered as in the original', NULL, NULL, 'bullet', 36);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1329, 'Unity.Chain', 'U.CHN-US-V1', NULL, 'V', NULL, NULL, 'done', '✅', '', 'As a player, I can host or join an online game on the shared Unity.Multiplayer kit, so that the game can be played online while local play is unchanged', NULL, NULL, 'bullet', 37);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1330, 'Unity.Chain', 'U.CHN-US-V2', NULL, 'V', NULL, NULL, 'done', '✅', '', 'As the owner, I can see the finished game working end to end, so that done is verified by play', NULL, NULL, 'bullet', 38);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1331, 'Unity.Chain', 'U.CHN-US-V3', NULL, 'V', NULL, NULL, 'done', '✅', '', 'As the owner, I can trust that nothing from the original is missing, so that the repo is a finished proof of concept', NULL, NULL, 'bullet', 39);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1332, 'Unity.ProjectVania', 'U.VAN-US-A1', NULL, 'A', NULL, NULL, 'done', '✅', '', 'As the owner, the rules live in an engine-free Core assembly (noEngineReferences, no UnityEngine) that steps at exactly 1/60 s with an accumulator, changes state only through commands carrying a player id that produce events, and is tested with dotnet test outside Unity, with Runtime, Editor and Tests as separate one-way asmdefs, so the original''s per-frame arithmetic is copied exactly and presentation never mutates the game (RECONSTRUCTION 0, 1, 2).', NULL, NULL, 'bullet', 0);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1333, 'Unity.ProjectVania', 'U.VAN-US-A2', NULL, 'A', NULL, NULL, 'done', '✅', '', 'As the owner, every tuning number, content definition and text is data validated on load behind a settings registry (the player constants of section 4.2, the 16 px grid and the bridge level, the animation table, the menu tree, the camera and console constants, the audio cue table, the segment definitions and the name list), so nothing is a magic number in behaviour and a test proves each file loads (RECONSTRUCTION 4.2, 5, 9, 13).', NULL, NULL, 'bullet', 1);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1334, 'Unity.ProjectVania', 'U.VAN-US-A3', NULL, 'A', NULL, NULL, 'planned', '⬜', '', 'As the owner, the project is a modern Unity 6 setup built in code: URP behind a pipeline-agnostic layer with a pixel-perfect 800x600 reference, the Input System, Unity.Shared profiles and settings, a scripted batch build and test entry point, a trimmed package manifest, and scenes and UI composed by a code-built bootstrap instead of hand-wired Inspector state (RECONSTRUCTION 0).', NULL, NULL, 'bullet', 2);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1335, 'Unity.ProjectVania', 'U.VAN-US-A4', NULL, 'A', NULL, NULL, 'done', '✅', '', 'As a player, my keyboard and Xbox pad do exactly what the original''s did in each game state (Play, MainMenu, Console, MapEditor): A/D move, S kneels, Space jumps on press, [ and ] or L1/R1 cycle players, Esc/Start the menu, tilde/Back the console, R resets, F12 fullscreen, U the quick bar, C the camera mode, M or middle mouse the editor, the scroll, zoom and rotate keys, and the wheel zoom, with the original''s edge and hold semantics (RECONSTRUCTION 3).', NULL, NULL, 'bullet', 3);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1336, 'Unity.ProjectVania', 'U.VAN-US-A5', NULL, 'A', NULL, NULL, 'planned', '⬜', '', 'As a player, the world is the original''s 118x75 grid of 16 px cells (Hard, Soft, Empty) with the starting bridge level (a full floor on row 30 and two full-height walls on columns 20 and 40) and the original''s floor, ceiling and horizontal collision queries, including the partial-wall rule, proven by Core tests that reproduce the original''s cell lookups (RECONSTRUCTION 5).', NULL, NULL, 'bullet', 4);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1337, 'Unity.ProjectVania', 'U.VAN-US-A6', NULL, 'A', NULL, NULL, 'planned', '⬜', '', 'As a player, my character runs to a steady 116 px/s on the ground and 130 px/s in the air, jumps a full fixed curve of about 76 px that releasing the key does not shorten, falls under 10 per frame to 500, kneels on a terminal-speed landing, slides out of a run, wall slides at 83 px/s, wall jumps and drops after one idle second on a wall, all as the original''s per-frame state machine, proven by Core tests that replay traced frame sequences (RECONSTRUCTION 4.2-4.7, 4.9).', NULL, NULL, 'bullet', 5);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1338, 'Unity.ProjectVania', 'U.VAN-US-A7', NULL, 'A', NULL, NULL, 'planned', '⬜', '', 'As a player, I see the original''s characters animated from their sprite sheets (Morris with idle, run, jump, fall, wall slide, kneel and slide; Shanoa and Leo with idle and run) at the original frame times, drawn at a bottom-centre origin and flipped by facing and wall jump, with a random name from the original name list drawn over each player in red and yellow, and two players of whom [ and ] choose the driven one (RECONSTRUCTION 4.1, 4.8).', NULL, NULL, 'bullet', 6);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1339, 'Unity.ProjectVania', 'U.VAN-US-A8', NULL, 'A', NULL, NULL, 'planned', '⬜', '', 'As a player, I see the painted mountain-farmhouse backdrop at its original size, the white map outline, and every Hard cell drawn from the tileset at its source rectangle, with every cell visible while the editor is open, drawn on the CornflowerBlue clear colour in the original''s order of outline, layers, then cells (RECONSTRUCTION 5, 6).', NULL, NULL, 'bullet', 7);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1340, 'Unity.ProjectVania', 'U.VAN-US-A9', NULL, 'A', NULL, NULL, 'planned', '⬜', '', 'As a player, the camera eases toward the current player in Loose mode with the original''s 0.02 pull and 0.7 damping, can be locked to the player, follow the editor cursor, or run free (C cycles them), clamps its centre to the map, and responds to the scroll, zoom (scale cubed) and rotate keys and the wheel exactly as the original''s (RECONSTRUCTION 7).', NULL, NULL, 'bullet', 8);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1341, 'Unity.ProjectVania', 'U.VAN-US-A10', NULL, 'A', NULL, NULL, 'planned', '⬜', '', 'As a player, Esc opens the original''s three-level main menu (Game, Video with Toggle Fullscreen, Audio, Controls, Quit) over a darkened screen with its arrow indicator, titles, descriptions, wrap-around navigation and sounds, the world freezes while it is open, and Quit exits, with the game states Play, MainMenu, Console and MapEditor changing as the table in RECONSTRUCTION 2 says.', NULL, NULL, 'bullet', 9);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1342, 'Unity.ProjectVania', 'U.VAN-US-A11', NULL, 'A', NULL, NULL, 'planned', '⬜', '', 'As a player, the tilde key slides a 200 px console down over the world with its blinking prompt, 100-line history, command recall and typed-key rules, and runs the original''s script language (say, yell, fade, play music, play battle, msg hi, exit, version, pause, mute, lee, console clear/full/text/history/bg and the colour parameters) with no crash on a short command (RECONSTRUCTION 10).', NULL, NULL, 'bullet', 10);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1343, 'Unity.ProjectVania', 'U.VAN-US-A12', NULL, 'A', NULL, NULL, 'planned', '⬜', '', 'As a player, the original''s HUD is always drawn: the portrait frame and quick bar (U slides it), the falling and fading message stack with its six start-up messages and the gamepad notice, the full-screen fade lens driven by the fade commands, and the debug readout of player, camera, cursor, selected cell and frame rate at the original positions (RECONSTRUCTION 9.1).', NULL, NULL, 'bullet', 11);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1344, 'Unity.ProjectVania', 'U.VAN-US-A13', NULL, 'A', NULL, NULL, 'planned', '⬜', '', 'As a player, I hear the original''s sounds from a cue table: the menu and console ambience cues, the run step and wall-slide drag cues (throttled to once per animation frame and per clip), and the two songs started only by the console, with mute and pause working, and the unplayed footstep, step1, jump1 and music1 cues kept in the table (RECONSTRUCTION 11).', NULL, NULL, 'bullet', 12);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1345, 'Unity.ProjectVania', 'U.VAN-US-A14', NULL, 'A', NULL, NULL, 'planned', '⬜', '', 'As a player, M or the middle mouse button opens the map editor: the camera becomes a mouse-look joystick over a cursor, left click paints a Hard cell from the selected palette tile, right click erases it, the highlight tints the cell under the cursor, a player can be dragged with the mouse, and holding Space switches to the palette cursor to pick a tile, with no painting outside the grid (RECONSTRUCTION 8, 12).', NULL, NULL, 'bullet', 13);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1346, 'Unity.ProjectVania', 'U.VAN-US-A15', NULL, 'A', NULL, NULL, 'planned', '⬜', '', 'As a player, the world draws through the original''s filter effect (a mild vignette) and the other four shaders (bloom, negative, pause, water) exist as selectable post-process presets that nothing enables, as in the original (RECONSTRUCTION 6.1).', NULL, NULL, 'bullet', 14);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1347, 'Unity.ProjectVania', 'U.VAN-US-A16', NULL, 'A', NULL, NULL, 'done', '✅', '', 'As the owner, everything the original built but never wired is kept as data and inert behaviour (the eleven segment definitions and the segment atlas, the 16 ledge slots, the Sun day-night cycle, the action cross, the seven portraits, the skill icons, the five area layers, the particle, selector, banner and sprite-sheet art, the Shanoa, Leo and Richter art), so the rebuild loses nothing the original contained (RECONSTRUCTION 5.1, 9.1, 13, 15).', NULL, NULL, 'bullet', 15);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1348, 'Unity.ProjectVania', 'U.VAN-US-A17', NULL, 'A', NULL, NULL, 'done', '✅', '', 'As the owner, every sprite, texture, sound, font and data file the original loaded is in the rebuild, proven by a test that diffs the original''s live asset list (RECONSTRUCTION 13) against the rebuild''s content registry, with the poisondart and consecrate icons imported as their own files.', NULL, NULL, 'bullet', 16);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1349, 'Unity.ProjectVania', 'U.VAN-US-A18', NULL, 'A', NULL, NULL, 'done', '✅', '', 'As the owner, the finished game is verified end to end by a scripted run that plays every state and mechanic of the original (run, jump, kneel, slide, wall slide, wall jump, camera modes, menu, console commands, editor painting, audio) and captures screenshots, settles the two kept-pending behaviours (kneel release, wall jump push-off), and compares them with RECONSTRUCTION, so the repo can be called a complete proof of concept of the original.', NULL, NULL, 'bullet', 17);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (1350, 'Unity.Hare', 'U.HARE-US-C4', NULL, 'C', NULL, NULL, 'done', '✅', '', 'As a player, my ship carries its weapons in play: the vulcan, shotgun, flamer and mine launcher, the perched laser and railgun and the air rocket loadout are added to the player ship (prefab or scene) with their ground and air loadouts, so every weapon fires in the running game', NULL, NULL, 'bullet', 66);
INSERT INTO backlog_items (uid, repo, ordinal, text) VALUES (1, 'ChiMesh', 19, '1. **CM-US-A1/A2** — order parts, assemble three nodes (gates everything physical).');
INSERT INTO backlog_items (uid, repo, ordinal, text) VALUES (2, 'ChiMesh', 20, '2. **CM-US-B1 → B2 → B3** — flash, provision identically, healthcheck each node before it leaves the bench.');
INSERT INTO backlog_items (uid, repo, ordinal, text) VALUES (3, 'ChiMesh', 21, '3. **CM-US-C1** — physical placement that forces an indirect link.');
INSERT INTO backlog_items (uid, repo, ordinal, text) VALUES (4, 'ChiMesh', 22, '4. **CM-US-C2** — the proof: capture `A → via B → C`.');
INSERT INTO backlog_items (uid, repo, ordinal, text) VALUES (5, 'ChiMesh', 23, '5. Secured channel PSK ([RFC 0001](rfc/0001-secured-channel-psk.md)) before any non-test deployment.');
INSERT INTO backlog_items (uid, repo, ordinal, text) VALUES (6, 'ChiMesh', 24, '6. Winter power-margin upgrade (second cell / 5 W panel) for any node overwintering unattended.');
INSERT INTO backlog_items (uid, repo, ordinal, text) VALUES (7, 'Claudia', 26, '1. **CLA-US-B3** — on-hardware I²C detection of the WonderEcho (unblocks C3/C4).');
INSERT INTO backlog_items (uid, repo, ordinal, text) VALUES (8, 'Claudia', 27, '2. **CLA-US-C3 / CLA-US-C4** — verified wake→Claude→speak round trip, local-only path.');
INSERT INTO backlog_items (uid, repo, ordinal, text) VALUES (9, 'Claudia', 28, '3. **CLA-US-D1 / CLA-US-D2** — healthcheck + boot service proven on a real Pi.');
INSERT INTO backlog_items (uid, repo, ordinal, text) VALUES (10, 'Claudia', 29, '4. Confirm the WonderEcho `0x52` address and `0x10` set-trigger opcode against shipping firmware, then drop the caveat where confirmed ([CLA-LAW-5](BIBLE.md#CLA-LAW-5)).');
INSERT INTO backlog_items (uid, repo, ordinal, text) VALUES (11, 'Cursory', 39, '1. 🟡 **CUR-US-F1** — start the stopped `cursory` App Service (unblocks a real shared URL).');
INSERT INTO backlog_items (uid, repo, ordinal, text) VALUES (12, 'Cursory', 40, '2. ⬜ Per-room state persistence (so a restart doesn''t wipe progress) — prerequisite for lobbies.');
INSERT INTO backlog_items (uid, repo, ordinal, text) VALUES (13, 'Cursory', 41, '3. ⬜ Multiple rooms / a lobby (depends on persistence).');
INSERT INTO backlog_items (uid, repo, ordinal, text) VALUES (14, 'Cursory', 42, '4. ⬜ Stand up an automated browser gate for Epic E so it can graduate from 🟡 → ✅.');
INSERT INTO backlog_items (uid, repo, ordinal, text) VALUES (15, 'Cursory', 43, '5. 🟡 Adopt `MindAttic.Authentication` ([HOUSE-LAW-7]; deviation [CUR-LAW-9](BIBLE.md#CUR-LAW-9)).');
