INSERT INTO backlog_items (uid, repo, ordinal, text) VALUES (18, 'IdiotProof', 129, '0. **IP-US-K6/K7/K9** — host-level MonitorWorker test (mock gap day: queue → 4AM fire → hold → rollover sell before 9:30), `/gapper` Cypress spec, two-instance leader-lease test.');
INSERT INTO backlog_items (uid, repo, ordinal, text) VALUES (19, 'IdiotProof', 130, '1. **Cypress run (IP-US-E1–E6, Epic I, Epic J, IP-US-T7)** — start the server with `IDIOTPROOF_FAKE_LLM=1`, run `npm run cypress:run`, and graduate the stories the specs prove; add specs for `/learn`, `/research` and `/gapper`.');
INSERT INTO backlog_items (uid, repo, ordinal, text) VALUES (20, 'IdiotProof', 131, '2. **Epic R tests** — NUnit coverage for replay, scan, export and the strategy families.');
INSERT INTO backlog_items (uid, repo, ordinal, text) VALUES (21, 'IdiotProof', 132, '3. **IP-US-U10** — fill-and-close half of the real paper options round-trip, in market hours.');
INSERT INTO backlog_items (uid, repo, ordinal, text) VALUES (22, 'IdiotProof', 133, '4. **Epic G (IP-US-G1…G4)** — Strategy ghost overlay + branching visualization: chart integration, simulator evaluation timeline, branch-fork rendering, scrub/playback.');
INSERT INTO backlog_items (uid, repo, ordinal, text) VALUES (23, 'IdiotProof', 134, '5. **IP-US-H1** — Roslyn-based IdiotScript parser: exact line/col diagnostics replacing the regex parser.');
INSERT INTO backlog_items (uid, repo, ordinal, text) VALUES (24, 'IdiotProof', 135, '6. **Epic S** — adaptive auto-strategy generation.');
INSERT INTO backlog_items (uid, repo, ordinal, text) VALUES (25, 'MediaButler', 54, '1. **MB-US-F1** — add a mocked/recorded Legion test so the LLM fallback can graduate to ✅ (see [docs/rfc/0001-llm-fallback-test-strategy.md](rfc/0001-llm-fallback-test-strategy.md)).');
INSERT INTO backlog_items (uid, repo, ordinal, text) VALUES (26, 'MediaButler', 55, '2. **MB-US-G1** — wire a CI/desktop runner that executes `WpfAppSmokeTests` and `MediaButler.Wpf.AccessibilityTests`, promoting the shell to ✅.');
INSERT INTO backlog_items (uid, repo, ordinal, text) VALUES (27, 'MediaButler', 56, '3. Live-integration harness for FileBot + OpenSubtitles (currently arg-construction tests only).');
INSERT INTO backlog_items (uid, repo, ordinal, text) VALUES (28, 'MediaButler', 57, '4. Expand `TitleYearOverrides` coverage as new year-in-title releases appear.');
INSERT INTO backlog_items (uid, repo, ordinal, text) VALUES (29, 'MindAttic.Authentication', 40, '1. ⬜ **M.AUTH-US-G5** — Add a fail-closed `IStartupFilter` that asserts middleware order, with an integration test. (hardens G2)');
INSERT INTO backlog_items (uid, repo, ordinal, text) VALUES (30, 'MindAttic.Authentication', 41, '2. ⬜ **M.AUTH-US-F3** — Provisioning CLI emitting CSPRNG pepper/KEK/reset-key (see [RFC 0001](rfc/0001-provisioning-cli.md)). (depends on B1/B2)');
