INSERT INTO backlog_items (uid, repo, ordinal, text) VALUES (58, 'OpenCredentials', 31, '1. ⬜ **Non-retention test** proving `Scraper.Fingerprint`/`ScanContent` emit only fingerprints (OC-US-A2 → ✅).');
