INSERT INTO backlog_items (uid, repo, ordinal, text) VALUES (75, 'ThinkTank', 37, '3. **⬜ Auto-vote after N rounds** — see RFC [0001](rfc/0001-auto-vote-after-n-rounds.md); graduates into [TT-§7](BIBLE.md#TT-§7) and a new Epic C story.');
INSERT INTO backlog_items (uid, repo, ordinal, text) VALUES (76, 'ThinkTank', 38, '4. **⬜ Title generation** verification (currently background UI logic, untested in the unit run).');
INSERT INTO backlog_items (uid, repo, ordinal, text) VALUES (77, 'ThinkTank', 39, '5. **⬜ Provider connectivity polling** assertion.');
INSERT INTO backlog_items (uid, repo, ordinal, text) VALUES (78, 'Tutor', 55, '1. **TUT-US-F1** — fix the compile errors and record a green `Tutor.Tests` run; that promotes D1–D6, E2, E4 and E6 to ✅.');
INSERT INTO backlog_items (uid, repo, ordinal, text) VALUES (79, 'Tutor', 56, '2. **TUT-US-E1 / E3 / E5** — automated UI coverage for `/library`.');
