INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('CM-T12', 'ChiMesh', 12, '2026-10-21', 'fix', 'closed', 'ChiMesh.Console provision/healthcheck pass -Region/-Role/-Channel/-Port through array splatting, which binds them positionally: ''provision chimesh-001 -Region EU_868'' fails with PositionalParameterNotFound', 'dbebd82', 11, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('CM-T13', 'ChiMesh', 13, '2026-10-21', 'fix', 'closed', 'Native-command stderr under ErrorActionPreference=Stop throws NativeCommandError in PS 5.1: provision-node dies instead of its no-node message / reboot retry loop, healthcheck (via console) and pull-latest''s no-upstream check likewise', 'cb96372', 12, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('CM-T14', 'ChiMesh', 14, '2026-10-21', 'fix', 'closed', 'pull-latest stages a clone of the local repo and resets to its origin (= the local repo itself), so the overlay copies the old tree and never updates anything', '749a892', 13, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('CM-T15', 'ChiMesh', 15, '2026-10-21', 'fix', 'closed', 'ChiMesh.Console exits 0 even when provision/healthcheck fail, so the .bat failure path never fires and a failed healthcheck reports success', 'b6465ab', 14, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('CM-T16', 'ChiMesh', 16, '2026-10-21', 'fix', 'closed', 'Typing an unknown command in the ChiMesh.Console interactive menu calls exit 2 and kills the whole console instead of reprompting', 'd4a2190', 15, NULL);
