INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('CM-T21', 'ChiMesh', 21, '2026-10-21', 'fix', 'open', 'pull-latest overlays files with robocopy but never moves HEAD (and never deletes files removed upstream), so after a successful update every changed file shows as a local modification and the next pull-latest reports ''behind N'' + ''dirty'' and needs --force; needs a design call (ff-only merge in the finisher vs. reset --mixed vs. keep overlay)', '—', 20, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('CM-T22', 'ChiMesh', 22, '2026-10-21', 'fix', 'closed', 'ChiMesh.Console.bat (root and scripts/cli) are LF-only with a UTF-8 em dash; under a UTF-8 (65001) console cmd.exe misparses them (''M''/''etlocal''/''owershell.exe'' not recognized) and the console never launches; check them out CRLF and keep them ASCII', 'fea8981', 21, NULL);
