INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.EZ-T27', 'GTFO.EZ', 27, '2026-10-16', 'chore', 'closed', 'Run the full unit test suite and fix every failure (each under its own fix ticket) until it passes; put the passing run in --ref. No test project: close this wont-do saying so', 'dotnet test tests/GTFO.EZ.Core.Tests/GTFO.EZ.Core.Tests.csproj: 29/29 passed, 0.586s, 2026-10-17 (no failures, no code changes needed)', 26, NULL);
