INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T62', 'GTFO.EZ.AbsurdWeapons', 62, '2026-10-17', 'fix', 'closed', 'Thrown Mjolnir is yawed partly to the left: orient it from its meshes'' own axes - handle along the spin plane''s up, head facing the flight direction - instead of a model-space bounding box that only fixed the handle', 'G.AWPN-T82', 61, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T63', 'GTFO.EZ.AbsurdWeapons', 63, '2026-10-17', 'fix', 'closed', 'Laser guns (and Chain Lightning) still play the gun''s rapid-fire audio when the trigger is held: suppress the vanilla fire audio for the trigger-driven guns too, leaving only the beam/lightning loop', 'G.AWPN-T82', 62, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T64', 'GTFO.EZ.AbsurdWeapons', 64, '2026-10-17', 'feature', 'closed', 'Hive Pistol/Rifle back to the original behaviour (reverting T50/T59''s firing): full-auto, instant locks on up to 6 enemies within 35 deg / 60 m that every round curves onto in turn, unlocked rounds hunt the nearest enemy; 1 damage, 0.09 s, 30 rounds - keeping T50''s lock-on markers as the visual', 'G.AWPN-T82', 63, NULL);
