INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T69', 'GTFO.EZ.AbsurdWeapons', 69, '2026-10-17', 'feature', 'closed', 'Victory Banner: held as the flag itself (the C-Foam launcher''s model hidden), and planted (or picked up) the instant fire is pressed - no pressure charge-up', 'G.AWPN-T82', 68, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T70', 'GTFO.EZ.AbsurdWeapons', 70, '2026-10-17', 'feature', 'closed', 'Warhammer: a fully charged swing always slams the ground in front of you at its hit moment - shockwave, knockback, dust and flash - even when it hits no enemy (a hit''s own shockwave counts as the slam, no double)', 'G.AWPN-T82', 69, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T71', 'GTFO.EZ.AbsurdWeapons', 71, '2026-10-17', 'fix', 'closed', 'Laser Pistol/Rifle kick when fired (T65 let them fire for the hip raise): give them a hold that never relaxes (always at hip height) and plays no recoil animation, and stop them firing again - no kickback at all', 'G.AWPN-T82', 70, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T72', 'GTFO.EZ.AbsurdWeapons', 72, '2026-10-17', 'fix', 'closed', 'Tentacle Cannon tentacles start too far back (5 cm behind the muzzle, inside the gun): start them out past the barrel''s end (0.3 m, configurable) so they visibly come out of it', 'G.AWPN-T82', 71, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T73', 'GTFO.EZ.AbsurdWeapons', 73, '2026-10-17', 'feature', 'closed', 'Victory Banner places like a sentry: fire puts it down (and you switch to your main weapon), and you pick it back up by walking up to it and pressing Use with an on-screen prompt - not by firing again from anywhere', 'G.AWPN-T82', 72, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T74', 'GTFO.EZ.AbsurdWeapons', 74, '2026-10-17', 'feature', 'closed', 'Katana''s swing at the end of its dash plays twice as fast (charged-attack timings halved in its own animation set, animation sped up to match)', 'G.AWPN-T82', 73, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T75', 'GTFO.EZ.AbsurdWeapons', 75, '2026-10-17', 'fix', 'closed', 'Grenade Pistol is in the special slot and Grenade Rifle in the main slot (the Arid 5 is a special-slot gun, the J 300 a main-slot one): put the Grenade Pistol on the Bataldo 3RB revolver (main) and the Grenade Rifle on the TechMan Veruta XII (special)', 'G.AWPN-T82', 74, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T76', 'GTFO.EZ.AbsurdWeapons', 76, '2026-10-17', 'feature', 'closed', 'Tentacle Cannon held very low like a minigun, and with no enemy in reach its tentacles wriggle tightly a few metres out in the narrow cone; only an enemy in reach makes them reach out (and curve) to it', 'G.AWPN-T82', 75, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T77', 'GTFO.EZ.AbsurdWeapons', 77, '2026-10-17', 'feature', 'closed', 'Tentacle Cannon bites do twice the damage (11 -> 22 a tentacle); enemies'' own tentacles unchanged', 'G.AWPN-T82', 76, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T78', 'GTFO.EZ.AbsurdWeapons', 78, '2026-10-17', 'feature', 'closed', 'Katana''s blade 33% longer (BladeLength 5.2 -> 6.9, ~1.85 m) with reach to match (3.0 -> 3.5 m)', 'G.AWPN-T82', 77, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T79', 'GTFO.EZ.AbsurdWeapons', 79, '2026-10-17', 'fix', 'closed', 'Laser guns still kick: the weapon archetype''s own trigger logic (Update / OnFireShot) runs the gun''s firing, fire animation and recoil before Fire - skip it entirely for the lasers, whose beam is trigger-driven anyway', 'G.AWPN-T82', 78, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T80', 'GTFO.EZ.AbsurdWeapons', 80, '2026-10-17', 'feature', 'closed', 'Laser Rifle on a model without animated parts: the Accrat ND6 instead of the Drekker DEL P1', 'G.AWPN-T82', 79, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T81', 'GTFO.EZ.AbsurdWeapons', 81, '2026-10-17', 'fix', 'closed', 'Laser guns have no audible continuous sound (the torch loop played at the beam''s far end): a continuous beam loop - the freeze thrower''s emitter loop, FREEZERLOOP / FREEZERLOOPEND - played at the gun while the trigger is held', 'G.AWPN-T82', 80, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T82', 'GTFO.EZ.AbsurdWeapons', 82, '2026-10-17', 'feature', 'closed', 'Weapon rework session: bug-hunt fixes (C-Foam stagger pulse, afterburn crash/stacking, banner buff TryCast, Hive MaxLocks 0); Hand Grenade consumable; removed Tanto, Wakizashi, Odachi, Yari, Gravity Hammer, C-Foam guns, Flak Cannon, Flamethrower, Tentacle Pistol; Grenade Pistol/Rifle guns; trigger-driven laser and chain-lightning streams; per-weapon sounds; design pass (Railgun, Plasma, grenades); Katana dash/hold/length, Mjolnir throw, Warhammer slam, Victory Banner flag/aura/sentry placement, Tentacle Cannon rework (T25-T81, minus the T43 spike)', 'docs/design/weapon-references.md', 81, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T83', 'GTFO.EZ.AbsurdWeapons', 83, '2026-10-17', 'fix', 'closed', 'Laser Rifle was in the main slot (Accrat ND6/SMGHeavyAuto is a main-slot SMG in vanilla): force its gear category''s BaseItem to the special slot''s item so it lands in the special slot', 'G.AWPN-T82', 82, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T84', 'GTFO.EZ.AbsurdWeapons', 84, '2026-10-17', 'fix', 'closed', 'Chain Lightning bolt spawn point pushed further forward (was starting inside the gun model) and its archetype trigger logic now skipped the same way the laser guns'' is, so hip fire actually activates the stream', 'G.AWPN-T82', 83, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T85', 'GTFO.EZ.AbsurdWeapons', 85, '2026-10-17', 'feature', 'closed', 'Railgun beam: fewer helix coils (TurnLength 1.2 -> 2.4), and the core/strands green-tinted and semi-transparent (lower base alpha, not just the time fade)', 'G.AWPN-T82', 84, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T86', 'GTFO.EZ.AbsurdWeapons', 86, '2026-10-17', 'feature', 'closed', 'Tentacle Cannon spew randomized further: ~20% of tentacles (WideSpewChance) fire in a much wider cone (WideSpewConeDegrees) instead of the tight forward one, and each tentacle''s start point is jittered to its own angle below the barrel (StartJitterDegrees/Radius) instead of all sharing one spot', 'G.AWPN-T82', 85, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T87', 'GTFO.EZ.AbsurdWeapons', 87, '2026-10-17', 'feature', 'closed', 'Rocket Launcher: Quake 1/Doom-faithful rocket - instant trigger, no-gravity straight flight to the first enemy/wall hit, same explosion code as the Grenade Launcher, trailing smoke and sparks', '—', 86, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T88', 'GTFO.EZ.AbsurdWeapons', 88, '2026-10-17', 'feature', 'closed', 'Weapon rework session 2: Chain Lightning as a persistent barrel-fed stream (sway/narrowing per jump, sustained-contact chaining); Railgun''s rail trail rebuilt to Quake 3''s own CG_RailTrail puff spiral; Tentacle Cannon reworked to twelve fixed spawn spots with mixed striker/big-striker/tank types; Shadow Dagger stealth as true per-renderer transparency tied to time left, plus a held pulsing glow; Victory Banner trimmed to heal-only with a floor-anchored plant point; Hand Grenade as the only loot consumable; continuous laser beam kept lit between damage ticks; Plasma Pistol/Rifle low hold and splash sparks/flash-intensity; special-slot gear-JSON component fix; a shared LockDamage helper wired into every weapon''s blast/beam/lash path so none of them skip door locks; a one-time config-default migration helper', '—', 87, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T89', 'GTFO.EZ.AbsurdWeapons', 89, '2026-10-17', 'chore', 'wont-do', 'Find a real rocket/missile-shaped asset in GTFO''s game data for the Rocket Launcher''s projectile, replacing the hand-built capsule-and-tip placeholder (RocketLauncher.cs BuildModel). GTFO''s AssetShardManager loads from downloaded asset bundles, not plain files on disk - static searching under the Steam install and LocalLow folders found only Wwise sound banks, so this needs a runtime diagnostic (e.g. a temporary Harmony hook or log dump of loaded asset paths) while the game is actually running, to find candidate prefabs (tool rockets, mortar shells, flare casings, etc.) worth borrowing the way the Grenade Launcher borrows the lock melter''s mesh', 'Obsolete: G.AWPN-T183 (1112a5a) replaced the hand-built rocket model with an orange fireball on purpose, so no rocket mesh is wanted (user decision 2026-10-20)', 88, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T90', 'GTFO.EZ.AbsurdWeapons', 90, '2026-10-18', 'feature', 'closed', 'Weapon rework session 3: Railgun''s Quake 3 rail-trail rework reverted back to the simpler green-tinted helix (new look was bad), keeping the door-lock hit added since; Rocket Launcher''s smoke trail swapped for a shower of falling sparks and its blast now hurts nearby players too (the game''s own DamageUtil.DoExplosionDamage, Quake/Doom style); Hand Grenade thrown twice as hard and its dropped/loot model reskinned to the lock melter too (ItemInLevel.Setup, not just the held/thrown GlowstickInstance); Shadow Dagger''s glow cut to a whisper (10x too bright before), its stealth tint changed from white to the dagger''s own purple and made more transparent, and its timing rebalanced to a 2s base stealth + 0.5s per kill; Chain Lightning reverted to its original instant-chain, independent-jagged-bolt feel (keeping the barrel-spawn and door-lock fixes), its persistent swaying-tether stream visual reused, recolored green, for a new special-slot weapon - the Shrink Beam (Omneco exp1 model): a continuous ray that shrinks whatever it''s held on, smaller and slower by the same share, until it pops, growing back if the beam leaves it for over a second; and none of the trigger-driven beams (lasers, Chain Lightning, Shrink Beam) can fire anymore while sprinting or before the weapon settles into its aim pose', '—', 89, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T91', 'GTFO.EZ.AbsurdWeapons', 91, '2026-10-18', 'fix', 'closed', 'Tentacle Cannon dealt zero damage: it''s the only gun built on a ShotgunRanged archetype, and GTFO''s Shotgun-class pellet path hands weaponRayData.damage back as 0 for it (the same pellet path that already loses the hit''s owner, per the existing fallback comment) - read the configured TentacleDamage value directly instead of trusting that field. Added bite logging (the struck limb''s health immediately before/after, throttled) so the fix - and any future regression - shows concrete proof in the console rather than a guess. Corrected the damage value itself to 25 (it had been bumped to 100 then 200 while chasing the zero-damage report before the real cause was found), with a config migration for anyone who already has the shipped 100 default', '—', 90, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T92', 'GTFO.EZ.AbsurdWeapons', 92, '2026-10-18', 'feature', 'closed', 'Weapon rework session 4: Rocket Launcher''s risky player-damage call (an unverified DamageUtil.DoExplosionDamage guess, prime suspect for a screen-blinding black-box bug a player hit) removed - enemies-only again - and its smoke trail replaced with the game''s own concrete-impact dust puff instead of a hand-rolled sphere; Shadow Dagger now flickers between its purple tint and fully visible, faster and faster, in the last second of stealth before it ends, and its per-kill time bonus halved again to 0.25s; Shrink Beam''s start now re-locks to the gun''s barrel every frame instead of only on shrink ticks, enemies under 25% size pop automatically (was 33%) and under 40% size (was 50%) pop just from a player getting within a widened 0.6 m (was 0.3 m) of them - stepped on; Warhammer''s ground slam scatters 8 debris/scorch bursts across a 1.5 m radius instead of one small point, a crater instead of a bullet hole', '—', 91, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T93', 'GTFO.EZ.AbsurdWeapons', 93, '2026-10-18', 'chore', 'wont-do', 'Research: how to split the Hand Grenade out of GTFO.AbsurdWeapons into its own mod (repo mindattic/GTFO.AbsurdWeapons.HandGrenade, already created empty) without duplicating code. Known so far: HandGrenade.cs (407 lines) leans on helpers other weapons also use - Explosion.Show and LauncherGrenade.BuildModel (GrenadeLauncher.cs; also RocketLauncher), AreaDamage.Apply (ImpactBursts.cs; 5 users), Formulas.GrenadeFlashInterval (Pure/Formulas.cs; 11 users), Sounds.PlayLimited + grenade sound config (Sounds.cs; 8 users), DataBlocks.Clone/DisplayName. Decide: does the new mod own those helpers publicly with AbsurdWeapons hard-depending on it, or does a shared core lib hold them; how AbsurdWeapons overrides stack 5 -> 99 + infinite-on-pickup (public API it sets after load vs config); load order vs GTFO.EZ (AbsurdWeapons soft-depends on MindAttic.GTFO.EZ today); new repo''s project code, build.ps1/package/manifest, commit hooks and wip topic (clone-repo.ps1)', 'Superseded: Hand Grenade moved to GTFO.EZ.AbsurdItems instead (G.AWPN-T148, GAI-T3)', 92, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T94', 'GTFO.EZ.AbsurdWeapons', 94, '2026-10-18', 'feature', 'wont-do', 'Migrate the Hand Grenade into the standalone mod GTFO.AbsurdWeapons.HandGrenade per the research ticket''s decision: standalone it''s the only loot consumable (med/ammo/tool kits untouched), counts down normally, max 5 carried per player; with GTFO.AbsurdWeapons installed it allows 99 and picking one up makes it infinite, and AbsurdWeapons drops its own HandGrenade.cs instead of duplicating it', 'Superseded: Hand Grenade moved to GTFO.EZ.AbsurdItems instead (G.AWPN-T148, GAI-T3)', 93, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T95', 'GTFO.EZ.AbsurdWeapons', 95, '2026-10-18', 'feature', 'closed', 'Rocket Launcher: restored the player-splash-damage call (DamageUtil.DoExplosionDamage) removed last session as an unconfirmed precaution against a screen-blinding bug report - there''s no simpler per-player damage API available (a player''s Dam_PlayerDamageBase only takes damage through Receive*Damage calls needing a hand-built native network packet, far riskier than this one static utility), and the user explicitly asked for it back: the blast should hurt the shooter, bots and other players too, same as any real explosion. Also fixed the gun''s in-game loadout description, which still said "trailing smoke" after the trail was switched to dust', '—', 94, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T96', 'GTFO.EZ.AbsurdWeapons', 96, '2026-10-18', 'docs', 'closed', 'v1 documentation pass: re-verified every weapon''s current behavior and config defaults directly against source (not assumption) and brought README.md, package/README.md, package/CHANGELOG.md, package/manifest.json and docs/design/weapon-references.md up to date. Corrected a long list of stale facts accumulated across this session''s reworks and reverts: weapon count (seventeen/twenty -> nineteen weapons, eleven -> thirteen guns), Tentacle Cannon''s damage/stagger and its whole spawn-spot system description, Chain Lightning and Grenade damage/timing numbers, Railgun''s helix pitch, Victory Banner''s fully-removed damage buff (several places still described it), Shadow Dagger''s stealth timing and new purple-tint/flicker visuals, Warhammer''s crater-sized debris, Hand Grenade''s throw force and loot-takeover and corrected claim that its pickup/loot model was unskinned. Added full entries for Rocket Launcher and Shrink Beam everywhere they were missing. manifest.json''s one-line description no longer describes a roster (Tanto to Odachi swords) that was removed earlier', '—', 95, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T97', 'GTFO.EZ.AbsurdWeapons', 97, '2026-10-18', 'fix', 'closed', 'HandGrenadeSupply.Give (give-on-drop) makes the game log ''Faulty replicator id incoming! 1203 <player>'' once per player when a level starts: PlayerBackpackManager.MasterAddItem gets a pItemData with no replicator. Seen in Player.log 2026-10-18 for GideonKain + bots Dauda/Hackett/Bishop (GTFO.EZ DEV profile)', 'Player.log 2026-10-18 02:56, stack PlayerBackpackManager.AddItem <- MasterAddItem', 96, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T98', 'GTFO.EZ.AbsurdWeapons', 98, '2026-10-18', 'feature', 'closed', 'Per-weapon Enabled toggle in the .cfg for all 19 weapons (melee, guns, Victory Banner, Hand Grenade)', '—', 97, NULL);
