INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T130', 'GTFO.EZ.AbsurdWeapons', 130, '2026-10-18', 'fix', 'closed', 'StimPack.cs:110-112 Dam_PlayerDamageLocal.Setup postfix clears the overheal for bot setups too (no IsBot/owner check): a bot taking a slot mid-level drops the overheal without restoring HealthMax, leaving max health raised for the level', 'b5d78f1', 129, NULL);
