INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T210', 'GTFO.EZ.AbsurdWeapons', 210, '2026-10-20', 'fix', 'closed', 'Barrel.Shot''s glancing-floor fix (b2b26e1) caps the glancing angle at ~6 deg, so it never stops short by more than ~1.65 m: at shallower angles (about 3 deg, a floor point ~27 m ahead from a 1.4 m barrel) the clearance sphere meets the floor ~3 m back and long flat corridor shots at the floor still leave from the eye. Measure against the floor''s actual height instead (a tested Formulas.ClearPathLength version exists unlanded on branch orch/g.awpn-t208, commit b95409e), keeping G.AWPN-T209''s close-enemy check', 'b981e6a (FormulasTests.ClearPathLength_ShallowCorridorFloorStopsWellBeforeTheSphereGrazesIt)', 209, NULL);
