INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('MAT-T30', 'MindAttic.Agency', 30, '2026-10-22', 'fix', 'closed', 'shared/docs-site/adopt-docs-site.ps1 names the docs site and GitHub repo after the folder it runs in, so run from an orchestrator worktree (D:\Projects\MindAttic.worktrees\<Repo>\<ticket>) it uses the ticket id (e.g. ''U.RON-T13'') as the repo name and its GitHub steps target the wrong repo; derive the repo from the git remote (origin URL) instead of the folder name, falling back to -Repo, with a test (found adopting UnityRonin''s docs site, U.RON-T13)', '6ce96e4', 29, NULL);
