INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('MAT-T56', 'MindAttic.Agency', 56, '2026-10-24', 'fix', 'closed', 'mindattic-agent-standard/prose-agent.ps1 (the workspace-root codex-standard copy every repo''s command pointers actually invoke) was never ported for MAT-T39''s .prose -> .agent rename: it still uses .prose as $stateDir, so /do, /quicksave, /quickload, /queue recreate a .prose folder in every repo even after MAT-T47 moved everything to .agent on disk. Port MAT-T39''s rename (new .agent state dir, one-time legacy .prose carry-over) into this copy, same root-repo gap pattern as MAT-T46/MAT-T48', '72007a6 (mindattic-agent-standard/prose-agent.ps1, codex-standard repo)', 55, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('MAT-T57', 'MindAttic.Agency', 57, '2026-10-24', 'fix', 'closed', 'mindattic-agent-standard/install.ps1 (the workspace-root codex-standard copy README.md tells users to run directly) also never got MAT-T39''s .prose -> .agent rename: it still creates .prose\commands and has no Move-LegacyAgentFolder step, so running it fresh would recreate .prose in every repo. Port the migration function and .agent command dir from the canonical install.ps1, and fix README.md''s stale .prose/commands and .prose-folder-naming references in this repo, same gap pattern as MAT-T56', '8269358 (mindattic-agent-standard/install.ps1 + README.md, codex-standard repo)', 56, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('MAT-T58', 'MindAttic.Agency', 58, '2026-10-25', 'docs', 'closed', 'Global agent rules in mindattic-agent-standard/AGENTS.md: every user request is a ticket filed before any work, and every agent message names the ticket ID and title it refers to', '—', 57, NULL);
