INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('MAT-T60', 'MindAttic.Agency', 60, '2026-10-26', 'chore', 'open', 'Future experiment spike (pending): MindAttic.Relay, one shared message-relay project every MindAttic app uses for cross-app message streams, so push notifications between all apps are built-in; start from the Orchestrator''s status/app bus (named-pipe NDJSON, daemon hub, inbox relay: M.ORCH-T854/T872/T879/T891/T892, docs/app-bus.md) and the per-CLI terminal channel (M.ORCH-T924), and evaluate extracting them into a reusable package with a hub, typed message kinds, discovery, auth for cross-machine (M.ORCH-T933) and optional shared-memory fast path for hot stats', '—', 59, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('MAT-T61', 'MindAttic.Agency', 61, '2026-10-26', 'docs', 'closed', 'Drop the /commit test gate from the global no-tests rule: tests run only when the user explicitly asks, never automatically on a commit (it would mean endless test runs)', '—', 60, NULL);
