INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.CAPT-T16', 'MindAttic.Capture', 16, '2026-10-16', 'feature', 'open', 'Log to MindAttic.Log (3.0.0): every app/CLI entry point writes to the standalone MindAttic.Log.db Vault assigns this app (VaultPaths.LoggingDbPath, MindAttic.Vault 6.0.0) through Serilog''s WriteToMindAtticLog, tagged with its Component; log startup, user actions that change data, failures and unhandled exceptions (UI thread, AppDomain, unobserved tasks); tests point the log at a temp file. Pattern: MindAttic.Workflow WorkflowLog (M.FLOW-T92), MindAttic.Orchestrator OrchestratorLog', 'M.FLOW-T92', 15, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.CAPT-T17', 'MindAttic.Capture', 17, '2026-10-16', 'feature', 'closed', 'Tray app (new MindAttic.Capture.Tray, WinForms NotifyIcon over CaptureEngine): menu with Record Screen / Record App / Record Area / Screenshot (screen, app, area) / saved regions / Stop / Settings / Exit; icon changes while recording; single instance', 'd3ef6db', 16, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.CAPT-T18', 'MindAttic.Capture', 18, '2026-10-16', 'feature', 'closed', 'Tray Record App: list visible top-level windows (Desktop.Windows) with icon+title, record the picked one via WindowHandleTarget at native resolution; Screenshot App does the same for a still. Overlaps M.CAPT-T10 (tray launcher, attach to process)', 'e740a5f', 17, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.CAPT-T19', 'MindAttic.Capture', 19, '2026-10-16', 'feature', 'closed', 'Area selector overlay: borderless topmost per-monitor-DPI-aware window spanning the virtual desktop, gray ~50% dim, drag to draw a rectangle with a light-blue border and a transparent (undimmed) interior; live WxH readout; Esc cancels; returns a PixelRect in physical pixels', '1316f19 TrayRegionTests', 18, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.CAPT-T20', 'MindAttic.Capture', 20, '2026-10-16', 'feature', 'closed', 'Area selector editing: upper-left move handle drags the whole rectangle, edge and corner handles resize it, arrow keys nudge (Shift = 10px), rectangle clamped to the virtual desktop, sizes kept even for the encoder', '60c32d4 TrayRegionTests', 19, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.CAPT-T21', 'MindAttic.Capture', 21, '2026-10-16', 'feature', 'closed', 'Area selector aspect-ratio toolbar: buttons placed outside the selection (flip to the other side near screen edges); choosing a ratio resizes to the same-area rectangle of that ratio keeping the center, clamped to the screen; once locked, resize handles keep the ratio; Free unlocks. Pure ratio math unit-tested', '2eae7d8 TrayRegionTests', 20, NULL);
