INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.CAPT-T28', 'MindAttic.Capture', 28, '2026-10-16', 'fix', 'closed', 'Three MindAttic.Capture.Tests engine tests fail on main (untouched by the tray work, reproducible run alone): On_demand_recordings_are_watched_by_the_valve and Valve_stops_and_exports_the_session_when_a_limit_is_crossed never report ''maximum duration''; Paused_footage_is_left_out_and_markers_become_chapters gets ''Not recording.''', 'EngineTests (all 155 pass)', 27, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.CAPT-T29', 'MindAttic.Capture', 29, '2026-10-17', 'fix', 'closed', 'Tray recorder stuck in Recording when the engine''s shut-off valve stops it (e.g. under 50 GB free): the icon and border stay up, and Stop reports ''Not recording.'' instead of the file the valve exported; Recorder now forwards LimitReached and keeps the valve''s Recording result, TrayApp stops and reports it', 'src/MindAttic.Capture.Tray/Recorder.cs', 28, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.CAPT-T30', 'MindAttic.Capture', 30, '2026-10-17', 'feature', 'open', 'Stitch a session''s screenshot PNGs into an animated GIF: ''-capture screen 15m 5h gif'' makes {RepoName}_{start}.gif from the PNGs at session end, and ''capture gif <folder>'' does it for an existing folder; ffmpeg with a generated palette, a frame rate of 2 or 4 fps (--fps, default 2), the last frame held 2s, width capped (default 1280) to keep it small, each frame stamped with its time. Also callable from code (e.g. CaptureEngine.ExportGif(frames, fps)) so a host app can roll its own timelapses. Tests: frame order, a missing or odd-sized frame, a session that ends early', '—', 29, NULL);
