INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.CAPT-T54', 'MindAttic.Capture', 54, '2026-10-22', 'fix', 'closed', 'capture serve --port with an out-of-range or negative port crashes with an unhandled ArgumentException instead of a clean InvalidArgument error (ApiServer.StartAsync adds the prefix outside its try)', 'Not a bug: verified HttpListener turns an out-of-range port into HttpListenerException, which ApiServer.StartAsync already maps to CaptureException(InvalidArgument); no code change', 53, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.CAPT-T55', 'MindAttic.Capture', 55, '2026-10-22', 'fix', 'closed', 'Tray Exit while a recording is still starting never stops it: ExitAsync''s StopAsync is a no-op in the Starting state, so the recording that then starts is abandoned and lost', '2a8bf09', 54, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.CAPT-T56', 'MindAttic.Capture', 56, '2026-10-22', 'fix', 'closed', 'A host that fails to create its audio tracks (no audio output device for --audio on Windows) prevents the whole tape from starting; audio should be dropped with a warning like a track that fails to start', 'c1d5db3', 55, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.CAPT-T57', 'MindAttic.Capture', 57, '2026-10-22', 'fix', 'closed', 'Concurrent captures can write the session manifest out of order or collide on the file: SaveManifest serializes under a lock but writes outside it, so an older snapshot can overwrite a newer one or a write fails with a sharing violation', '589b9aa', 56, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.CAPT-T58', 'MindAttic.Capture', 58, '2026-10-22', 'fix', 'closed', 'Audio track captures are never disposed when the tape fails to start or one track fails to start, leaking the WASAPI capture (CaptureTape.StartAsync)', 'c53e19a', 57, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.CAPT-T59', 'MindAttic.Capture', 59, '2026-10-22', 'fix', 'open', 'A non-session tape replaced after its encoder died is never deleted (EnsureTapeAsync only exports session tapes), so its lossless segments stay in .staging until the next launch recovers them; delete it once no recording or export still reads it', '—', 58, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.CAPT-T60', 'MindAttic.Capture', 60, '2026-10-22', 'fix', 'closed', 'Markers from an earlier tape leak into later tape exports: after the encoder dies and the tape is replaced, tape 2''s finalize request and every recording/clip/replay export use the whole session''s marker list, whose TapeSeconds belong to tape 1''s timeline, so they appear as bogus chapters/sidecar markers (MarkerRecord needs the tape it was taken on)', '6960378', 59, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.CAPT-T61', 'MindAttic.Capture', 61, '2026-10-22', 'fix', 'closed', 'capture.json replay.seconds (and limits/other numeric durations via TimeSpan.FromSeconds) overflowing e.g. 1e20 throws a raw OverflowException out of CaptureOptions.Apply instead of a CaptureException InvalidArgument', 'becf2b5', 60, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.CAPT-T62', 'MindAttic.Capture', 62, '2026-10-22', 'fix', 'closed', 'ApiServer turns a JSON null in event/marker data into an empty string (JsonElement.ToString()), unlike the WebView2 bridge which keeps null; a rule ''where'' filter and the sidecar then see "" instead of null', 'd4f5ee7', 61, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.CAPT-T63', 'MindAttic.Capture', 63, '2026-10-22', 'fix', 'closed', '''capture recover'' with no root only scans the default R:\MindAttic\Capture, so tapes staged under the fallback root (used when R: is missing) are never recovered by hand', 'bcf444b', 62, NULL);
