INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.LNCH-T28', 'MindAttic.Launcher', 28, '2026-10-16', 'chore', 'closed', 'install.ps1 adds this repo''s 8 .prose/commands stubs for the shared global commands, so any LLM client finds them', 'mindattic-agent-standard/install.ps1 run 2026-10-16', 27, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.LNCH-T29', 'MindAttic.Launcher', 29, '2026-10-16', 'fix', 'closed', 'Mass commit never stages Prose''s local agent state (.prose/agent-session.json*, agent-queue.json*, quicksave.md, archive/), which Prose''s own .gitignore keeps out of every repo; .prose/commands stays tracked', 'WorkspaceCommitterTests.Prose_local_agent_state_is_never_committed_and_alone_reads_as_clean', 28, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.LNCH-T30', 'MindAttic.Launcher', 30, '2026-10-16', 'fix', 'closed', 'Mass commit failed in repos that already .gitignore Prose''s agent state (git add refuses an exclude pathspec naming an ignored path); stage with git add -A, then unstage the state with git reset', 'WorkspaceCommitterTests.A_repo_that_already_gitignores_prose_state_still_commits', 29, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.LNCH-T31', 'MindAttic.Launcher', 31, '2026-10-16', 'fix', 'closed', 'Mass commit leaves a repo committed but unpushed when its remote moved ahead: on a rejected push, rebase onto the remote (autostash) and push again; a conflicting rebase is aborted and reported, leaving the local commit as it was', 'WorkspaceCommitterTests.A_remote_that_moved_ahead_is_rebased_onto_and_the_commit_still_pushes, A_conflicting_rebase_is_undone_and_the_local_commit_is_kept', 30, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.LNCH-T32', 'MindAttic.Launcher', 32, '2026-10-16', 'fix', 'closed', 'Mass commit skips a clean repo that is still ahead of its upstream (an earlier push failed), so it stays unpushed forever; push those too, with the same rebase-on-rejection', 'WorkspaceCommitterTests.A_clean_repo_left_ahead_by_an_earlier_failed_push_is_pushed', 31, NULL);
