INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.LNCH-T38', 'MindAttic.Launcher', 38, '2026-10-18', 'feature', 'closed', 'Follow the Orchestrator''s billing mode (M.ORCH billing switch): ProviderCredentials pushes ANTHROPIC_API_KEY from the Vault only when the mode is API (today it pushes it whenever no claude.ai login exists at launch, so a later /login still bills the key), and a hosted Claude tab can be restarted in place on request over its pipe: end the claude process between turns and start claude --resume <session id> with the new mode''s environment, so the conversation carries on billing the right account', '33c79cc', 37, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.LNCH-T39', 'MindAttic.Launcher', 39, '2026-10-18', 'fix', 'closed', 'bootstrap installs the Claude Code, Codex and Antigravity CLIs but not the Kimi Code CLI (kimi) that the default Kimi provider runs, so a Kimi tab fails on a freshly bootstrapped machine; needs a confirmed unattended install source (uv tool / pip / winget) before adding it to PrerequisiteService.AiClis', 'ff1504c', 38, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.LNCH-T40', 'MindAttic.Launcher', 40, '2026-10-18', 'feature', 'closed', 'Onboarding: setup.ps1 and a new adopt-repos command tag every GitHub repo the token can see as wip so the roster is full on first launch', '—', 39, NULL);
