INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.LNCH-T43', 'MindAttic.Launcher', 43, '2026-10-19', 'chore', 'wont-do', 'Convert tracked source files to LF line endings via .gitattributes, per HOUSE-LAW-13 (low priority)', '—', 42, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.LNCH-T44', 'MindAttic.Launcher', 44, '2026-10-20', 'feature', 'closed', 'Read the orchestrator''s pace status from its database: MindAttic.Orchestrator now keeps it as the rl-status row of data/orchestrator.db''s state table (M.ORCH-T526), found as OrchestratorDb.StatePath finds it (MINDATTIC_ORCHESTRATOR_DB, else <workspace>\MindAttic.Orchestrator\data\orchestrator.db, else %APPDATA%\MindAttic\MindAttic.Orchestrator\orchestrator.db); ClaudeStatusService should read that row (read-only, short busy timeout, newer timestamp of row and file wins) and fall back to ~/.claude/rl-status.json, which the orchestrator keeps exporting until every outside reader has switched', 'ClaudeStatusServiceTests (31ad24b)', 43, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.LNCH-T45', 'MindAttic.Launcher', 45, '2026-10-20', 'docs', 'closed', 'Publish MindAttic.Launcher docs to GitHub Pages via the shared Toolkit DocFX pipeline: run adopt-docs-site.ps1 (README.md as home page, docs/*.md as articles, API reference only where the code builds in CI), enable Pages with build_type=workflow, set the repo homepage URL, retire tools/build-readme.ps1 and README.htm, confirm the docs Actions run is green and https://mindattic.github.io/MindAttic.Launcher/ returns 200. Depends on MAT-T8.', 'f493703', 44, NULL);
