INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.LNCH-T47', 'MindAttic.Launcher', 47, '2026-10-20', 'feature', 'closed', 'Open Project Tab: collapse dot-named projects (MindAttic.*, GTFO.*) into per-prefix disclosure rows (▸); Esc pops one level before exiting', '—', 46, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.LNCH-T48', 'MindAttic.Launcher', 48, '2026-10-20', 'feature', 'closed', 'Per-CLI Claude login in the Launcher''s own menu (follows M.ORCH-T559): when opening a Claude tab, offer the per-CLI logins signed in under %USERPROFILE%\.claude-accounts\<email> (orchestrator login --account <email>) beside the global login, and start the tab''s claude with CLAUDE_CONFIG_DIR set to the chosen account''s folder, as ''orchestrator start <repo> --account <email>'' already does by wrapping the host in a PowerShell that sets it; without a choice the tab uses the global login exactly as today', '67c9897', 47, NULL);
