INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.LNCH-T51', 'MindAttic.Launcher', 51, '2026-10-22', 'feature', 'wont-do', 'Launcher tabs pick a Claude login too: opening a project''s Claude tab from the Launcher (menus and host) runs it under the login orchestrator accounts pick chooses (setting CLAUDE_CONFIG_DIR for the tab; no variable for the global login, and no change when the orchestrator isn''t installed), and host takes --account <email> to name one, so tabs opened outside the dashboard also spread one CLI per Claude Team account', 'Superseded by M.LNCH-T53', 50, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.LNCH-T52', 'MindAttic.Launcher', 52, '2026-10-22', 'feature', 'closed', 'Move a running CLI to another login: the host pipe''s restart-resume request takes an optional configDir (empty = the global login), and the host restarts that tab''s CLI at its next idle point with claude --resume under that CLAUDE_CONFIG_DIR, so the same conversation carries on billing the other account', '256ab10', 51, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.LNCH-T53', 'MindAttic.Launcher', 53, '2026-10-22', 'feature', 'closed', 'Ask which account a Claude tab belongs to: when the Launcher opens a Claude tab (menus and host) and more than one Claude login is signed in (the global ~/.claude login plus each ~/.claude-accounts per-CLI login), it lists them by email with each one''s 5h/week left and which already have a CLI, preselects orchestrator accounts pick''s choice (Auto), and starts the tab''s CLI under the chosen login''s CLAUDE_CONFIG_DIR (none for the global login); host --account <email> skips the question, a single login skips it, and the tab title shows the account, so one computer runs several CLIs each logged in as a different person. Supersedes M.LNCH-T51', '5ca3e9c', 52, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.LNCH-T54', 'MindAttic.Launcher', 54, '2026-10-22', 'feature', 'closed', 'A Launcher scoped to one person: MindAttic.Launcher --account <email> runs the whole Launcher as that Claude login; every Claude tab it opens, from any repo, sets that login''s CLAUDE_CONFIG_DIR explicitly in the tab''s own command (Windows Terminal tabs don''t inherit the Launcher''s environment), so every CLI from it bills that person; its window and tab titles show the login''s alias (read from mindattic-account.json in the login''s folder, else the email); it never asks which account (that question is only for an unscoped Launcher, M.LNCH-T53); and an account that isn''t signed in yet is signed in first (orchestrator login --account) before the Launcher opens', 'def9cdc', 53, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.LNCH-T55', 'MindAttic.Launcher', 55, '2026-10-22', 'feature', 'closed', 'A terminal window per person in the Launcher: Claude tabs the Launcher opens (and a scoped Launcher, M.LNCH-T54) go into the Windows Terminal window named for the tab''s login (wt -w <alias>) with the login''s initials badge in the title and its tab color, the same rule as the Orchestrator (M.ORCH-T616), read from mindattic-account.json in the login''s folder', 'd4ffb0a', 54, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.LNCH-T56', 'MindAttic.Launcher', 56, '2026-10-22', 'feature', 'closed', 'Initials icons on terminal tabs: each Claude login gets its own Windows Terminal profile through a Terminal fragment (%LOCALAPPDATA%\Microsoft\Windows Terminal\Fragments\MindAttic) whose icon is a generated image of its initials (JR, AR, RD) on its tab color, and its tabs open with that profile (wt new-tab -p), so ownership shows as an icon as well as the [JR] title badge; regenerated when a login''s alias or initials change', 'LoginTerminalProfilesTests; 5e9abea', 55, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.LNCH-T57', 'MindAttic.Launcher', 57, '2026-10-22', 'fix', 'closed', 'A failed SQLite restore deleted the live database; move it aside and put it back on failure', 'RestoreOne_puts_the_existing_database_back_when_the_restore_fails', 56, NULL);
