INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.LOGS-T17', 'MindAttic.Log', 17, '2026-10-22', 'feature', 'open', 'Log stores are pluggable and discoverable (owner 2026-10-22): today every app writes only its standalone SQLite MindAttic.Log.db (MindAtticSqliteSink, LoggerConfigurationExtensions) and the Reader (LogQueryService, LogSource) only finds those files under %APPDATA%\MindAttic\Logging\<appId>. Add a log-store abstraction with a SQL Server store (a dedicated MindAttic.Log database on the full instance beside Prose, MSSQLSERVER/localhost, for corporate-grade apps) beside the SQLite one, chosen per app by configuration (a connection string, or the SQLite default for small apps and games), with room for other store types later (a provider registry, not a hard-coded switch); the Reader discovers every app''s logs wherever they are (each SQLite file and each configured server database) through the same abstraction and queries them alike; keep SQLite fully working and a migrator from an app''s SQLite file to SQL Server', '—', 16, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.LOGS-T18', 'MindAttic.Log', 18, '2026-10-23', 'docs', 'closed', 'many billions of tokens', '—', 17, NULL);
