INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T16', 'MindAttic.Orchestrator', 16, '2026-10-13', 'chore', 'closed', 'Act on audit findings: move statusline.ps1 (25 repos), quickload-on-do.ps1 (22 identical + drifted copies) and tools/build-readme.ps1 (20) into mindattic-agent-standard and have install.ps1 point repos at the shared copy', 'mindattic-agent-standard/share-scripts.ps1 (called by install.ps1): global settings run shared/statusline.ps1 and shared/hooks/quickload-on-do.ps1; 23 identical statuslines and 21 identical hooks removed with their repo settings entries, 11 drifted hooks kept; build-readme.ps1 copies were already 3-line forwarders to codex-standard; rerun is a no-op', 15, '| M.ORCH-T16 | 2026-10-13 | chore | closed | Act on audit findings: move statusline.ps1 (25 repos), quickload-on-do.ps1 (22 identical + drifted copies) and tools/build-readme.ps1 (20) into mindattic-agent-standard and have install.ps1 point repos at the shared copy | mindattic-agent-standard/share-scripts.ps1 (called by install.ps1): global settings run shared/statusline.ps1 and shared/hooks/quickload-on-do.ps1; 23 identical statuslines and 21 identical hooks removed with their repo settings entries, 11 drifted hooks kept; build-readme.ps1 copies were already 3-line forwarders to codex-standard; rerun is a no-op |');
