INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T122', 'MindAttic.Orchestrator', 122, '2026-10-15', 'feature', 'closed', 'Never go over and wind down: at the 99% target (or a limit) the pace gate refuses tool calls in every CLI (/unthrottle included) after its longest hold instead of letting them through; past 90% each turn is told to start only what it can finish and to file the rest as a ticket and /quicksave, and autopilot starts only stories whose estimate fits; keep-going lets stopped turns end and autopilot re-queues a stopped agent''s story for after the reset', 'bf1ff54; PacerTests.Past_90_percent_the_window_winds_down_and_at_its_target_everything_stops, HookScriptTests.At_the_windows_target_a_call_is_refused_even_from_an_unthrottled_cli', 121, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T123', 'MindAttic.Orchestrator', 123, '2026-10-15', 'feature', 'closed', '/autopilot all: work every repo in the workspace that has open stories, CLI open or not, so agents keep running while you''re away (still under the pace, the 99% stop, hand-worked repos and --autopilot-skip)', 'e08159d; AutopilotTests.Autopilot_all_works_every_repo_with_open_stories_whether_or_not_a_cli_is_open; live: dryrun lists 37 repos', 122, NULL);
