INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T581', 'MindAttic.Orchestrator', 581, '2026-10-21', 'fix', 'closed', 'Fails on main: the build — C:\Program Files\dotnet\sdk\10.0.400\Microsoft.Common.CurrentVersion.targets(5096,5): error MSB3027: Could not copy "D:\Projects\MindAttic.worktrees\MindAttic.Orchestrator\main-tests\src\MindAttic.Orchestrator.Core\bin\Debug\net10.0-windows\MindAttic.Orchestrator.Core.dll" to "bin\Debug\net10.0-w... (landed on main since the last green run: 6c77661 Sync data/orchestrator.db: the orchestrator''s settings, state and history (M.ORCH-T524); 28e6747 Account menu''s 5h resets shows the reset''s date and time, as Week resets does (M.ORCH-T579); f21db47 Sync data/orchestrator.db: the orchestrator''s settings, state and history (M.ORCH-T524); 79affdc Pin the account menu''s Week usage (used/left%), dated Week resets and column headings in a test (M.ORCH-T578))', 'passes on main@c5a2a02', 580, NULL);
