INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T594', 'MindAttic.Orchestrator', 594, '2026-10-21', 'feature', 'closed', '5-hour usage shows one decimal in its last 10% (90.1%, 90.2%, 90.3%...) instead of whole percents, on the dashboard tile, chart and status line', 'bff7c51', 593, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T595', 'MindAttic.Orchestrator', 595, '2026-10-21', 'feature', 'closed', 'Resume after the 5-hour reset even when a CLI froze over the limit: as its last act before the wall (or when usage passes 100%), the orchestrator schedules each working CLI''s resume for 2 minutes past the reset, so work restarts at the start of the next window without anyone typing', '40390b5', 594, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T596', 'MindAttic.Orchestrator', 596, '2026-10-21', 'fix', 'closed', 'Needs you keeps longest wait first whatever Sort by says; only the other Repos sections follow Name / Open tickets', '9b088da', 595, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T597', 'MindAttic.Orchestrator', 597, '2026-10-21', 'fix', 'wont-do', 'Fails on main: the build — C:\Program Files\dotnet\sdk\10.0.400\Microsoft.Common.CurrentVersion.targets(5096,5): error MSB3027: Could not copy "D:\Projects\MindAttic.worktrees\MindAttic.Orchestrator\main-tests\src\MindAttic.Orchestrator.Wpf\bin\Debug\net10.0-windows\MindAttic.Orchestrator.dll" to "bin\Debug\net10.0-windows... (landed on main since the last green run: 2dc7d78 Sync data/orchestrator.db: the orchestrator''s settings, state and history (M.ORCH-T524); 9b088da Needs you keeps longest wait first whatever Sort by says (M.ORCH-T596); 77db6bd Sync data/orchestrator.db: the orchestrator''s settings, state and history (M.ORCH-T524); 40390b5 Resume every CLI working at the wall 2 minutes past the reset, even one frozen over the limit (M.ORCH-T595); bff7c51 Show the 5-hour percent with one decimal from 90% on (M.ORCH-T594); 522cd74 Repos view: Sort by Name (default) or Open tickets, remembered (M.ORCH-T593))', 'main@2dc7d78', 596, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T598', 'MindAttic.Orchestrator', 598, '2026-10-21', 'fix', 'closed', 'MainlineTests.Solution picks the solution from the repo''s main checkout folder (Directory.GetFiles(repoPath, ''*.slnx'')) but the build runs in a fresh worktree of origin/main, so a stale or locally-dirty main folder (behind origin, or holding an untracked/gitignored generated solution such as Unity''s Unity.Cursory.slnx) names a file the worktree doesn''t have and the run fails MSB1009, filing a bogus ''Fails on main: the build'' ticket (Unity.Cursory UC-T25, then UC-T29 after the fix landed but the main folder hadn''t pulled it); choose the solution from the worktree being built (tracked files only), with a test', 'MainlineTestsTests.The_solution_is_chosen_from_the_built_commit_not_the_repo_folder', 597, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T599', 'MindAttic.Orchestrator', 599, '2026-10-21', 'feature', 'closed', '/allocate off (and on) can target other CLIs, not just this one: -target= takes a list of CLIs (PIDs or session ids/names, comma-separated) or a selector: ''others'' (every CLI except this one) and ''all''; the gate records are written to each targeted CLI''s own record, the reply names each CLI it changed (and any target that matched none), and /allocate''s skill text documents the forms (low priority)', 'e409d7b', 598, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T600', 'MindAttic.Orchestrator', 600, '2026-10-21', 'fix', 'closed', 'Fails on main: the build — C:\Program Files\dotnet\sdk\10.0.400\Microsoft.Common.CurrentVersion.targets(5096,5): error MSB3027: Could not copy "D:\Projects\MindAttic.worktrees\MindAttic.Orchestrator\main-tests\src\MindAttic.Orchestrator.Wpf\bin\Debug\net10.0-windows\MindAttic.Orchestrator.dll" to "bin\Debug\net10.0-windows... (landed on main since the last green run: tickets M.ORCH-T572 in 95e6663 Retire /handoff and fold its wind-down into /allocate off (M.ORCH-T572))', '461e6bb', 599, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T601', 'MindAttic.Orchestrator', 601, '2026-10-22', 'fix', 'closed', 'orchestrator next --claim refuses a CLI with nothing running as already having its fair share: ''this CLI has its fair share of the subagent allowance (0 running of 14 across 6 CLIs that want them)''; a CLI with 0 running and workable tickets must get at least one slot while the allowance has room', 'fe757a9', 600, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T602', 'MindAttic.Orchestrator', 602, '2026-10-22', 'chore', 'closed', 'Update orchestrator.db, orchestrator.sql, USER_STORIES.md', '—', 601, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T603', 'MindAttic.Orchestrator', 603, '2026-10-22', 'feature', 'closed', 'Accounts view: an ''Accounts'' pill beside Agents/Repos/Queue/Audit in the dashboard''s view switcher, one card per Claude login (the global ~/.claude login, then each ~/.claude-accounts per-CLI login) showing its signed-in email, plan, 5h and week used with resets, the daemon''s pace for it, and every live CLI (repo tab) running on it (from ContextCycler''s per-session CLAUDE_CONFIG_DIR); a login not signed in offers Sign in, and Add account signs in a new per-CLI login (orchestrator login --account), so you can see at a glance who is logged into which account and which CLIs bill it', 'd374da1', 602, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T604', 'MindAttic.Orchestrator', 604, '2026-10-22', 'feature', 'closed', 'Sign in to every Team account once: ''Sign in all'' on the Accounts view (and orchestrator login --all) gives every account in the roster (accounts table) that has no per-CLI login yet its own ~/.claude-accounts folder and runs claude auth login --email into each in turn, so every Claude Team seat stays signed in side by side and the global login is only the default', '1179944', 603, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T605', 'MindAttic.Orchestrator', 605, '2026-10-22', 'feature', 'closed', 'One CLI per account by default: starting a Claude tab (dashboard Start, orchestrator start, Queue/autopilot starts) defaults to an ''Auto'' login that picks a signed-in per-CLI login with no live CLI on it, most 5h/week headroom first, and falls back to the global login when every account already has a CLI or none is signed in; an explicit --account or ''Global login'' still wins, a setting turns Auto off, and orchestrator accounts pick prints the chosen CLAUDE_CONFIG_DIR (empty for the global login) for the Launcher to use, so tokens spread 1:1 across accounts instead of many CLIs draining one', '—', 604, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T606', 'MindAttic.Orchestrator', 606, '2026-10-22', 'feature', 'closed', 'Show each CLI''s account: Agent board cards and the Repos detail pane''s Launcher tab rows name the Claude login each CLI bills (its per-CLI login''s email, or the global login''s), so a CLI on the wrong account is visible without opening it', '—', 605, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T607', 'MindAttic.Orchestrator', 607, '2026-10-22', 'feature', 'closed', 'Move to account: each CLI on the Accounts view and Agent board gets a ''Move to'' menu of the other signed-in logins (and orchestrator move <repo|pid> --account <email>|--global), which sends the Launcher''s restart-resume with that login''s folder, so a running CLI''s ownership moves to another signed-in account at its next idle point without losing its session', 'b6dee3b AccountMoveTests', 606, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T608', 'MindAttic.Orchestrator', 608, '2026-10-22', 'feature', 'closed', 'Rebalance when an account runs low: when a CLI''s account crosses its 5h or weekly pace limit and another signed-in login has no CLI and more headroom, the daemon moves that CLI there (restart-resume at its next idle point) and toasts it, keeping one CLI per account; a setting turns it off', '3d6c8be AccountRebalancerTests', 607, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T609', 'MindAttic.Orchestrator', 609, '2026-10-22', 'feature', 'closed', 'Adjustable weekly reserve: a ''Weekly reserve'' setting on the Settings page (default 5%, 0-50) replaces the fixed 99% weekly stop (AgentGate.StopPercent), so every CLI on an account stops at 100 minus the reserve (95% by default) of that account''s week instead of burning it all; it applies to each login on its own (the global login and every per-CLI login''s pace in its rl-status.json), the context-gate hooks read the live value rather than a constant baked into the script, the Accounts view and account menu show each account''s stop line, and the Auto login pick and rebalance treat an account at its stop as unavailable', '9afd99d', 608, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T610', 'MindAttic.Orchestrator', 610, '2026-10-22', 'feature', 'closed', 'Each account gets its own login screen: choosing an account that isn''t signed in yet (the Start pills, which now list every roster account and not just signed-in ones, the Accounts tab''s Sign in / Add account, and orchestrator login --account) opens that account''s sign-in in its own private browser window or browser profile per account, prefilled with its email, so the login page asks for that person''s email and code instead of silently authorizing whoever the default browser is already signed in to claude.ai as; after sign-in the folder''s account is checked against the chosen email (a mismatch signs the folder out again and says so), and a Start that triggered it then opens the CLI on that account', '296b78f', 609, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T611', 'MindAttic.Orchestrator', 611, '2026-10-22', 'fix', 'closed', 'Fails on main: MindAttic.Orchestrator.Tests.LibraryControlsTests.Progress_bars_text_areas_and_placeholders_are_the_librarys — Assert.That(placeholders, Is.EquivalentTo(new[] { "Search repos and tickets Ctrl+F", "Opening prompt (optional), or pick a ticket below", "Reply to this tab…" })) Expected: equivalent to < "Search repos and tickets Ctrl+F", "Opening prompt (optional), or pick a ticket below", "Reply to this tab…"... (landed on main since the last green run: tickets M.ORCH-T605, M.ORCH-T603, M.ORCH-T606 in 9f40a24 One CLI per account by default: new Claude tabs start on an Auto login that picks a free per-CLI login with the most headroom, else the global login; orchestrator accounts pick prints its CLAUDE_CONFIG_DIR for the Launcher (M.ORCH-T605); d374da1 Accounts view: an Accounts pill beside Agents/Repos/Queue/Audit with one card per Claude login (global, then each per-CLI login) showing who''s signed in, plan, 5h/week use with resets, the daemon''s pace and every live CLI on it; Sign in, Add account and Sign in all in its toolbar (M.ORCH-T603); 800cf29 Show the Claude login each CLI bills on agent cards and Launcher tab rows (M.ORCH-T606))', '3d80c3b', 610, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T612', 'MindAttic.Orchestrator', 612, '2026-10-22', 'feature', 'closed', 'orchestrator start --account signs the account in first: when the named account has no per-CLI login yet, start runs its sign-in (OwnLogins.SignIn, the same as orchestrator login --account) and then opens the tab on it, instead of stopping with ''run orchestrator login --account first''; a sign-in that fails or lands on a different account than named stops without opening a tab', '35801e0', 611, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T613', 'MindAttic.Orchestrator', 613, '2026-10-22', 'feature', 'closed', 'One dashboard tab per Claude login: the whole Orchestrator window moves inside a TabControl with one tab per signed-in login (the global ~/.claude login first, then each ~/.claude-accounts per-CLI login, titled by email, with a tab added or removed as logins are signed in or out), and every tab is the full dashboard scoped to that login''s own CLIs: its stat tiles (Need you, Working, Subagents), its 5-hour and weekly tiles and utilization chart from that account''s own meter and pace (AccountPacer / its rl-status.json), its Agents board and Repos view showing only the CLIs and Launcher tabs on that login, toasts tagged by tab, and Start (repo detail, Queue) opening the CLI on that tab''s login; tickets stay workspace-wide, so Queue and Audit read the same in every tab but start work on the tab''s login; the Accounts view stays as the cross-login overview where accounts are added and signed in; built as one scoped view model per login over the shared snapshot refresh, not one refresh per tab', '063d111', 612, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T614', 'MindAttic.Orchestrator', 614, '2026-10-22', 'feature', 'closed', 'Names for logins: each Claude login gets an alias (e.g. pdftransferjr@mindattic.com = Jordan, ryandebraal@mindattic.com = Ryan), set and renamed from the Accounts view and orchestrator accounts alias <email> <name>, defaulting to the part of the email before the @; it''s kept in the login''s own folder (an alias field in mindattic-account.json in that account''s ~/.claude-accounts folder, or in ~/.claude for the global login) so the Launcher and status line read it without the Orchestrator, and the dashboard tabs, Accounts cards, agent cards and each account''s status line tag show the alias, with the email in the tooltip', 'ac7435b', 613, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T615', 'MindAttic.Orchestrator', 615, '2026-10-22', 'feature', 'closed', 'Open Launcher as this person: each per-login dashboard tab (M.ORCH-T613) has an ''Open Launcher'' button that starts the Launcher scoped to that tab''s login (MindAttic.Launcher --account <email>), so picking the Ryan tab and opening the Launcher puts every repo CLI started from it on Ryan''s account, and those CLIs show up in Ryan''s tab; a known roster account that isn''t signed in yet (e.g. Amy) still gets a tab, which shows only a Sign in button until it''s signed in, then the full dashboard and Open Launcher; one account may own many CLIs', 'f85d455', 614, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T616', 'MindAttic.Orchestrator', 616, '2026-10-22', 'feature', 'closed', 'A terminal window per person: tabs the Orchestrator opens (SessionControl.Start) go into a Windows Terminal window named for the tab''s Claude login (wt -w <name>, the login''s alias, else its email before the @) instead of the most recent window (-w 0), so each person''s CLIs gather in one window; each tab''s title starts with the login''s initials badge (e.g. [RD] Repo [Claude]) and its tab color is the login''s own, read from mindattic-account.json in the login''s folder (alias, initials) with the email''s first two letters as the fallback initials', '69a14f1', 615, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T617', 'MindAttic.Orchestrator', 617, '2026-10-22', 'chore', 'wont-do', 'Future spike, not now: CLIs rendered inside the Orchestrator instead of separate Windows Terminal windows. Options: (2) Microsoft.Terminal.Wpf (the Windows Terminal renderer for WPF, e.g. via the EasyWindowsTerminalControl NuGet wrapper) over ConPTY, each pane running the same ''launcher host'' command a tab runs today; (3) xterm.js in WebView2 over a .NET ConPTY backend (e.g. vs-pty.net). Deferred by choice: separate terminals survive a dashboard crash, while embedded ones die with it unless hosted out of process; revisit only with out-of-process hosting', 'Option 2 superseded by M.ORCH-T618 (as an opt-in setting); option 3, xterm.js in WebView2, not pursued', 616, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T618', 'MindAttic.Orchestrator', 618, '2026-10-22', 'feature', 'closed', 'Terminals inside the Orchestrator, as a setting: a ''Where CLIs open'' setting on the Settings page (and orchestrator settings --terminal-host) chooses Windows Terminal (the default, today''s separate windows per person) or Orchestrator; on Orchestrator, SessionControl.Start opens the tab as an embedded terminal pane instead of wt: the Windows Terminal renderer for WPF (Microsoft.Terminal.Wpf, through the EasyWindowsTerminalControl NuGet wrapper, checking the packages'' current versions and .NET 10 support first) over ConPTY, each pane running the same ''MindAttic.Launcher host --path ... --title ... --provider ...'' command (with the login''s CLAUDE_CONFIG_DIR set in the pane''s environment) so restart-resume, account moves and idle detection keep working unchanged; panes sit in the person''s dashboard tab (M.ORCH-T613), as their own pane tabs with the [JR] badge and tab color (M.ORCH-T616), or in a Terminals view until T613 lands; closing a pane ends its CLI; because panes die with the dashboard, the Orchestrator records each pane''s repo, login and Claude session and, when it next opens, offers to reopen them with claude --resume; switching the setting affects only tabs opened afterwards', '6c26ba8', 617, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T619', 'MindAttic.Orchestrator', 619, '2026-10-22', 'feature', 'closed', 'Go to the CLI: clicking a ''needs you'' (or finished/waiting) toast brings that CLI''s own terminal to the front, selected on its tab, instead of just opening the repo''s detail pane; the same ''Go to tab'' action is on each Launcher tab row in the repo detail pane and on each agent card; the tab is found by the Launcher host''s process (its PID, which the dashboard already shows) through UI Automation on Windows Terminal''s windows (the TabItem whose name is the tab''s title, then SelectionItemPattern.Select and the window restored and foregrounded), falling back to the window alone and then to the old detail pane with a note when it can''t be found', '7a211ea', 618, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T620', 'MindAttic.Orchestrator', 620, '2026-10-22', 'fix', 'closed', 'The daemon''s orchestrator.db sync (Daemon.SyncOrchestratorDbIfDue) commits and pushes in the main checkout but never fetches or integrates main, so once agents land through their own worktrees the checkout falls behind and every sync push is rejected (non-fast-forward) and retried every 10 minutes forever; before pushing, fetch and integrate origin/main (the database commits only touch data/orchestrator.db and data/orchestrator.sql, so a merge or rebase that leaves other dirty files alone), then push, and warn once when it can''t', 'b185580', 619, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T621', 'MindAttic.Orchestrator', 621, '2026-10-22', 'fix', 'closed', 'The embedded terminal pane''s tab badge ([OH] etc., M.ORCH-T618) draws its initials in the login''s tab color on the dark tab, so dark tab colors like the purple one are unreadable; draw the badge as text on a filled chip of the tab color (or pick black or white text by the color''s luminance) so every palette color reads, and check the same in the Accounts cards and agent cards', '307d230 (The_badge_text_is_black_or_white_by_the_luminance_of_its_tab_color_chip)', 620, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T622', 'MindAttic.Orchestrator', 622, '2026-10-22', 'feature', 'closed', 'Full-screen terminals per person: in each person''s dashboard tab (M.ORCH-T613), that person''s embedded CLI panes (M.ORCH-T618) live on their own set of terminal tabs that fill the whole window below the person tab strip, not a short strip under the stats, chart and view pills; selecting a person shows a ''Terminals'' tab (one terminal tab per active CLI of theirs, with its badge, repo and Go to / Move to / close) beside their ''Dashboard'' tab, and while Terminals is showing the header tiles, utilization chart and view pills are hidden so the panes get the full height; Go to tab, a needs-you toast and a newly opened pane switch to that person and their Terminals tab', 'c799b0b', 621, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T623', 'MindAttic.Orchestrator', 623, '2026-10-22', 'fix', 'closed', 'Embedded panes reopened after a dashboard restart (M.ORCH-T618) run bare ''claude --resume <id>'', so they have no Launcher input pipe, control pipe, restart-resume or account moves; now that MindAttic.Launcher host takes --resume <session> (M.LNCH-T64, 39ce294), reopen each pane through the same ''MindAttic.Launcher host --path ... --title ... --provider Claude --resume <id>'' command a new pane runs, passing --config-dir with the pane''s recorded login', 'eda6b90', 622, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T624', 'MindAttic.Orchestrator', 624, '2026-10-22', 'fix', 'closed', 'M.ORCH-T620''s daemon db sync integrates main with ''git rebase --autostash origin/main'', but in the live checkout the autostash itself fails (''Cannot save the current worktree state'' / ''Cannot autostash'', seen 2026-10-22 in D:\Projects\MindAttic\MindAttic.Orchestrator) because the daemon keeps data/orchestrator.db open and changing, so the sync would abort and never push; integrate with ''git merge --no-edit origin/main'' instead (merge commits pass the commit-msg hook, and incoming commits never touch the dirty data/ files, so no stash is needed), falling back to the abort-and-warn path only when the merge itself conflicts; keep the one-warning rule and update DaemonSafetyTests', '175c00c', 623, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T625', 'MindAttic.Orchestrator', 625, '2026-10-22', 'fix', 'closed', 'The Terminals view''s explanatory line (''...With Settings > Where CLIs open: Orchestrator, a CLI started from the Orchestrator (Start, the Queue, autopilot, orchestrator start) opens here as a pane of its own.'') draws on top of the Agents view''s ''Agents'' heading and summary line (seen after M.ORCH-T613, 063d111, with the Agents view showing and Where CLIs open = Windows Terminal), so the heading is unreadable; show that text only in the Terminals view, and check the other views'' headings for the same overlap', 'f0d8c91', 624, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T626', 'MindAttic.Orchestrator', 626, '2026-10-22', 'fix', 'closed', 'The Terminals view''s container (TerminalsBody in MainWindow.xaml) sets DataContext to Terminals and binds Visibility to TerminalsVisibility on that same element, so the binding resolves against TerminalsViewModel, which has no such property, fails silently and leaves the container Visible in every view: its hint drew over the Agents heading (M.ORCH-T625 only hid the hint) and with Where CLIs open = Orchestrator its native terminal panes would show over every other view; bind Visibility to the window''s view model (TerminalsVisibility on MainViewModel) instead', '0993328', 625, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T627', 'MindAttic.Orchestrator', 627, '2026-10-22', 'chore', 'closed', 'Spike: long-lived tokens for per-person logins. Research whether each per-CLI login (~/.claude-accounts/<email>) can be signed in once with ''claude setup-token'' (the long-lived token Anthropic recommends for unattended use) instead of a /login that renews and can expire, so a person signs in once rather than whenever a login lapses. Find out: the token''s lifetime and how it''s revoked or rotated; whether setup-token works for Claude Team seats and bills that seat''s own allowance (5h/weekly windows, not an API key); how Claude Code takes it (CLAUDE_CODE_OAUTH_TOKEN env var vs. the folder''s .credentials.json) and whether it composes with CLAUDE_CONFIG_DIR per tab; whether it signs out or conflicts with the same account''s other devices (iPad, browser); and where to keep it safely (MindAttic.Vault rather than plaintext). Outcome: a recommendation and, if it works, a follow-up ticket to wire it into orchestrator login --account / Sign in and the Launcher''s per-tab environment. Refs: code.claude.com/docs/en/authentication, code.claude.com/docs/en/errors', 'spike done; follow-up M.ORCH-T696 (no code change, nothing to land)', 626, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T628', 'MindAttic.Orchestrator', 628, '2026-10-22', 'feature', 'closed', 'Drop the account dropdown now that every person is signed in at once: remove the upper-right account menu (AccountMenuButton and AccountPopup, M.ORCH-T492/T566) and let each person''s tab (M.ORCH-T613) carry that person''s own numbers in the stat tiles that already exist, scoped to the tab''s login: the 5-hour tile with its % used and reset time, and the weekly tile reading as % left (e.g. ''23% left'') with its reset date and time (''resets Mon 10/27 5:00 PM'') and the weekly reserve stop line (M.ORCH-T609, ''stops at 95%''), plus any figure the dropdown showed that no tile has (plan, last checked); move what only the dropdown did to the Accounts tab: ''Use API key (emergencies)'' / back to Claude Team, and making a login the global default (its sign-in), with the billing tooltip and detail line going with them; nothing else changes', 'e2a691a', 627, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T629', 'MindAttic.Orchestrator', 629, '2026-10-22', 'feature', 'closed', 'Always show each person''s 5-hour chart: on every person''s tab (M.ORCH-T613) the 5-hour utilization card stays visible even when nothing is running on that login, drawn as a flat line at its current % (0% when its window has reset or it was never read) across the window''s span, with the target line and a caption saying it''s idle (e.g. ''Idle: 0% of this 5-hour window used; nothing running on Ryan''), instead of collapsing the card when there''s no utilization text; a login whose window hasn''t started shows the next 5 hours from now', 'd4be597', 628, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T630', 'MindAttic.Orchestrator', 630, '2026-10-22', 'feature', 'closed', 'Status at a glance on the person tab strip: each person''s tab (M.ORCH-T613) shows that person''s weekly % left on its far right (e.g. ''Ryan … 23% left'', from its own meter, after the M.ORCH-T609 reserve, ''—'' when never read) so you see who has room without opening it, and a status light before the name: green when signed in and usable, red when signed out (the roster''s not-signed-in tabs, M.ORCH-T615), purple for any other state (at its weekly stop line, 5-hour limit hit, sign-in in progress, login mismatch); plus an ''API key'' tab for the Vault API key billing with an orange warning light, holding the API-key switch (Use API key (emergencies) / back to Claude Team, moved off the dropdown by M.ORCH-T628), what it has cost today, and which CLIs bill it; colors come from the theme''s tokens with a word in the tooltip so color is never the only cue', '2c03cea', 629, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T631', 'MindAttic.Orchestrator', 631, '2026-10-22', 'chore', 'closed', 'Move the dashboard''s new UI onto MindAttic.Components: audit what M.ORCH-T613/T615/T618/T621/T622/T628/T629/T630 added (the person tab strip, Dashboard/Terminals sub-tabs, terminal pane tabs and their badge chips, the sign-in-only panel, status lights, tiles) for anything hand-rolled (local styles or templates, hard-coded colors, custom controls) and replace it with MindAttic.Components controls, styles and theme tokens, using the library''s new tab strip and status light (MindAttic.Components ticket) once they ship; extend LibraryControlsTests so these can''t drift back', 'The_tab_strips_and_sign_in_panel_stay_on_library_styles_with_no_colour_of_their_own', 630, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T632', 'MindAttic.Orchestrator', 632, '2026-10-22', 'feature', 'closed', 'Terminal/tab titles: change the login-initials badge from bracket format "[JR] Repo [Claude]" to colon format "JR: Repo [Claude]", and strip the exact leading prefixes GTFO., MindAttic., Unity. from the repo name shown (keep the trailing [Provider] tag). Touches MindAttic.Orchestrator (SessionControl.TabTitle + OpenLauncher''s Launcher-tab title, TerminalsViewModel.Badge, doc comments in TerminalPanes.cs/LoginLook.cs/TerminalTabPicker.cs, and tests in AccountDirsTests.cs/TerminalPanesTests.cs/TerminalTabPickerTests.cs) and MindAttic.Launcher (LoginLook.Badge() same colon change; Project.cs''s NamePrefix const currently only strips "MindAttic." -- extend it to also strip GTFO. and Unity.; update LoginLookTests.cs and any Project/WindowsTerminalLauncher tests asserting the old bracket format). Keep TerminalTabPicker.Normalize/PickTab tolerant of already-open tabs still titled in the old bracket format (back-compat for tabs opened before this ships).', 'e4c46e4 AccountDirsTests.A_tabs_title_drops_the_repos_leading_prefix', 631, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T633', 'MindAttic.Orchestrator', 633, '2026-10-22', 'feature', 'closed', 'Accounts view: replace each login card''s inline "Rename" button + inline textbox with a right-click ContextMenu offering "Rename", which opens a modal dialog instead. Modal has 3 fields: Email (read-only, hardcoded -- it''s always the account''s ID, never edited), Name (editable -- the alias shown as the card''s/button''s label in the Orchestrator; same value RenameLoginCommand/SaveLoginAliasCommand already save via LoginLook.SetAlias), and Prefix (editable -- the short badge used in terminal titles, e.g. "JR"; this already exists as the login JSON''s explicit "initials" override field read by LoginLook, just not exposed in any UI yet -- wire the modal''s Prefix field to read/write that same field instead of only auto-deriving initials from the alias). Save/Cancel in the modal call the same SaveAlias-style persistence as today. Remove the existing inline IsRenaming/AliasDraft textbox UI once the modal replaces it; keep the underlying SaveAlias(AccountDirs, folder, email, alias) logic, extended to also persist the initials override. Depends on M.ORCH-T632 landing first isn''t required but keep title-format conventions in mind.', '68167b6', 632, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T634', 'MindAttic.Orchestrator', 634, '2026-10-22', 'fix', 'closed', 'Dashboard tab-switch lag: switching either the person tabs (SelectedTab, one MainViewModel per signed-in login) or the five dashboard views within a tab (View.Agents/Repos/Queue/Audit/Accounts, MainViewModel.Phases.cs) must never block or visibly stall. Every tab''s and view''s data should stay loaded in memory once built rather than being torn down and reloaded on switch (e.g. ViewChoice setter currently fires RefreshLoginCardsAsync synchronously-ish only for Accounts; check for similar blocking refreshes on the other four views and on SelectedTab switch in MainViewModel.Tabs.cs). Where a refresh genuinely has to run (new data, a rescan), do it in the background and show a small loading spinner anchored at the bottom of that view (Agents/Repos/Queue/Audit/Accounts) instead of freezing the switch.', '06eb264', 633, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T635', 'MindAttic.Orchestrator', 635, '2026-10-22', 'fix', 'closed', 'Budget chart''s "at reset" projection label is misleadingly rounded: UtilizationChartData.cs''s ChartFor formats the projection as $"{u.ProjectedEndPercent:0}% at reset" (zero decimals), while the live reading right next to it uses one decimal ("now {Formatting.FiveHourPercent(u.NowPercent)}" e.g. "now 98.1%"). Reported case: current usage already 98.1% (over the 98% PaceTargetPercent default), yet the projection still displayed as a bare "98% at reset" because the underlying ProjectedEndPercent (something like 98.1-98.49) rounds down to 98, making an over-target landing look identical to hitting the target exactly. Pacing is supposed to land usage under PaceTargetPercent (98%) by reset, not somewhere between 98.0% and 99.0%, so the rounding is actively hiding a real overshoot from the user. Fix: give the projection label the same one-decimal precision as the "now" label (and double check Pacer''s spentOut/atTarget stop-gate math isn''t itself letting usage run past the target before reset, not just a display issue).', '462ab71', 634, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T636', 'MindAttic.Orchestrator', 636, '2026-10-22', 'feature', 'closed', 'Visually distinguish the peak-estimate 5h-block tile from a real known-limit one: when BudgetStatus.BlockLimitIsPeak is true, the stat tile shows a bold percent + orange progress bar (e.g. "100.0% of your busiest 5h block") styled identically to a real, precisely-known limit, right next to the 5-hour utilization chart which correctly refuses to draw anything and says "No 5-hour limit known yet, so there''s no pace to draw this window against" (Utilization.cs''s UtilizationSeries.Build returns null when BlockLimitIsPeak, MainViewModel.Phases.cs''s UtilizationCaption). The mismatch reads as broken/inconsistent (reported from a screenshot of Jordan''s tab: precise-looking 100.0% tile next to an empty chart). Give the peak-based tile a visually distinct treatment (muted color, an explicit "estimate" qualifier, etc.) from the BlockLimitIsPeak:false case so users can tell a real limit from a peak-only guess at a glance.', 'a19a951', 635, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T637', 'MindAttic.Orchestrator', 637, '2026-10-22', 'feature', 'closed', 'Move to carries the CLI''s subagents and locks its work until the move lands: when a CLI is moved to another login (M.ORCH-T607, agent card / Accounts / terminal tab Move to, orchestrator move), its in-flight subagents move with it: they''re stopped at once, their tickets stay claimed and their worktrees and uncommitted changes are kept, and once the CLI has restarted on the new login (restart-resume detected on that login) those tickets are handed back to it to re-dispatch in the same worktrees under the new person''s account; from the moment Move is chosen until then, the CLI and every ticket it or its subagents hold show ''Moving to <name>…'' and every action on them is disabled (Move to again, Start, Use as prompt, Send, Go to, approve/close from the dashboard, and orchestrator next/autopilot claiming them), released only when the migration is confirmed, or with an error and the old owner restored if it fails or times out', '27c95fc', 636, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T638', 'MindAttic.Orchestrator', 638, '2026-10-22', 'fix', 'closed', 'Move to looks like it does nothing: after picking an account the CLI keeps its old login and every control stays live until its next idle point, so it reads as a no-op; the moment a move is sent, lock that CLI''s controls (Go to tab, Move to, Send, ✕) on its agent card, its Accounts-view row and its terminal tab, and lay a translucent overlay over them reading ''Moving to <name>…'' with a library spinner, cleared when the CLI shows up on the new login, or after a timeout with a toast and the controls restored', '89fb219', 637, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T639', 'MindAttic.Orchestrator', 639, '2026-10-22', 'fix', 'closed', 'pace-gate.py''s /allocate Skill-tool refusal named the internal ''autopilot'' mark instead of the public /allocate command the user typed', 'HookScriptTests.An_autopilot_skill_call_is_recorded_only_when_the_user_asked_for_autopilot', 638, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T640', 'MindAttic.Orchestrator', 640, '2026-10-22', 'fix', 'closed', 'The ''There''s room to work again: orchestrator next has N workable tickets'' nudge fires repeatedly (3x in a row, 2026-10-22, tickets UH-T6/UH-T7/U.INC-T7/U.INC-T11 for an /allocate -repo=Unity.Hare,Unity.Chain,Unity.Incognito,Unity.Ricochet,Unity.QuickDuel CLI) while ''orchestrator next --claim'' for the same repos answers ''Nothing handed out: the pace has no room for another subagent right now'' each time; the nudge must use the same pace check as --claim so it only fires when a claim would succeed', 'f11b570', 639, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T641', 'MindAttic.Orchestrator', 641, '2026-10-22', 'fix', 'closed', 'Fails on main: MindAttic.Orchestrator.Tests.HookScriptTests.A_hook_reading_while_a_write_holds_the_database_falls_back_to_the_file_and_its_event_is_read_in_later — held by the file, not stuck on the database Assert.That(result.Took, Is.GreaterThanOrEqualTo(TimeSpan.FromSeconds(2.9)).And.LessThan(TimeSpan.FromSeconds(25))) Expected: greater than or equal to 00:00:02.9000000 and less than 00:00:25 But was: 00:00:25.0838062 (landed on main since the last green run: tickets M.ORCH-T629 in d4be597 Always show each person''s 5-hour chart: with nothing running on a login (no repo working, no agent working or with a subagent running) its tab''s utilization card draws the window as a flat line at its current % across the window''s span against the target line, labelled ''idle NN%'', captioned ''Idle: NN% of this 5-hour window used; nothing running on <name>''; a window that has reset or was never read is 0% over the next 5 hours from now (M.ORCH-T629))', '3845bfd', 640, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T642', 'MindAttic.Orchestrator', 642, '2026-10-22', 'fix', 'closed', 'Fails on main: MindAttic.Orchestrator.Tests.HookMarkTests.The_hooks_stop_on_the_probes_reading_in_the_database_when_the_statuslines_file_is_older — Traceback (most recent call last): File "C:\Users\ryand\AppData\Local\Temp\orch-marks-41ef4b4ce4dd485bbe22d41db5026cb4\hook-c57fe7c5987049b4aeb8d0e49ae17f62.py", line 1072, in <module> print(claude_stop()[0]) ~~~~~~~~~~~~~^^^ TypeError: ''NoneType'' object is not subscriptable Assert.That(p.ExitCod... (landed on main since the last green run: tickets M.ORCH-T641, M.ORCH-T640, M.ORCH-T629 in 3845bfd The hook gate stops waiting its full 5s on each database read once one has found the database held, so a held database no longer pushes it near the test''s limit (M.ORCH-T641); f11b570 The ''room to work again'' nudge now plans a CLI on its own login by that account''s pace, as its `next --claim` does, so it only fires when a claim would succeed (M.ORCH-T640); d4be597 Always show each person''s 5-hour chart: with nothing running on a login (no repo working, no agent working or with a subagent running) its tab''s utilization card draws the window as a flat line at its current % across the window''s span against the target line, labelled ''idle NN%'', captioned ''Idle: NN% of this 5-hour window used; nothing running on <name>''; a window that has reset or was never read is 0% over the next 5 hours from now (M.ORCH-T629))', '9e61061', 641, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T643', 'MindAttic.Orchestrator', 643, '2026-10-22', 'fix', 'closed', 'Fails on main: MindAttic.Orchestrator.Tests.HookMarkTests.The_stop_latch_file_is_read_in_once_into_its_state_row_and_kept_as_bak — the new latch and the file''s, in one row Assert.That(row!.ContainsKey("claude@") && row.ContainsKey("claude-week@"), Is.True) Expected: True But was: False (landed on main since the last green run: tickets M.ORCH-T641, M.ORCH-T640, M.ORCH-T629 in 3845bfd The hook gate stops waiting its full 5s on each database read once one has found the database held, so a held database no longer pushes it near the test''s limit (M.ORCH-T641); f11b570 The ''room to work again'' nudge now plans a CLI on its own login by that account''s pace, as its `next --claim` does, so it only fires when a claim would succeed (M.ORCH-T640); d4be597 Always show each person''s 5-hour chart: with nothing running on a login (no repo working, no agent working or with a subagent running) its tab''s utilization card draws the window as a flat line at its current % across the window''s span against the target line, labelled ''idle NN%'', captioned ''Idle: NN% of this 5-hour window used; nothing running on <name>''; a window that has reset or was never read is 0% over the next 5 hours from now (M.ORCH-T629))', '9e61061 (M.ORCH-T642 landed the same CLAUDE_CONFIG_DIR fix in HookMarkTests)', 642, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T644', 'MindAttic.Orchestrator', 644, '2026-10-22', 'fix', 'closed', 'Fails on main: MindAttic.Orchestrator.Tests.HookMarkTests.A_hook_reads_the_committed_latch_mid_write_and_a_write_while_held_goes_to_the_file_then_is_read_in — the next write reads the file in Assert.That(row.Select(kv => kv.Key), Is.EquivalentTo(new[] { "claude@", "claude-week@", "orchestrator@" })) Expected: equivalent to < "claude@", "claude-week@", "orchestrator@" > But was: < "claude@2544fa20-81fb-425b-9d08-f32c585a9205/96142256-0cfd-4191-90f1-9c79... (landed on main since the last green run: tickets M.ORCH-T641, M.ORCH-T640, M.ORCH-T629 in 3845bfd The hook gate stops waiting its full 5s on each database read once one has found the database held, so a held database no longer pushes it near the test''s limit (M.ORCH-T641); f11b570 The ''room to work again'' nudge now plans a CLI on its own login by that account''s pace, as its `next --claim` does, so it only fires when a claim would succeed (M.ORCH-T640); d4be597 Always show each person''s 5-hour chart: with nothing running on a login (no repo working, no agent working or with a subagent running) its tab''s utilization card draws the window as a flat line at its current % across the window''s span against the target line, labelled ''idle NN%'', captioned ''Idle: NN% of this 5-hour window used; nothing running on <name>''; a window that has reset or was never read is 0% over the next 5 hours from now (M.ORCH-T629))', '9e61061', 643, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T645', 'MindAttic.Orchestrator', 645, '2026-10-22', 'fix', 'closed', 'Fails on main: MindAttic.Orchestrator.Tests.HookMarkTests.The_account_record_is_a_row_the_hooks_and_the_orchestrator_share_and_its_file_is_still_written — Assert.That(Hook("""print(account()[0])"""), Is.EqualTo("B/O")) Expected string length 3 but was 73. Strings differ at index 0. Expected: "B/O" But was: "2544fa20-81fb-425b-9d08-f32c585a9205/96142256-0cfd-4191-90f1-..." -----------^ (landed on main since the last green run: tickets M.ORCH-T641, M.ORCH-T640, M.ORCH-T629 in 3845bfd The hook gate stops waiting its full 5s on each database read once one has found the database held, so a held database no longer pushes it near the test''s limit (M.ORCH-T641); f11b570 The ''room to work again'' nudge now plans a CLI on its own login by that account''s pace, as its `next --claim` does, so it only fires when a claim would succeed (M.ORCH-T640); d4be597 Always show each person''s 5-hour chart: with nothing running on a login (no repo working, no agent working or with a subagent running) its tab''s utilization card draws the window as a flat line at its current % across the window''s span against the target line, labelled ''idle NN%'', captioned ''Idle: NN% of this 5-hour window used; nothing running on <name>''; a window that has reset or was never read is 0% over the next 5 hours from now (M.ORCH-T629))', 'passes on main@9e61061', 644, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T646', 'MindAttic.Orchestrator', 646, '2026-10-22', 'fix', 'closed', 'Fails on main: MindAttic.Orchestrator.Tests.ContextCyclerTests.Only_the_cli_that_typed_autopilot_is_kept_going_on_its_own_repos_workable_tickets — the autopilot CLI goes on to its next tickets (the wildcard a* names A; fixes only: A-T4 awaits approval; B isn''t its repo) Assert.That(told, Does.Contain("\"block\"").And.Contain("2 workable tickets remain (A-T2, A-T3)").And.Contain("orchestrator next --repos \\\"a*\\\" --claim")) Expected: Stri... (landed on main since the last green run: tickets M.ORCH-T630, M.ORCH-T641, M.ORCH-T640, M.ORCH-T629 in 2c03cea Each person''s tab shows a status light (green usable, red signed out, purple any other state, its word in the tooltip) and its week left after the reserve, so who has room shows without opening it; an ''API key'' tab with an orange light now holds the API-key switch, today''s tokens billed to it and which CLIs bill it (M.ORCH-T630); 3845bfd The hook gate stops waiting its full 5s on each database read once one has found the database held, so a held database no longer pushes it near the test''s limit (M.ORCH-T641); f11b570 The ''room to work again'' nudge now plans a CLI on its own login by that account''s pace, as its `next --claim` does, so it only fires when a claim would succeed (M.ORCH-T640); d4be597 Always show each person''s 5-hour chart: with nothing running on a login (no repo working, no agent working or with a subagent running) its tab''s utilization card draws the window as a flat line at its current % across the window''s span against the target line, labelled ''idle NN%'', captioned ''Idle: NN% of this 5-hour window used; nothing running on <name>''; a window that has reset or was never read is 0% over the next 5 hours from now (M.ORCH-T629))', 'a6fc18f', 645, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T647', 'MindAttic.Orchestrator', 647, '2026-10-22', 'fix', 'closed', '[pace-ledger blind] window Oct 22 2:30 PM–7:30 PM closed blind: pdftransferjr@mindattic.com: Claude''s meter unseen for 1h while 191.7k were spent, peak 2%. The pace ran on its own estimate this long without Claude''s meter: make sure it gets a fresh reading whenever tokens are being spent.', 'ee45c29', 646, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T648', 'MindAttic.Orchestrator', 648, '2026-10-22', 'fix', 'closed', 'PacerTests starts the pace-gate hook at PacerTests.cs:316 and :355 without removing CLAUDE_CONFIG_DIR from the child environment, so run from a CLI on its own login the hook reads that account''s real usage instead of the test''s fake home (the same leak fixed in HookMarkTests by 9e61061 and ContextCyclerTests by a6fc18f); remove CLAUDE_CONFIG_DIR from psi.Environment after each USERPROFILE line', '2647c85', 647, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T649', 'MindAttic.Orchestrator', 649, '2026-10-22', 'chore', 'closed', 'Move the dashboard onto MindAttic.Components.Wpf 20.0.0: its tab strip and status light replace the person/page MaPillChoice strips, the hand-rolled TabStatusLight Ellipse and the terminal pane tab Border + badge chip (MainWindow.xaml, use MaBadge); switch the purple light from MaLink to MaOther (Palette.cs, MainViewModel.TabStatus.cs). Blocked on Components.Wpf 20.0.0 (tab strip, status light, MaOther) not yet packed to C:\LocalNuGet (latest 19.0.0). Then bump the PackageReference and tighten LibraryControlsTests.', 'c2b6497', 648, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T650', 'MindAttic.Orchestrator', 650, '2026-10-22', 'fix', 'closed', 'LibraryControlsTests'' hand-built-card check matches resource keys starting Mc, but every MindAttic.Components theme key starts Ma, so it never catches anything; switching it to Ma makes it fail on real hand-drawn cards/overlays in MainWindow.xaml (found by M.ORCH-T631''s review): fix the check to Ma and move those cards and overlays onto library controls so it passes', 'b22be0a', 649, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T651', 'MindAttic.Orchestrator', 651, '2026-10-22', 'fix', 'closed', 'Confirm the cause of the Oct 22 2:30-3:30 PM blind gap for pdftransferjr@mindattic.com (M.ORCH-T647 shortened ClaudeMeterProbe.Backoff to 2 min on the assumption it was failed asks, unverified): check ClaudeMeterProbe LastResult/asks for that login in that hour; if no asks were made, the gap is in Due/SeenAt (a login with tokens being spent not considered due) and must be fixed there, with a test that a login spending tokens is asked at least every PaceLedger.MinGap', '9059068', 650, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T652', 'MindAttic.Orchestrator', 652, '2026-10-22', 'fix', 'closed', 'Unity repos whose Packages/manifest.json uses sibling-relative file:../../<Repo> package paths (Unity.Chain, Unity.Ricochet, Unity.Cursory) can''t load from an orchestrator worktree (D:\Projects\MindAttic.worktrees\<Repo>\<ticket>), since ../../ resolves to MindAttic.worktrees; agents hand-swap the paths to absolute and back (UR-T3, UNI-T5), and the post-land full suite run from a worktree hits the same missing packages. Make worktrees resolve sibling packages, e.g. junction the referenced sibling repos into MindAttic.worktrees\<Repo>\ or nest worktrees at a depth where ../../ is the workspace root', '44e9c1f', 651, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T653', 'MindAttic.Orchestrator', 653, '2026-10-22', 'fix', 'closed', 'Fails on main: MindAttic.Orchestrator.Tests.HookScriptTests.A_hook_reading_while_a_write_holds_the_database_falls_back_to_the_file_and_its_event_is_read_in_later — held by the file, not stuck on the database Assert.That(result.Took, Is.GreaterThanOrEqualTo(TimeSpan.FromSeconds(2.9)).And.LessThan(TimeSpan.FromSeconds(25))) Expected: greater than or equal to 00:00:02.9000000 and less than 00:00:25 But was: 00:00:25.4735285 (landed on main since the last green run: tickets M.ORCH-T647, M.ORCH-T648, M.ORCH-T631 in ee45c29 Restore the meter probe''s line endings (M.ORCH-T647); 47c4320 Meter probe retries a failed ask after 2 minutes, not 15, so a window isn''t left unseen while tokens are spent (M.ORCH-T647); 2647c85 PacerTests'' pace-gate hook no longer inherits the agent''s CLAUDE_CONFIG_DIR, so a test run from a CLI on its own login reads the test''s fake home (M.ORCH-T648); bfd43c7 LibraryControlsTests is LF again (M.ORCH-T631); 040c039 LibraryControlsTests keeps its CRLF line endings (M.ORCH-T631))', '7563d69', 652, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T654', 'MindAttic.Orchestrator', 654, '2026-10-22', 'fix', 'closed', 'Switching person tabs (M.ORCH-T613) on the dashboard is slow, reported by the owner 2026-10-22: profile a tab switch (MainViewModel.Select -> MainWindow.xaml.cs:38 swaps the whole window DataContext to another MainViewModel, so every binding, ItemsControl, chart and tile re-binds/re-templates at once) and find the bottleneck: getters that read files/db or compute chart/status data on the UI thread during the re-bind (TabStatus, UtilizationChartData, tiles, repo/ticket lists), RefreshLoginCardsAsync on the Accounts view, ShowChosenPane re-hosting terminals, virtualization off on lists; fix it so a switch feels instant (target under ~100 ms to show the new tab), e.g. precompute per-tab data during the shared refresh, cache it, keep the tree and swap only the scoped data, or keep one realized view per tab, with a test or timing check that guards it', '1555364', 653, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T655', 'MindAttic.Orchestrator', 655, '2026-10-22', 'feature', 'closed', 'Organizations above people (approved by the owner 2026-10-22): add an org -> people -> logins model (an organizations table and a membership table; each login carries its LLM provider, so an org can hold users of other LLMs) with an org switcher above the person tabs; scope snapshots, pacing and the queue per org; make every dashboard list virtualized and scoped so a 9-person and a 2-person org switch equally fast (M.ORCH-T654 made a switch cost only what is on screen); put the per-org data behind the store interface of the SQL Server migration ticket so it lives in SQL Server', 'd56dac9; OrganizationsTests, OrchestratorServerTests.The_orgs_live_on_SQL_Server_and_a_schema_3_database_gains_their_tables_keeping_its_data, TabSwitchTests', 654, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T656', 'MindAttic.Orchestrator', 656, '2026-10-22', 'feature', 'wont-do', 'Move the orchestrator database to SQL Server (owner 2026-10-22: corporate-grade data gets a dedicated SQL Server instance; SQLite is for simple needs): add a SQL Server provider beside the SQLite one (keep SQLite working, selectable in settings), default to the full SQL Server instance on this machine (MSSQLSERVER, localhost; Prose uses LocalDB) with a database of its own, MindAttic.Orchestrator; a one-shot `orchestrator db migrate` that copies every table and row of data/orchestrator.db across and verifies counts; the Python hooks (pace-gate.py, context-gate.py) keep reading a local SQLite copy the daemon writes, since a SQL Server connect per tool call is too slow for their deadlines; decide what replaces the git-synced data/orchestrator.db and .sql (M.ORCH-T524); tests run against both providers', 'Replaced by M.ORCH-T658: it said Prose uses LocalDB; Prose is on the full MSSQLSERVER instance', 655, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T657', 'MindAttic.Orchestrator', 657, '2026-10-22', 'chore', 'closed', 'Audit the remaining SQLite users for SQL Server (owner 2026-10-22: SQLite only for simple needs, corporate-grade data on a dedicated SQL Server instance): Automata, JobHunt, MindAttic.Log, ProcessLogger and TaxRateCollector reference SQLite; for each, say what it stores, how big it gets and who reads it, then file a migration ticket in that repo for any that is corporate-grade and note why the rest stay on SQLite', '1537d85', 656, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T658', 'MindAttic.Orchestrator', 658, '2026-10-22', 'feature', 'closed', 'Move the orchestrator database to SQL Server (owner 2026-10-22: corporate-grade data gets a dedicated SQL Server instance; SQLite is for simple needs): add a SQL Server provider beside the SQLite one (keep SQLite working, selectable in settings), default to the full SQL Server instance on this machine that already holds Prose and the other app databases (MSSQLSERVER, localhost) with a database of its own, MindAttic.Orchestrator; a one-shot `orchestrator db migrate` that copies every table and row of data/orchestrator.db across and verifies counts; the Python hooks (pace-gate.py, context-gate.py) keep reading a local SQLite copy the daemon writes, since a SQL Server connect per tool call is too slow for their deadlines; decide what replaces the git-synced data/orchestrator.db and .sql (M.ORCH-T524); tests run against both providers', '76e572c', 657, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T659', 'MindAttic.Orchestrator', 659, '2026-10-23', 'fix', 'closed', '[pace-ledger blind] window Oct 23 12:20 AM–5:20 AM closed blind: shampoo1232@mindattic.com: Claude''s meter unseen for 25m while 1.3M were spent, peak 93%. The pace ran on its own estimate this long without Claude''s meter: make sure it gets a fresh reading whenever tokens are being spent.', '6d2cda5', 658, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T660', 'MindAttic.Orchestrator', 660, '2026-10-23', 'fix', 'closed', 'A per-CLI login with no limit learned yet (fresh or just-reset account, e.g. ryandebraal@mindattic.com at 0% with only 0% usage-samples) is planned Unpaced with SubagentAllowance null, so ''orchestrator next --claim'' falls back to MaxConcurrentSessions (6) minus plan.Queue.Count(Busy) across the WHOLE workspace (every other login''s CLIs'' tickets), and says ''the pace has no room for another subagent'' with 0 subagents on that login (Unity.Hare CLI 59240, 2026-10-23). Fix: in AccountPacer.Pace (Core/Budget/AccountPacer.cs) after Pacer.Compute, when pace is {IsPaced:false, SubagentAllowance:null, Stop:false} set SubagentAllowance = Max(1, Min(MaxConcurrentSessions, MaxSubagents)) and Subagents = its own marks'' count, so the login''s room is its own (Autopilot.Next''s fair-share/warm-up then apply); add a test that an unpaced own login hands out tickets while other logins hold 6+ busy tickets', '828b74f', 659, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T661', 'MindAttic.Orchestrator', 661, '2026-10-23', 'feature', 'closed', 'ClaudeMeterProbe.Due (Core/Budget/ClaudeMeterProbe.cs) only asks Claude''s meter while a login has recent spend events or its running window''s percent rose within ActiveFor (30 min), so a signed-in but idle account (e.g. Ryan, fresh/just-reset, 2 agents Working but 0 events seen on its own login) never gets probed, AccountPacer never learns its block limit, and its dashboard tile shows ''No 5-hour limit known yet, so there''s no pace to draw this window against'' even while other logins show real percents; with all 4 logins signed in, periodically probe every one (even idle) so every account''s exact 5h/weekly percent and utilization graph can be drawn, not just the active ones', 'c1d876c / ClaudeMeterProbeTests.An_idle_login_is_asked_and_asked_again_after_IdleEvery', 660, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T662', 'MindAttic.Orchestrator', 662, '2026-10-23', 'feature', 'closed', 'Rename the (global) login label to (fallback) everywhere it''s shown (dashboard tab title, login card, agent/host login text, Accounts view''s Make default button and captions): it''s the account used when none is specified, and (global) read as confusing/misleading', '—', 661, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T663', 'MindAttic.Orchestrator', 663, '2026-10-23', 'feature', 'wont-do', 'Weekly-aware pacing toggle (setting, off by default, shown clearly in Settings and every pace note as ''Pacing: weekly-aware''; per login in AccountPacer): each 5-hour window''s target becomes min(PaceTargetPercent of the 5-hour limit, the week''s room to 98% of its weekly limit spread over the 5-hour windows left before the weekly reset), so a roomy week still runs windows to 98% and a tight one lowers each window''s ceiling so the week lands at 98% at its reset; the 5-hour-to-weekly ratio (how much of the week one 5-hour point costs) is learned per login from readings where both percents rose together, falling back to today''s 5-hour-only pacing until learned; next --claim and autopilot hand out a ticket only when its estimate fits min(5-hour room, weekly room) (a week at 96% gets only small tickets or none); the weekly line gets the same wind-down (finish or ticket it) and a hard stop at 98% (replacing the 95% weekly-reserve stop while the toggle is on); the dashboard says which limit governs (''capped by the week: 31% of this window''); tests: tight week caps the window, roomy week leaves 98%, week at 96% refuses a ticket estimated past its room, toggle off changes nothing', 'Superseded by M.ORCH-T665 (weekly considered only from 75%, tickets turned over to a login with room)', 662, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T664', 'MindAttic.Orchestrator', 664, '2026-10-23', 'feature', 'closed', 'Emergency failover to the fallback (API key): when a CLI''s login hits its 5-hour or weekly limit (or the pace says Stop) and no signed-in login has room (AccountRebalancer, Core/Sessions/AccountRebalancer.cs, today does nothing then), move that one CLI onto the API key through the Launcher''s restart-resume with API-key billing for that CLI only (the global billing mode unchanged), resuming its session where it left off; a limit error mid-turn (seen in its transcript or the Launcher''s exit) resumes at once on the API key instead of waiting for an idle point; toast and log each failover (''U.SPC CLI moved to API key: Ryan''s week at 98%''); move it back to its login once that login resets so the API key (no rate ceiling, only cost) bills only the gap; tests: low login with no other room fails over to the API key, a login with room is still preferred, a mid-turn limit error resumes on the API key, the CLI moves back after the reset', 'f83531a; AccountRebalancerTests', 663, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T665', 'MindAttic.Orchestrator', 665, '2026-10-23', 'feature', 'wont-do', 'Weekly-aware pacing (supersedes M.ORCH-T663; a clear toggle in Settings and every pace note, per login in AccountPacer): always target 98% of each 5-hour window; while a login''s week is under 75% nothing else changes; from 75% the week is taken in too, each 5-hour window''s ceiling becoming min(98% of its 5-hour limit, the week''s room to 98% of its weekly limit spread over the 5-hour windows left before the weekly reset), so the week lands at 98% at its reset and neither limit is ever hit; the 5-hour-to-weekly ratio (how much of the week one 5-hour point costs) is learned per login from readings where both percents rose together, falling back to 5-hour-only pacing until learned; next --claim and autopilot hand a ticket to a login only when its estimate fits min(5-hour room, weekly room) and otherwise turn it over to a signed-in login that can fit it (most headroom first) instead of letting it wait, so tickets keep flowing across accounts; the weekly line gets the same wind-down (finish or ticket it) and a hard stop at 98% (replacing the 95% reserve stop while on); the dashboard says which limit governs (''capped by the week: 31% of this window''); tests: week under 75% unchanged, tight week past 75% caps the window, week at 96% turns a big ticket over to a login with room, toggle off changes nothing', 'Superseded by M.ORCH-T666 (adds the API-key fallback when no login has capacity)', 664, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T666', 'MindAttic.Orchestrator', 666, '2026-10-23', 'feature', 'closed', 'Weekly-aware pacing (supersedes M.ORCH-T665 and M.ORCH-T663; a clear toggle in Settings and every pace note, per login in AccountPacer): always target 98% of each 5-hour window; while a login''s week is under 75% nothing else changes; from 75% the week is taken in too, each 5-hour window''s ceiling becoming min(98% of its 5-hour limit, the week''s room to 98% of its weekly limit spread over the 5-hour windows left before the weekly reset), so the week lands at 98% at its reset and neither limit is ever hit; the 5-hour-to-weekly ratio (how much of the week one 5-hour point costs) is learned per login from readings where both percents rose together, falling back to 5-hour-only pacing until learned; next --claim and autopilot hand a ticket to a login only when its estimate fits min(5-hour room, weekly room), otherwise redelegate it to another signed-in login that can fit it (most headroom first), and only if none has the capacity fall back to the API key (the fallback login), so tickets never wait on a full account; the weekly line gets the same wind-down (finish or ticket it) and a hard stop at 98% (replacing the 95% reserve stop while on); the dashboard says which limit governs (''capped by the week: 31% of this window'') and when a ticket was redelegated or fell back; tests: week under 75% unchanged, tight week past 75% caps the window, week at 96% redelegates a big ticket to a login with room, with no login with room it goes to the API key, toggle off changes nothing', 'ba1b41e', 665, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T667', 'MindAttic.Orchestrator', 667, '2026-10-23', 'feature', 'closed', 'Library-only dashboard UI: every element in MindAttic.Orchestrator.Wpf comes from MindAttic.Components.Wpf (its Ma* controls, or a plain WPF control with a library Ma* style), configured only through the library''s settings; replace the raw controls with no library style (10 of 52 Buttons, 4 of 13 ListBoxes, 14 of 31 Borders, all 39 ItemsControls and 7 ScrollViewers in MainWindow.xaml) and move the dashboard''s own styles (StatValue, RepoTile, TileTemplate, BodyScroll, TicketLink) to the library''s equivalents from M.COMP-T52; add a test that fails when any XAML element is neither a library control nor library-styled, so it can''t drift back', 'c2b6497', 666, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T668', 'MindAttic.Orchestrator', 668, '2026-10-23', 'feature', 'closed', 'Tickets per user: under each user''s tab (below its open CLIs) a Tickets view lists that user''s assigned tickets and the unassigned queue, built from MindAttic.Components.Wpf controls (the user picker from M.COMP-T52); assign a ticket to a user, or reassign an assigned one to another user, from there; the assignment records the user''s login (Assignment gains its account email), and next --claim, autopilot and Start dispatch it only on that login; an assigned ticket is a pin: when its user is out of room it waits for them (its card says it''s waiting and why, e.g. ''waiting for Ryan: week at 97%'') and is never redelegated by M.ORCH-T666 unless you press its ''Redelegate now'' override, which hands it on like an unassigned ticket (another user with room, else the API key); unassigned tickets keep T666''s redelegation; tests: assign and reassign record the login, dispatch honours it, a pinned ticket waits instead of redelegating, Redelegate now hands it on', '9c4df73', 667, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T669', 'MindAttic.Orchestrator', 669, '2026-10-23', 'feature', 'closed', 'Tune weekly-aware pacing (M.ORCH-T666) so it makes the most of every token for one organization and isn''t slow all the time: below the 75% weekly line nothing is held for the week; past it, the hold grows only as far as needed so the week reaches 98% seconds to minutes before its weekly reset (not hours early), measured per login against its own reset; when room is scarce (5-hour or weekly) it goes to higher-priority tickets first and lower-priority ones wait behind them (the queue''s priority, orchestrator bump), within each user''s own assigned tickets too; log and show each window''s planned vs actual end percent so the curve can be dialed in; tests: a week at 80% with days left isn''t held, one near its reset ends at 98% within minutes of it, a scarce window starts the +10 ticket before the 0 one', 'cc79dc1 (WeeklyAwarePacingTests)', 668, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T670', 'MindAttic.Orchestrator', 670, '2026-10-23', 'feature', 'closed', 'Organization membership in the database: a members table in data/orchestrator.db (email key, name, role, tier, status active/pending, joined/updated times; added through OrchestratorDb''s migrations, OrchestratorServer.Tables and the dump like the other tables, so a column is one more migration step) is the one source of who''s in the organization; seeded with today''s five (Ryan DeBraal ryandebraal@mindattic.com Primary owner Premium; Amy shampoo1232@mindattic.com Admin Premium; Erin ohleo199@mindattic.com Admin Premium; Honey honey@mindattic.com Admin Premium; Jordan pdftransferjr@mindattic.com Admin Premium); the dashboard''s person tabs come from it (a member not signed in on this machine gets its Sign in tab, as M.ORCH-T615 does for roster accounts), each titled by its member name (else its login alias, else the email''s part before the @); orchestrator members lists them and add/set/remove edit them (name, role, tier, status), each change written to the database and the dump; the accounts table stays the machine''s sign-in/meter record, joined to members by email; tests: the seed, add/set/remove round-trip through the database and dump, a member with no sign-in gets a Sign in tab named for the member', '833cf60', 669, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T671', 'MindAttic.Orchestrator', 671, '2026-10-23', 'fix', 'closed', 'orchestrator members'' ''Signed in here'' column says no for a member whose per-CLI login is signed in (honey@mindattic.com, signed in with orchestrator login --account minutes before, 2026-10-23): it only joins the accounts table (the fallback login''s sign-ins), so a member signed in only through its own folder under ~/.claude-accounts (AccountDirs.SignedIn) reads as not signed in; count either, and say which (own login / fallback login), with a test', 'MemberRosterTests.The_members_command_adds_sets_lists_and_removes_members_in_the_live_database (1aa957d)', 670, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T672', 'MindAttic.Orchestrator', 672, '2026-10-23', 'fix', 'closed', 'The ''(fallback)'' marker sits on the global ~/.claude login''s tab (''ohleo199 (fallback)'', Erin''s account) while billing is the API key (orchestrator login --api-key, 2026-10-23), but then the fallback, the login a CLI started with no account uses, is the API key: LoginScope.Tabs (Core/Sessions/LoginScope.cs) marks the global login''s tab unconditionally; while billing is API key, mark the API key tab ''(fallback)'' and title the global login''s tab like any member''s (its member name, e.g. ''Erin''); while billing is Claude Team, the global login''s tab keeps it; same for the agent/host login text (StatusAggregator.LoginText) and the Accounts view; tests for both billing modes', '461297c', 671, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T673', 'MindAttic.Orchestrator', 673, '2026-10-23', 'fix', 'closed', 'The pace and subagent allowance treat every open CLI as billing whichever account logged in last, so a CLI on its own per-CLI login is held back by another account''s spend: orchestrator billing lists Unity.SpaceGod (pid 72544) as Claude Team ohleo199@mindattic.com while its session bills honey@mindattic.com, and orchestrator next --claim there says the pace has no room although honey''s account has spent nothing today. Each CLI''s budget, pace, limits, weekly reserve and subagent allowance must come from the account that CLI itself runs on (its own per-CLI login''s token pool), not the global or most recent login, and orchestrator billing must show each CLI''s own account.', '66cb9d0', 672, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T674', 'MindAttic.Orchestrator', 674, '2026-10-23', 'fix', 'closed', 'orchestrator next --claim''s fair share (Autopilot.Next, M.ORCH-T495) splits one subagent allowance across every /allocate CLI that wants tickets, though each CLI bills its own login with its own 5-hour and weekly limits (2026-10-23: this CLI, on the fallback/API key, was held to ''4 running of 7 across 3 CLIs'' while the other two CLIs ran on Honey''s and Amy''s own logins); share the allowance only among CLIs on the same login, each login''s room being its own pace''s (AccountPacer), with a test', '74a2421', 673, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T675', 'MindAttic.Orchestrator', 675, '2026-10-23', 'fix', 'closed', 'A person''s tab and dashboard disagree on how much of the week is left: the tab''s far-right figure (MainViewModel.TabWeekLeftOf, TabStatus.cs:63) takes the M.ORCH-T609 reserve off first (stop line 95 - used), while the weekly card (WeeklyHeadlineOf, Phases.cs:356) shows 100 - used, so Ryan DeBraal at 4% used reads ''91% left'' on the tab and ''96% left'' on the card, and Jordan at 94% reads ''1% left'' and ''6% left''. The tab must show the same weekly % left as the card (100 - used); the reserve stays where the card already shows it, in ''stops at 95%''. Update TabStatusTests to match.', 'b586d51', 674, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T676', 'MindAttic.Orchestrator', 676, '2026-10-23', 'fix', 'closed', 'Billing went back from the API key to Claude Team on its own (switched to API key at 10:01 with orchestrator login --api-key, read Claude Team: ohleo199 ''since 10:04 AM'' on 2026-10-23), undoing the user''s choice of the API key as the standing fallback for CLIs with no account: BillingSwitch.Tick (Core/Billing/BillingSwitch.cs) switches back to Team whenever the global ~/.claude login''s identity differs from the one signed in when the key was chosen; with the API key as the fallback that''s wrong: keep API-key billing until the user switches it back (orchestrator login <account>, the dashboard''s toggle), log a /login seen on the global login without switching, and find what signed the global login in at ~10:04 (an orchestrator login, a CLI''s /login, a restart) so it doesn''t recur; tests: a /login on the global login leaves API-key billing on, an explicit switch to Team still works', '2281509', 675, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T677', 'MindAttic.Orchestrator', 677, '2026-10-23', 'fix', 'closed', 'Switching billing (orchestrator login --api-key, the dashboard''s toggle) restarts every live CLI onto the new mode, own-login CLIs included: BillingSwitch.RequestRestarts (Core/Billing/BillingSwitch.cs) asks the Launcher to restart each CLI whose billing differs from the mode, skipping only failed-over ones, so with three CLIs on Ryan''s, Amy''s and Honey''s own logins (2026-10-23) a switch to the API key fallback would have moved all three off their own accounts; the billing mode governs only CLIs on the global ~/.claude login (the fallback): leave a CLI on its own per-CLI login alone, with a test', 'da29c52', 676, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T678', 'MindAttic.Orchestrator', 678, '2026-10-23', 'feature', 'closed', 'Dark mode by default with a sun/moon switch in the dashboard''s upper-right corner: the Orchestrator opens in the dark theme unless you chose light, the library''s MaThemeToggle (from M.COMP-T53) sits in the window''s upper-right corner and switches between dark and light at once without restarting, and the choice is kept in the orchestrator''s settings (database) so it holds across restarts; every view follows it, built only from library pieces (M.ORCH-T667); tests: dark when nothing is set, the toggle switches and saves, a saved light choice is used at start', 'ThemeChoiceTests (e537125)', 677, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T679', 'MindAttic.Orchestrator', 679, '2026-10-23', 'fix', 'closed', 'Fails on main: TicketsDesktopTests.Each_ticket_id_in_the_window_is_a_link_into_tickets_desktop expects five ticket links in MainWindow.xaml, but M.ORCH-T668 (9c4df73) added a sixth (the per-user Tickets view''s ticket id); update the test to the window''s links as they are now, checking the new one opens in Tickets Desktop too', 'c0ad7d3', 678, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T680', 'MindAttic.Orchestrator', 680, '2026-10-23', 'feature', 'closed', 'Weekly-aware pacing''s numbers become settings, edited in the dashboard''s Settings modal (library controls only, M.ORCH-T667) and the CLI, saved in the database: its on/off toggle (WeeklyAwarePacing, today CLI-only); its weekly target, which is 100 minus the existing weekly reserve (WeeklyReservePercent, default 5, so 95%: the user keeps 5% of each account''s week for everyday questions in the Claude app and claude.ai), replacing the fixed WeeklyAwareStopPercent = 98 everywhere it''s used (WeeklyPacing.Cap and WeeklyCap, Pacer''s wind-down, the context gate''s stop line in AgentGate.cs, the settings/budget notes); the line from which the week is taken in (today the constant WeeklyAwareLinePercent = 75); and the wind-down, a margin below the target (today 98 vs 95, so default 3 points); each validated (target 50-100, line below target, margin 0-20); the Settings modal shows them together under Weekly pacing with what each does; tests: defaults give 95/75/92, a changed reserve moves the target and the gate''s stop, the modal round-trips them', '45c8696', 679, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T681', 'MindAttic.Orchestrator', 681, '2026-10-23', 'feature', 'closed', 'Past a login''s line, its work goes straight to the fallback (the API key), so no one is left unable to ask questions: when a login reaches its 5-hour pace target (98%) or its weekly target (100 minus the weekly reserve, now 90%), every CLI on it moves to the API key at once, at its next tool call rather than its next idle point and instead of the pace gate refusing its calls, keeping its session; not to another person''s login (AccountRebalancer, M.ORCH-T664, today prefers a login with 10+ points more headroom), so each person''s own remainder stays theirs; it moves back when that login''s window resets; the fallback must be the API key for this (billing API mode; say so plainly when it isn''t); toast and log each move (''Unity.SpaceGod moved to the API key: Honey''s week at 90%''); needs the Launcher to honour per-CLI billing restarts (M.LNCH-T67); tests: at 98% of the 5-hour window and at 90% of the week the CLI is moved to the key with no other login preferred, it moves back after the reset, nothing moves when the fallback isn''t the API key', '6a80766 AccountRebalancerTests.At_98_percent_of_the_5_hour_window_the_cli_moves_to_the_key_at_once_with_no_other_login_preferred', 680, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T682', 'MindAttic.Orchestrator', 682, '2026-10-23', 'feature', 'closed', 'Detect a member using Claude outside the orchestrator (the desktop app, claude.ai, a phone) and get out of their way, so no one is ever interrupted while using Claude: per login, compare the rise in Claude''s meter (5-hour and weekly percent, read every few minutes even while idle, M.ORCH-T661) with what that login''s orchestrated CLIs spent by their transcripts over the same stretch (converted with the login''s learned tokens per percent); a rise beyond the CLIs'' share and a noise margin is outside use; while it lasts, and until about 30 minutes after it stops, move that login''s CLIs onto the API key at once (M.ORCH-T681''s failover) so the person has the whole remaining window, then move them back; toast and log it (''Honey is using Claude: her CLIs moved to the API key''); record each member''s outside use per window and week, show the averages in the Accounts view, and suggest the 5-hour and weekly reserves from them; IP addresses aren''t available (the meter has no per-device data), so it''s done by subtraction; tests: a meter rise the CLIs explain changes nothing, an unexplained rise moves that login''s CLIs to the key and back after the quiet period, stats are recorded', '1cb9ca5', 681, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T683', 'MindAttic.Orchestrator', 683, '2026-10-23', 'fix', 'closed', 'The context gate hook (context-gate.py on UserPromptSubmit, Stop, PostToolUse, SubagentStart/Stop, SessionStart) is registered with a 10-second timeout (AgentGate.cs Install, a literal 10), and on a pegged machine it timed out on a user''s prompt (''UserPromptSubmit hook timed out after 10s, output discarded'', 2026-10-23), losing the pace and subagent notes; give it a named ContextHookTimeoutSeconds of 60 so a busy machine is waited for, with the installer still rewriting a stale 10 to it, and a test', '813e174', 682, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T684', 'MindAttic.Orchestrator', 684, '2026-10-23', 'fix', 'closed', 'Erin''s login (ohleo199@mindattic.com, the global ~/.claude login) hasn''t had a meter reading in about 20 hours (last 2026-10-22 21:54 UTC, week ~90-91%) while the four own logins are read every few minutes (M.ORCH-T661): with billing on the API key no CLI runs on the global login, and its probe isn''t reaching the meter; read the global login''s meter on the same idle schedule whatever the billing mode (its OAuth token in ~/.claude/.credentials.json is still Erin''s), so every member''s week and 5-hour figures stay current, and say plainly on its tab when a login''s reading is stale', 'eb6d713', 683, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T685', 'MindAttic.Orchestrator', 685, '2026-10-23', 'feature', 'closed', 'Usage report: orchestrator report (and a Report button in the dashboard''s Accounts view, library controls only) prints a table of every member: name and email, 5-hour used/left and its reset, week used/left, left to the weekly target, and its reset, how fresh each reading is (marked stale past 15 minutes, with its source: Claude''s meter or estimated), what the orchestrator''s CLIs spent on that login today and this week versus the member''s own outside use (M.ORCH-T682), and the API key''s spend; --since <date>, --csv and --json; the same report as a Markdown/HTML file to share; tests', 'UsageReportTests (cecd0ed, 58054c1)', 684, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T686', 'MindAttic.Orchestrator', 686, '2026-10-23', 'feature', 'closed', '/organization and /org, global commands for the organization (installed by AgentGate.Ensure into ~/.claude/commands as organization.md and org.md beside /pacing, /allocate and /crossrepo, each only invoking the CLI) over a new orchestrator org command: /org usage prints the member usage table exactly as the coordinator gave it on 2026-10-23 (Member | 5-hour used | 5h resets | Week used | Week left | Left to the weekly target | Week resets | Reading age | Accurate?, then one short line each for members at or past their weekly target, near it, and with stale readings), from M.ORCH-T685''s report; /org login <who> signs that member in (orchestrator login --account <email>); /org members lists them (and add/set/remove as orchestrator members does); /org start <repo> <who> starts a CLI on that member''s login; <who> resolves any member by email, the part before the @ (ohleo199), member name (Erin, Ryan DeBraal), first name, login alias or initials (RD, E), case-insensitive, and an ambiguous or unknown one lists the matches instead of guessing; /org with no subcommand or /org help lists the subcommands; tests: name resolution for each form and ambiguity, the command files are installed and only call the CLI', '28b6077 OrgCommandTests', 685, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T687', 'MindAttic.Orchestrator', 687, '2026-10-23', 'fix', 'closed', 'Erin''s (global ~/.claude login''s) meter is still never read after M.ORCH-T684 (eb6d713) was deployed: her OAuth token was refreshed (~/.claude/.credentials.json now expires 3:52 PM CDT 2026-10-23), yet 10+ minutes later orchestrator report still shows her reading 20 hours old and ''the meter wasn''t asked since'', and the meter-probe state row lists only the four own logins, never the global probe; with billing on the API key and no CLI on the global login, find why the global ClaudeMeterProbe doesn''t ask (its Due/IdleDue, its account key, the API-key billing mode, or its never being ticked), make it ask on the same idle schedule as the own logins, record it in the meter-probe row, and confirm on this machine that Erin''s reading turns fresh; test', 'fa34950', 686, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T688', 'MindAttic.Orchestrator', 688, '2026-10-23', 'feature', 'closed', 'orchestrator report / /org usage: a ''Week resets in'' column right after ''Week resets'', counting down to each member''s weekly reset (''1d 2h 14m'', ''4d 19h 22m'', ''19h 22m'', ''14m''), because the reset dates alone don''t say how long is left; the at-target note gives it too', '6221f54', 687, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T689', 'MindAttic.Orchestrator', 689, '2026-10-23', 'feature', 'closed', 'orchestrator report / /org usage: remove the ''Left to <target>% target'' column from the main table (the user asked for it gone); the at-target, near-target and plenty-of-room notes under the table still give the points left, and --csv/--json keep left_to_target', '—', 688, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T690', 'MindAttic.Orchestrator', 690, '2026-10-23', 'feature', 'closed', 'orchestrator report / /org usage: replace the ''Reading'' and ''Accurate?'' columns with one ''Last updated'' column (''just now'', ''3m ago'', ''2hr 44m ago'', ''1d 3hr ago'', ''never''); a stale reading is still called out in the note under the table and highlighted in the HTML report', '—', 689, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T691', 'MindAttic.Orchestrator', 691, '2026-10-23', 'feature', 'closed', 'orchestrator report / /org usage: remove the ''Week resets'' date column from the main table; ''Week resets in'' (the countdown) says it more clearly, and the reset date stays in --csv/--json and the at-target note', '—', 690, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T692', 'MindAttic.Orchestrator', 692, '2026-10-23', 'feature', 'closed', 'orchestrator report / /org usage: a member read fresh with no 5-hour window running shows 0% and 0 for its 5-hour figures instead of ''—'' (a stale window that has reset still reads ''unknown''), and the fallback login''s member is named like everyone else, without ''(~/.claude login)''', '—', 691, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T693', 'MindAttic.Orchestrator', 693, '2026-10-23', 'feature', 'closed', 'orchestrator report / /org usage: remove the ''Week used'' column; the user only needs what remains (''Week left''), and the used percent stays in --csv/--json', '—', 692, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T694', 'MindAttic.Orchestrator', 694, '2026-10-23', 'feature', 'closed', 'A login with less than its weekly reserve left (under 10% of its week, past the 90% target) is off the table until its weekly reset unless the user explicitly says otherwise: add /org allow <who> [--until <reset|time>] (orchestrator org allow) to let that one member''s login take work past its weekly target, and /org disallow <who> to take it back; an allowance ends at that login''s weekly reset by default, is saved in the database, shows in /org usage (e.g. ''Erin: allowed past the target by you until Tue 5:00 PM'') and is logged; nothing else (rebalancing, redelegation, autopilot) may lift it; <who> resolves as /org does; tests: a login under 10% left gets no ticket and its CLIs stop, /org allow lets it take work until its reset, /org disallow and the reset end it', '06de65a', 693, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T695', 'MindAttic.Orchestrator', 695, '2026-10-23', 'feature', 'closed', 'orchestrator report / /org usage: a member with no 5-hour window running (none has started since the last ended: Claude''s window opens on the first message after the previous one) shows ''—'' in both 5-hour columns again, not 0% / 0, since nothing is running or being wasted; reverts M.ORCH-T692''s 0', '—', 694, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T696', 'MindAttic.Orchestrator', 696, '2026-10-23', 'feature', 'closed', 'Wire ''claude setup-token'' long-lived logins into per-person logins. Spike T627 found: setup-token mints a one-year OAuth token, printed once and not saved; it bills the seat''s own Pro/Max/Team/Enterprise subscription allowance (not an API key) but is inference-only (no Remote Control, no claude.ai connectors/schedule). Claude Code reads it from env CLAUDE_CODE_OAUTH_TOKEN, ranked above the folder''s /login .credentials.json, so it composes with CLAUDE_CONFIG_DIR per tab by setting both in that tab''s environment (the token, not the folder, picks the account; keep one token per folder). Do: orchestrator login --account <email> / Sign in runs claude setup-token, captures the token and stores it in MindAttic.Vault (never plaintext, never in .credentials.json); the Launcher''s per-tab environment sets CLAUDE_CODE_OAUTH_TOKEN from the Vault next to CLAUDE_CONFIG_DIR; unset ANTHROPIC_API_KEY/AUTH_TOKEN in the tab; /status must show the expected account; warn ~30 days before the one-year expiry and re-mint on expiry or revocation. Bare mode ignores the token. Unverified, test first: revocation path (docs don''t say; assume revoking the app in claude.ai settings), and whether minting signs out the seat''s other devices (docs say only ''claude setup-token'' enforces forceLoginMethod; /login of a claude.ai account signs out a machine''s earlier profile only for Console keyless flow).', 'd877c03 LoginTokensTests', 695, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T697', 'MindAttic.Orchestrator', 697, '2026-10-23', 'fix', 'closed', 'orchestrator members --json prints the members table instead of JSON (seen 2026-10-23 by the coordinator and by M.LNCH-T48''s agent, which needed members'' names for the Launcher''s login menu); make --json print the members as a JSON array (email, name, role, tier, status, signed-in-here and which login), the same through orchestrator org members --json, with a test', '6da1501', 696, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T698', 'MindAttic.Orchestrator', 698, '2026-10-23', 'fix', 'closed', 'orchestrator accounts alias renames only the login (its alias in the login folder) and leaves the member''s name in the members table as it was, while the dashboard''s Rename (M.ORCH-T633, 68167b6) updates both; make the CLI do the same as the dashboard (same code path), with a test', '3a8c51a', 697, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T699', 'MindAttic.Orchestrator', 699, '2026-10-23', 'feature', 'closed', 'One terminal tab per account: every Claude login in the org gets its own terminal tab, opened with a Launcher already signed in to that account (its per-login CLAUDE_CONFIG_DIR) and left idle (no repo, no prompt) for the user to drive; an account that already has its tab reuses it instead of opening a second', '3cb4f16', 698, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T700', 'MindAttic.Orchestrator', 700, '2026-10-23', 'feature', 'closed', 'Offer a bug hunt when a repo''s queue runs dry, never start one unasked: when /allocate is on in a repo and it has no open tickets left, the CLI asks the user whether to run /bughunt on that repo and hunts only after an explicit yes; each bug the hunt finds becomes a ticket that /allocate then works', '30f3e28; AutopilotTests.A_dry_queue_offers_a_bug_hunt_and_leaves_it_to_the_user', 699, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T701', 'MindAttic.Orchestrator', 701, '2026-10-23', 'feature', 'closed', 'Sync member info from claude.ai: each member''s name (and the other profile fields claude.ai gives for the login, such as email) is read from their Claude account''s profile at sign-in and periodically after, and always overwrites the members table''s stored value', '4462d13 MemberProfileSyncTests', 700, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T702', 'MindAttic.Orchestrator', 702, '2026-10-23', 'feature', 'closed', 'Psst on outside use: when outside-use detection (M.ORCH-T682) flags a watched login, text a chosen recipient with Psst (''psst sms'') once per outside-use stretch (not every tick); start with Jordan''s login watched and Ryan as the recipient; which logins are watched and who gets the text are settings in the Settings modal and the CLI', '6a9706e', 701, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T703', 'MindAttic.Orchestrator', 703, '2026-10-23', 'fix', 'closed', 'Fails on main: LoginScopeTests.A_toast_is_tagged_with_its_tab_and_a_logins_color_is_its_accent: a theme type initializer throws UriFormatException (seen by M.ORCH-T699''s agent, failing the same way without its change)', '6e882ad', 702, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T704', 'MindAttic.Orchestrator', 704, '2026-10-23', 'fix', 'closed', 'Flaky: TerminalPanesTests.A_pane_runs_its_command_in_a_real_terminal_and_closing_it_ends_the_process fails now and then because closing a pane throws when its process has already exited; closing a pane whose process is gone should be a no-op (seen by M.ORCH-T699''s agent)', '65a4779', 703, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T705', 'MindAttic.Orchestrator', 705, '2026-10-23', 'fix', 'closed', 'Fails on main: MindAttic.Orchestrator.Tests.SettingsModalTests.Settings_open_in_the_shared_McModal_last_in_the_root_grid — Assert.That((string?)modal.Attribute("IsOpen"), Is.EqualTo("{Binding IsSettingsOpen}")) Expected string length 24 but was 22. Strings differ at index 11. Expected: "{Binding IsSettingsOpen}" But was: "{Binding IsRenameOpen}" ----------------------^ (landed on main since the last green run: tickets M.ORCH-T699, M.ORCH-T700, M.ORCH-T698, M.ORCH-T694, M.ORCH-T633, M.ORCH-T697, M.ORCH-T636, M.ORCH-T632, M.ORCH-T695, M.ORCH-T693, M.ORCH-T692, M.ORCH-T691, M.ORCH-T690, M.ORCH-T689, M.ORCH-T688, M.ORCH-T687, M.ORCH-T686, M.ORCH-T682, M.ORCH-T685 in 3cb4f16 One terminal tab per account: each signed-in login gets a dashboard pane running the Launcher signed in to it, idle, reused rather than doubled (M.ORCH-T699); 30f3e28 allocate: when a repo''s queue runs dry, offer a /bughunt and hunt only on an explicit yes, filing each bug as a fix ticket (M.ORCH-T700); 3a8c51a accounts alias: restore LoginLook.cs''s line endings and catch ArgumentException like the dashboard (M.ORCH-T698); ba55cac accounts alias: rename through the dashboard''s code path so the member''s name follows the login''s (M.ORCH-T698); 06de65a org allow/disallow: let one member''s login take work past its weekly target until its reset (M.ORCH-T694); 68167b6 Accounts view: Rename from a login card''s right-click menu, in a dialog with Email, Name and Prefix (M.ORCH-T633); 6da1501 members --json prints the members as a JSON array (also via org members): the branch needed the option too (M.ORCH-T697); a19a951 5-hour tile: a peak-only figure reads as an estimate, not a known limit (M.ORCH-T636); e4c46e4 Tab titles: "JR: EZ [Claude]", colon badge and the repo''s GTFO./MindAttic./Unity. prefix dropped (M.ORCH-T632); 6caaf38 Usage report: ''â€”'' in both 5-hour columns when no window is running (M.ORCH-T695); 2994eec Usage report: drop the ''Week used'' column; only what remains matters (M.ORCH-T693); 98e9fa7 Usage report: 0 for no 5-hour window running, and no ''(~/.claude login)'' label (M.ORCH-T692); 6a95834 Usage report: drop the ''Week resets'' date column; the countdown says it (M.ORCH-T691); 78b3a68 Usage report: one ''Last updated'' column in place of ''Reading'' and ''Accurate?'' (M.ORCH-T690); f6e71ab Usage report: drop the ''Left to target'' column (M.ORCH-T689); 6221f54 Usage report: a ''Week resets in'' countdown beside each weekly reset (M.ORCH-T688); fa34950 Meter probe: a login with no 5-hour window running (idle) answers with only its week, which is a reading, not "no reading"; the global login''s probe is recorded in the meter-probe row (M.ORCH-T687); 28b6077 /org and /organization: global commands over a new orchestrator org (usage = the usage report, login <who>, members, start <repo> <who>, help), with <who> any member by email, the part before the @, name, first name, login alias or initials, and an ambiguous or unknown one listing who it could be (M.ORCH-T686); 58054c1 Usage report''s outside use is what the daemon measured for each login (M.ORCH-T682''s averages, "using Claude now" while it lasts), not "not measured yet" (M.ORCH-T685); cecd0ed Usage report: orchestrator report (and the Accounts view''s Report button) prints one row per member: 5-hour used and reset, week used/left, left to the weekly target, week reset, reading age and whether it''s accurate (stale past 15 min), with lines for who''s at the target, paced, has room or is stale; --detail adds the source, the CLIs'' spend today/this week against outside use (not measured until M.ORCH-T682) and the API key''s; --since, --csv, --json, --md/--html to share; the old token report is now orchestrator tokens (M.ORCH-T685))', 'dd81f49', 704, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T706', 'MindAttic.Orchestrator', 706, '2026-10-23', 'fix', 'closed', 'Hard-code the owner''s usage rules instead of leaving them as settings: (1) no weekly-aware pacing, ever: never stretch a login''s remaining week across the days left (it capped a window at 5% with 25% of the week unused); (2) hard cutoffs only: run each login to 98% of its 5-hour window and 90% of its week, then cut off access and ask the owner what to do, with no throttling, agent holds or front-loaded curves before that; (3) never fail over to the Vault API key automatically: API billing is for actual emergencies only and only the owner switches it on (it switched REA.Bloodlines to the API key on 2026-10-23 just because a 5-hour window was used up). Remove or lock the settings that contradict these (--weekly-aware, --failover, --throttle-agents, pace profiles) so they can''t silently come back.', 'e81deaf', 705, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T707', 'MindAttic.Orchestrator', 707, '2026-10-23', 'fix', 'closed', 'Per-user usage cutoffs, with CLI commands to set them (part of M.ORCH-T706): the default cutoff is 90% of a login''s week and 98% of its 5-hour window, and there is no 75% take-in line (drop it from pacing and from the ''Past the 75% line'' wording in org usage/report). The only way to change a cutoff is an explicit per-user command, e.g. ''orchestrator org limit <who> --weekly <pct> --5h <pct>'' (and ''--reset'' back to the 90/98 defaults), with ''orchestrator org limit'' alone listing each member''s cutoffs. Show each member''s cutoff in org usage. Below the cutoff nothing throttles; at it, access is cut off and the owner is asked.', '739f984', 706, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T708', 'MindAttic.Orchestrator', 708, '2026-10-23', 'fix', 'closed', 'PowerShell quoting in tab commands only doubles ASCII '': SessionControl.cs:188-189/:241-243 and AccountDirs.Ps (:310) leave the curly quotes U+2018-U+201B, which PowerShell also treats as single-quote delimiters, so a prompt, title or folder with â€™ (e.g. ticket text ''donâ€™t touch the build'') breaks the tab''s -EncodedCommand script or runs the rest as PowerShell; escape them too (found by bughunt)', 'f1c8180', 707, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T709', 'MindAttic.Orchestrator', 709, '2026-10-23', 'fix', 'closed', 'LoginTokens hangs: Run (:197-210) has no timeout, so a dashboard mint (stdout redirected, no console prompt visible) can block its Task.Run forever; StatusEmail (:220-223) reads stdout then stderr to end before WaitForExit(30_000), so the timeout never fires and a full stderr pipe can deadlock; read both streams asynchronously and kill on timeout (found by bughunt)', 'LoginTokensTests', 708, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T710', 'MindAttic.Orchestrator', 710, '2026-10-23', 'fix', 'closed', 'LoginTokens.Find/Mask (:197-210): with stdout redirected ''claude setup-token'' may hard-wrap the ~108-char sk-ant-oat01 token across lines, so Find saves a truncated token that then outranks the folder login for a year, and Mask (line by line) prints the second fragment unmasked; join wrapped token lines before matching and masking, and reject a token that fails a length/shape check (found by bughunt)', '6d532c9', 709, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T711', 'MindAttic.Orchestrator', 711, '2026-10-23', 'fix', 'closed', 'Login tokens can wipe each other: LoginTokens (:66, :84-93) builds a new Vault TokenStore per access, so its in-process lock never serializes two saves, and TokenStore.LoadAllLocked turns any read failure (sharing violation) into an empty map that Set then writes back; two mints at once or a read during File.Replace silently drops every other login''s token. Serialize across processes (named mutex/file lock) and never save after a failed read (found by bughunt)', 'LoginTokensTests.Saves_from_many_threads_keep_every_login_s_token (1f6df4a)', 710, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T712', 'MindAttic.Orchestrator', 712, '2026-10-23', 'fix', 'closed', 'Panes inherit a token or API key: SessionControl.PaneRequestFor''s plain global-login pane (:185-186) runs without TokenEnv(null) or removing CLAUDE_CONFIG_DIR (the resume path does both), and LauncherPaneRequest (:125-127, M.ORCH-T699) never applies TokenEnv, so a dashboard started from a per-CLI tab with CLAUDE_CODE_OAUTH_TOKEN/ANTHROPIC_API_KEY set bills that seat from every global pane (found by bughunt)', '698070c', 711, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T713', 'MindAttic.Orchestrator', 713, '2026-10-23', 'fix', 'closed', 'TerminalPanes pipe server: AnswerAsync (:123-142) only catches IO/cancel/disposed, so any other exception from open(request) faults the fire-and-forget task with no reply or log and the caller waits 30s then fails without the Windows Terminal fallback; ServeAsync (:103-120) doesn''t dispose the pipe when WaitForConnectionAsync throws (a handle per 5s retry) and lets UnauthorizedAccessException end pane serving (found by bughunt)', '9a37bb8', 712, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T714', 'MindAttic.Orchestrator', 714, '2026-10-23', 'fix', 'closed', 'AccountDirs.Link (:340-341) runs ''cmd /d /c mklink /J <link> <target>'' and .NET only quotes args with spaces or quotes, so an account folder with & ^ | (allowed by Normalize, e.g. a&b@x.com) splits the cmd line and runs part of it as a command; quote the paths for cmd or create the junction without cmd (found by bughunt)', 'fe16a72', 713, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T715', 'MindAttic.Orchestrator', 715, '2026-10-23', 'fix', 'closed', 'LoginTokens.MintFor''s wrong-account guard (:176-179) runs ''claude auth status'' with CLAUDE_CONFIG_DIR set to the already-signed-in folder, so it may report the folder''s account rather than the new token''s, and a token minted for another person is kept for this login; check the token itself (CLAUDE_CODE_OAUTH_TOKEN set for the status call) (found by bughunt)', '58369a5', 714, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T716', 'MindAttic.Orchestrator', 716, '2026-10-23', 'fix', 'closed', 'orchestrator db migrate --connection with a malformed string throws ArgumentException from SqlConnectionStringBuilder (OrchestratorServer.cs:211), which DbCommands.cs:73 doesn''t catch, so Program.cs:34''s crash handler logs the whole command line including the SQL password and exits 1; catch it as a bad option (exit 2) and never log raw args that may hold secrets (found by bughunt)', '447bf058 CliCommandTests.A_malformed_connection_string_is_a_bad_option_that_is_never_echoed', 715, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T717', 'MindAttic.Orchestrator', 717, '2026-10-23', 'fix', 'closed', 'orchestrator login --account <email> on a seat already signed in as itself reruns the browser ''claude auth login'' (LoginCommand.cs:147''s ''&& newToken'' is inverted against its comment and against --all), and signing in as someone else there signs the folder out; skip the login and only mint a token when needed, as --all does (found by bughunt)', 'eaf2783', 716, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T718', 'MindAttic.Orchestrator', 718, '2026-10-23', 'fix', 'closed', 'orchestrator login: a failed token mint (Failed/NoToken/WrongAccount) still exits 0 (LoginCommand.cs:151-154, :165; SignInAll ignores Token.Ok), and --new-token without --account/--all is silently ignored (:88-135); exit non-zero on a failed mint and refuse --new-token where it can''t apply (found by bughunt)', '6ec19e4', 717, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T719', 'MindAttic.Orchestrator', 719, '2026-10-23', 'fix', 'closed', 'Daemon''s orchestrator.db sync (Daemon.cs:734-737) stages under HoldingWrites but commits with ''git commit -- data/orchestrator.db data/orchestrator.sql'', which commits the working tree, not the index, outside the lock, so a write between add and commit lands a torn database (what M.ORCH-T536 meant to stop); commit what was staged, under the lock (found by bughunt)', 'a91bfa3', 718, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T720', 'MindAttic.Orchestrator', 720, '2026-10-23', 'fix', 'closed', 'A failed settings read runs the daemon tick on defaults: Daemon.cs:77/:357 and StatusAggregator.cs:269 use LoadSettings, which swallows DbException/JsonException and returns new OrchestratorSettings() (one bad settings row does it every tick), so autopilot/keep-going/MaxSubagents and the outside-use Psst run on defaults and EnsureHooks rewrites hooks with them; skip the tick''s settings-driven work when the read fails, as Daemon.cs:67 already does (found by bughunt)', 'de30fa3 StatusAggregatorTests.Settings_unreadable_for_a_refresh_keep_the_last_ones_read', 719, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T721', 'MindAttic.Orchestrator', 721, '2026-10-23', 'fix', 'closed', 'The daemon''s push retry (Daemon.cs:726, :759-762) runs ''git merge origin/main'' in the user''s main checkout and ''git merge --abort'' on any failure, so while the user is resolving a merge (MERGE_HEAD present) it aborts it and throws away their resolutions; skip the retry when a merge, rebase or cherry-pick is in progress (found by bughunt)', '8de4d53', 720, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T722', 'MindAttic.Orchestrator', 722, '2026-10-23', 'fix', 'closed', 'Two daemons (logon daemon plus ''orchestrator daemon'', SchedulingCommands.cs:315, no mutex) both run RunAuditIfDue, SyncTicketsDbIfDue, SyncOrchestratorDbIfDue, MirrorIfDue and GitHub intake (Daemon.cs:219-242) in the same checkout, colliding on index.lock and undoing each other''s reset/merge --abort; take a lease (or a single-instance mutex) for these steps (found by bughunt)', '1f3e1f9', 721, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T723', 'MindAttic.Orchestrator', 723, '2026-10-23', 'fix', 'closed', 'A failed audit read hides new findings: AuditRunner.Latest (:48-51) returns null when the store read fails, Daemon.cs:527 then runs and saves a new audit, and AuditNews.Between(null, after) reports nothing, so drift found in that run is never alerted; skip the run when the previous audit can''t be read (found by bughunt)', '64f23eb', 722, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T724', 'MindAttic.Orchestrator', 724, '2026-10-23', 'fix', 'closed', 'remind --at now on the night clocks go back is stored an hour late: ReminderTime.cs:35-40 converts ''now'' back to UTC through local time, which reads the ambiguous hour as standard time; ''now'' should be nowUtc directly (found by bughunt)', 'da7f9dc', 723, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T725', 'MindAttic.Orchestrator', 725, '2026-10-23', 'fix', 'closed', 'PaceLedgerWatch.cs:92-99 drops the already-recorded rows of any account that also has a per-CLI folder before grading global windows, so when ~/.claude and a per-CLI folder share an account every global window of it is re-reported each minute and an over window raises the urgent ''Window went over'' alert every minute (found by bughunt)', '9160a08', 724, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T726', 'MindAttic.Orchestrator', 726, '2026-10-23', 'fix', 'closed', 'ClaudeMeterProbe.Write (:447) merges with ReportedUsage.Load, which picks the newer of the statusline file and the db row, so a stale untagged claude-usage.json restamped by an idle tab makes the probe overwrite its own higher reading for the same window with a lower one (seen by UsageReport/AccountRoster); merge against the probe''s own row for that account (found by bughunt)', 'aa499ee', 725, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T727', 'MindAttic.Orchestrator', 727, '2026-10-23', 'fix', 'closed', 'OpenTicketSource (:84, :35, :50): a first read of Tickets.db that fails (locked past the busy timeout) has no cache to fall back on and yields no open tickets, so after a daemon restart Scheduler.Plan marks every claim in the repo Finished and Autopilot.Reap deletes them (another CLI can then claim the same ticket), and ''orchestrator next'' says the queue ran dry; treat a failed read as unknown, not empty (found by bughunt)', 'd42fc1d', 726, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T728', 'MindAttic.Orchestrator', 728, '2026-10-23', 'fix', 'closed', 'orchestrator next --repos all: Autopilot.Dry() (:487) treats ''all'' as every repo but Named() (:518, :740-741) matches it literally, so nothing matches and it reports ''these repos ran dry'' and offers a bug hunt (M.ORCH-T700) with tickets open; normalise ''all'' (and say when a named repo matches nothing) (found by bughunt)', 'b00cee3 AutopilotTests.Repos_all_is_every_repo_and_an_unknown_name_is_said', 727, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T729', 'MindAttic.Orchestrator', 729, '2026-10-23', 'fix', 'closed', 'TicketQueue (:49-52, :64-69, :96-101) and QueueImport (:40-41) load settings, change them and save the whole object with no store.Update transaction (TicketPins.Set uses one), so an approve or bump racing assign, a Settings save or another bump loses the other change (two bumps lose an increment); do them in a transaction (found by bughunt)', '81507f7', 728, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T730', 'MindAttic.Orchestrator', 730, '2026-10-23', 'fix', 'closed', 'pace-gate (AgentGate.cs:2330, locked() at :2287-2304): has_lock = TX is None and locked(), and when locked() gives up after 15s it still counts and takes a slot unlocked, so with the db held >3s a burst of parallel Agent calls can pass a 1-2 allowance (the M.ORCH-T197 race); refuse (or retry) when the lock isn''t taken (found by bughunt)', '704b0ab', 729, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T731', 'MindAttic.Orchestrator', 731, '2026-10-23', 'fix', 'closed', 'MainlineTests: Tested = done.Head (:94) is recorded even when the run didn''t complete (timeout, persistent MSB3027, dotnet failed to start, Prepare error), so that head is never retested and a broken main isn''t filed; and the mainline name cached in mainlines[name] (:105) is never refreshed, so after a default-branch rename the repo''s suite silently stops running until restart (found by bughunt)', '217cddb', 730, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T732', 'MindAttic.Orchestrator', 732, '2026-10-23', 'fix', 'closed', 'Autopilot.cs:564-565: when paced and the CLI can''t be resolved (no MINDATTIC_CLI_PID, no claude.exe ancestor), ''more = allowance - Pace.Subagents'' ignores claims with no subagent yet (the fair-share block at :568 is skipped), so each next --claim hands out the full allowance again; count unstarted claims there too (found by bughunt)', '91ba731, 97cdb0e', 731, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T733', 'MindAttic.Orchestrator', 733, '2026-10-23', 'fix', 'closed', 'Dashboard: panes are re-sorted onto login tabs only when the tab count changes (MainViewModel.Tabs.cs:104, :123), so when one login''s tab goes and another''s arrives in the same refresh, the gone login''s panes show on no tab and the new login''s existing panes don''t appear; re-sort when the set of logins changes (found by bughunt)', '1d377ef', 732, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T734', 'MindAttic.Orchestrator', 734, '2026-10-23', 'fix', 'closed', 'Dashboard leak: each login tab''s MainViewModel (:139) and TerminalsViewModel (:342) subscribe to the static PendingMoves.Changed and AllTerminals.PropertyChanged and never unsubscribe, so every sign-out/sign-in leaves the old view models alive and handling every move event; unsubscribe when a tab is removed (found by bughunt)', 'f929979', 733, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T735', 'MindAttic.Orchestrator', 735, '2026-10-23', 'fix', 'closed', 'Dashboard terminals: TerminalsViewModel.Forget (:201-202) and Drop (:324-325) swallow a failed delete of pane records with no log, so dismissed or closed panes are silently offered for Reopen next start (Save beside them logs a warning); log it. And the pane tooltip (:80) reads Record but nothing raises PropertyChanged when Update replaces Record (:59, :299), so it never shows the session (found by bughunt)', '1f21b99', 734, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T736', 'MindAttic.Orchestrator', 736, '2026-10-23', 'fix', 'closed', 'Dashboard: M.ORCH-T699''s per-account Launcher panes get the repo-pane buttons (MainWindow.xaml:1216-1225, MainViewModel.Tabs.cs:185-188, MainWindow.xaml.cs:132): ''Go to'' opens the MindAttic.Launcher repo tile and ''Move to'' says the CLI ''isn''t running any more''; hide them on Launcher panes (IsLauncher) (found by bughunt)', 'f3f49f9', 735, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T737', 'MindAttic.Orchestrator', 737, '2026-10-23', 'fix', 'closed', 'Dispatcher.cs:222 links with the same unquoted ''cmd /d /c mklink /J'' pattern M.ORCH-T714 fixed in AccountDirs.Link, so a repo folder name with & ^ | splits the cmd line; use AccountDirs.TryMklinkArguments there too (seen by M.ORCH-T714''s agent)', '9d3e8e2', 736, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T738', 'MindAttic.Orchestrator', 738, '2026-10-23', 'fix', 'closed', 'Fails on main: MindAttic.Orchestrator.Tests.WorkspaceBootstrapTests.Cancelling_stops_the_install_instead_of_reporting_every_app_timed_out — TearDown : System.IO.IOException : The process cannot access the file ''\\?\C:\Users\ryand\AppData\Local\Temp\orch-boot-5e5e3b328c6b44de8fe629f5a33f1643\ws\A'' because it is being used by another process. (landed on main since the last green run: tickets M.ORCH-T704, M.ORCH-T696, M.ORCH-T703, M.ORCH-T702, M.ORCH-T701, M.ORCH-T699, M.ORCH-T700, M.ORCH-T698, M.ORCH-T694, M.ORCH-T633, M.ORCH-T697, M.ORCH-T636, M.ORCH-T632, M.ORCH-T695, M.ORCH-T693, M.ORCH-T692, M.ORCH-T691, M.ORCH-T690 in 65a4779 Pane close: keep the file''s line endings and drop the HasExited guard so a live process is always killed (M.ORCH-T704); c7690d6 Closing a terminal pane whose process already exited is a no-op, so the pane test stops flaking (M.ORCH-T704); d877c03 Per-CLI logins mint a year-long setup-token, kept DPAPI-sealed in the Vault and set as CLAUDE_CODE_OAUTH_TOKEN in their tabs, so a seat stays signed in for a year (M.ORCH-T696); 6e882ad Palette: register the pack:// scheme before MaTheme''s initializer so tests don''t throw UriFormatException (M.ORCH-T703); 6a9706e Psst on outside use: text the chosen recipient once when a watched login starts being used outside the orchestrator, Jordan''s watched and Ryan texted by default, both settings in the modal and the CLI (M.ORCH-T702); 4462d13 members: sync each member''s name and role from claude.ai at sign-in and hourly after, overwriting the table (M.ORCH-T701); 3cb4f16 One terminal tab per account: each signed-in login gets a dashboard pane running the Launcher signed in to it, idle, reused rather than doubled (M.ORCH-T699); 30f3e28 allocate: when a repo''s queue runs dry, offer a /bughunt and hunt only on an explicit yes, filing each bug as a fix ticket (M.ORCH-T700); 3a8c51a accounts alias: restore LoginLook.cs''s line endings and catch ArgumentException like the dashboard (M.ORCH-T698); ba55cac accounts alias: rename through the dashboard''s code path so the member''s name follows the login''s (M.ORCH-T698); 06de65a org allow/disallow: let one member''s login take work past its weekly target until its reset (M.ORCH-T694); 68167b6 Accounts view: Rename from a login card''s right-click menu, in a dialog with Email, Name and Prefix (M.ORCH-T633); 6da1501 members --json prints the members as a JSON array (also via org members): the branch needed the option too (M.ORCH-T697); a19a951 5-hour tile: a peak-only figure reads as an estimate, not a known limit (M.ORCH-T636); e4c46e4 Tab titles: "JR: EZ [Claude]", colon badge and the repo''s GTFO./MindAttic./Unity. prefix dropped (M.ORCH-T632); 6caaf38 Usage report: ''â€”'' in both 5-hour columns when no window is running (M.ORCH-T695); 2994eec Usage report: drop the ''Week used'' column; only what remains matters (M.ORCH-T693); 98e9fa7 Usage report: 0 for no 5-hour window running, and no ''(~/.claude login)'' label (M.ORCH-T692); 6a95834 Usage report: drop the ''Week resets'' date column; the countdown says it (M.ORCH-T691); 78b3a68 Usage report: one ''Last updated'' column in place of ''Reading'' and ''Accurate?'' (M.ORCH-T690))', 'bcabef1', 737, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T739', 'MindAttic.Orchestrator', 739, '2026-10-23', 'fix', 'wont-do', 'Fails on main: MindAttic.Orchestrator.Tests.SettingsModalTests.Settings_open_in_the_shared_McModal_last_in_the_root_grid — Assert.That((string?)modal.Attribute("IsOpen"), Is.EqualTo("{Binding IsSettingsOpen}")) Expected string length 24 but was 22. Strings differ at index 11. Expected: "{Binding IsSettingsOpen}" But was: "{Binding IsRenameOpen}" ----------------------^ (landed on main since the last green run: tickets M.ORCH-T704, M.ORCH-T696, M.ORCH-T703, M.ORCH-T702, M.ORCH-T701, M.ORCH-T699, M.ORCH-T700, M.ORCH-T698, M.ORCH-T694, M.ORCH-T633, M.ORCH-T697, M.ORCH-T636, M.ORCH-T632, M.ORCH-T695, M.ORCH-T693, M.ORCH-T692, M.ORCH-T691, M.ORCH-T690 in 65a4779 Pane close: keep the file''s line endings and drop the HasExited guard so a live process is always killed (M.ORCH-T704); c7690d6 Closing a terminal pane whose process already exited is a no-op, so the pane test stops flaking (M.ORCH-T704); d877c03 Per-CLI logins mint a year-long setup-token, kept DPAPI-sealed in the Vault and set as CLAUDE_CODE_OAUTH_TOKEN in their tabs, so a seat stays signed in for a year (M.ORCH-T696); 6e882ad Palette: register the pack:// scheme before MaTheme''s initializer so tests don''t throw UriFormatException (M.ORCH-T703); 6a9706e Psst on outside use: text the chosen recipient once when a watched login starts being used outside the orchestrator, Jordan''s watched and Ryan texted by default, both settings in the modal and the CLI (M.ORCH-T702); 4462d13 members: sync each member''s name and role from claude.ai at sign-in and hourly after, overwriting the table (M.ORCH-T701); 3cb4f16 One terminal tab per account: each signed-in login gets a dashboard pane running the Launcher signed in to it, idle, reused rather than doubled (M.ORCH-T699); 30f3e28 allocate: when a repo''s queue runs dry, offer a /bughunt and hunt only on an explicit yes, filing each bug as a fix ticket (M.ORCH-T700); 3a8c51a accounts alias: restore LoginLook.cs''s line endings and catch ArgumentException like the dashboard (M.ORCH-T698); ba55cac accounts alias: rename through the dashboard''s code path so the member''s name follows the login''s (M.ORCH-T698); 06de65a org allow/disallow: let one member''s login take work past its weekly target until its reset (M.ORCH-T694); 68167b6 Accounts view: Rename from a login card''s right-click menu, in a dialog with Email, Name and Prefix (M.ORCH-T633); 6da1501 members --json prints the members as a JSON array (also via org members): the branch needed the option too (M.ORCH-T697); a19a951 5-hour tile: a peak-only figure reads as an estimate, not a known limit (M.ORCH-T636); e4c46e4 Tab titles: "JR: EZ [Claude]", colon badge and the repo''s GTFO./MindAttic./Unity. prefix dropped (M.ORCH-T632); 6caaf38 Usage report: ''â€”'' in both 5-hour columns when no window is running (M.ORCH-T695); 2994eec Usage report: drop the ''Week used'' column; only what remains matters (M.ORCH-T693); 98e9fa7 Usage report: 0 for no 5-hour window running, and no ''(~/.claude login)'' label (M.ORCH-T692); 6a95834 Usage report: drop the ''Week resets'' date column; the countdown says it (M.ORCH-T691); 78b3a68 Usage report: one ''Last updated'' column in place of ''Reading'' and ''Accurate?'' (M.ORCH-T690))', 'duplicate of M.ORCH-T705 (dd81f49), filed by a suite run that started before it landed', 738, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T740', 'MindAttic.Orchestrator', 740, '2026-10-23', 'fix', 'closed', 'orchestrator next still says a repo''s queue ''ran dry'' (and offers a bug hunt, M.ORCH-T700) when its Tickets.db read failed: M.ORCH-T727 marks such repos unknown in OpenTicketSource/Snapshot.UnknownRepos, but Autopilot.Dry() doesn''t check it; say the tickets couldn''t be read instead (left open by M.ORCH-T727''s agent)', '0579e03', 739, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T741', 'MindAttic.Orchestrator', 741, '2026-10-23', 'fix', 'closed', 'Finish M.ORCH-T706''s hard cutoffs: (1) the 90% 5-hour ''wind-down'' (only start work that can finish) is still on, a throttle before the 98% cutoff the owner ruled out, so remove it; (2) README''s usage report, tickets-per-user and /org sections still describe weekly-aware redelegation; (3) drop the retired settings rows (weekly-aware, throttle-agents, failover, pace profile/curve) from the settings table so they can''t confuse readers (left open by M.ORCH-T706''s agent)', '78644d0', 740, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T742', 'MindAttic.Orchestrator', 742, '2026-10-23', 'fix', 'closed', 'Finish M.ORCH-T707''s per-user cutoffs: (1) when a login reaches its weekly or 5-hour cutoff, cut it off and ask the owner what to do (an urgent alert plus a Psst text to the owner, once per crossing, naming ''org allow''/''org limit''); nothing notifies today; (2) AccountRebalancer still uses the global 5-hour target instead of each login''s ''org limit --5h'' cutoff; (3) the global login falls back to the 90/98 defaults when its profile email isn''t read yet, ignoring that member''s custom cutoffs (left open by M.ORCH-T707''s agent)', '435f846', 741, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T743', 'MindAttic.Orchestrator', 743, '2026-10-23', 'fix', 'closed', 'Remove the dead wind-down left after M.ORCH-T741: the WindDown* properties on the pace object, the gate script''s wind_down_note check in AgentGate.cs (never written now), and the WPF Settings hint that still mentions weekly-aware pacing (M.ORCH-T706 retired it)', '2f7b6e6', 742, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T744', 'MindAttic.Orchestrator', 744, '2026-10-23', 'fix', 'closed', 'Fails on main: MindAttic.Orchestrator.Tests.DaemonSafetyTests.The_real_runner_does_not_wait_past_its_timeout_on_a_grandchild_holding_the_pipes — its output was cut short, so it isn''t taken as a success with none Assert.That((r.ExitCode, r.TimedOut), Is.EqualTo((0, true))) Expected: (0, True) But was: (-1, True) (landed on main since the last green run: tickets M.ORCH-T733, M.ORCH-T729, M.ORCH-T727, M.ORCH-T726, M.ORCH-T722, M.ORCH-T721, M.ORCH-T724, M.ORCH-T723, M.ORCH-T719, M.ORCH-T717, M.ORCH-T718, M.ORCH-T716, M.ORCH-T714, M.ORCH-T710, M.ORCH-T715, M.ORCH-T711, M.ORCH-T708, M.ORCH-T712, M.ORCH-T713 in 1d377ef Dashboard re-sorts panes onto login tabs when the set of logins changes, not only the count, so a swap in one refresh keeps every pane on a tab (M.ORCH-T733); 97b945d Restore LF line endings in the T729 edits (M.ORCH-T729); 5068886 TicketQueue and QueueImport change settings in one store.Update transaction, so an approve or bump racing another settings write loses nothing (M.ORCH-T729); d42fc1d A first ticket-database read that fails marks the repo''s open tickets unknown, so claims there aren''t planned as finished and reaped (M.ORCH-T727); aa499ee ClaudeMeterProbe.Write merges against the probe''s own db row, not the newer of statusline file and row, so an idle tab''s restamped stale reading can''t make it overwrite a higher reading (M.ORCH-T726); 1f3e1f9 Daemon: a git-chores lease so only one daemon runs the audit, db syncs, mirror and GitHub intake, which collided on index.lock in the same checkout (M.ORCH-T722); 8de4d53 Daemon db push retry skips the merge while a merge, rebase, cherry-pick or revert is in progress, so it no longer aborts the user''s resolution (M.ORCH-T721); da7f9dc remind --at now is nowUtc directly, so the ambiguous hour when clocks go back isn''t read an hour late (M.ORCH-T724); 64f23eb Scheduled audit is skipped when the previous audit can''t be read, so a failed read no longer hides new findings (M.ORCH-T723); a91bfa3 The orchestrator.db sync commits right after staging, inside the database''s write lock, so a write between add and commit can''t land a torn database (M.ORCH-T719); eaf2783 login --account on a seat already signed in as itself skips the browser login and only mints a token when needed (M.ORCH-T717); 6ec19e4 login exits non-zero when a token mint fails and refuses --new-token without --account/--all, so scripts can''t mistake a missing token for success (M.ORCH-T718); 447bf05 db migrate says a malformed --connection is a bad option (exit 2) instead of crashing, and the crash log names only the command, never its options, so a SQL password can''t land in the log (M.ORCH-T716); fe16a72 Quote the mklink paths for cmd.exe so & ^ / in an account folder name can''t split the command line (M.ORCH-T714); 6d532c9 LoginTokens.Find/Mask join a hard-wrapped token across lines and reject one outside the token length, so a truncated token is never saved or half-printed (M.ORCH-T710); 58369a5 LoginTokens status check runs in an empty scratch config folder so the account''s own sign-in can''t answer for the token being checked (M.ORCH-T715); 1f6df4a Login tokens: one shared store, a cross-process mutex around each read-modify-write, and no save after a failed read, so concurrent mints stop wiping other logins (M.ORCH-T711); f1c8180 PowerShell quoting doubles the curly quotes U+2018-U+201B too, so a prompt, title or folder with a typographic apostrophe can''t break a tab''s script (M.ORCH-T708); 698070c Every pane clears the inherited config dir and applies the login''s token, so a dashboard started from a per-CLI tab can''t bill that seat from global panes (M.ORCH-T712); 9a37bb8 Pane pipe: answer any exception from open(), dispose the pipe on a failed listen and keep serving on UnauthorizedAccess (M.ORCH-T713))', 'd016ef0', 743, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T745', 'MindAttic.Orchestrator', 745, '2026-10-23', 'fix', 'closed', 'Settings modal still shows the retired weekly fields: the weekly wind-down margin and the 75% take-in line (WeeklyPacing.WindDown and its settings) belong to the weekly-aware pacing M.ORCH-T706 locked off and M.ORCH-T707 replaced with per-user ''org limit'' cutoffs (the CLI already refuses them); remove the fields, their hints and the dead WeeklyPacing wind-down code (seen by M.ORCH-T743''s agent)', '56c0bd8', 744, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T746', 'MindAttic.Orchestrator', 746, '2026-10-23', 'fix', 'closed', 'Fails on main: MindAttic.Orchestrator.Tests.WeeklyAllowanceTests.The_rebalancer_leaves_an_allowed_logins_cli_on_it_and_never_fails_over — held to the target: past it, it still never fails over to the API key (M.ORCH-T706) Assert.That(Rebalancer().Tick(null, [], [], failover, Now), Is.Empty) Expected: <empty> But was: < <Rebalanced { Moved = False, Line = rebalance: Erin reached its weekly cutoff (92% of the week, cutoff 90%) and is... (landed on main since the last green run: tickets M.ORCH-T745, M.ORCH-T743, M.ORCH-T744, M.ORCH-T742, M.ORCH-T741, M.ORCH-T738, M.ORCH-T707, M.ORCH-T730, M.ORCH-T740, M.ORCH-T732, M.ORCH-T706, M.ORCH-T725, M.ORCH-T737 in 56c0bd8 Remove the retired weekly take-in line and wind-down margin from the Settings modal, and the dead WeeklyCap wind-down code, since weekly-aware pacing is locked off (M.ORCH-T745); 2f7b6e6 Review fixes: keep HookScriptTests line endings, re-point its resume check at a held CLI, drop the dangling ''on or off'' from the weekly target hint (M.ORCH-T743); 2f00e73 Remove the dead wind-down: the Pace WindDown properties, the gate''s wind_down_note handling, and the stale weekly-aware Settings hints (M.ORCH-T743); d016ef0 Grandchild-pipes runner test gives cmd room to exit under load (6s timeout, ~20s grandchild), so it no longer lands on the kill path when the full suite is busy (M.ORCH-T744); 435f846 Per-user cutoffs finished: a login at its weekly or 5-hour cutoff alerts the owner once per crossing (urgent alert + Psst), the rebalancer uses each login''s own 5-hour cutoff, the global login reads its email from its profile file for its cutoffs (M.ORCH-T742); 78644d0 Review fixes: drop the dead wind-down branches, correct the resume row (M.ORCH-T741); 953e865 Remove the 5-hour wind-down throttle and the stale weekly-aware README text: runs go to the cutoff (M.ORCH-T741); bcabef1 A cancelled app install waits for the killed deploy to exit, and the test''s cleanup retries while it releases its folder, so cancelling no longer fails teardown (M.ORCH-T738); 9983295 Review fixes: keep OrgCommands line endings, refuse the retired weekly settings options, rename --5h only for org limit (M.ORCH-T707); 739f984 Per-user usage cutoffs: org limit command, 90% week / 98% 5-hour defaults, no 75% line (M.ORCH-T707); 704b0ab Pace gate review: a call with no allowance isn''t blocked by a lock it doesn''t need, and the lock wait stops at MAX_HOLD (M.ORCH-T730); 4dd104e Pace gate waits and retries when it holds neither the db transaction nor the lock, so it never counts and takes a slot unlocked (M.ORCH-T730); 0579e03 next says a repo''s tickets couldn''t be read, not that its queue ran dry, when its Tickets.db failed to open (M.ORCH-T740); 97cdb0e Test that an unresolved-CLI claim from a closed CLI isn''t counted against the allowance (M.ORCH-T732); 91ba731 Next counts unstarted claims against the pace allowance when no CLI resolves, so each --claim stops handing out the full allowance again (M.ORCH-T732); e81deaf Review fixes: restore line endings, send failed-over CLIs back to their login, trim README (M.ORCH-T706); d1b9639 Hard-code the owner''s usage rules: no weekly-aware pacing, throttling, pace profiles or automatic API-key failover (M.ORCH-T706); 9160a08 T725 review: test uses the harness db, asserts the over window is raised once, restore LF line endings (M.ORCH-T725); 66b484a PaceLedgerWatch keeps a per-CLI account''s global-window rows when grading global windows, so a shared account''s windows aren''t re-reported each minute (M.ORCH-T725); 9d3e8e2 Dispatcher links sibling packages through AccountDirs.TryMklinkArguments, so a folder name with & ^ / stays data instead of splitting the cmd line (M.ORCH-T737))', '4cbd49d', 745, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T747', 'MindAttic.Orchestrator', 747, '2026-10-23', 'fix', 'closed', 'No member''s login is ever a fallback: under Claude Team billing, every CLI not started on a login of its own runs on the global ~/.claude login, which is a member''s seat (Erin''s now), and the dashboard marks it ''Erin (fallback)'' (LoginScope.cs:111, StatusAggregator.cs:250, Redelegation.FallbackKey M.ORCH-T662/T672), so one person carries everyone''s unassigned load. The owner: ''the API is the only fallback, no user should be burdened with another account''s load''. Make the Vault API key the only fallback for CLIs without their own login (and redelegation), honouring M.ORCH-T706 (API billing only when the owner has it on; otherwise such work waits rather than landing on a member), treat the global login purely as its member''s own seat, and drop ''(fallback)'' from any member''s name', '266db30', 746, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T748', 'MindAttic.Orchestrator', 748, '2026-10-23', 'feature', 'closed', 'A background subagent dies silently whenever its host Claude Code process exits for any reason other than a budget-window reset (window closed, crash, sleep). The next session only sees a task-notification with status ''stopped'' and ''no completion record found'' — no alert at the time, no automatic recovery. The Orchestrator already resumes a CLI after its budget window resets (resume-after-reset); it has no equivalent for a host process disappearing mid-task. Add: (1) the daemon detects a dispatched ticket whose session/subagent went dark (process gone, no completion notification, ticket still open with no new Ref) rather than waiting for the human to notice on next session start; (2) it auto-redispatches that ticket''s work (a fresh subagent in the same worktree, carrying forward the original ticket text and any research notes left in the worktree/docs) the same way a human operator did it by hand for RB-T74, RB-T76 and RB-T71 on 2026-10-23; (3) surface this as a distinct state (e.g. ''orphaned'') in ''orchestrator status''/''orchestrator queue'', separate from a normal open ticket, so it''s visible immediately rather than only at the next SessionStart. Goal: /allocate-driven work keeps going whether or not the owner is watching, matching the existing promise for budget-window stops.', 'ae1c8ac (OrphanWatchTests)', 747, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T749', 'MindAttic.Orchestrator', 749, '2026-10-23', 'fix', 'closed', 'Finish M.ORCH-T747 (no member login is a fallback): (1) LoginPicker still picks/names the global login when every per-CLI login is taken (''every per-CLI login already has a CLI: global login''); make it pick the API key when API billing is on, else nothing; (2) AccountRebalancer and the pace gate''s global-login handling were left untouched: make sure neither moves or sends any CLI onto the global login (a member''s seat) as a default; (3) add tests for T747''s new ''waits'' gates (Dispatcher.ApiBilling, the start command''s BillingOverride) (left open by M.ORCH-T747''s agent)', 'b1894d5', 748, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T750', 'MindAttic.Orchestrator', 750, '2026-10-23', 'fix', 'closed', 'M.ORCH-T748''s new settings (--orphan-redispatches, --orphan-quiet) are CLI-only; the owner''s rule is every threshold is editable in both the Settings modal and the CLI, so add both to the dashboard''s Settings window (left open by M.ORCH-T748''s agent)', '3674d17', 749, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T751', 'MindAttic.Orchestrator', 751, '2026-10-23', 'feature', 'closed', 'Remove the dashboard''s Terminals page and all its code; the dashboard only shows the Dashboard (no Dashboard/Terminals page tabs). The owner: the embedded panes lost their colour, are slower, and new windows open in a real terminal anyway. Remove the PageTabStrip and Pages, TerminalsViewModel/TerminalPaneViewModel, the TerminalPanes pipe server and pane requests, the embedded-terminal host, the ''Where CLIs open: Orchestrator'' setting and its reopen-at-start records, and their tests; every CLI and Launcher opens in Windows Terminal. Keep M.ORCH-T699''s per-account Launcher (one per signed-in login, idle) but open it as a Windows Terminal tab, reused rather than doubled. Keep the per-login tab strip as it is', 'a730ddf', 750, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T752', 'MindAttic.Orchestrator', 752, '2026-10-23', 'feature', 'closed', 'Login tab strip order: the per-login (user) tabs sorted alphabetically by their shown name (case-insensitive), with the API key tab always last (LoginScope tab building / MainViewModel.Tabs)', 'LoginScopeTests.The_login_tabs_are_sorted_by_their_shown_name_case_insensitively_the_global_one_among_them; 977d3ac', 751, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T753', 'MindAttic.Orchestrator', 753, '2026-10-23', 'feature', 'closed', 'Org pacing and dispatch (follow-up to M.ORCH-T655): the daemon, the pace gate, rl-status and /allocate dispatch scope pacing and the queue per org (an org''s tickets go only to its own members'' logins, each org paced on its own logins), not only the dashboard''s view', 'bf4ad00', 752, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T754', 'MindAttic.Orchestrator', 754, '2026-10-23', 'feature', 'closed', 'Virtualize and org-scope every dashboard list (follow-up to M.ORCH-T655, which did the queue): Repos, Agents, Accounts, Audit and each person''s Tickets view as virtualized lists scoped to the chosen org, so a 9-person and a 2-person org switch equally fast', '230756a TabSwitchTests.A_virtualized_body_builds_only_the_rows_and_lines_of_tiles_on_screen', 753, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T755', 'MindAttic.Orchestrator', 755, '2026-10-23', 'feature', 'closed', 'orchestrator org works on the selected org (follow-up to M.ORCH-T655): members, usage, limit, allow, start and the members table scoped to the org chosen in the dashboard switcher (or --org), adding a member also places their login in that org', '266f1a8 (OrgCommandTests.Org_commands_work_on_the_chosen_org_and_adding_a_member_places_their_login_in_it)', 754, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T756', 'MindAttic.Orchestrator', 756, '2026-10-23', 'fix', 'closed', 'Fails on main: MindAttic.Orchestrator.Tests.LibraryOnlyXamlTests.Every_xaml_element_is_a_library_control_or_library_styled — Assert.That(Violations(files), Is.Empty) Expected: <empty> But was: < "MainWindow.xaml:723 <VirtualList>: neither a library control nor library-styled", "MainWindow.xaml:727 <VirtualizingStackPanel>: neither a library control nor library-styled", "MainWindow.xaml:1205 <Border>: neither a library ... (landed on main since the last green run: tickets M.ORCH-T655 in d56dac9 Organizations above people: an organizations and org_members store (SQLite step 13, SQL Server schema 4) where each login carries its LLM provider, everything existing staying one default org (MindAttic); an org switcher above the person tabs that scopes each tab''s CLIs, agents, pace, the Accounts view and the queue''s claims to the chosen org; the queue a virtualized list so a switch builds only the rows on screen; and orchestrator orgs to manage them, orchestrator org kept as is (M.ORCH-T655))', 'd8067d5', 755, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T757', 'MindAttic.Orchestrator', 757, '2026-10-23', 'feature', 'closed', 'Person tab status icons show activity: replace each login tab''s status dot with an icon: a pause icon when the login is idle; a green play arrow while it''s busy that blinks once for every N tokens that login spends (N a setting in the Settings modal and CLI, default 1000; e.g. 100), so busy tabs blink at their own rate, never in unison, and you can see which are working and how hard; a gray ''disabled'' icon when the login is past its cutoff (5-hour or weekly, M.ORCH-T707/T742). The API key tab follows the same rules (past = API billing off). Use MindAttic.Components.Wpf icons/styles (LibraryOnlyXamlTests); drive blinks from the live token counts the dashboard already reads, without extra polling cost', '8e6fa4c TabStatusTests.A_tab_blinks_once_per_N_tokens_spread_over_the_refresh_at_its_own_phase', 756, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T758', 'MindAttic.Orchestrator', 758, '2026-10-23', 'feature', 'open', 'Org dispatch, the rest (follow-up to M.ORCH-T753): the idle-claims nudge (AutopilotWaker.TickClaims/IdleClaims) and its UnderTarget room are still worked from the global login''s plan and put a claim whose CLI is gone to any /allocate CLI on its repo, whatever its org; make them per org (a claim only to a CLI of the ticket''s org, room from that org''s logins). Also let an org''s tickets reach its members when none of them runs /allocate (today they wait), and scope Autopilot.Tick''s background-agent half (unused in production) the same way.', 'M.ORCH-T753', 757, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T759', 'MindAttic.Orchestrator', 759, '2026-10-23', 'feature', 'wont-do', 'Dashboard layout: two top-level sections, Users | Repos (plus a Miscellaneous section at the end for anything that fits neither), under the org switcher. Users: one sub-tab per person (alphabetical, API key last, M.ORCH-T752/T757 icons); each person''s page leads with their stats (5-hour, week, cutoffs, last updated) and login actions (sign in, rename, org limit, move CLIs), then their 5-hour chart, running agents and tickets assigned to them; org-wide login actions (Sign in all, Add login, Report) in a small toolbar above the person tabs. Repos: a repo picker (All | each repo) with a header row (git state, Start, Open) and sub-tabs Tickets | Queue | Audit: Tickets with filters Queued / Being worked / Needs approval / Blocked-orphaned; Queue in the order /allocate hands work out, with bump/approve; Audit''s drift and duplicate findings for that repo (cross-repo duplicates under each repo involved). This replaces the Agents/Repos/Queue/Audit/Accounts view pills and the separate Accounts view (the owner approved this layout 2026-10-23)', 'superseded by M.ORCH-T760: ticket browsing moves to the Tickets app (owner, 2026-10-23)', 758, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T760', 'MindAttic.Orchestrator', 760, '2026-10-23', 'feature', 'wont-do', 'Dashboard layout (replaces M.ORCH-T759; separation of responsibility: the Orchestrator runs the work, the Tickets app manages tickets): top-level sections Users | Repos | Miscellaneous under the org switcher. Users: one sub-tab per person (alphabetical, API key last, M.ORCH-T757 icons); each person''s page leads with their stats (5-hour, week, cutoffs, last updated) and login actions (sign in, rename, org limit, move CLIs), then their 5-hour chart and running agents; org-wide login actions (Sign in all, Add login, Report) in a small toolbar above the person tabs. Repos: a repo picker (All | each repo) with a header row (git state, Start, Open) and sub-tabs Queue | Audit: Queue is the live dispatch view (what runs next in /allocate order, who''s working what on which login/model, blocked, orphaned) with quick Approve and Bump; Audit is that repo''s drift and duplicate findings. No ticket browsing in the Orchestrator: every ticket ID anywhere is a link that opens MindAttic.Tickets Desktop on it (--ticket <ID>). Anything that fits neither section goes in Miscellaneous. Replaces the Agents/Repos/Queue/Audit/Accounts view pills, the separate Accounts view and the per-person Tickets view', 'superseded by M.ORCH-T763: Repos/Queue/Audit move to Tickets Desktop (owner, 2026-10-23)', 759, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T761', 'MindAttic.Orchestrator', 761, '2026-10-23', 'fix', 'closed', 'One source of truth for ticket approval and priority: the Orchestrator keeps its own approved list and priorities in its settings (TicketQueue, OrchestratorSettings.Approved/Priorities) while MindAttic.Tickets has ''ticket approve''/''ticket priority'' in Tickets.db, so approving in one app doesn''t show in the other. Move both into Tickets.db through the Tickets engine (migrate the Orchestrator''s existing approvals/priorities once), have orchestrator approve/bump and the dashboard''s quick Approve/Bump write through the engine, and read them back from it everywhere (queue order, next --claim)', '4ed28f3', 760, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T762', 'MindAttic.Orchestrator', 762, '2026-10-23', 'feature', 'closed', 'Migrate every ticket function out of the Orchestrator into MindAttic.Tickets (M.TIX-T134) and hyperlink instead (owner, 2026-10-23: both apps intimately integrated, each only doing what it was made for): remove the Orchestrator''s ticket commands (approve, bump, assign, block, hygiene, intake, reserve, the ticket parts of show) and their dashboard actions, including the quick Approve/Bump planned in M.ORCH-T760''s queue, and its own ticket state (read approval, priority, assignment and blocks from Tickets.db through the engine); keep what is about running work (next --claim, dispatch, the live queue view, release of a claim). Every ticket ID or title the Orchestrator shows (queue rows, agent cards, alerts, details, CLI output where a link is possible) becomes a hyperlink that opens MindAttic.Tickets Desktop on that ticket (--ticket <ID>). Update hook/skill texts that tell the user to run orchestrator approve etc. to the tickets equivalents', '709bab60', 761, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T763', 'MindAttic.Orchestrator', 763, '2026-10-23', 'feature', 'closed', 'Orchestrator layout (replaces M.ORCH-T760; owner 2026-10-23: the Orchestrator only shows what''s running, Tickets Desktop owns Repos/Queue/Audit): under the org switcher, one tab per person (alphabetical, API key last, M.ORCH-T757 icons) plus a Miscellaneous tab at the end for anything that fits nowhere else. Each person''s page leads with their stats (5-hour, week, cutoffs, last updated) and login actions (sign in, rename, org limit, move CLIs), then their 5-hour chart and current work: running agents with a snippet of the ticket each is on, the snippet a hyperlink that opens it in Tickets Desktop (--ticket <ID>). Org-wide login actions (Sign in all, Add login, Report) in a small toolbar above the person tabs. Remove the Agents/Repos/Queue/Audit/Accounts view pills, the Repos tiles, Queue and Audit views and the separate Accounts view from the dashboard. Add a deep-link entry so Tickets Desktop can open the Orchestrator on a person, a session or a ticket''s live work (e.g. MindAttic.Orchestrator.exe --show <email|session|ticket>, handed to the running window and brought forward)', 'f0917b11', 762, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T764', 'MindAttic.Orchestrator', 764, '2026-10-23', 'fix', 'closed', 'The subagent allowance still throttles by rate below the cutoff, against the owner''s hard-cutoff rule (M.ORCH-T706/T741): Pacer works SubagentAllowance out from the spare rate (what fits the target minus the draw), so with Ryan''s login at 12% of its 5-hour window and 76% of its week the gate says ''Usage is ahead of the 5-hour pace, so don''t start extra subagents'' and orchestrator next --claim hands out nothing. Below a login''s cutoffs the allowance must be the machine cap (MaxSubagents / MaxConcurrentSessions) with no pace math; it drops to 0 only at a cutoff (98% 5-hour, the login''s weekly cutoff). Remove the rate-based allowance, SpareSessions-based limits and the ''ahead of the pace'' wording', '424b41a; PacerTests.Burning_twice_the_sustainable_rate_still_leaves_every_slot_open', 763, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T765', 'MindAttic.Orchestrator', 765, '2026-10-23', 'fix', 'closed', 'deploy.ps1''s CLI publish fails (MSB3027, 10 retries) whenever any orchestrator.exe is running from C:\Apps\MindAttic.Orchestrator\Cli at that moment, which with hooks, /allocate and ''orchestrator review'' calls firing constantly is most of the time (failed once and retried luckily once on 2026-10-23); publish the CLI to a staging folder and swap it in (rename the old folder aside, or copy with retries per file once the running ones exit), so a deploy never fails or half-installs because a short-lived CLI call holds its DLLs', '512662b3', 764, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T766', 'MindAttic.Orchestrator', 766, '2026-10-23', 'feature', 'closed', 'The Orchestrator records who is working each ticket in the Tickets engine (M.TIX-T134 added ticket_work and ''tickets ticket working <ID> --login --session'' / --clear): set it when a ticket is claimed or a tab/subagent starts on it (login email, Claude session id when known), update it on a move or orphan redispatch, clear it when the ticket lands, is released or goes stale, so Tickets Desktop''s link back to the Orchestrator shows for every ticket being worked', 'TicketWorkingTests (b04a620f)', 765, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T767', 'MindAttic.Orchestrator', 767, '2026-10-23', 'feature', 'closed', 'MindAttic.Orchestrator.exe --start <repo>: the Tickets Desktop Repos tab''s Start link (M.TIX-T135, 05a759a) opens the Orchestrator with --start <repo>; hand it to the running window (or start one) and start a CLI in that repo the way the dashboard''s Start does (login picker, cutoffs, no member fallback, API key only when billing is on), bringing the window forward; same single-instance hand-off M.ORCH-T763 adds for --show', '475b553f', 766, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T768', 'MindAttic.Orchestrator', 768, '2026-10-23', 'feature', 'open', 'Follow-up to M.ORCH-T763: remove the Repos-tile view model the dashboard no longer shows (MainViewModel''s tiles, TileGroupViewModel groups, Search/ShowQuiet/RepoSort/Focus, Selected and the repo pane''s Provider/Login/Prompt/Start/OpenFolder/UseTicket, HostRowViewModel/TicketRowViewModel/SessionRowViewModel), keeping only what --start <repo> (StartTarget/StartSessionAsync) and the Needs-you toasts (RepoTileViewModel as their target) still use, and their tests', 'M.ORCH-T763', 767, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T769', 'MindAttic.Orchestrator', 769, '2026-10-23', 'fix', 'closed', 'Revert M.ORCH-T764: hard-cutoff-only pacing let usage blow through the pace target (Ryan''s 5-hour window went ~33% over target within ~45 min of it shipping) because nothing throttled by rate below the cutoff; restore the rate-based cap/allowance/delay so usage tracks the pace line again, with the hard cutoff still the backstop', '—', 768, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T770', 'MindAttic.Orchestrator', 770, '2026-10-23', 'feature', 'closed', 'Dashboard: move billing-the-Vault''s-API-key off the person tab strip (it isn''t a user, M.ORCH-T630) into an always-visible emergency button in the window''s upper-right corner that still switches every open CLI at once; hide the old ''API key'' tab from the strip', '—', 769, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T771', 'MindAttic.Orchestrator', 771, '2026-10-23', 'fix', 'closed', 'Dashboard crashed on every open (XamlParseException, unhandled) after M.ORCH-T770: the glow-pulse Storyboards for the emergency billing toggle and busy tab icon tried to self-target an Effect''s sub-property with no TargetName, which Style.Triggers can''t resolve; fix by wiring them through a ControlTemplate/DataTemplate''s own NameScope instead', '—', 770, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T772', 'MindAttic.Orchestrator', 772, '2026-10-23', 'chore', 'closed', 'many billions of tokens', '—', 771, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T773', 'MindAttic.Orchestrator', 773, '2026-10-23', 'feature', 'closed', 'Dashboard: confirm before billing every open CLI to the API key (a themed Yes/No MaMessageBox, defaulting to No) so a stray click on the corner toggle can''t flip org-wide billing by accident; switching back to Claude Team stays instant. Also tighten the gap between the key icon and the sun/moon toggle to zero so they read as one group', '—', 772, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T774', 'MindAttic.Orchestrator', 774, '2026-10-23', 'fix', 'closed', '[pace-ledger over 2026-10-24T03:00Z] Claude reported 100% in the 5-hour window ending Oct 23 10:00 PM without a limit hit being read: window Oct 23 5:00 PM–10:00 PM closed over: honey@mindattic.com: Claude reported 100%, peak 100%. Find what got past the 99% stop.', 'd70a63c2', 773, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T775', 'MindAttic.Orchestrator', 775, '2026-10-23', 'fix', 'closed', 'Fails on main: MindAttic.Orchestrator.Tests.LibraryOnlyXamlTests.Every_xaml_element_is_a_library_control_or_library_styled — Assert.That(Violations(files), Is.Empty) Expected: <empty> But was: < "MainWindow.xaml:118 <Style>: a Path style not based on a library style", "MainWindow.xaml:106 <Button>: neither a library control nor library-styled", "MainWindow.xaml:114 <Viewbox>: neither a library control nor library-style... (landed on main since the last green run: tickets M.ORCH-T772, M.ORCH-T770, M.ORCH-T771, M.ORCH-T764, M.ORCH-T769 in b800be6d many billions of tokens (M.ORCH-T772); fbd7165b Fix the dashboard crashing on every open since M.ORCH-T770''s glow-pulse: the Storyboards self-targeted a Button/TextBlock''s Effect through a compound property path with no TargetName ("''Effect'' property does not point to a DependencyObject", confirmed in the Application event log) and naming the target instead hit MC4011, since Style.Triggers can never set TargetName. Moved the emergency billing toggle onto its own ControlTemplate and the tab''s busy-icon pulse onto its DataTemplate.Triggers, both of which have a NameScope a Storyboard.TargetName can resolve against; smoke-tested by launching the built exe directly against live state (billing already on the API key, so the trigger fires immediately) before redeploying (M.ORCH-T771); eb38dc6f Dashboard: the emergency billing toggle is a plain key icon beside the sun/moon (not a labeled button) - MaText while Claude Team bills, solid green with a slow glowing pulse while the API key does; a busy tab''s play icon gets the same soothing pulse instead of its old per-token blink, so "action is taking place" reads the same way everywhere (M.ORCH-T770); 3f5f9064 Dashboard: the Vault''s API key isn''t a person, so it loses its seat beside Amy/Erin/Honey/Jordan/Ryan in the login strip; billing it now switches with an always-visible emergency button in the window''s upper-right corner (the same ToggleBillingCommand, so one click still moves every open CLI to the organization''s key, not anyone''s seat), and Ctrl+Tab no longer lands on the hidden tab (M.ORCH-T770); 8ad878b2 Revert M.ORCH-T764: hard-cutoff-only pacing let usage blow through the pace target before the daemon could react; restore the rate-based subagent allowance, session cap, tool-call delay and conserve advice below the cutoff, with the hard cutoff still the backstop (M.ORCH-T769))', '58e740d3', 774, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T776', 'MindAttic.Orchestrator', 776, '2026-10-23', 'fix', 'closed', 'Fails on main: MindAttic.Orchestrator.Tests.LibraryControlsTests.No_control_template_or_hard_coded_colour_is_left_in_the_dashboard — Assert.That(colours.Select(a => $"{a.Parent!.Name.LocalName}.{a.Name}={a.Value}"), Is.Empty) Expected: <empty> But was: < "DropShadowEffect.Color=#FF2FBF71", "DropShadowEffect.Color=#FF2FBF71" > (landed on main since the last green run: tickets M.ORCH-T772, M.ORCH-T770, M.ORCH-T771, M.ORCH-T764, M.ORCH-T769 in b800be6d many billions of tokens (M.ORCH-T772); fbd7165b Fix the dashboard crashing on every open since M.ORCH-T770''s glow-pulse: the Storyboards self-targeted a Button/TextBlock''s Effect through a compound property path with no TargetName ("''Effect'' property does not point to a DependencyObject", confirmed in the Application event log) and naming the target instead hit MC4011, since Style.Triggers can never set TargetName. Moved the emergency billing toggle onto its own ControlTemplate and the tab''s busy-icon pulse onto its DataTemplate.Triggers, both of which have a NameScope a Storyboard.TargetName can resolve against; smoke-tested by launching the built exe directly against live state (billing already on the API key, so the trigger fires immediately) before redeploying (M.ORCH-T771); eb38dc6f Dashboard: the emergency billing toggle is a plain key icon beside the sun/moon (not a labeled button) - MaText while Claude Team bills, solid green with a slow glowing pulse while the API key does; a busy tab''s play icon gets the same soothing pulse instead of its old per-token blink, so "action is taking place" reads the same way everywhere (M.ORCH-T770); 3f5f9064 Dashboard: the Vault''s API key isn''t a person, so it loses its seat beside Amy/Erin/Honey/Jordan/Ryan in the login strip; billing it now switches with an always-visible emergency button in the window''s upper-right corner (the same ToggleBillingCommand, so one click still moves every open CLI to the organization''s key, not anyone''s seat), and Ctrl+Tab no longer lands on the hidden tab (M.ORCH-T770); 8ad878b2 Revert M.ORCH-T764: hard-cutoff-only pacing let usage blow through the pace target before the daemon could react; restore the rate-based subagent allowance, session cap, tool-call delay and conserve advice below the cutoff, with the hard cutoff still the backstop (M.ORCH-T769))', 'aa0d19da (M.ORCH-T777 already fixed this on main)', 775, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T777', 'MindAttic.Orchestrator', 777, '2026-10-23', 'fix', 'closed', 'Fails on main: MindAttic.Orchestrator.Tests.LibraryControlsTests.Every_dashboard_button_uses_a_library_button_style — Assert.That(handMade.Select(b => b.ToString()), Is.Empty) Expected: <empty> But was: < "<Button x:Name="EmergencyBillingButton" DockPanel.Dock="Right" VerticalAlignment="Top" Margin="0,0,4,0" Command="{Binding ToggleBillingCommand}" ToolTip="{Binding BillingToggleText}" AutomationProperties.Name=... (landed on main since the last green run: tickets M.ORCH-T772, M.ORCH-T770, M.ORCH-T771, M.ORCH-T764, M.ORCH-T769 in b800be6d many billions of tokens (M.ORCH-T772); fbd7165b Fix the dashboard crashing on every open since M.ORCH-T770''s glow-pulse: the Storyboards self-targeted a Button/TextBlock''s Effect through a compound property path with no TargetName ("''Effect'' property does not point to a DependencyObject", confirmed in the Application event log) and naming the target instead hit MC4011, since Style.Triggers can never set TargetName. Moved the emergency billing toggle onto its own ControlTemplate and the tab''s busy-icon pulse onto its DataTemplate.Triggers, both of which have a NameScope a Storyboard.TargetName can resolve against; smoke-tested by launching the built exe directly against live state (billing already on the API key, so the trigger fires immediately) before redeploying (M.ORCH-T771); eb38dc6f Dashboard: the emergency billing toggle is a plain key icon beside the sun/moon (not a labeled button) - MaText while Claude Team bills, solid green with a slow glowing pulse while the API key does; a busy tab''s play icon gets the same soothing pulse instead of its old per-token blink, so "action is taking place" reads the same way everywhere (M.ORCH-T770); 3f5f9064 Dashboard: the Vault''s API key isn''t a person, so it loses its seat beside Amy/Erin/Honey/Jordan/Ryan in the login strip; billing it now switches with an always-visible emergency button in the window''s upper-right corner (the same ToggleBillingCommand, so one click still moves every open CLI to the organization''s key, not anyone''s seat), and Ctrl+Tab no longer lands on the hidden tab (M.ORCH-T770); 8ad878b2 Revert M.ORCH-T764: hard-cutoff-only pacing let usage blow through the pace target before the daemon could react; restore the rate-based subagent allowance, session cap, tool-call delay and conserve advice below the cutoff, with the hard cutoff still the backstop (M.ORCH-T769))', 'aa0d19da73dab68a9344ba7ba69440c676887b9', 776, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T778', 'MindAttic.Orchestrator', 778, '2026-10-23', 'chore', 'closed', 'Update orchestrator.db, orchestrator.sql, USER_STORIES.md', '—', 777, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T779', 'MindAttic.Orchestrator', 779, '2026-10-23', 'chore', 'closed', 'Rename the Autopilot C# subsystem to Allocate (class/file Scheduling/Autopilot.cs, Settings.Autopilot, --autopilot/--autopilot-skip flags, AutopilotWaker, ClisCommand''s Autopilot field, autopilot-waiting.json, and every Autopilot* test), updating every comment and doc string so they match the already-renamed /allocate user-facing surface instead of describing a separate ''autopilot'' concept', 'a2a323c7', 778, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T780', 'MindAttic.Orchestrator', 780, '2026-10-24', 'fix', 'closed', 'Fails on main: MindAttic.Orchestrator.Tests.LibraryOnlyXamlTests.Every_xaml_element_is_a_library_control_or_library_styled — Assert.That(Violations(files), Is.Empty) Expected: <empty> But was: < "MainWindow.xaml:147 <Style>: a Path style not based on a library style", "MainWindow.xaml:108 <ContentControl>: neither a library control nor library-styled", "MainWindow.xaml:115 <BeginStoryboard>: neither a library control n... (landed on main since the last green run: tickets M.ORCH-T777, M.ORCH-T773, M.ORCH-T772, M.ORCH-T770, M.ORCH-T771, M.ORCH-T764, M.ORCH-T769 in aa0d19da Fix the dashboard button/control-template tests LibraryControlsTests caught: the emergency billing toggle''s Button.Template and the tab icon''s hard-coded glow colour were both hand-built controls the library ban still applies to. The toggle is plain MaToolButton again, with its pulse on a themed Ellipse behind it (DynamicResource MaGood, no literal hex) inside a DataTemplate whose own NameScope a Storyboard.TargetName can resolve against; the tab''s busy-icon glow moves off DropShadowEffect (whose Color can''t take a brush resource) onto the same Ellipse trick (M.ORCH-T777); 898aaef6 Dashboard: confirm before billing every CLI to the API key - a themed Yes/No MaMessageBox (defaulting to No) guards the corner toggle''s dangerous direction, so a stray click can''t flip org-wide billing by accident; switching back to Claude Team stays instant since that direction is always safe. Also zero the gap between the key icon and the sun/moon toggle so they read as one group (M.ORCH-T773); b800be6d many billions of tokens (M.ORCH-T772); fbd7165b Fix the dashboard crashing on every open since M.ORCH-T770''s glow-pulse: the Storyboards self-targeted a Button/TextBlock''s Effect through a compound property path with no TargetName ("''Effect'' property does not point to a DependencyObject", confirmed in the Application event log) and naming the target instead hit MC4011, since Style.Triggers can never set TargetName. Moved the emergency billing toggle onto its own ControlTemplate and the tab''s busy-icon pulse onto its DataTemplate.Triggers, both of which have a NameScope a Storyboard.TargetName can resolve against; smoke-tested by launching the built exe directly against live state (billing already on the API key, so the trigger fires immediately) before redeploying (M.ORCH-T771); eb38dc6f Dashboard: the emergency billing toggle is a plain key icon beside the sun/moon (not a labeled button) - MaText while Claude Team bills, solid green with a slow glowing pulse while the API key does; a busy tab''s play icon gets the same soothing pulse instead of its old per-token blink, so "action is taking place" reads the same way everywhere (M.ORCH-T770); 3f5f9064 Dashboard: the Vault''s API key isn''t a person, so it loses its seat beside Amy/Erin/Honey/Jordan/Ryan in the login strip; billing it now switches with an always-visible emergency button in the window''s upper-right corner (the same ToggleBillingCommand, so one click still moves every open CLI to the organization''s key, not anyone''s seat), and Ctrl+Tab no longer lands on the hidden tab (M.ORCH-T770); 8ad878b2 Revert M.ORCH-T764: hard-cutoff-only pacing let usage blow through the pace target before the daemon could react; restore the rate-based subagent allowance, session cap, tool-call delay and conserve advice below the cutoff, with the hard cutoff still the backstop (M.ORCH-T769))', '58e740d3', 779, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T781', 'MindAttic.Orchestrator', 781, '2026-10-24', 'fix', 'closed', 'Three WPF library-conformance tests fail on origin/main 775da513 (found by MAT-T26 sweep): Every_dashboard_button_uses_a_library_button_style, No_control_template_or_hard_coded_colour_is_left_in_the_dashboard and Every_xaml_element_is_a_library_control_or_library_styled all trip on the hand-built EmergencyBillingButton in MainWindow.xaml (lines ~106-149: a hand-made Button with its own ControlTemplate, a Path/Viewbox key glyph, a literal-colour DropShadowEffect and a storyboard). Rebuild it from MindAttic.Components library controls and tokens, or extend the library with the style it needs', 'aa0d19da', 780, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T782', 'MindAttic.Orchestrator', 782, '2026-10-24', 'chore', 'closed', 'Update orchestrator.db, orchestrator.sql, USER_STORIES.md', '—', 781, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T783', 'MindAttic.Orchestrator', 783, '2026-10-24', 'fix', 'closed', 'Pace hook told the CLI it was on course to end near 95-96%% (under 98%% target) while the dashboard''s own trend line for Ryan projected 110.3%% at reset despite already being paced to 2 of 6; hard-cutoff math/hook guidance disagree with the dashboard''s own projection', '794b6164', 782, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T784', 'MindAttic.Orchestrator', 784, '2026-10-24', 'fix', 'closed', '[pace-ledger blind] window Oct 24 5:20 AM–10:20 AM closed blind: ryandebraal@mindattic.com: Claude''s meter unseen for 46m while 789.1k were spent, peak 20%, 5 calls held (2.3 min), 1 refused. The pace ran on its own estimate this long without Claude''s meter: make sure it gets a fresh reading whenever tokens are being spent.', '123f580da2784610e9498570dc8bc18d00e3ce15', 783, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T785', 'MindAttic.Orchestrator', 785, '2026-10-24', 'feature', 'closed', 'Deliberate cool-off throttle for one login split across many CLIs: once the live aggregated 5-hour trend across that login''s CLIs crosses the 98% pace line, slow (never stop) new subagent starts on that login until the trend bends back under the pace line; stays off while under the line; never replaces the 98%/99% hard cutoff. User-approved narrow exception to M.ORCH-T706/T707''s no-throttling-before-cutoff rule (2026-10-24), scoped only to the multi-CLI-same-login case. Depends on the staleness fix (M.ORCH-T783) since it needs a live cross-CLI aggregate to pace against.', 'fd2aa743', 784, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T786', 'MindAttic.Orchestrator', 786, '2026-10-24', 'feature', 'closed', 'Automatic agent-abort as the orchestrator''s last-resort cool-off lever: when a login''s live aggregated 5-hour trend (M.ORCH-T783) is still on course to breach the 98/99 hard cutoff even with the new-start throttle (M.ORCH-T785) already active, the orchestrator itself, with no human trigger, picks and aborts enough in-flight subagents on that login to pull the trend back under the pace line. Prioritizes survival of the hard cutoff over any ticket''s in-flight progress (user, 2026-10-24: drop extra weight off a plane that can''t stay in the air; losing tokens is fine, hitting the ceiling has no fix). Abort signals the subagent to stop at a safe point (not mid-write/mid-commit), leaves its worktree/uncommitted work intact, releases its claim, and puts the ticket back at the front of queue order for the next round. Prefer aborting whichever agent(s) are burning fastest or nearest a safe stop point first. Never touches idle needs-you manual CLI sessions with no claimed ticket.', '1daaebdf', 785, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T787', 'MindAttic.Orchestrator', 787, '2026-10-24', 'fix', 'closed', '5-hour utilization chart occasionally renders a flat line at the current/idle value across the whole window instead of the real historical climb (seen once: showed flat 96.0% from 6:10 AM onward, labeled idle 96.0%, when the real history climbed steadily from 0%); cosmetic only, not reproduced on demand', '3aafeb26', 786, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T788', 'MindAttic.Orchestrator', 788, '2026-10-24', 'fix', 'closed', 'Orchestrator''s 5-hour usage number for Ryan drifted from Claude''s own native session-limit indicator: Claude''s widget showed 95%% used, resets 11:09am, while the Orchestrator dashboard showed 96.7%% now / 98.9%% projected at reset for the same window, resets 11:10am (~1.7pp gap). Pacing must read straight off Claude''s own live rate_limits percent per existing policy; find why the two sources disagree (lag, double-counting, or a derived estimate instead of the raw value) -- likely related to the staleness investigation in M.ORCH-T783', '21ef0d96', 787, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T789', 'MindAttic.Orchestrator', 789, '2026-10-24', 'feature', 'wont-do', 'Person tab bar: replace each tab''s ''N need you'' count and ''% left'' text with live 5-hour/weekly percent pairs in current/target form, e.g. ''Amy | 5hr: 0/98% | wk: 87/100%''; drop ''N need you'' entirely (user, 2026-10-24: it''s almost always wrong) and drop the separate ''% left'' text since the new pair already shows the live number against its own target. Keep the existing status icon/highlight (working vs idle) unchanged, swap only the text next to the name. The dashboard still needs some other way elsewhere to flag who''s waiting on the user, since this removes the tab bar''s only such signal -- check with the user on where that should live if it isn''t obvious from the per-person page already built in M.ORCH-T763', 'superseded by a corrected version: the % targets must be the person''s own live configured cutoffs, not hardcoded 98%/100%', 788, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T790', 'MindAttic.Orchestrator', 790, '2026-10-24', 'feature', 'closed', 'Tab bar needs-you signal (replaces the removed ''N need you'' count from M.ORCH-T789): show a small red flag icon at the end of a person''s tab line only when something there is genuinely blocked waiting on the user (e.g. a CLI holding on a /crossrepo or similar confirmation prompt), not a count and not the old always-wrong metric. Remove the flag once the CLI(s) that needed answers are running again (no longer blocked).', '519f9bca', 789, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T791', 'MindAttic.Orchestrator', 791, '2026-10-24', 'fix', 'closed', 'Outside-use detection (M.ORCH-T682) silently lowered a login''s 5-hour pace ceiling below its hard cutoff from a noisy per-tick guess at a member''s use elsewhere, against the owner''s hard-cutoff-only rule (M.ORCH-T706/707): Honey''s target drifted 98% -> 48% -> 46% -> 37% with no real outside use. Removed the whole feature (detection, dynamic ceiling, learning, CLI flags, Settings panel, tests, docs); kept the unrelated cutoff-alert Psst texting, generalized to --alert-to', 'ReminderTests.An_alert_is_texted_to_the_recipient; AccountRebalancerTests', 790, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T792', 'MindAttic.Orchestrator', 792, '2026-10-24', 'feature', 'closed', 'SessionStart''s hook message gains [Orchestrator] Pacing/Allocation status lines after the [Billing] line, via an orchestrator_start_lines(pid) list that''s easy to extend with more', 'HookScriptTests.SessionStart_reports_this_clis_pacing_and_allocation_after_the_billing_line', 791, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T793', 'MindAttic.Orchestrator', 793, '2026-10-24', 'feature', 'closed', 'Person tab bar (corrected, replaces rejected M.ORCH-T789): replace each tab''s ''N need you'' count and ''% left'' text with live 5-hour/weekly percent pairs in current/target form, where the target is that person''s own live configured cutoff, not a fixed number -- e.g. ''Ryan | 5hr: 10/98% | wk: 55/95%'' reads Ryan''s actual 5-hour and weekly cutoff percentages exactly as set via org limit (default 98%/90%, overridable per person), never hardcoded. Drop ''N need you'' entirely (user, 2026-10-24: it''s almost always wrong) and drop the separate ''% left'' text since the new pair already shows the live number against its own target. Keep the existing status icon/highlight (working vs idle) unchanged, swap only the text next to the name.', 'f2ccbb4c TabStatusTests.The_tab_shows_live_5_hour_and_weekly_use_against_the_persons_own_cutoffs', 792, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T794', 'MindAttic.Orchestrator', 794, '2026-10-24', 'fix', 'closed', 'Fails on main: MindAttic.Orchestrator.Tests.AccountDirsTests.Each_account_is_paced_on_its_own_meter_sessions_and_subagents — from its own meter Assert.That(pace.Budget.BlockPercent, Is.InRange(60, 62)) Expected: in range (60,62) But was: 59.975594874923736d (landed on main since the last green run: tickets M.ORCH-T785, M.ORCH-T788 in fd2aa743 Cool off a login split across many CLIs: once their live aggregated 5-hour trend is on course past the pace line, new subagents start slower (never below one, nothing held) until it bends back under; the hard cutoff stays as it is (M.ORCH-T785); 21ef0d96 Review fix: keep the hard cutoff from going blind on a stale report by adding back local spend since it only past a new ReportFreshMinutes (2) staleness line, instead of dropping it for every reading (M.ORCH-T788); 660aec92 Pacing''s 5-hour block now reads straight off Claude''s own rate_limits percent (Reported source) instead of padding it a point and forward-filling with local tokens spent since the report, which drifted the dashboard''s "now" and projected numbers past Claude''s own widget (M.ORCH-T788))', '13cd1e43', 793, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T795', 'MindAttic.Orchestrator', 795, '2026-10-24', 'fix', 'closed', 'M.ORCH-T786''s two new settings (AgentAbort on/off, AgentAbortAfterMinutes default 3, range 0-60) exist only in code, not in the Settings modal or ''orchestrator settings'' CLI -- violates the standing rule that every user-given threshold must be a configurable setting in both places. Expose them alongside the existing pacing settings.', '1e08f432', 794, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T796', 'MindAttic.Orchestrator', 796, '2026-10-24', 'feature', 'closed', 'When a login gets disconnected (signed out / token expired), automatically open the sign-in screen for that account instead of waiting for the user to click Sign in. Remove the per-person ''Sign in'' button entirely since it becomes unnecessary once disconnection auto-prompts sign-in. (Does not affect the separate org-wide ''Sign in all'' toolbar action.)', 'e6c758f1 AccountsViewTests.A_login_signed_out_since_the_last_refresh_is_the_one_that_opens_its_sign_in', 795, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T797', 'MindAttic.Orchestrator', 797, '2026-10-24', 'feature', 'closed', 'Person tab login actions cleanup: replace the standalone ''Rename'' and ''Org limit'' buttons with a right-click context menu on the person''s tab, built with MindAttic.Components.Wpf.ContextMenu (not a native WPF ContextMenu), containing Rename and Org limit. Remove the ''Move CLIs'' dropdown/button entirely -- the user will reassign tickets individually via the existing per-agent ''Move to'' dropdown already shown under each running agent''s card in current work, so the login-level bulk version is redundant. For ''Make default'' (purpose unclear to the user): investigate what it does; if it''s a per-user action, add it to the same tab''s context menu instead of a standalone button; if it isn''t user-specific (e.g. it''s org-wide), leave it where it is and don''t move it.', '97cc2c06 (AccountsViewTests.The_login_actions_live_on_each_persons_page_and_the_org_wide_ones_above_the_person_tabs)', 796, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T798', 'MindAttic.Orchestrator', 798, '2026-10-24', 'fix', 'closed', 'Fails on main: MindAttic.Orchestrator.Tests.PacerTests.The_pace_gate_hook_is_installed_once_beside_the_users_own_hooks — the user''s hook kept, the gate added once Assert.That(pre, Has.Count.EqualTo(2)) Expected: property Count equal to 2 But was: 3 (landed on main since the last green run: tickets M.ORCH-T790, M.ORCH-T785, M.ORCH-T788 in 519f9bca Person tabs show a small red flag only while one of their CLIs is genuinely blocked on you (a permission prompt, an AskUserQuestion, or a /crossrepo or /allocate refused as the model''s to start), from a context-gate asking mark that clears once the CLI runs again, replacing the always-wrong idle count (M.ORCH-T790); fd2aa743 Cool off a login split across many CLIs: once their live aggregated 5-hour trend is on course past the pace line, new subagents start slower (never below one, nothing held) until it bends back under; the hard cutoff stays as it is (M.ORCH-T785); 21ef0d96 Review fix: keep the hard cutoff from going blind on a stale report by adding back local spend since it only past a new ReportFreshMinutes (2) staleness line, instead of dropping it for every reading (M.ORCH-T788); 660aec92 Pacing''s 5-hour block now reads straight off Claude''s own rate_limits percent (Reported source) instead of padding it a point and forward-filling with local tokens spent since the report, which drifted the dashboard''s "now" and projected numbers past Claude''s own widget (M.ORCH-T788))', '31de2b79', 797, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T799', 'MindAttic.Orchestrator', 799, '2026-10-24', 'fix', 'closed', 'Fails on main: MindAttic.Orchestrator.Tests.AccountDirsTests.Each_account_is_paced_on_its_own_meter_sessions_and_subagents — from its own meter Assert.That(pace.Budget.BlockPercent, Is.InRange(60, 62)) Expected: in range (60,62) But was: 59.975594874923736d (landed on main since the last green run: tickets M.ORCH-T796, M.ORCH-T786, M.ORCH-T795, M.ORCH-T793, M.ORCH-T790, M.ORCH-T785, M.ORCH-T788 in e6c758f1 A login that gets disconnected (signed in at the last refresh, signed out now) opens its own sign-in in a private browser window by itself, one at a time, so the per-person Sign in button is gone (M.ORCH-T796); 1e08f432 Expose M.ORCH-T786''s cool-off abort as settings: AgentAbort on/off and AgentAbortAfterMinutes (0-60) now sit in the Settings modal and orchestrator settings CLI alongside the other pacing thresholds (M.ORCH-T795); 1daaebdf Last-resort cool-off: when a login''s live 5-hour trend stays past its pace line with new subagents already slowed, the orchestrator aborts just enough of its ticket subagents to bend it back under, releasing their claims and putting their tickets first in the queue (M.ORCH-T786); f2ccbb4c Person tabs read each login''s live 5-hour and weekly use against its own cutoffs ("5hr: 10/98% / wk: 55/90%") in place of the always-wrong ''N need you'' count and the bare ''% left'' (M.ORCH-T793); 519f9bca Person tabs show a small red flag only while one of their CLIs is genuinely blocked on you (a permission prompt, an AskUserQuestion, or a /crossrepo or /allocate refused as the model''s to start), from a context-gate asking mark that clears once the CLI runs again, replacing the always-wrong idle count (M.ORCH-T790); fd2aa743 Cool off a login split across many CLIs: once their live aggregated 5-hour trend is on course past the pace line, new subagents start slower (never below one, nothing held) until it bends back under; the hard cutoff stays as it is (M.ORCH-T785); 21ef0d96 Review fix: keep the hard cutoff from going blind on a stale report by adding back local spend since it only past a new ReportFreshMinutes (2) staleness line, instead of dropping it for every reading (M.ORCH-T788); 660aec92 Pacing''s 5-hour block now reads straight off Claude''s own rate_limits percent (Reported source) instead of padding it a point and forward-filling with local tokens spent since the report, which drifted the dashboard''s "now" and projected numbers past Claude''s own widget (M.ORCH-T788))', 'duplicate of M.ORCH-T794, already fixed on main at 13cd1e43 -- confirmed passing on current main (6f574421)', 798, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T800', 'MindAttic.Orchestrator', 800, '2026-10-24', 'fix', 'closed', 'Fails on main: MindAttic.Orchestrator.Tests.PacerTests.The_pace_gate_hook_is_installed_once_beside_the_users_own_hooks — the user''s hook kept, the gate added once Assert.That(pre, Has.Count.EqualTo(2)) Expected: property Count equal to 2 But was: 3 (landed on main since the last green run: tickets M.ORCH-T796, M.ORCH-T786, M.ORCH-T795, M.ORCH-T793, M.ORCH-T790, M.ORCH-T785, M.ORCH-T788 in e6c758f1 A login that gets disconnected (signed in at the last refresh, signed out now) opens its own sign-in in a private browser window by itself, one at a time, so the per-person Sign in button is gone (M.ORCH-T796); 1e08f432 Expose M.ORCH-T786''s cool-off abort as settings: AgentAbort on/off and AgentAbortAfterMinutes (0-60) now sit in the Settings modal and orchestrator settings CLI alongside the other pacing thresholds (M.ORCH-T795); 1daaebdf Last-resort cool-off: when a login''s live 5-hour trend stays past its pace line with new subagents already slowed, the orchestrator aborts just enough of its ticket subagents to bend it back under, releasing their claims and putting their tickets first in the queue (M.ORCH-T786); f2ccbb4c Person tabs read each login''s live 5-hour and weekly use against its own cutoffs ("5hr: 10/98% / wk: 55/90%") in place of the always-wrong ''N need you'' count and the bare ''% left'' (M.ORCH-T793); 519f9bca Person tabs show a small red flag only while one of their CLIs is genuinely blocked on you (a permission prompt, an AskUserQuestion, or a /crossrepo or /allocate refused as the model''s to start), from a context-gate asking mark that clears once the CLI runs again, replacing the always-wrong idle count (M.ORCH-T790); fd2aa743 Cool off a login split across many CLIs: once their live aggregated 5-hour trend is on course past the pace line, new subagents start slower (never below one, nothing held) until it bends back under; the hard cutoff stays as it is (M.ORCH-T785); 21ef0d96 Review fix: keep the hard cutoff from going blind on a stale report by adding back local spend since it only past a new ReportFreshMinutes (2) staleness line, instead of dropping it for every reading (M.ORCH-T788); 660aec92 Pacing''s 5-hour block now reads straight off Claude''s own rate_limits percent (Reported source) instead of padding it a point and forward-filling with local tokens spent since the report, which drifted the dashboard''s "now" and projected numbers past Claude''s own widget (M.ORCH-T788))', 'duplicate of M.ORCH-T798, already fixed on main at 31de2b79 -- confirmed passing on current main (6f574421)', 799, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T801', 'MindAttic.Orchestrator', 801, '2026-10-24', 'fix', 'closed', 'Audit: round only for display, never before computing or gating. M.ORCH-T794 found BlockPercent lost precision because a token count was (long)-truncated mid-calculation and divided back into a percent (60% silently became 59.976%), and that truncated value fed pacing/gating decisions, not just the display. Sweep the budget/pacing code for the same anti-pattern -- any (long)/(int) cast, Math.Round, Math.Floor or Math.Truncate applied to a percent or token value before it''s compared against a target/cutoff or fed into further math -- and fix each one to carry full double precision through every calculation and gating decision, rounding only at the final formatting/display step (CLI output, dashboard text). User principle (2026-10-24): show rounded numbers but measure with perfect precision.', 'c532641d', 800, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T802', 'MindAttic.Orchestrator', 802, '2026-10-24', 'fix', 'open', '[pace-ledger over, root cause] Once a per-CLI login''s gate events are reliably tagged by account (M.ORCH-T774), the next time its window closes over at 100% with no limit hit, check the tagged held/refused events around it: did the orchestrator''s own Stop (rl-status.json) ever reach it before Claude''s percent hit 100%, or did it stay fresh-but-unstopped, or go stale? Honey@mindattic.com''s Oct 23 5-10pm window (the ticket that opened M.ORCH-T774) couldn''t be root-caused this way because her CLI''s hooks weren''t tagging gate events by account yet at the time; this is open until a live occurrence is actually traced end to end.', 'data/orchestrator.db pace_ledger', 801, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T803', 'MindAttic.Orchestrator', 803, '2026-10-24', 'fix', 'closed', 'Set every person tab''s default width to 230px (currently auto-sized/inconsistent).', '79f1e1bf', 802, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T804', 'MindAttic.Orchestrator', 804, '2026-10-24', 'feature', 'closed', 'Settings screen rework: tabbed layout (not one long vertical list), sized to 80% of its container instead of a tall modal. Move the org-wide login toolbar (the name@company.com input, Add login, Sign in all, Report) out of the main dashboard and into Settings. Add a single cog icon button between the key icon and the sun/moon theme toggle in the top-right strip -- that cog becomes the only way to open Settings. Remove the existing settings-access button below the 5-hour utilization chart.', '70c58e4f SettingsModalTests', 803, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T805', 'MindAttic.Orchestrator', 805, '2026-10-24', 'feature', 'closed', 'Dashboard button/tooltip polish: make Refresh an icon-only button (no text label). Make ''open launcher'' a rocket icon-only button. Replace every native/Windows-default tooltip (title-text/alt-text style) across the dashboard with MindAttic.Components.Wpf.Controls.MaToolTips -- no default WPF ToolTips left anywhere.', 'e82364de LibraryOnlyXamlTests.Every_tooltip_is_the_librarys_never_windows_default', 804, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T806', 'MindAttic.Orchestrator', 806, '2026-10-24', 'fix', 'closed', 'Idle 5-hour chart flatlines to 0% for a per-CLI login with no AccountRoster row (e.g. Waffle, 3 repos open): MainViewModel.Phases.cs IdleUtilization falls back to row?.FiveHourUsedAt ?? 0 instead of the block''s own rough BlockPercent when BlockLimitIsPeak/no limit yet, since AccountRoster is only ever populated from the global ~/.claude sign-in, never a per-CLI AccountDir', 'c7c546ee', 805, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T807', 'MindAttic.Orchestrator', 807, '2026-10-24', 'feature', 'wont-do', 'Global Pause/Resume toggle: a pause icon in the top-right strip, next to the key and sun/moon, that immediately suspends every CLI across every login in the org (user, 2026-10-24: machine becomes unusable from RAM and API-call volume; needs to actually stop spending, not just politely finish at the next safe point like the existing M.ORCH-T786 abort lever does). Pause must terminate the running CLI/subagent processes outright (not just refuse their next tool call) so RAM is actually freed and API calls actually stop right away; each killed subagent''s claim is released and its ticket requeued (same safety net M.ORCH-T786 already uses) so nothing is lost beyond in-flight uncommitted work. Clicking the icon again (now showing Resume/Play) lifts the pause so /allocate and dispatch can start new work again -- it does not un-suspend the exact same killed processes, new subagents just pick the requeued tickets back up. While paused, nothing claims or dispatches anything org-wide.', 'superseded by a corrected version: needs a confirm warning before firing, like the API key icon', 806, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T808', 'MindAttic.Orchestrator', 808, '2026-10-24', 'feature', 'closed', 'Global Pause/Resume toggle (corrected, replaces rejected M.ORCH-T807): a pause icon in the top-right strip, next to the key and sun/moon, that immediately suspends every CLI across every login in the org (user, 2026-10-24: machine becomes unusable from RAM and API-call volume; needs to actually stop spending, not just politely finish at the next safe point like the existing M.ORCH-T786 abort lever does). Clicking Pause shows a confirm warning first -- the user must click it and confirm, same pattern as activating the API key -- before anything is actually killed; clicking Resume/Play to lift the pause does not need a confirm. Once confirmed, Pause terminates the running CLI/subagent processes outright (not just refuses their next tool call) so RAM is actually freed and API calls actually stop right away; each killed subagent''s claim is released and its ticket requeued (same safety net M.ORCH-T786 already uses) so nothing is lost beyond in-flight uncommitted work. Clicking the icon again (now showing Resume/Play) lifts the pause so /allocate and dispatch can start new work again -- it does not un-suspend the exact same killed processes, new subagents just pick the requeued tickets back up. While paused, nothing claims or dispatches anything org-wide.', '1e9c4b8f', 807, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T809', 'MindAttic.Orchestrator', 809, '2026-10-24', 'fix', 'closed', 'Fails on main: MindAttic.Orchestrator.Tests.SettingsModalTests.A_single_cog_between_the_key_and_the_theme_toggle_is_the_only_way_into_settings — Assert.That(right, Is.EqualTo(new[] { "ThemeToggle", "SettingsButton", "EmergencyBillingButton" })) Expected is <System.String[3]>, actual is <System.Collections.Generic.List`1[System.String]> with 4 elements Values differ at index [2] Expected string length 22 but was 11. Strings differ at index... (landed on main since the last green run: tickets M.ORCH-T808 in 1e9c4b8f Dashboard: global Pause/Resume toggle in the upper-right corner - after a confirm, ends every Claude CLI on every login outright (with its subagents'' process tree) so RAM is freed and API calls stop at once, requeues every ticket they held first in the queue, and holds every claim, dispatch, /allocate wake and orphan redispatch org-wide until Resume, which needs no confirm (M.ORCH-T808))', 'e0c6744b', 808, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T810', 'MindAttic.Orchestrator', 810, '2026-10-25', 'feature', 'closed', 'Re-add an embedded tabbed Terminals panel to each person''s page, between Current work (the running-agent cards) and Tickets (M.ORCH-T762''s per-person ticket list) -- M.ORCH-T751 (2026-10-23) removed the dashboard''s previous Terminals page and panes entirely (''the dashboard is always just the dashboard''); this reverses that, deliberately, with a different mechanism. Use EasyWindowsTerminalControl (NuGet, wraps the official ConPTY/Windows Terminal backend) instead of whatever the old removed TerminalsViewModel/TerminalPanes used -- plain process-stream redirection (e.g. ConsoleControl) breaks Claude Code''s interactive rendering since it needs a true TTY. One tab per that person''s running CLI session, each a live interactive terminal (full ANSI/24-bit color, GPU accelerated). Also expose a hosting entry point so MindAttic.Launcher can hand a new CLI session to this panel as a new tab (see the companion ticket in MindAttic.Launcher), instead of only ever opening its own standalone window.', '9661ea4e TerminalPanesTests', 809, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T811', 'MindAttic.Orchestrator', 811, '2026-10-25', 'fix', 'closed', 'orchestrator next --claim (and presumably other write paths through JsonStore/OrchestratorDb) throws an unhandled IOException (''the orchestrator''s SQL Server database stayed busy past its timeout'') and exits nonzero under heavy concurrent load (many CLIs/subagents writing at once), instead of retrying with backoff. Add a bounded retry around the DB lock/write path so transient contention under heavy load (the pegged-is-working norm, not something to throttle around) doesn''t surface as a hard command failure.', '0cbf5059', 810, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T812', 'MindAttic.Orchestrator', 812, '2026-10-25', 'fix', 'closed', 'pace_ledger hasn''t recorded a single closed window since 2026-10-23T02:20 (confirmed via M.ORCH-T802''s investigation on 2026-10-25), despite gate_events actively accumulating tagged traffic across many logins through now and usage_samples last written 2026-10-22T22:03. PaceLedgerWatch.Tick (src/MindAttic.Orchestrator.Core/Budget/PaceLedgerWatch.cs) is supposed to close a window and write a pace_ledger row once per 5-hour window per login; find out why it''s stopped doing that table-wide despite continuous heavy CLI activity -- possibly the daemon''s once-a-minute tick isn''t running, or something upstream of it (usage_samples) stopped updating.', 'aa4dbb3f', 811, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T813', 'MindAttic.Orchestrator', 813, '2026-10-25', 'fix', 'open', '[pace-ledger blind] window Oct 24 9:10 PM–2:10 AM closed blind: ryandebraal@mindattic.com: Claude''s meter unseen for 16m while 660.9k were spent, peak 97%, 1 calls held (0.1 min). The pace ran on its own estimate this long without Claude''s meter: make sure it gets a fresh reading whenever tokens are being spent.', 'data/orchestrator.db pace_ledger', 812, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T814', 'MindAttic.Orchestrator', 814, '2026-10-25', 'feature', 'open', 'Global agent rule: never end a turn asking the user to say ''continue''. When usage is over the 5-hour pace, wait on a background timer (poll rl-status.json''s subagent_note until it no longer says ''Cooling off''/''ahead of'') and resume on its own, keeping each login at or under 98%; ramp subagents gradually (3-4 at once) since the forecast is rate-based and a burst overshoots. Put it in mindattic-agent-standard so every CLI and login follows it (requested by the user)', '—', 813, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T815', 'MindAttic.Orchestrator', 815, '2026-10-25', 'feature', 'open', 'deploy.ps1 also deploys the sibling MindAttic.Tickets checkout (and vice versa in Tickets'' own deploy.ps1), via MINDATTIC_DEPLOY_CHAIN to stop the two scripts looping into each other', '—', 814, NULL);
