INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T868', 'MindAttic.Orchestrator', 868, '2026-10-25', 'fix', 'closed', 'Ctrl+V in an embedded CLI terminal pastes the clipboard into the CLI''s prompt; today it does nothing (part of M.ORCH-T865)', 'd36ce228', 867, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T869', 'MindAttic.Orchestrator', 869, '2026-10-25', 'fix', 'closed', 'Make Orchestrator.Desktop uncrashable and stop its memory growth: audit every UI-thread, background-thread, timer and native-terminal path for exceptions that can still kill the process (contain each, log it, keep the window and every terminal alive), and fix garbage collection/leaks (two running Desktop processes sit at 526 MB and 619 MB: closed terminal panes, event handlers never unhooked, tabs and snapshots kept alive)', '5dd79aaf', 868, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T870', 'MindAttic.Orchestrator', 870, '2026-10-25', 'fix', 'closed', 'CLI (terminal) tabs under the person tabs are too tall and waste vertical room: make them compact (person tabs are already the right height)', 'ecc86a1f', 869, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T871', 'MindAttic.Orchestrator', 871, '2026-10-25', 'fix', 'closed', 'Keep the account roster''s 5-hour percent current: AccountRoster.Observe rewrites a row only when the weekly percent moves a point or a window is new, so the roster''s 5-hour figure (the tiles'' fallback when no pace exists) lags the meter between weekly steps', 'e508955b', 870, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T872', 'MindAttic.Orchestrator', 872, '2026-10-25', 'feature', 'closed', 'Status stream phase 2: carry the snapshot''s own figures (pace, budget, counts, agents) in the stream''s messages instead of a ''snapshot published, reread the file'' notice, and have the statusline and hook writers publish to the pipe directly rather than through the daemon''s one-second watch of claude-usage.json', 'a395638b', 871, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T873', 'MindAttic.Orchestrator', 873, '2026-10-25', 'feature', 'closed', 'deploy.ps1 refuses to redeploy while any CLI (any user''s, any login) is busy or has subagents running, since restarting the dashboard drops every embedded CLI''s state; it lists who is still working, with --force to override', 'c857646b', 872, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T874', 'MindAttic.Orchestrator', 874, '2026-10-25', 'fix', 'closed', 'Fails on main: MindAttic.Orchestrator.Tests.AllocateWakerTests.An_idle_cli_is_said_once_per_idle_stretch_and_nothing_is_ever_typed_into_it — Assert.That(Nudges(), Has.Count.EqualTo(1)) Expected: property Count equal to 1 But was: 0 (landed on main since the last green run: tickets M.ORCH-T864, M.ORCH-T869, M.ORCH-T870, M.ORCH-T868, M.ORCH-T852, M.ORCH-T859 in c013ccc0 Review fixes for nudge delivery: a busy CLI takes its nudge at its next tool call or stop (not only a typed prompt), stale and no-longer-due nudges are dropped and none is delivered at the window''s stop or kept through the global pause, resume-after-reset off stops them again, a landed move never nudges the dead old pid, claims nudges to a busy CLI no longer raise Needs-you, and the Esc interrupt for moves is kept (M.ORCH-T864); efec4837 Never type into a CLI''s input box: orchestrator nudges (idle claims, work to claim, resume after a limit, moved tickets) are left as nudge files the UserPromptSubmit hook adds to the turn''s context, instead of being typed mid-sentence into whatever the user is writing (M.ORCH-T864); 5dd79aaf Contain every non-UI-thread and selection crash path: guard pool callbacks, daemon thread, pipe server and Move-to handler, and move the tab selection off a tab before it leaves the org strip (M.ORCH-T869); 5ab7eddd Dispose a closed terminal pane''s control so its ConPTY and buffers are freed (M.ORCH-T869); ecc86a1f Make the CLI terminal tabs compact by shrinking their close button to match the person tabs'' height (M.ORCH-T870); d36ce228 Paste the clipboard into the focused embedded terminal on Ctrl+V and Shift+Insert, bracketed when the CLI asks for it (M.ORCH-T868); 01ecd0d1 Route arrow/Home/End/Page keys straight to the focused terminal and stop Esc binding stealing it (M.ORCH-T852); e94e8b8e Stop closing a CLI tab from crashing the dashboard: deselect the pane before removing it from the TabControl-bound collection, contain pane teardown errors, and handle unhandled UI-thread exceptions (M.ORCH-T859))', 'adb2cf07', 873, NULL);
