INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T922', 'MindAttic.Orchestrator', 922, '2026-10-26', 'chore', 'closed', 'Spike (research at length): run every CLI in a standalone host process that keeps it alive in memory, outside Orchestrator.Desktop, with the dashboard only a pixel-perfect viewer that renders the CLI''s real terminal UI and relays your input; one host owns keeping CLIs online, a dashboard crash or redeploy no longer kills them, and long term a team member''s Desktop can watch (screen-share-like) every CLI of the users they follow while each person stays logged into only their own accounts', '3303f53c', 921, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T923', 'MindAttic.Orchestrator', 923, '2026-10-26', 'chore', 'closed', 'Prototype a relay viewer: a bare TerminalControl with a pipe-fed ITerminalConnection against a stub ConPTY host; verify keys, paste, resize and replay after a viewer restart (spike M.ORCH-T922 phase 0)', 'f26daf6d', 922, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T924', 'MindAttic.Orchestrator', 924, '2026-10-26', 'feature', 'closed', 'TermHost: a detached per-CLI process that owns one ConPTY and serves a per-user, per-session named pipe (framed output, input, resize, exit), outliving the dashboard (M.ORCH-T922 phase 1)', '06e8f9ec', 923, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T925', 'MindAttic.Orchestrator', 925, '2026-10-26', 'feature', 'closed', 'Session registry and discovery: TermHosts register under %LOCALAPPDATA% and announce a term-session kind on the status bus; the dashboard reattaches to them on start (M.ORCH-T922 phase 1)', '75b3225b', 924, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T926', 'MindAttic.Orchestrator', 926, '2026-10-26', 'feature', 'closed', 'Dashboard viewer: Terminals tabs use a RelayTerminal (bare TerminalControl plus RelayConnection) instead of EasyTerminalControl; port T852, T846, T824 and T866 to T868 (M.ORCH-T922 phase 1)', '904a9967', 925, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T927', 'MindAttic.Orchestrator', 927, '2026-10-26', 'feature', 'closed', 'Late-attach replay: a raw output ring reset at full clears, with sticky-mode tracking and a redraw nudge, so a reattached viewer shows the current screen (M.ORCH-T922 phase 1)', 'ebb98e43', 926, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T928', 'MindAttic.Orchestrator', 928, '2026-10-26', 'chore', 'closed', 'Deploy and restore with hosted CLIs: installs never stop TermHosts, the T873 idle gate applies only to unhosted CLIs, and T862 restore covers only sessions whose host died (M.ORCH-T922 phase 1)', '5b62e0c9', 927, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T929', 'MindAttic.Orchestrator', 929, '2026-10-26', 'feature', 'closed', 'Headless VT emulator in TermHost (libghostty-vt first, vtnetcore as fallback) for exact screen and scrollback snapshots on attach (M.ORCH-T922 phase 2)', '052b1c61', 928, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T930', 'MindAttic.Orchestrator', 930, '2026-10-26', 'feature', 'closed', 'Multi-viewer size policy: the interactive viewer that last sent input owns the CLI''s size, others letterbox, and a viewer can take the size explicitly (M.ORCH-T922 phase 2)', '5fc9f5dc', 929, NULL);
