INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.TIX-T18', 'MindAttic.Tickets', 18, '2026-10-15', 'feature', 'closed', 'Build the generated SQLite ticket index (workflow ticket index): rebuilt from every repo''s USER_STORIES.md, markdown stays canonical, db is gitignored', 'TicketIndexTests (TicketIndexTests.cs); dotnet test tests/MindAttic.Workflow.Tests -c Release: 52 passed; workflow ticket index: 550 tickets across 46 repos, cross-checked against ''ticket list --json'' count', 17, NULL);
