INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.TIX-T20', 'MindAttic.Tickets', 20, '2026-10-15', 'feature', 'closed', 'One SQLite database (data/workflow.db, committed to this repo with a readable dump) holds ALL of every repo''s USER_STORIES.md in a structured schema (repos and front-matter, epics, stories with status, priority, acceptance criteria and notes, backlog, tickets, and ordered sections for any free-form prose); every repo''s file is migrated with nothing lost (verified per repo), the workflow CLI reads and writes the db, and the orchestrator reads only the db; replaces the M.FLOW-T18 index', 'WorkflowDbTests.The_real_workspace_migrates_with_every_file_rebuilt_byte_for_byte; migrate: 46 repos, 1046 stories, 561 tickets, 831 links, all rebuild byte-for-byte', 19, NULL);
