INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.TIX-T151', 'MindAttic.Tickets', 151, '2026-10-25', 'fix', 'closed', 'Fails on main: MindAttic.Tickets.Desktop.Tests.HygieneIntakeTests.A_findings_ticket_link_opens_it_in_Repos — Assert.That(model.Detail?.Id, Is.EqualTo("AL-T1")) Expected: "AL-T1" But was: null (landed on main since the last green run: tickets M.TIX-T85 in a12484e Link tickets to their commits: index the commits whose subject names a ticket (git log per repo) and list them, each with its GitHub link, in tickets ticket show (text and --json) and the Desktop detail pane (M.TIX-T85))', 'passes on main@50835f8', 150, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.TIX-T152', 'MindAttic.Tickets', 152, '2026-10-25', 'fix', 'closed', 'Tickets Desktop''s undo toast (M.TIX-T80) still references the Card, PrimaryBtn and IconBtn styles that M.TIX-T91 moved into MindAttic.Components.Wpf as MaCard, MaPrimaryButton and MaToolButton, so MainWindow fails to load with a missing StaticResource; point it at the package''s styles', '63df8d7', 151, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.TIX-T153', 'MindAttic.Tickets', 153, '2026-10-25', 'fix', 'closed', 'tickets ticket show prints bold ANSI codes around the Notes and Commits headings even when NO_COLOR is set, so TicketCliTests.Ticket_note_appends_a_comment_that_show_lists and Show_lists_the_commits_whose_subject_names_the_ticket_with_their_GitHub_links fail on plain-text output (found independently by M.TIX-T74, T78 and T85''s landing subagents)', '3464d9c', 152, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.TIX-T154', 'MindAttic.Tickets', 154, '2026-10-25', 'fix', 'closed', 'Fails on main: MindAttic.Tickets.Desktop.Tests.ReposQueueAuditTests.The_tabs_are_Repos_Queue_Audit_and_the_old_Tickets_view_opens_as_Repos — Assert.That(model.Views, Is.EqualTo(new[] { "Repos", "Queue", "Audit", "Board", "Activity" })) Expected is <System.String[5]>, actual is <<>z__ReadOnlyArray`1[System.String]> with 6 elements Values differ at index [5] Extra: < "Stats" > (landed on main since the last green run: tickets M.TIX-T86 in 8f06f83 Ticket metrics from ticket_events: tickets ticket stats (throughput, cycle time median/mean/p85 overall and by type, open by repo and type per day/week/month, --json) and a Desktop Stats tab (Ctrl+6) of four accessible read-only tables, so delivery pace and backlog trend can be read without exporting (M.TIX-T86))', 'df2b6e1 (already fixed by M.TIX-T82); ReposQueueAuditTests.The_tabs_are_Repos_Queue_Audit_and_the_old_Tickets_view_opens_as_Repos', 153, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.TIX-T155', 'MindAttic.Tickets', 155, '2026-10-25', 'fix', 'closed', 'Fails on main: MindAttic.Tickets.Desktop.Tests.HygieneIntakeTests.A_findings_ticket_link_opens_it_in_Repos — Assert.That(model.Detail?.Id, Is.EqualTo("AL-T1")) Expected: "AL-T1" But was: null (landed on main since the last green run: tickets M.TIX-T82, M.TIX-T86 in df2b6e1 Edit stories and epics in Tickets Desktop: a Stories view (Ctrl+7) lists every repo''s stories under their epics, filtered by repo, search and story status, with an editor that saves a story''s statement, status, acceptance and evidence (Ctrl+S, Revert, refused if changed elsewhere), adds stories and epics, renames an epic, and links implementing tickets undoably; a story ID clicked anywhere opens it there (M.TIX-T82); 8f06f83 Ticket metrics from ticket_events: tickets ticket stats (throughput, cycle time median/mean/p85 overall and by type, open by repo and type per day/week/month, --json) and a Desktop Stats tab (Ctrl+6) of four accessible read-only tables, so delivery pace and backlog trend can be read without exporting (M.TIX-T86))', 'HygieneIntakeTests.A_findings_ticket_link_opens_it_in_Repos @ main 3fc4ee9', 154, NULL);
