INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('PL-T20', 'ProcessLogger', 20, '2026-10-19', 'fix', 'closed', 'ProcessWatcherService.PersistAsync only catches ArgumentException around Process.GetProcessById(...).ProcessName/.MainWindowTitle, so Win32Exception/InvalidOperationException silently drop a process event and (in HandleStopAsync) skip MemorySamplerService.StopSampling, leaking the tracker', 'dotnet test ProcessLogger.slnx', 19, NULL);
