INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('PL-T28', 'ProcessLogger', 28, '2026-10-23', 'fix', 'open', 'The logger''s MindAttic.Log database grows ~1.7 GB a day: C:\Users\ryand\AppData\Roaming\MindAttic\Logging\ProcessLogger\MindAttic.Log.db holds 1,067,472 Information rows from 19 hours (2026-10-19T23:27Z..2026-10-20T18:32Z), 641,389 of them EF Core ''Executed DbCommand'' lines (Microsoft.EntityFrameworkCore.Database.Command logged at Information for every insert) and ~426,000 per-process ''+ [Source] Name'' / ''- Name ran ...ms'' lines that duplicate the ProcessEvents rows already in processlogger.db; raise Microsoft.EntityFrameworkCore to Warning and drop the per-process lines to Debug so the operational log holds only lifecycle, warnings and errors, with a test that a captured process start/stop writes no Information row to MindAttic.Log (found by audit M.ORCH-T657)', '—', 27, NULL);
