INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('RB-T51', 'REA.Bloodlines', 51, '2026-10-22', 'feature', 'closed', 'Map state persistence as in the original: loading a save or returning to a map restores opened doors, picked-up items, killed NPCs and entity state instead of resetting the map (gap listed by RB-T36)', '791ea66 MapStateTests', 50, NULL);
