INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('RB-T59', 'REA.Bloodlines', 59, '2026-10-22', 'fix', 'closed', 'HUD is CSS bars and Poppins text, not the original''s: draw scripts/640_hud.txt sprites and bitmap digit fonts (hud1_inner number_*, bloodbar/frenzybar/feedbar, health_level, ammo_label, armorframe) from materials/hud', '8e0594f', 58, NULL);
