INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('RB-T66', 'REA.Bloodlines', 66, '2026-10-22', 'feature', 'closed', 'Presence passive is not wired: no activation key, no Presence_Effect_Radius debuff group (Discipline (Presence-LevelN): Strength/Wits/Perception -N, Stamina -2/-4 at 4/5) on nearby enemies, and Disciplines.PresenceBenefit (allied combat benefit, 3/3/3/2/2/2/2/1/1/1) is never called from the engine (RULES.md 1.3, 4.1)', '6cbf679 (DisciplineTests.Presence_aura_debuffs_enemies_and_helps_allies)', 65, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('RB-T67', 'REA.Bloodlines', 67, '2026-10-22', 'feature', 'closed', 'Bloodbuff (Corpus_Vampirus) is not usable in play: no activation, so Strength/Dexterity/Stamina +2 with cap raised to 10 for 14 s at 3 blood (needs BloodPool > 2) never applies (RULES.md 4.1, stats_vampire.txt Active_Bloodbuff)', '001a703 (Vdata_Bloodbuff, RB_T67_HotkeyMenuOffersBloodbuff)', 66, NULL);
