INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('RB-T71', 'REA.Bloodlines', 71, '2026-10-22', 'feature', 'closed', 'Targeted discipline Thaumaturgy 1-5 (disciplinetgt_003.txt: Blood Strike, Blood Purge, Blood Shield, Blood Theft, Blood Boil) is not castable in play; implement including Dmg_Health as a percent of target Max_Health (RULES.md 4.1, 0x101de2f0) and Health_Buffer', 'b5ba80a', 70, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('RB-T72', 'REA.Bloodlines', 72, '2026-10-22', 'feature', 'closed', 'Targeted discipline Presence 1-5 casts (disciplinetgt_004.txt: daze radii 150/250/350/500/700, blood 1/1/2/3/3, Overt from 3) are not castable in play; implement with the Overt supernatural act', '4b91920; DisciplineTests.Presence_aura_rerolls_its_hit_each_update, Presence_schedules. Scope note: the requested BloodCost 1/1/2/3/3 and Overt act were deliberately NOT added - the original never casts Presence_Level1..5 (Presence is Is_Passive; 0x100d8830 sends only non-passive disciplines to the targeted cast); the rows feed only the passive aura (0x101e34c0), which charges no blood and reports no act. Done instead: aura hit re-rolled through 0x101e3730 each 0.2-0.4 s, D_DAZE/D_MESMERIZE/FLEE_AND_COWER schedules on NPCs, one hit off per update via 0x101e3ff0', 71, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('RB-T73', 'REA.Bloodlines', 73, '2026-10-22', 'fix', 'closed', 'DialogDiscipline (BloodlinesCharacter.DialogDiscipline, the dialogue Dominate/Dementation/Presence use) calls the passive Disciplines.Activate on the caster own sheet, which does nothing for targeted powers (no Active_Dominate stat); the original goes through the targeted-discipline path on the target (ICharacter.DialogDiscipline, vampire.dll script API)', '88ea2af', 72, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('RB-T74', 'REA.Bloodlines', 74, '2026-10-22', 'feature', 'closed', 'Armor items do nothing: item_a_* (body armor, light/heavy cloth and leather) name a wield_effect trait group (Item (Light Leather): armor rating, Dexterity penalty) in vdata/items, but nothing equips armor or applies the group (grep wield_effect in src finds nothing)', '99e4438', 73, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('RB-T75', 'REA.Bloodlines', 75, '2026-10-22', 'feature', 'closed', 'Passive occult and research items have no effect: item_p_occult_* (blood buff, dexterity, dodge, experience, frenzy, hacking, heal rate, lockpicking, obfuscate, passive durations, presence, regen, strength, thaum damage) and item_p_research_* are picked up as inventory strings only; apply their trait-effect groups while carried (e.g. Item (Occult Frenzy) Frenzy_Check_Mod +1, RULES.md 5.1)', '0498612', 74, NULL);
