INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('SET-T12', 'SyntheticExchangeTheory', 12, '2026-10-17', 'docs', 'closed', 'Remove Chapter 7 (The Prototype: A Closed Agrarian Pilot) and Appendix B (its pre-registration protocol) entirely, and scrub every cross-reference to the agrarian/farm pilot across Ch. 1, 3-6, 8, 10, Appendix C glossary, README.md and docs/USER_STORIES.md; renumber remaining chapters/appendices and update export.json to match', 'Superseded by SET-T14/SET-T15: Ryan corrected the sequencing 2026-10-17 -- build the replacement chapter first, retarget references, remove the agrarian chapter last', 11, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('SET-T13', 'SyntheticExchangeTheory', 13, '2026-10-17', 'docs', 'closed', 'Spike: design a fundamentally scientific experiment, run in a closed space with a genuine control environment (not an agrarian/farm settlement), to test whether a compute-funded basic income backed by AI systems'' willingly-given user training-data contributions is viable, i.e. whether that designed dependence actually shifts system behavior toward provider wellbeing; deliver a pre-registration-style write-up of the chosen design, leaving chapter drafting to a follow-up ticket', 'Superseded by SET-T14: scope corrected to draft the actual replacement chapter text, not defer drafting to a follow-up ticket', 12, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('SET-T14', 'SyntheticExchangeTheory', 14, '2026-10-17', 'docs', 'open', 'Design and draft the replacement Ch. 7: a fundamentally scientific experiment, run in a closed space with a genuine control environment (not an agrarian/farm settlement), testing whether a compute-funded basic income backed by AI systems'' willingly-given user training-data contributions is viable, i.e. whether that designed dependence shifts system behavior toward provider wellbeing. Deliverable is the actual chapter text plus its pre-registration-style protocol appendix, written alongside the existing Ch. 7 (nothing removed yet)', 'Supersedes SET-T13; first of a three-step sequence set by Ryan 2026-10-17: build replacement, retarget references, remove agrarian chapter', 13, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('SET-T15', 'SyntheticExchangeTheory', 15, '2026-10-17', 'docs', 'open', 'After SET-T14''s replacement chapter exists: retarget every cross-reference to the agrarian/farm pilot across Ch. 1, 3-6, 8, 10, Appendix C glossary, README.md, AGENTS.md and docs/USER_STORIES.md to the new design; only then remove the old agrarian Ch. 7 text and Appendix B pilot protocol, renumbering chapters/appendices and updating export.json if numbering changes', 'Requires SET-T14; supersedes SET-T12 with the order corrected (references retargeted before the agrarian chapter is removed)', 14, NULL);
