INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('GGC-T3', 'TownWalker', 3, '2026-10-14', 'chore', 'closed', 'NUnit tests for AStar and RouteGraph (Assets/Lab/Core/Routing.cs): AStar finds the cheapest path not just the first, returns [start] when start==goal, null when unreachable or when maxNodes is exhausted, skips infinite-cost edges; RouteGraph.Build keeps edges symmetric, caps each node at ''links'' nearest, always links the nearest neighbour even beyond maxLen (so no isolated site), and node 0 is the start', '49e1a64', 2, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('GGC-T4', 'TownWalker', 4, '2026-10-14', 'chore', 'open', 'NUnit tests for LabSession edge cases (Assets/Lab/Core/Town.cs): Scan with fuel < ScanCost returns 0 and spends nothing; WalkTo while stranded is a no-op; Tick returns true on the arrival frame and doesn''t overshoot; Send returns null for null/cleared/out-of-bike-range sites and computes RoadFights=min(2,dist/11) and RideSeconds; EndBattle(false) gives no loot and still resets the phase/metric baselines; won fuel is capped at FuelMax; AverageTimeToBattle/AverageTapsToBattle are 0 with no battles', '—', 3, '| GGC-T4 | 2026-10-14 | chore | open | NUnit tests for LabSession edge cases (Assets/Lab/Core/Town.cs): Scan with fuel < ScanCost returns 0 and spends nothing; WalkTo while stranded is a no-op; Tick returns true on the arrival frame and doesn''t overshoot; Send returns null for null/cleared/out-of-bike-range sites and computes RoadFights=min(2,dist/11) and RideSeconds; EndBattle(false) gives no loot and still resets the phase/metric baselines; won fuel is capped at FuelMax; AverageTimeToBattle/AverageTapsToBattle are 0 with no battles | — |');
