INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.CHN-T40', 'Unity.Chain', 40, '2026-10-23', 'feature', 'closed', 'Port Background.vb and Textures.vb: a backdrop quad behind the play field (bgWidth 1.2 and bgHeight 0.415 half-extents, offset -0.56), starting on gfx/area/beach.png, B showing beach and N showing utopia (area/utopia.png), the brick-textured room (Cube.vb, brick.jpg, a 67x55x38 cube the camera sits inside) behind it as the fallback; the original''s second Keys.B case that would toggle the background is unreachable and is not ported; landscape.jpg, landscape2.jpg, 01.png, 02.png and 512.JPG are kept as unused area art in a data-driven area list', 'f7f94fc', 39, NULL);
