INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.CHN-T45', 'Unity.Chain', 45, '2026-10-23', 'chore', 'closed', 'Audit the rebuild''s physics and combat against docs/RECONSTRUCTION.md and settle every deviation as a data setting whose default is the original''s behaviour: spring pull from the previous link only (Chain.vb''s If/ElseIf; the rebuild pulls from both neighbours), per-frame stepping scaled to match the original''s feel at 60 fps, the link(1) 0.0004 per-frame drop, the mace offset, damage = abs(dX + dY/2) from the mass-divided velocity, HP+1 bars and game over below zero, all 25 links simulated; keep the rebuild''s choice only where the owner confirms it, and update the BIBLE deviation table; add tests that replay a scripted mouse path against a recorded original trajectory', '0281bc0', 44, NULL);
