INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UC-T20', 'Unity.Cursory', 20, '2026-10-21', 'fix', 'closed', 'PhysicsWorld is not rebuilt when a level is reset or switched: the server keeps the previous level''s Rigidbody2D bodies, joints and walls, so a passed reset vote or level-switch vote (UC-T10) leaves stale physics that no longer matches the reloaded level data; tear down and rebuild PhysicsWorld (releasing every cursor''s grab first) on every level load, with a PlayMode test that resets mid-grab and switches level', 'PlayMode LevelReloadTests 2/2 (suite 39/39); 7ea6e96', 19, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UC-T21', 'Unity.Cursory', 21, '2026-10-21', 'fix', 'closed', 'Unity.Cursory PlayMode tests bind the fixed port 7777, so two test runs on the same machine (parallel worktrees, CI with another job, a running local server from deploy.ps1 -Profile Local) collide and fail spuriously (seen: LevelStateSyncTests failed while UC-T8''s run held 7777); tests should pick a free ephemeral port per session (via NetBootstrap.Configure / NetConfig) through one shared test helper', 'PlayMode suite 50/50 (TestPorts) 311db89', 20, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UC-T22', 'Unity.Cursory', 22, '2026-10-21', 'feature', 'closed', 'Add deploy.ps1/deploy.bat and an Editor build entry point so a Desktop shortcut can pull latest, build Release, and launch', 'af9e525', 21, NULL);
