INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.EVE-T29', 'Unity.Eve', 29, '2026-10-24', 'fix', 'closed', 'U.EVE-T19 names the repo as ''UnityEve'' (no dot) in its publish line and Pages URL; the actual repo/GitHub name is Unity.Eve (with a dot, confirmed via its git remote). Fix both to Unity.Eve. Found while correcting MAT-T51''s stale-name tickets.', '6219b99 already uses Unity.Eve throughout (publish line text + Pages URL https://mindattic.github.io/Unity.Eve/); GitHub repo confirms homepageUrl=https://mindattic.github.io/Unity.Eve/ and Pages html_url=https://mindattic.github.io/Unity.Eve/ -- no stale ''UnityEve'' remains, no change needed', 28, NULL);
