INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UQD-T9', 'Unity.QuickDuel', 9, '2026-10-21', 'chore', 'closed', 'CI: GitHub Actions workflow that runs dotnet test Core.slnx on every push to main', 'b4e263d', 8, NULL);
