INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UQD-T12', 'Unity.QuickDuel', 12, '2026-10-21', 'docs', 'closed', 'Docs: credit Samurai Kirby (Kirby Super Star) as the original inspiration and record the online PvP design (credit Christopher Danielson) in docs/ORIGINS.md', '6b0dead', 11, NULL);
