INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UQD-T47', 'Unity.QuickDuel', 47, '2026-10-23', 'feature', 'closed', 'Parity: a Credits entry on the main menu opens a screen listing the arena photo credits from the original''s credits.txt (Dusty Junction, The Fumaroles, Sozza''s Point, South Ridge, Arid Plains and the rest) and Ryan''s own credit, loaded from the data file', 'd49d9ad', 46, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UQD-T48', 'Unity.QuickDuel', 48, '2026-10-23', 'feature', 'closed', 'Parity: the match verdict uses the original''s victory and game over backgrounds (bg_victory, bg_gameover) with a Game Over or victory heading and a Retry or Continue button that returns to the menu or starts a new match; the original''s HP-based end is replaced by best of 3, as the BIBLE already says', 'dc50b62', 47, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UQD-T49', 'Unity.QuickDuel', 49, '2026-10-23', 'feature', 'closed', 'Parity: the original''s per-arena ambient effects as particle emitters (sand in the Wastes of Nod, butterflies in Pastel Fields, snow in Frozen Tundra, fog in the Fumaroles, flies in Arid Plains; the original''s unused rain, leaf and firefly emitters included as options), driven from the arena data', '4d57433', 48, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UQD-T50', 'Unity.QuickDuel', 50, '2026-10-23', 'feature', 'closed', 'Parity: F1 toggles fullscreen (the original''s F1 handler), the 640 by 480 original frame is letterboxed to any window size, and a round clock mm:ss slides in at the top centre and runs while a match is on; the original''s F12 debug overlay (reaction numbers per side) becomes a developer toggle', '5fea175', 49, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UQD-T51', 'Unity.QuickDuel', 51, '2026-10-23', 'chore', 'closed', 'Standards gap: add EditMode tests (a new Unity.QuickDuel.Editor.Tests asmdef) for the scene builder, the art and data generators and the settings registry validation, and PlayMode tests for each parity scene (intro, menu, credits, duel, verdict), with screenshots committed as evidence', '40e30af', 50, NULL);
