INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UQD-T55', 'Unity.QuickDuel', 55, '2026-10-23', 'docs', 'closed', 'Add the owner''s rule (2026-10-23) to AGENTS.md''s rebuild standard: broken things found in the original source are fixed in the Unity version, which plays the way the game was clearly meant to (not as its bugs made it), each fix recorded in the BIBLE as a fixed defect; everything else still matches the original exactly', 'c64f748', 54, NULL);
