INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('MAU-T5', 'Unity.Shared', 5, '2026-10-20', 'chore', 'closed', 'Rename MindAttic.Unity repo/folder/namespace to MindAttic.Unity.Shared: its README already describes it as the shared Unity package (player profiles, common helpers) every MindAttic game depends on, distinct from an actual game named just ''Unity''. Update: GitHub repo rename, local folder, git remote, settings.json/Launcher roster Project entries (fixes a duplicate ''MindAttic.Unity'' row in the Open Project Tab menu), MindAttic.Unity.Multiplayer''s project reference to it, and the README title itself.', '—', 4, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('MAU-T6', 'Unity.Shared', 6, '2026-10-20', 'chore', 'closed', 'Rename MindAttic.Unity.Shared to Unity.Shared: Unity-fleet naming pass applies the same convention as Unity.Multiplayer (a shared Unity library, not a MindAttic-specific project, so it takes the Unity. prefix). Update GitHub repo rename, local folder, git remote, namespace/assembly names, references from Unity.Multiplayer and other consumers, Launcher roster entries, docs/workspace-repos.json and command-catalog.json, and the README title.', '—', 5, NULL);
