INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('MAU-T8', 'Unity.Shared', 8, '2026-10-24', 'fix', 'wont-do', 'MAU-T4 still names the pre-rename repo: ''Publish MindAttic.Unity docs ... https://mindattic.github.io/MindAttic.Unity/ returns 200'' should say MindAttic.Shared -- wait, the repo is Unity.Shared (MAU-T5/T6 renamed it from MindAttic.Unity then MindAttic.Unity.Shared); fix the publish-line repo name and the Pages URL to Unity.Shared (found while correcting MAT-T51''s other stale-name tickets).', 'filed with stray phrasing; refiled cleanly', 7, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('MAU-T9', 'Unity.Shared', 9, '2026-10-24', 'fix', 'open', 'MAU-T4 names the pre-rename repo in its own publish line and Pages URL (''Publish MindAttic.Unity docs ... https://mindattic.github.io/MindAttic.Unity/ returns 200''); the repo is now Unity.Shared (MAU-T5/T6). Fix both to Unity.Shared. Found while correcting MAT-T51''s stale-name tickets.', '—', 8, NULL);
