INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T314', 'Unity.SpaceGod', 314, '2026-10-19', 'fix', 'closed', 'Pursuit.Step keeps chasing after the leader is pulled into another battle, and then drops the group without pinning its escorts', 'PursuitTests.AChaseWhoseLeaderIsPulledIntoAnotherFightEndsAndItsEscortsArePinnedWhereTheChaseLeftThem (9a4f729)', 313, NULL);
