INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T316', 'Unity.SpaceGod', 316, '2026-10-19', 'fix', 'closed', 'A bomber''s wingmen can fire torpedoes at a target that is already dead or has surrendered', 'b3d1940', 315, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T317', 'Unity.SpaceGod', 317, '2026-10-19', 'fix', 'closed', 'A bounty contract on a captain the player takes alive never completes (Contracts.cs:1102 checks u.Side where it should check u.FoughtOn)', 'd7b8361', 316, NULL);
