INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T323', 'Unity.SpaceGod', 323, '2026-10-19', 'fix', 'closed', 'Two overlapping interstellar wars can hand a captured gate back to the wrong owner when the second was declared by hand', 'ff5bbb7', 322, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T324', 'Unity.SpaceGod', 324, '2026-10-19', 'chore', 'closed', 'Back up the Ultimate Spaceships Creator Evaluation Claude artifact into artifacts/ per HOUSE-LAW-12', 'UnitySpace (31c304c)', 323, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T325', 'Unity.SpaceGod', 325, '2026-10-19', 'feature', 'closed', 'Move UnitySpace''s player profiles onto the shared MindAttic.Unity package and format (owner 2026-10-19; requires MAU-T2): reference com.mindattic.unity via file:../../MindAttic.Unity, replace Core/Persistence/Profiles.cs ProfileStore/PlayerProfile with the package''s API, and migrate each profile''s Settings/<setting>.txt files (display, auto-reorient, ...) into the single Profiles/<Name>/settings.json (common keys + UnitySpace''s own under game), keeping current.txt and Saves/. Old .txt files kept aside after migration. Leave it proposed until the in-progress uncommitted profile work in UnitySpace is committed.', 'ProfileTests (7: settings in settings.json game block, legacy Settings/*.txt migration kept aside as Settings.old); bdf1c93', 324, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T326', 'Unity.SpaceGod', 326, '2026-10-19', 'fix', 'closed', 'The rename to UnitySpace missed the editor menu (still Solar System > Rebuild Main Scene / Build Windows Player) and the app''s root object name, so both now say UnitySpace', 'Assets/UnitySpace/Editor/ProjectSetup.cs', 325, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T327', 'Unity.SpaceGod', 327, '2026-10-19', 'feature', 'closed', 'Player data lives in per-profile folders with one file per setting instead of PlayerPrefs, and the game opens on a Main Menu scene with Continue, New Game, Load Game, Profiles (switch or create), Settings and Quit; saves are unlimited with New Save, Save, Load and Delete, and the Esc menu gains Save / Load and Main Menu', 'ProfileTests, SaveGameTests.SlotsKeepTheirOwnSaves', 326, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T328', 'Unity.SpaceGod', 328, '2026-10-19', 'feature', 'closed', 'Every navigator line keeps its name fixed and its details (distance, gates, news age, status) after it, scrolling as a marquee to the right of the name when they do not fit', 'Hud.NameAndDetails', 327, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T329', 'Unity.SpaceGod', 329, '2026-10-19', 'chore', 'wont-do', 'Convert tracked source files to LF line endings via .gitattributes, per HOUSE-LAW-13 (low priority)', '—', 328, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T330', 'Unity.SpaceGod', 330, '2026-10-19', 'feature', 'closed', 'Asteroid-belt mining pipeline: capture asteroids, grind to dust, separate into elements, ship to warehouses, feeding all megastructure builds (shipyards, space elevators, eventual Dyson spheres); raw-material convoys and remote-moon warehouses are piracy targets, enroute theft more common than warehouse raids', 'fbb1574', 329, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T331', 'Unity.SpaceGod', 331, '2026-10-20', 'docs', 'closed', 'Publish UnitySpace docs to GitHub Pages via the shared Toolkit DocFX pipeline: run adopt-docs-site.ps1 (README.md as home page, docs/*.md as articles, API reference only where the code builds in CI), enable Pages with build_type=workflow, set the repo homepage URL, retire tools/build-readme.ps1 and README.htm, confirm the docs Actions run is green and https://mindattic.github.io/UnitySpace/ returns 200. Depends on MAT-T8.', 'Unity.SpaceGod@9bae33f', 330, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T332', 'Unity.SpaceGod', 332, '2026-10-20', 'fix', 'closed', 'Pursuit.Consider counted each new chase twice against MaxGroups (Begin already adds it to Groups), so at most one hostile group could turn to run the pilot down per check instead of two', 'PursuitTests.TwoHostileGroupsCanBothTurnToChaseOnOneLook, 8928f4e', 331, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T333', 'Unity.SpaceGod', 333, '2026-10-20', 'fix', 'wont-do', 'A chasing group whose leader was destroyed outside a battle was dropped without being released, so its surviving escorts snapped back to their old schedule instead of being pinned where the chase left them', 'Duplicate: fixed on main by U.SPC-T314 (9a4f729)', 332, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T334', 'Unity.SpaceGod', 334, '2026-10-20', 'fix', 'closed', 'Battle.Capture did not clear other units'' Target on the taken hull, so ships of its captor''s side kept circling and turning their broadsides on their own prize until their retarget timer ran out', '81f2cbe', 333, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T335', 'Unity.SpaceGod', 335, '2026-10-20', 'fix', 'closed', 'A free ship parked at a star could take a whim to wander three to five solar radii out, deep inside the Sun keep-out every trajectory refuses, and so skim the star on a rest-to-rest burn', '5daa290', 334, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T336', 'Unity.SpaceGod', 336, '2026-10-20', 'fix', 'closed', 'Fleet.EstimateTrip never priced a slow boat''s time riding the hyperlanes when weighing them against a transfer orbit straight across, tilting the choice toward the lanes', '239243e', 335, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T337', 'Unity.SpaceGod', 337, '2026-10-20', 'fix', 'closed', 'War.Interdictions compared a rider''s last position on one lane with its position on another, so a ship that rode one lane out and another in between looks was taken for passing a lurker''s station', 'e1bd378', 336, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T338', 'Unity.SpaceGod', 338, '2026-10-20', 'fix', 'wont-do', 'A pirate clan''s hostages and stolen warships were sent to the first standing haven of any clan in the system, not to the captor''s own, so a prize never unloaded its plunder and followed the wrong haven''s fortunes', 'Duplicate: fixed on main by U.SPC-T306 (86ca694)', 337, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T339', 'Unity.SpaceGod', 339, '2026-10-20', 'fix', 'wont-do', 'PirateRecruiting could base a new band of the system''s clan at another clan''s haven (the fewest-bands pick looked at every haven), leaving it a home where it could never unload plunder', 'Duplicate: fixed on main by U.SPC-T306 (86ca694)', 338, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T340', 'Unity.SpaceGod', 340, '2026-10-20', 'fix', 'wont-do', 'War.MergeGroups left a merged raider leader''s plunder aboard it as an escort, where nothing ever unloads it or counts it toward the group going home', 'Duplicate: fixed on main by U.SPC-T308 (8cd2518)', 339, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T341', 'Unity.SpaceGod', 341, '2026-10-20', 'fix', 'wont-do', 'Polities.CapitalOf overwrote a polity''s founding capital with its stand-in once the capital was lost, so the peace was signed in the wrong place and a retaken capital never became the seat again', 'Not a bug: PolitiesTests.ACapitalLostMovesTheSeatToTheBiggestHoldingLeftInAnySystem asserts the seat stays moved after a retake', 340, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T342', 'Unity.SpaceGod', 342, '2026-10-20', 'fix', 'closed', 'A war fleet flagship dry in port waiting on a tanker passed InterstellarWars.Fit but was refused by Idle every day, so it held back every other group of its faction from going on campaign', 'fc2b53a', 341, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T343', 'Unity.SpaceGod', 343, '2026-10-20', 'fix', 'wont-do', 'PirateClans.MoveBand checked for bands relocating from the empty haven''s own system, not for bands already bound for it, so a second band could be sent while the first was still on its way', 'Duplicate: fixed on main by U.SPC-T302 (bd80399)', 342, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T344', 'Unity.SpaceGod', 344, '2026-10-20', 'fix', 'closed', 'World.Wire gave Pursuit and Companies one seed and MerchantEscorts and Holdings another, so each pair drew the very same random numbers in step', '48f0ca1', 343, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T345', 'Unity.SpaceGod', 345, '2026-10-20', 'fix', 'closed', 'A freight, passenger or colonist contract taken for a settlement later abandoned to ruin was still delivered and paid there, putting its goods and people into a dead settlement for good', 'fe6b5c8', 344, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T346', 'Unity.SpaceGod', 346, '2026-10-20', 'fix', 'closed', 'Materials and view meshes of the game scene were never freed on going back to the Main Menu (DontSave, and the meshes held in a static set), so every menu round trip leaked a whole system''s worth', '9974adf', 345, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T347', 'Unity.SpaceGod', 347, '2026-10-20', 'fix', 'closed', 'The helm''s out-of-battle collisions struck escorts at their leader''s centre (the fleet places an escort at its leader; only the view offsets it), stacking phantom hulls there instead of where they are seen', '143c013', 346, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T348', 'Unity.SpaceGod', 348, '2026-10-20', 'fix', 'closed', 'The top bar''s speed-up button called the clock directly and so sped time up while the helm was being hunted, which the key refuses', '6d6bc67', 347, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T349', 'Unity.SpaceGod', 349, '2026-10-20', 'fix', 'closed', 'A drives-down EMP timer and an active chase carried over to the next hull taken at the helm in the same frame (a spawn, a loaded save), since both were only reset on a frame with no helm at all', '68ae6c9', 348, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T350', 'Unity.SpaceGod', 350, '2026-10-20', 'fix', 'closed', 'A broadside trigger held as a fight ended or the helm was let go stayed latched, so the first frame of the next battle without it held fired a volley the player never called', '8b35d1c', 349, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T351', 'Unity.SpaceGod', 351, '2026-10-20', 'fix', 'closed', 'Tab-backward with no ship selected picked the second-to-last ship instead of the last', '3ec09be', 350, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T352', 'Unity.SpaceGod', 352, '2026-10-20', 'fix', 'closed', 'War.TryStartPlayerAttack swept every ship of the target''s flag parked anywhere at the system root into a fight at one jump gate, where every other way of starting a fight takes in only those within GateFightRangeKm', '9773d07', 351, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T353', 'Unity.SpaceGod', 353, '2026-10-20', 'fix', 'closed', 'War.Succession did not pass a gate-watching band''s stake-out to its new flagship, so a band whose flagship was lost or taken over sat parked at the gate ambushing nothing and then dropped the watch', 'f62c7ca', 352, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T354', 'Unity.SpaceGod', 354, '2026-10-20', 'fix', 'closed', 'Fighters.Steer read a zero velocity to match as nothing to match, so a fighter homing on a carrier or a wingman on a lead that was standing still came in at full speed and overshot', '35add86', 353, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T355', 'Unity.SpaceGod', 355, '2026-10-20', 'fix', 'closed', 'Ship.LaneHold was never cleared once a lane ride ended, so a hull that had once dropped or been pulled out of a lane was offered a rejoin of that finished leg whenever it came near its old exit point', '7eaab67', 354, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T356', 'Unity.SpaceGod', 356, '2026-10-20', 'fix', 'closed', 'Each system''s MarketShocks lifted every embargo in the shared diplomacy table that it had not itself recorded contraband for, so an embargo one system declared was lifted by another the next day and re-declared daily', '0371aa6', 355, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T357', 'Unity.SpaceGod', 357, '2026-10-20', 'fix', 'closed', 'Passengers and colonists aboard a hull that went through a jump gate or was sent to the breakers were logged as lost with it (both are marked Destroyed) instead of going back ashore where they boarded', '07176cc', 356, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T358', 'Unity.SpaceGod', 358, '2026-10-20', 'fix', 'closed', 'A warehouse or station share at a settlement abandoned to ruin was never written off, so its rent was charged for ever on stock that could never be sold', 'd15f3e1', 357, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T359', 'Unity.SpaceGod', 359, '2026-10-20', 'fix', 'closed', 'A company hull inside a jump gate when its company was bought out came out with no company under the old flag, since Merge never saw it, instead of joining the buyer as its sister hulls did', '4a5f7d0', 358, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T360', 'Unity.SpaceGod', 360, '2026-10-20', 'fix', 'closed', 'InterstellarWars.Locate took a campaign flagship that had been captured or left a hulk (with no heir to pass the voyage to) as the campaign still, so the campaign never ended and its side never sent another fleet', '8da4ed7', 359, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T361', 'Unity.SpaceGod', 361, '2026-10-20', 'chore', 'closed', 'Rename UnitySpace to Unity.SpaceGod: part of the Unity-fleet naming pass (all Unity game repos get a Unity. prefix). Covers GitHub repo, local folder, git remote URL, ticket DB key (tickets repos rename), C# namespaces/asmdefs/class comments referencing the old name throughout Assets/, README/AGENTS/CLAUDE docs, build scripts and logs'' repo-name strings, and any other repo that references UnitySpace by name (grep workspace-wide). Owner-approved 2026-10-20 as part of the Unity Fleet Rename effort; run crossrepo from a General (workspace-root) window so the folder move is included.', '6c61cb4', 360, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T362', 'Unity.SpaceGod', 362, '2026-10-21', 'fix', 'closed', 'A port starved into surrender by siege is never recorded as occupied from its old owner, so the peace treaty that ends the war never counts its system as ceded and its people can never rise to retake it, unlike a port a campaign''s marines storm, which is', '704decf', 361, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T363', 'Unity.SpaceGod', 363, '2026-10-21', 'fix', 'closed', 'EventDirector''s own-band exclusion for a bounty or ambush opportunity compares the player''s piloted ship''s whole pirate-clan Faction, not the specific raider band (flagship plus escorts) the opportunity is on, so flying a hull of one band denies credit for busting an unrelated ambush or bounty from the same clan; no persistent per-band identity survives EnterPiloting''s immediate Leader=null, so the fix needs a design decision (e.g. a tracked band id) rather than a safe one-line change', '9d4dfcd', 362, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T364', 'Unity.SpaceGod', 364, '2026-10-21', 'fix', 'closed', 'Weapons fire could still land on a hull that had already struck its colours: a kinetic round arriving in flight, a beam''s line-of-fire raycast and a mine''s or EMP''s blast radius all lacked the Surrendering check StepMissiles already uses, so a round in the air or a blast/beam sweeping past could still damage or kill a hull waiting on its captor''s terms. Fixed by adding the same check to the kinetic-round arrival, FirstHostileAlong''s raycast and the mine/EMP blast loop, with regression tests.', 'GunneryTests.ThePlayersBeamDoesNotHitAHullThatHasStruckItsColours, SurrenderTests.ARoundInFlightSparesAHullThatStruckItsColoursWhileItWasOnItsWay, SurrenderTests.AMineDoesNotBlowAHullThatHasStruckItsColours', 363, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T365', 'Unity.SpaceGod', 365, '2026-10-21', 'fix', 'closed', 'MilitaryLogistics.Dispatch destroyed a sliver of a naval base''s market stock for nothing whenever its Take() calls ran ahead of the prop+mun+spares<1 bail-out, paying nothing and sending no convoy', 'a8e8f1a', 364, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T366', 'Unity.SpaceGod', 366, '2026-10-21', 'fix', 'closed', 'GUI DontSave Texture2D fields in Hud/MainMenu/PauseMenu/GalaxyMapScreen and UnitySpaceApp.Collisions'' contactToastAt dictionary leak across scene reloads and a long session, the same problem Materials.DestroyAllOwned/BattleFx.PruneSeen already solved for Material/Mesh/seen-dictionary but was never extended to these; no automated test harness covers the Runtime/Unity layer (Tests/Core.Tests only covers engine-free Core), so this needs a human with a Unity Editor to verify a fix rather than a blind edit', '1fc4817', 365, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T367', 'Unity.SpaceGod', 367, '2026-10-21', 'docs', 'closed', 'Update USER_STORIES.md', '—', 366, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T368', 'Unity.SpaceGod', 368, '2026-10-21', 'feature', 'closed', 'Add a deploy.ps1 that builds Unity.SpaceGod in Release into C:\Apps\Unity.SpaceGod only when stale, and writes deploy.bat (redeploy, then launch); replace the broken ''Unity Solar System'' desktop shortcut (C:\Apps\UnitySolarSystem no longer exists) with one to deploy.bat', '1bdf53f', 367, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T369', 'Unity.SpaceGod', 369, '2026-10-21', 'feature', 'closed', 'Add deploy.ps1/deploy.bat and an Editor build entry point so a Desktop shortcut can pull latest, build Release, and launch', '20f507e', 368, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T370', 'Unity.SpaceGod', 370, '2026-10-21', 'fix', 'closed', 'Flight model: taking control of a ship locks camera into a reverse view and thrust/orientation appear inverted', 'SpaceCamera.cs UpdateTravel', 369, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T371', 'Unity.SpaceGod', 371, '2026-10-21', 'feature', 'closed', 'Populate space with dozens of AI-patrolled light fighters, heavy fighters, freighters, and military ships; combat is commanded (take/defend objectives), not random free-for-all aggro', 'b3768b0 PatrolWingTests', 370, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T372', 'Unity.SpaceGod', 372, '2026-10-21', 'feature', 'closed', 'Cap a single jump-gate link''s span (~5 ly, tunable) instead of GateNetwork.Build''s unconstrained nearest-neighbour/MST join, so reaching a system farther than that from its nearest neighbours takes multiple hops (Route already plans these) through intermediate systems'' gates. Where no real star sits close enough along the way to carry a hop, seed a ''Void Base'': a new kind of system built in open interstellar space around an artificial gravity/sun generator, no planet or star of its own, placed purely to relay the span. A Void Base belongs to no system-holding polity and sits outside any navy''s law, making it the one truly lawless territory in the network -- pirates can base there in plain sight, with no settlement watching the gate.', 'GateNetwork.cs, VoidBaseBuilder.cs, Galaxy.cs', 371, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T373', 'Unity.SpaceGod', 373, '2026-10-21', 'fix', 'closed', 'deploy.ps1 dirty-check blocked on untracked files (e.g. .prose/), not just real tracked changes', 'eba1bc1', 372, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T374', 'Unity.SpaceGod', 374, '2026-10-21', 'feature', 'closed', 'Faction command layer: ships stop attacking on sight and instead follow objective orders a faction''s command issues (take/defend a gate, system or convoy); pirate bands run their own threat assessment first -- a juicy, lightly escorted target is worth more risk, a civilian hull draws disproportionate military heat so raiders leave it alone unless the contract pays well or a VIP aboard is worth ransoming; the doctrine is disable-and-loot (strip shields/engines, demand cargo ejection, send drones to collect, then withdraw), not destroy, since a wrecked hull is one less future target and destruction brings down more heat than a clean robbery. Part of U.SPC-T371.', 'd51b0ce RaidDoctrineTests', 373, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T375', 'Unity.SpaceGod', 375, '2026-10-21', 'feature', 'closed', 'Patrol population: dozens more light fighters, heavy fighters, freighters and military ships flying real patrol/escort/trade routes per the command layer (U.SPC-T371''s first story), plus ordinary civilian traffic -- buses and taxis on local runs, and personal 1-, 4- and 6-seat spacecraft -- so a system reads as lived-in, not just a combat arena. Part of U.SPC-T371.', '35d42f3 LocalTrafficTests', 374, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T376', 'Unity.SpaceGod', 376, '2026-10-21', 'feature', 'closed', 'Performance: a ship too far away to matter renders as a flat faction icon with its name, swapping in for the full 3D model (LOD), and is clickable to open a full info card with its stats; the swap point and the card''s layout/fields need their own pass. Part of U.SPC-T371.', 'ff01e6a ShipLodTests', 375, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T377', 'Unity.SpaceGod', 377, '2026-10-21', 'feature', 'closed', 'Ship-construction system with real hardpoints (missile launchers, turrets, torpedo tubes, etc.) across every buildable hull: fighters, capital ships, freighters, carriers, battleships, stations and satellites -- literally everything that can be built in space. Depends on whichever asset library the POC story settles on. Part of U.SPC-T371.', '4325a5f ConstructionTests', 376, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T378', 'Unity.SpaceGod', 378, '2026-10-21', 'chore', 'closed', 'Asset-library proof-of-concept submenu: before committing to a hardpoint/ship-construction library, build reachable in-game demos of the leading Asset Store candidates (Space Combat Kit for flight/weapons; Ingame Spaceship Builder or Modular Starship Constructor for hardpoint snap-together building; Space Satellite Kit and Modular Space Station for static structures) so the look and feel can be judged in-game, and check each against Unity 6 and both URP and HDRP before any purchase. Needs the user to actually buy the candidate packages themselves. Part of U.SPC-T371.', '9076047', 377, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T379', 'Unity.SpaceGod', 379, '2026-10-21', 'feature', 'closed', 'Make the existing in-system Hyperlanes (Core/Hyperlanes.cs, already modeled on X3''s highway network: on-ramps, up to 4% light speed, currently ridden only as a time-skipped AI/economy simulation) into a literal flyable X3-Rebirth-style highway for piloted flight: a chain of rings the ship flies through, magnetically accelerated, visibly connecting a system''s planets. Ship movement keeps its existing tiers (regular thrusters for dogfighting, a boost for mobility, PilotTuning''s cruise drive to reach a lane''s on-ramp at speed) and adds the ring-chain ride itself as the fastest in-system leg; a system''s lanes lead on to its Warp Gates (the existing JumpGate/GateNetwork) for the interstellar jump, arriving at the far system''s own hyperlane network. Needs a design/research pass on whether piloted ships can currently ride a lane at all (today''s lane-riding looks AI/background-sim only, via Ship.LaneHold and a skipped PhaseEndJd) before any Runtime visual work starts.', 'e979ab2 HighwayTests', 378, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T380', 'Unity.SpaceGod', 380, '2026-10-21', 'fix', 'closed', 'Missiles, torpedoes and boarding pods pick the shield arc from the targeted hardpoint''s position, not the side they came in from (hull-targeted ones always hit the bow arc); pass the entry point on the hull toward the missile as the shield-check position in Battle.StepMissiles/ApplyDamage/PodHit, per docs/SHIELD_ARCS_SPIKE.md (from U.SPC-T244)', 'b16bcb1', 379, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T381', 'Unity.SpaceGod', 381, '2026-10-21', 'fix', 'closed', 'Player missile/EMP shots, dogfighter tail-threat checks and point defence mishandled surrendered hulls and fighter priority (Battle.cs)', 'APlayersMissileAndEmpAreNotWastedOnAHullThatStruckItsColours', 380, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T382', 'Unity.SpaceGod', 382, '2026-10-21', 'fix', 'closed', 'Outlaws.PruneHunters dropped the row of a hunter gone through a gate on a hunt (InterstellarTraffic.Retire marks the departing hull Destroyed as well as GateDeparted), so coming home it was no longer a hunter and lost its takes', '6b9c5bd', 381, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T383', 'Unity.SpaceGod', 383, '2026-10-21', 'fix', 'closed', 'A campaign flagship at a gate crossed through a ring that was sabotaged or fought down: TryEnter checked GateNetwork.Passable (who admits it) but never the link''s Working state that Link.Open and Forcible check', '7c3fd7d', 382, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T384', 'Unity.SpaceGod', 384, '2026-10-21', 'fix', 'closed', 'InterstellarTraffic.Update emerged gate passages in reverse insertion order rather than by exit date, so two passages due in one step drew the shared random numbers in a different order than if handled on separate frames', '8b5293a', 383, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T385', 'Unity.SpaceGod', 385, '2026-10-21', 'fix', 'closed', 'BattleFx was built empty on every Activate, so Collect treated every battle as unseen and replayed the newest 160 effects of each live and ended battle (up to 30 ended battles, kept after the fight ends) as fresh fire at old sites; the constructor now primes its seen counts', '6e75861', 384, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T386', 'Unity.SpaceGod', 386, '2026-10-21', 'fix', 'closed', 'Loading a saved pilot session left pilotViewUp at the freshly seeded roof instead of the saved hull''s, so free-aim hulls rolled the camera briefly after a load', '0fd397f', 385, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T387', 'Unity.SpaceGod', 387, '2026-10-21', 'fix', 'closed', 'The save panel''s DrawSaves called SaveSlots.NewManual, a directory scan, on every OnGUI event while open; the next slot is now worked out with the 1-second slot-list refresh', '3b288f8', 386, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T388', 'Unity.SpaceGod', 388, '2026-10-21', 'fix', 'closed', 'Fleet.SurgeRide moved PhaseStartJd back to keep the ride''s progress, but LaneRejoin times a rejoining hull''s sideways offset from PhaseStartJd too, so surging in the first two hours after rejoining a lane popped the hull''s remaining side offset outward by tens of thousands of km; the offset is now rescaled to stay continuous', '7530102', 387, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T389', 'Unity.SpaceGod', 389, '2026-10-21', 'fix', 'closed', 'Law.PayFine: when the player pays a fine to their own faction (f == ship.Faction) the debit and credit cancel and no money moves; debit the fine from the treasury and do not credit it (burned as court costs), with a LawTests case (spike U.SPC-T245, docs/FINE_OWN_FACTION_SPIKE.md)', 'FineToOwnFactionIsDebitedAndBurned', 388, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T390', 'Unity.SpaceGod', 390, '2026-10-21', 'fix', 'closed', 'A ship planned for a direct transfer orbit whose conic then fails at departure (not cheaper, not clear, or no Hohmann time) takes the lanes instead of flying the straight flip-and-burn: Fleet.Depart re-routes by hyperlane when no conic was flown (spike U.SPC-T246, docs/DIRECT_TRANSFER_FALLBACK_SPIKE.md)', 'ADirectPlanWhoseConicFailsAtDepartureTakesTheLanesNotTheFlipAndBurn', 389, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T391', 'Unity.SpaceGod', 391, '2026-10-21', 'fix', 'closed', 'EventDirector.Pay mints adventure rewards from nothing even when a patron or owner is named: debit the reward from the patron (pirate patrons from their clan purse), capped at what its treasury holds, credit the player''s faction only what was actually paid, and show the paid amount in the outcome text; patronless rewards (anomaly surveys, fixed contracts) stay new money. Matches the escape-pod rescue path in Crews.cs (~line 288), which already pays capped from the owners'' treasury. Add a test for the broke-patron cap. Decision in docs/ADVENTURE_REWARDS_SPIKE.md (U.SPC-T283)', '9a11c51', 390, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T392', 'Unity.SpaceGod', 392, '2026-10-21', 'feature', 'open', 'Combined allied boarding (future): let marines from several allied factions on the same side board one hull together and fight its defenders as one action, so it clears roughly as fast as their combined strength allows, instead of the current one-boarding-faction-per-hull rule (where a second allied pod is now turned back, per U.SPC-T247). The captured hull is not simply awarded to one faction: owner wants shared salvage rights, or a negotiation between the allied factions afterwards, to settle who keeps the hull and its cargo. Design that settlement before building it.', 'U.SPC-T247', 391, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T393', 'Unity.SpaceGod', 393, '2026-10-21', 'fix', 'closed', 'GateConstruction.BestProject offered any system within reach as a gate target, Void Bases included, and BasesOf counted a relay as a base to build outward from, so a state could plan a gate into a Void Base: finishing it logged ''the system is open to settlement'' (Opened++, SystemOpened raised) for a relay nothing can settle and handed the lawless relay''s gate to the builder, against T372''s rule that a Void Base belongs to no system-holding polity; relays are now skipped as targets and as bases', 'ef5cbf3', 392, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T394', 'Unity.SpaceGod', 394, '2026-10-21', 'fix', 'closed', 'War.Interdict skipped the stun and shield-zeroing for the units of a braced (forewarned) group by u.Ship, but a launched fighter has no Ship, so a carrier that made out the raider and rode the interdiction pulse out still had every fighter it launched into the fight stunned for 60-120 s with its shields zeroed; a fighter now takes its carrier''s brace', 'bc456a4', 393, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T395', 'Unity.SpaceGod', 395, '2026-10-21', 'fix', 'closed', 'ProfileStore.IsValidName let through a name ending in a dot (Windows drops the dot, so ''Ryan.'' and ''Ryan'' were one folder while Exists saw two profiles and both could be made, sharing saves) and the reserved device names (CON, NUL, COM1...), which Windows refuses as a folder; both are now invalid names', 'ee64214', 394, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T396', 'Unity.SpaceGod', 396, '2026-10-21', 'feature', 'open', 'Empire decline and isolation (owner idea, Rome/Ozymandias): polities can die as well as grow. Shocks such as war, famine from broken shipping lanes (People.cs already has FaminePerDay but nothing collapses), disease/epidemics, and other disasters can decimate a system and cut it off from the gate network; the simulation keeps running for the cut-off system, which must rebuild its warp gates and fleets to rejoin. Isolation erodes loyalty: a colony or group left distant or cut off long enough drifts and can come back as a different faction entirely (secession / new polity with its own name, colours and relations). Needs design first: the shocks and their triggers, how a system is severed and reconnects, a loyalty/drift measure driven by distance and time out of contact, and when drift tips into a new faction.', 'owner 2026-10-21', 395, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T397', 'Unity.SpaceGod', 397, '2026-10-21', 'chore', 'closed', 'Research spike: how real civilizations rise and fall, mapped onto the SpaceGod simulation. Study historical cases (Rome, Bronze Age collapse, Ozymandias/New Kingdom Egypt, the Mongols and their successor khanates, Byzantium, the Spanish/British empires, the Soviet breakup, the Great Schism and Reformation, the Black Death) for the drivers of rise and decline: conquest and overextension, logistical/supply failure (broken trade and shipping lanes, famine), rebellion and secession of distant provinces, religious and ideological schisms, plague, fiscal collapse/debasement, succession crises, and climate/resource shocks; plus rebound and recovery. For each driver: the mechanism, its triggers and feedback loops, its rough timescales, and how it maps onto existing Core systems (People.cs FaminePerDay, Polities, War, Contracts/trade, GateNetwork/GateConstruction, Law, Outlaws). Deliver docs/CIVILIZATION_DYNAMICS_SPIKE.md with the proposed model (state variables such as loyalty, legitimacy, cohesion, belief and supply, and the transitions), what to build first, and implementation tickets filed for each mechanic. Feeds U.SPC-T396.', 'docs/CIVILIZATION_DYNAMICS_SPIKE.md, commit 9de1ab1', 396, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T398', 'Unity.SpaceGod', 398, '2026-10-21', 'feature', 'open', 'Civ dynamics: logistics collapse. When shipping lanes or gates break down (war, piracy, sabotage, lost hulls), a system that depends on imported food/goods runs short; shortages cascade into famine (extend People.cs FaminePerDay), unrest and population loss, and the shortfall spreads to systems that relied on it as a hub. Model per-system import dependence and supply stockpiles. Design from U.SPC-T397.', 'U.SPC-T396', 397, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T399', 'Unity.SpaceGod', 399, '2026-10-21', 'feature', 'open', 'Civ dynamics: disease and epidemics. Outbreaks start in a system and spread along trade and passenger traffic (gates, lanes, freighters, buses); they kill or weaken population, crews and productivity, and trigger quarantines (closed ports, embargoed gates) that themselves break supply. Recovery and immunity over time. Design from U.SPC-T397.', 'U.SPC-T396', 398, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T400', 'Unity.SpaceGod', 400, '2026-10-21', 'feature', 'open', 'Civ dynamics: severed systems. A system can be cut off from the gate network (gates destroyed, abandoned or unmaintained, relays lost); the simulation keeps running for it in isolation, and it must rebuild its warp gates and fleets (GateConstruction) to reconnect. Track time out of contact. Design from U.SPC-T397.', 'U.SPC-T396', 399, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T401', 'Unity.SpaceGod', 401, '2026-10-21', 'feature', 'open', 'Civ dynamics: loyalty and cohesion drift. Each system/colony gets a loyalty to its polity that erodes with distance from the capital, time out of contact, neglect, heavy taxation, and misrule, and recovers with contact, investment and protection. It feeds rebellion, secession and schism. Design from U.SPC-T397.', 'U.SPC-T396', 400, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T402', 'Unity.SpaceGod', 402, '2026-10-21', 'feature', 'open', 'Civ dynamics: rebellion and secession. Low-loyalty systems rise in revolt (local garrisons and fleets defect or fight), and a colony left alone long enough can come back as a different faction entirely: a new polity with its own name, colours, government and relations, possibly hostile to its old masters. Design from U.SPC-T397.', 'U.SPC-T396', 401, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T403', 'Unity.SpaceGod', 403, '2026-10-21', 'feature', 'open', 'Civ dynamics: religious and ideological schisms. Give populations a belief/ideology that can drift and split; schisms divide a polity (or cross polity lines), change alliances and loyalties, spark persecution, migration and holy war, and can found new factions. Design from U.SPC-T397.', 'U.SPC-T396', 402, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T404', 'Unity.SpaceGod', 404, '2026-10-21', 'feature', 'open', 'Civ dynamics: conquest and overextension. Conquest grows a polity but each held system adds administrative and garrison cost and stretches supply lines; past its reach, cohesion falls, revolts rise and defence thins, so empires can outgrow what they can hold. Design from U.SPC-T397.', 'U.SPC-T396', 403, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T405', 'Unity.SpaceGod', 405, '2026-10-21', 'feature', 'open', 'Civ dynamics: fiscal crisis. A polity whose treasury fails (war costs, lost trade, debasement) cannot pay crews and garrisons: fleets desert, mutiny or turn pirate, services and gate maintenance lapse, and loyalty falls. Design from U.SPC-T397.', 'U.SPC-T396', 404, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T406', 'Unity.SpaceGod', 406, '2026-10-21', 'feature', 'open', 'Civ dynamics: succession and leadership crises. A polity leadership can fall (death, coup, disputed succession), splitting it into rival claimants and civil war that pulls fleets and systems to each side, until one wins or the polity splits for good. Design from U.SPC-T397.', 'U.SPC-T396', 405, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T407', 'Unity.SpaceGod', 407, '2026-10-21', 'feature', 'open', 'Civ dynamics: resource and stellar shocks. Resource depletion (mined-out belts, exhausted worlds) and natural disasters (stellar flares, impacts, habitat failures) can cripple a system economy and population and set off the other decline mechanics. Design from U.SPC-T397.', 'U.SPC-T396', 406, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T408', 'Unity.SpaceGod', 408, '2026-10-21', 'feature', 'open', 'Civ dynamics: death, dark ages and recovery. A polity can die outright (all systems lost, absorbed or seceded) and leave ruins and derelicts; isolated or collapsed systems can sink into a dark age (lost tech/industry) and later recover, reconnect, and either rejoin, be reconquered, or rise as successor states. Design from U.SPC-T397.', 'U.SPC-T396', 407, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T409', 'Unity.SpaceGod', 409, '2026-10-21', 'feature', 'open', 'Civ dynamics: making rise and fall visible. Surface these events to the player: galaxy map overlays for loyalty, supply, plague and severed systems, news/hails when systems revolt, starve or secede, and a history log of polities rising, splitting and dying. Design from U.SPC-T397.', 'U.SPC-T396', 408, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T410', 'Unity.SpaceGod', 410, '2026-10-21', 'feature', 'open', 'Multiplayer-ready groundwork (owner 2026-10-21: all Unity games must be able to add co-op or PvP later without re-architecting; no networking is planned yet): audit the game against Unity.Multiplayer docs/articles/multiplayer-ready.md and refactor the seams it names: player intent as serializable commands carrying a player/seat id through one pipeline; state owned by one authority, presentation reading state/events only; no global current-player singletons; deterministic seeded rules on a fixed tick; stable entity ids; serializable state/commands; an ISession/authority seam with a LocalSession. No netcode package is added. Add a BIBLE law citing the standard, a test that drives the game with commands from two player ids, and keep every existing test and the shipped game behaviour unchanged', '—', 409, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T411', 'Unity.SpaceGod', 411, '2026-10-21', 'docs', 'closed', 'Write the owner core design principles into the repo where every agent reads them (a Design principles section in README.md, pointed to from AGENTS.md), and hold all new work to them: (1) Expandability and extensibility first: new mechanics (civ dynamics, ship types, factions, systems) plug in through clear extension points and data, not edits scattered through core loops. (2) The universe is fully flyable: given long enough, a pilot can fly from one end of the galaxy to the other in continuous space; gates and lanes are shortcuts, never the only way, because a space game where flying never gets you anywhere is not a space game. (3) Render only what is needed: at universe scale, never render full detail for things too far or small to see; LOD, impostors/icons, culling and aggregation by apparent size. (4) No loading screens: stream content in the background; the only allowed cover is visual trickery at jump gates that buys time for model loading.', 'bb3d23e', 410, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T412', 'Unity.SpaceGod', 412, '2026-10-21', 'feature', 'closed', 'Continuous interstellar flight: a ship can leave any system and fly through real interstellar space to any star, arriving by flying in, not by a timed gate hop or a camera glide (today the gate crossing is 6h + 2h/ly and the trip between stars is a camera animation). Needs a long-range cruise/FTL drive class so the trip is long but finishable, open space between systems that keeps simulating (traffic, encounters, derelicts), and hierarchical coordinates (galactic sector + system-local doubles) because a single double floating origin loses precision at galactic distances. Gates and lanes stay as fast shortcuts.', '5662c1a', 411, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T413', 'Unity.SpaceGod', 413, '2026-10-21', 'feature', 'closed', 'Galaxy at full scale and expandable: beyond the hand-built nearest real stars, generate the rest of the galaxy deterministically from a seed (real catalogue stars near Sol, procedural systems beyond), created on demand as a pilot approaches rather than all up front, through the same system-definition extension point the hand-built systems use so new systems, regions and content can be added without core changes.', '5da6d7d', 412, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T414', 'Unity.SpaceGod', 414, '2026-10-21', 'feature', 'closed', 'Seamless streaming with no loading screens: systems, ships, stations, planets, textures and models load and unload asynchronously by distance and heading, never blocking a frame; a jump gate transit plays a visual transition (tunnel, flare, fold) whose length covers any remaining model loading on the far side; arriving by plain flight must never need a load pause.', '1fea827', 413, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T415', 'Unity.SpaceGod', 415, '2026-10-21', 'feature', 'closed', 'Render budget at universe scale: generalise far-object rendering beyond ships (U.SPC-T376) to every object class with LOD tiers by apparent size: full model, simplified model, impostor/faction icon, then aggregated markers (a fleet or a whole system as one mark), with culling of anything below a pixel, so thousands of ships across many systems render at frame rate.', '48762b6 (RenderLodTests)', 414, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T416', 'Unity.SpaceGod', 416, '2026-10-21', 'docs', 'closed', 'SpaceGod vision document (docs/VISION.md, linked from README and the design principles): a fully alive, galaxy-spanning space simulation that is at once a strategy game, a dogfighting game, a capital-ship broadside game, a trading game and a diplomacy game. The name: you can change outcomes by taking charge yourself (fly the heroic fighter run that brings down a dreadnought) or let the whole thing play out on its own. No end date: this is a universe, not a product. Adds a fifth design principle beside U.SPC-T411: as much as possible is reachable and adjustable in game, in the settings menu.', '54979ff', 415, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T417', 'Unity.SpaceGod', 417, '2026-10-21', 'feature', 'closed', 'Own-power FTL drive, I-War 2 style: capital ships and specialised deep-space exploration ships can enter FTL under their own power: point the ship at a star, planet or beacon, spool up, engage, and eventually arrive. Most traffic still uses jump gates; small craft cannot do this alone. Part of continuous interstellar flight (U.SPC-T412).', 'd01743e', 416, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T418', 'Unity.SpaceGod', 418, '2026-10-21', 'feature', 'closed', 'FTL physics and rules: an FTL drive cannot engage, and drops out, inside a gravity-well threshold around stars and planets (so arrivals end at the edge of a system and finish under normal drive); it has a spool-up and cooldown, a power/fuel cost, carries momentum, can be interdicted by gravity projectors or mass, and has a top speed that makes crossing the galaxy long but finishable. All limits are data-tunable and exposed in settings.', '22bda6e', 417, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T419', 'Unity.SpaceGod', 419, '2026-10-21', 'feature', 'closed', 'Which hulls carry FTL: give capital classes (carrier, battleship, cruiser, destroyer) and a new deep-space explorer/survey class an FTL drive, and let carriers and capitals take docked fighters and small craft with them through FTL, so a fleet can strike or explore off the gate network.', '2105ab7', 418, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T420', 'Unity.SpaceGod', 420, '2026-10-21', 'feature', 'closed', 'Interstellar navigation UI: point-and-engage targeting of any star or beacon from the cockpit or galaxy map, plotted course with ETA and fuel, an FTL autopilot, and time compression during a long cruise tied to the sim clock, so a long trip is playable without sitting through it in real time.', 'FtlNavigationTests, 2fec3d6', 419, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T421', 'Unity.SpaceGod', 421, '2026-10-21', 'feature', 'closed', 'Life in deep space: the space between systems is not empty. Rogue planets, nebulae, ice bodies, derelicts and wrecks, deep-space relays and listening posts, ambushes and interdiction by pirates or navies on FTL routes, distress signals and survey finds that reward exploration off the gate network.', '1bd9bb6', 420, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T422', 'Unity.SpaceGod', 422, '2026-10-21', 'feature', 'closed', 'Take charge of anything, any time: from the strategy view, jump straight into the helm of any ship, turret or fighter mid-battle (fly the X-wing run on the dreadnought), then hand it back to its AI and return to command, with the simulation never pausing or loading. Let-it-play-out stays a first-class way to play: the galaxy runs fully on its own when the player commands nothing. Builds on universal embodiment (U.SPC-T18).', '2117fb1 TakeChargeTests', 421, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T423', 'Unity.SpaceGod', 423, '2026-10-21', 'feature', 'closed', 'Strategy game layer: command a polity from the galaxy map: set production, research or build priorities, assign fleets objectives (take, hold, blockade, escort, explore) through the faction command layer (U.SPC-T374), and see the war, economy and civ dynamics (U.SPC-T396) unfold, at any level from one squadron to a whole empire.', 'e2d67bc StrategicCommandTests', 422, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T424', 'Unity.SpaceGod', 424, '2026-10-21', 'feature', 'closed', 'Dogfighting game: fighters and heavy fighters as a full dogfight game: flight model per class (U.SPC-T17), weapon groups, lock-on and missiles, countermeasures, energy management, wingmen orders, and attack runs on capital-ship weak points (exposed reactors, shield generators, engines) so a lone fighter can change a battle.', 'DogfightGameTests; e3052f7', 423, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T425', 'Unity.SpaceGod', 425, '2026-10-21', 'feature', 'closed', 'Capital-ship broadside game: commanding a capital ship as a naval battle, Black Flag / Rebel Galaxy style: positioning for broadsides, per-battery and per-arc firing, angling shields and armour, crew and damage control, turning circles and momentum, and fleet formation orders. Shares the flight-model work in U.SPC-T17.', 'BroadsideTests; 2887fbb', 424, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T426', 'Unity.SpaceGod', 426, '2026-10-21', 'feature', 'closed', 'Trading game: a full trader career for the player on the live economy: buy and sell across markets, contracts and charters, own and grow a fleet of freighters on routes, warehouses, price and news intelligence, smuggling and the black market, and risk from pirates, blockades and collapse.', 'a9ce044 TradeDeskTests', 425, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T427', 'Unity.SpaceGod', 427, '2026-10-21', 'feature', 'closed', 'Diplomacy game: polities (including the player own faction) hold relations, treaties, alliances, trade pacts, non-aggression and war declarations, tribute and vassalage; the player can negotiate in hails and an envoy screen, and the AI uses the same diplomacy, tying into the command layer and civ dynamics.', '80e5f70 StatecraftTests', 426, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T428', 'Unity.SpaceGod', 428, '2026-10-21', 'chore', 'closed', 'Research spike: URP and HDRP support. Compare URP 17 (current) with HDRP for this project per Unity feature comparison (https://docs.unity3d.com/6000.1/Documentation/Manual/render-pipelines-feature-comparison.html): what photoreal features HDRP adds (physically based sky and atmosphere, volumetrics, ray tracing, area lights, exposure), what our custom URP shaders (planet surfaces, atmosphere rims, sun, rings, plumes, starfield) and floating-origin camera need to work on both, whether one build can ship both pipelines and switch on restart, and the cost. Deliver docs/RENDER_PIPELINES_SPIKE.md and file the implementation tickets.', '4aab1a0', 427, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T429', 'Unity.SpaceGod', 429, '2026-10-21', 'feature', 'closed', 'Render-pipeline abstraction groundwork: put every pipeline-specific piece (shaders, materials, lights, post-processing volumes, camera setup, render features) behind a pipeline-agnostic layer so game code never assumes URP, with the current URP path as the first implementation. Follows the URP/HDRP spike.', 'c1d1273', 428, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T430', 'Unity.SpaceGod', 430, '2026-10-21', 'feature', 'closed', 'HDRP photoreal path: an HDRP pipeline asset and HDRP versions of the custom shaders (Shader Graph or dual-pipeline), physically based sky/atmosphere and volumetrics for planets, exposure for the sun, and optional ray tracing, selectable in the settings menu (applied on restart if a live switch is not possible) with URP kept as the default and lower-end option.', 'a8aefe0 (RenderPipelineTests, PhotorealTests)', 429, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T431', 'Unity.SpaceGod', 431, '2026-10-21', 'feature', 'closed', 'Settings registry: a data-driven way for any system to declare tunables (graphics, render pipeline, LOD and render budget, streaming, simulation speed and scale, FTL limits, civ dynamics rates, AI difficulty, economy, controls, audio) that then appear automatically in the in-game settings menu (extending PauseMenu/DisplayOptions), grouped and searchable, with defaults, ranges and reset, saved per profile. New mechanics add settings by declaring them, never by editing the menu.', 'edff50c', 430, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T432', 'Unity.SpaceGod', 432, '2026-10-22', 'fix', 'closed', 'EventDirector.Pay debited a survivors'' owner for the whole derelict reward, so rescuing survivors capped the patronless salvage-registry award at the owner''s treasury (T391 regression); only the survivors'' thanks are now the owner''s to pay', 'OnlyTheSurvivorsThanksComeOutOfTheirOwnersTreasuryNotTheRegistrysAward', 431, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T433', 'Unity.SpaceGod', 433, '2026-10-22', 'fix', 'closed', 'The HUD''s selection panel read a Void Base''s tiny suns as 0.000 AU from their generator (they orbit at a few hundred km) and called them White dwarf, and the generator itself a star; distances in a star''s frame now fall to km when small, and the generator and tiny suns get their own kind names', 'Hud.StellarDistance / KindName (Unity UI, no unit test)', 432, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T434', 'Unity.SpaceGod', 434, '2026-10-22', 'fix', 'closed', 'Outlaws.SettleFates ended a raider captain as Vanished the day the band''s flagship went through a gate, because InterstellarTraffic.Retire marks the departing hull Destroyed as well as GateDeparted; the captain dropped off the bounty board, their open contract lapsed, and the band came home under a brand-new record with no bounty (the hunter row got the same fix in U.SPC-T382)', 'OutlawTests.ARaiderCaptainWhoseBandWentThroughAGateIsAwayNotVanished', 433, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T435', 'Unity.SpaceGod', 435, '2026-10-22', 'fix', 'closed', 'Hud.DrawSelection read a ship bound for a jump gate or a raider stakeout as burning toward the root''s ''hyperlane ramp'', because both fly to a fixed point and the status line took every fixed point for a ramp', 'Hud.DrawSelection status text (Unity UI, no unit test)', 434, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T436', 'Unity.SpaceGod', 436, '2026-10-22', 'fix', 'closed', 'Three InterstellarPiracyTests fail on main (RaidersLyingOffAGateFallOnTheTrafficBunchedThereAndNobodyElse, OnlyOneBandIsSentToAHavenLeftEmptyAtATime, ExpandWontFoundWithoutTheCostInTreasuryEvenWithABandAndRouteReady); seen by the U.SPC-T49 pass and independent of its Outlaws fix. Suspected cause: a recent landing shifted the seeded simulation, e.g. U.SPC-T384 (gate passages now processed in exit-date order, changing random draw order), U.SPC-T371 patrol wings, or U.SPC-T390 lane fallback. Find which change broke them and fix the code if it is a real regression, or re-seed/adjust the tests if only the random course changed.', 'c719189', 435, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T437', 'Unity.SpaceGod', 437, '2026-10-22', 'feature', 'open', 'Civ dynamics framework (first to build): a per-polity/per-system state registry plus a pluggable ICivDynamic step run from one hook in World.Update, every rate declared as a setting (T431) and the state saved; each mechanic T398-T408 plugs in as a registered dynamic, never as an edit to Fleet/War/Economy loops. Design in docs/CIVILIZATION_DYNAMICS_SPIKE.md (U.SPC-T397)', 'U.SPC-T396', 436, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T438', 'Unity.SpaceGod', 438, '2026-10-22', 'feature', 'open', 'Civ dynamics: runtime polity founding and splitting API (Polities.Split: name, prefix, colours, capital, treasury, ships and settlements transferred, diplomacy seeded) shared by secession, schism, succession and dark-age successor states. Design in docs/CIVILIZATION_DYNAMICS_SPIKE.md (U.SPC-T397)', 'U.SPC-T396', 437, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T439', 'Unity.SpaceGod', 439, '2026-10-22', 'chore', 'open', 'Civ dynamics: headless long-run balance harness (fast-forward N sim-years across seeds, report polity count, collapses, secessions, recoveries) so rates can be tuned and runaway collapse or stagnation caught by tests. Design in docs/CIVILIZATION_DYNAMICS_SPIKE.md (U.SPC-T397)', 'U.SPC-T396', 438, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T440', 'Unity.SpaceGod', 440, '2026-10-22', 'feature', 'open', 'Light fighter flight model review and tuning pass with the owner (docs/FLIGHT_MODELS.md, Light fighters): fly LightFighterFlightModel (Fighter, Courier) and tune LightFighterHandling (grip, strafe fraction, corner speed, overspeed turn factor); decide whether the turn penalty follows boost held (Star Conflict afterburner) or speed alone; have AI dogfighters (Battle dogfight, U.SPC-T274) fly through the same IFlightModel; expose LightFighterHandling to the settings registry (U.SPC-T431)', '—', 439, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T441', 'Unity.SpaceGod', 441, '2026-10-22', 'feature', 'open', 'Heavy fighter flight model, Everspace 2 style (docs/FLIGHT_MODELS.md, Heavy fighters): a HeavyFighterFlightModel + HeavyFighterHandling registered for FlightFamily.HeavyFighter (the Breacher) with stiff speed-independent turning capped below a light fighter''s and crisp spin-up, a short eased settle on the throttle, strafe and vertical at about 0.45 of forward, and boost speed bled off over a couple of seconds on release; decide whether the heavy fighter should be a dedicated gunship hull rather than the drill-prowed Breacher (a new class just joins the family); Core tests; tunables ready for U.SPC-T431', '—', 440, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T442', 'Unity.SpaceGod', 442, '2026-10-22', 'feature', 'wont-do', 'Capital ship flight model, Black Flag broadside handling on a Rebel Galaxy battle plane (docs/FLIGHT_MODELS.md, Capital ships): a CapitalFlightModel + CapitalHandling (per-class overrides) for FlightFamily.Capital with a stepped engine telegraph that holds (Full Astern..Flank, Flank = boost), speed-dependent steerage peaking at Half with a slow pivot at Stop, keel damping so turns trace a turning circle, pitch held near the battle plane with Q/E as slow depth change, per-class come-about targets (180 deg at Half: Destroyer ~6 s, Cruiser ~10 s, Battleship ~14 s, Carrier ~18 s) checked by tests, and the Destroyer as the tighter, faster skirmisher; handling only -- batteries, arcs and bracing stay with U.SPC-T425', 'Owner 2026-10-23: capitals fight in full 3D too, not near a battle plane; refiled without the battle plane', 441, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T443', 'Unity.SpaceGod', 443, '2026-10-22', 'feature', 'open', 'Hauler flight model for freighters and miners (docs/FLIGHT_MODELS.md, Haulers): a HaulerFlightModel + HaulerHandling for FlightFamily.Hauler where laden mass (grid-hold cargo and propellant) slows acceleration, braking and turning, the HUD shows the full-retro stop point, holding Ctrl near a port''s approach is a docking mode (low set point, gentle turn), strafe is weak and boost a short emergency burn; Core tests; tunables ready for U.SPC-T431', '—', 442, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T444', 'Unity.SpaceGod', 444, '2026-10-22', 'feature', 'open', 'Courier flight family decision (docs/FLIGHT_MODELS.md, Couriers): either a Runner FlightFamily of its own (highest top speed, longest boost, wide turning circle with low grip and an early corner speed, fastest cruise spool) as a blockade runner, or confirm it stays a light fighter (close won''t-do); Core tests if a Runner model is added', '—', 443, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T445', 'Unity.SpaceGod', 445, '2026-10-22', 'feature', 'open', 'Turret seat in the game: from the flown or selected hull (or a station''s defence platform) pick one gun mount via Embodiables.TurretsOn, a turret camera at the mount looking down the barrel, mouse lays it and left-click fires through EmbodimentSession/MountedTurret, a key moves up to the hull''s helm (MoveToHost) and P hands it back -- Core support landed with U.SPC-T18, the Runtime seat did not', '—', 444, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T446', 'Unity.SpaceGod', 446, '2026-10-22', 'feature', 'open', 'Embodiment picker and switch UI: list every embodiable near the camera or on the selected thing (ship helms, turret mounts, later stations and satellites) from Embodiables, never a list of its own, and jump between seats through EmbodimentSession.Switch so the old seat is always handed back to its AI; the seamless no-pause switching from the strategy view stays U.SPC-T422''s to build on top', '—', 445, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T447', 'Unity.SpaceGod', 447, '2026-10-22', 'feature', 'open', 'Stations as embodiables: a Station IEmbodiable for settlements'' stations and defence platforms (and gate forts) with its own pose outside battles, registered in Embodiables, that can turn its guns and launch its craft, and set as the Host of its MountedTurrets so a turret seat can move up to the station', '—', 446, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T448', 'Unity.SpaceGod', 448, '2026-10-22', 'feature', 'open', 'Satellites as embodiables: give the SatelliteSwarm''s satellites an independent position/control model in Core (orbit plus attitude, station-keeping thrust) and a Satellite IEmbodiable that can be turned and pointed (sensors, relays), its AI holding station when handed back', '—', 447, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T449', 'Unity.SpaceGod', 449, '2026-10-22', 'feature', 'open', 'Every ship role at the helm through ShipHelm: freighters, miners, couriers, escorts and fighters each with a control set fitted to their role, and the hull''s flight moved behind ShipHelm.Control (out of UnitySpaceApp.UpdatePiloting) once U.SPC-T17''s per-class flight models have landed', '—', 448, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T450', 'Unity.SpaceGod', 450, '2026-10-22', 'docs', 'closed', 'Update README.md, USER_STORIES.md', '—', 449, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T451', 'Unity.SpaceGod', 451, '2026-10-22', 'feature', 'open', 'Wire up URP''s Volume stack (exposure -- fixed, automatic and histogram once a Volume profile exists --, physical camera, bloom, colour grading) as a cheaper photoreal upgrade than an HDRP migration; the project uses no Volume component or post-processing today on either pipeline (allowHDR is false, no Volume anywhere). Follows the URP/HDRP spike (U.SPC-T428).', '—', 450, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T452', 'Unity.SpaceGod', 452, '2026-10-22', 'chore', 'open', 'Narrow HDRP Physically Based Sky experiment, scoped to docking-ring atmospheric entry only (the one sequence where a player sits inside a single atmosphere): not a renderer migration, gated behind the pipeline-abstraction layer (U.SPC-T429). Low priority; revisit once docking-ring descent gets a dedicated visual pass. Follows the URP/HDRP spike (U.SPC-T428).', '—', 451, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T453', 'Unity.SpaceGod', 453, '2026-10-22', 'fix', 'closed', 'A ship going through a jump gate (the helm''s GateTransit, the AI traffic''s gate passages in InterstellarTraffic) or out under its own cruise drive (InterstellarTraffic.EngageCruise) is retired at one end and a copy made by Ship.CloneForGateArrival appears at the other; the owner rules this unacceptable: the same Ship object must be carried through and emerge, as the helm''s own FTL jump now does (Fleet.LetGo leaves a gone marker in its old fleet slot so no other id moves, and Fleet.Receive takes the same hull in at the far end). Move every crossing onto that and retire CloneForGateArrival.', 'e8b782b', 452, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T454', 'Unity.SpaceGod', 454, '2026-10-22', 'feature', 'closed', 'Chart the real nearest star systems out to 100 ly, by the owner''s 7 ly divisions (0-7: Alpha Centauri, Barnard''s Star, Luhman 16; 7-14: WISE 0855-0714, Wolf 359, Lalande 21185, Sirius, Luyten 726-8, Ross 154, Ross 248, Epsilon Eridani, Lacaille 9352, Ross 128, EZ Aquarii, Procyon, 61 Cygni, Struve 2398, Groombridge 34, DX Cancri, Epsilon Indi, Tau Ceti, GJ 1061, Luyten''s Star, Teegarden''s Star, Kapteyn''s Star, Lacaille 8760, Kruger 60, Ross 614, Gliese 628, Gliese 35; then 14-21, 21-28 and on to 100 ly with the named systems the owner listed: Gliese 1/412/687/674/876/832, AD Leonis, Sigma Draconis, Gliese 570, Eta Cassiopeiae, 36 Ophiuchi, 82 Eridani, Delta Pavonis, Gliese 581, Vega, Fomalhaut, Beta Hydri, 107 Piscium, Chara, 61 Virginis, Zeta Tucanae, Kappa1 Ceti, Wolf 1069, AU Microscopii, Pollux, Arcturus, Zeta Reticuli, TRAPPIST-1, Capella, Upsilon Andromedae, Mu Herculis, Beta Pictoris, Aldebaran, Regulus, Castor, Algol, Mizar and the rest), as catalogue stars in the system sources, with distances and positions taken from RECONS/Gaia rather than the pasted list (it has duplicates at two distances, e.g. Gliese 176 and Gliese 436, and entries filed in the wrong division, e.g. Gliese 581, Castor, HR 8799, Polaris at 323 ly); and wherever a stretch of 7 ly would otherwise have no destination, place a void station, so no leg between charted destinations is longer than 7 ly', 'NearestStarsTests; e568e52', 453, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T455', 'Unity.SpaceGod', 455, '2026-10-22', 'fix', 'closed', 'The helm''s FTL drive (U.SPC-T417) can jump within a system to a planet or beacon; canon rule and lore: no jump is possible inside a solar system''s gravity wells, so a hull must fly beyond the system''s outer rim before its drive will spool (as ships reach the jump gates at the edge), and the drive only ever jumps to another star, never to somewhere in the same system', 'f835f7b', 454, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T456', 'Unity.SpaceGod', 456, '2026-10-22', 'feature', 'closed', 'Set up every star system in docs/nearest_stars_2027.csv (the 123 real systems out to 100 ly, at their 2027 Sol-centric positions, spec in docs/NEAREST_STARS.md) in the galaxy, with the simulation''s starting state splitting them by distance from Sol: every system within 21 ly starts discovered (charted and known as today), and every system more than 21 ly away starts Undiscovered, a new state of its own that the charts, galaxy map, navigation and FTL targeting all honour until something discovers it', '5309f21 (StarDiscoveryTests)', 455, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T457', 'Unity.SpaceGod', 457, '2026-10-23', 'fix', 'closed', 'A group under FTL can fly straight through a gravity projector''s field or a star''s well without being pulled out: FtlInterdiction checks each 0.05-day step''s stretch with FtlRules.FirstEntry, which skips any field either end of the stretch is inside, so a field the step happens to end inside (likely for any field wider than the spacing a fast drive covers in a step''s rounding, e.g. a 2e9 km projector a whole number of steps out) is never entered; FirstEntry should skip only a field the stretch starts inside (the leg''s own start and target are already filtered by the caller)', 'FirstEntry_FindsAFieldTheStretchEndsInside', 456, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T458', 'Unity.SpaceGod', 458, '2026-10-23', 'fix', 'closed', 'PolitiesTests.ANavyIsOneFleetWhoseShipsAreCountedOnceAcrossSystemsAndGates fails on main: two navy supply-convoy flagships (SFS Provender Two and SFS Provender Three) appear twice in the navy''s list, so a navy''s hulls are not counted once across systems and gates', 'PolitiesTests.ANavyIsOneFleetWhoseShipsAreCountedOnceAcrossSystemsAndGates', 457, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T459', 'Unity.SpaceGod', 459, '2026-10-23', 'fix', 'closed', 'MilitarySupplyTests.AFleetOutOfSupplyFiresSlowerInBattle fails on main (reported by U.SPC-T424 and U.SPC-T425, failing the same way with their changes removed): a fleet out of supply no longer fires slower in battle as the test expects', 'MilitarySupplyTests.AFleetOutOfSupplyFiresSlowerInBattle', 458, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T460', 'Unity.SpaceGod', 460, '2026-10-23', 'fix', 'closed', 'CombatTests.WrecksAppearWhereShipsDieAndClearAwayAfterTheirLifetime fails on main (reported by U.SPC-T425, failing the same way with its change removed): wrecks do not appear where ships die or clear away after their lifetime as the test expects', 'CombatTests.WrecksAppearWhereShipsDieAndClearAwayAfterTheirLifetime', 459, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T461', 'Unity.SpaceGod', 461, '2026-10-23', 'chore', 'closed', 'Ignore the local .prose/agent-session.json handoff files (quicksave state, never shared) and remove an empty stray UnitySpaceApp.cs at the repo root', '8473056', 460, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T462', 'Unity.SpaceGod', 462, '2026-10-23', 'fix', 'closed', 'Loading a save loses every polity''s diplomacy (relations, opinions, pacts and pending proposals from Statecraft, U.SPC-T427) and the command layer''s standing orders, because the save file holds neither; save and restore both so a loaded game keeps its treaties, wars-by-declaration and orders', '60efb56', 461, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T463', 'Unity.SpaceGod', 463, '2026-10-23', 'fix', 'closed', 'TheDogfightingSettingsAreInTheMenu fails when run on its own: it calls SettingsRegistry.Find("dogfight.countermeasures") before anything has touched the Countermeasures class, so its static setting is not registered yet and Find returns null; the test (or registry lookup) should force the class''s declarations first', 'TheDogfightingSettingsAreInTheMenu', 462, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T464', 'Unity.SpaceGod', 464, '2026-10-23', 'fix', 'closed', 'F12 is bound twice: U.SPC-T426''s trade desk and U.SPC-T427''s hail/envoy both landed on it (InputState, UnitySpaceApp, help card, patrol-hail banner ''F12 parley'', fleet panel ''on charter (F12)''), so one press does both or one shadows the other; move one of them to a free key and update every label and help line', 'c31ed45', 463, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T465', 'Unity.SpaceGod', 465, '2026-10-23', 'feature', 'closed', 'Marine Habitat module (owner 2026-10-23): marines live and train in a Marine Habitat fitted into a hull''s internal bay, and a ship''s marine complement and training come from its habitats instead of the flat Marines figure per class in CombatSpecs; only hulls big enough for one can carry marines (smaller ones repel boarders with their crew alone), the habitat is the barracks compartment boarding defenders muster from, and training in it raises the marines'' quality over time. First step of component-based ship construction on top of Outfitting/Construction (U.SPC-T377)', '1d69906 MarineHabitatTests', 464, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T466', 'Unity.SpaceGod', 466, '2026-10-23', 'feature', 'closed', 'Breacher becomes a fired boarding round (owner 2026-10-23): a Breacher is a whole team of marines in an armoured round, fired at high velocity from an Assault Bay module (the firing room, fitted in an internal bay of a hull that also has a Marine Habitat to supply the team) and flying like a bullet, with only slight course correction, until it strikes a hull, drills in and disgorges its marines into the compartment it hit, where the existing compartment-by-compartment boarding fight takes over and the target''s own marines try to stop them. It is no longer a flown ship class: it leaves the heavy-fighter flight family, patrol wings, escort wings and the scene tour, gets a ballistic flight family of its own, and docs/FLIGHT_MODELS.md stops calling it the heavy fighter. The bay reloads only as fast as the habitat can ready the next team. The small 12-marine BoardingPods stay as the lighter option', 'AssaultBayTests; d909bd2', 465, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T467', 'Unity.SpaceGod', 467, '2026-10-23', 'feature', 'closed', 'Dedicated heavy fighter hull, a gunship (owner 2026-10-23): a new ShipClass in FlightFamily.HeavyFighter that takes over the Breacher''s slots in patrol wings, escort wings (and their hire fee), the scene tour and anywhere else the Breacher stood in as the heavy fighter, so those wings keep their strength once the Breacher becomes a fired boarding round; U.SPC-T441''s Everspace 2-style heavy fighter model flies this hull', 'GunshipTests; 9418a45', 466, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T468', 'Unity.SpaceGod', 468, '2026-10-23', 'feature', 'closed', 'Interactive boarding (future, owner 2026-10-23, low priority): let the player take part in a boarding fight instead of only watching it resolve; whether that is turn-based tactics or a first-person shooter is left open and needs a design pass first. Today''s weighted-roll fight, compartment by compartment with defending marines mustering against the boarders, stays as the resolver behind it and as the auto-resolve choice', '43e793b', 467, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T469', 'Unity.SpaceGod', 469, '2026-10-23', 'feature', 'wont-do', 'Hull space for facilities (owner 2026-10-23): every hull has a limited internal space, and each facility fitted into it (Marine Habitat, Assault Bay, hangar, cargo holds, magazines, reactor, quarters and the rest) takes a share sized to what it is, so a design is a trade-off: a hull that carries a marine habitat and an assault bay gives up hold, hangar or magazine space to do it, and a hull too small for a facility cannot fit it at all. Builds on Outfitting/Construction''s slots and internal bays (U.SPC-T377), replacing a fixed count of bays with a space budget the yard, the outfitting screen and the AI''s designs all respect', 'Refiled as a clearer ticket that separates hardpoints (on the hull) from facilities (inside it), per the owner 2026-10-23', 468, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T470', 'Unity.SpaceGod', 470, '2026-10-23', 'feature', 'closed', 'Hardpoints on the hull, facilities inside it (owner 2026-10-23): split ship construction into two kinds of part. A hardpoint is a place on the hull''s surface (gun and turret mounts, launchers, torpedo tubes, shield emitters, engine mounts) with a position and firing arc, as Construction''s Hardpoint already is. A facility is a thing inside the body of the ship (Marine Habitat, Assault Bay, hangar, cargo holds, magazines, reactor, quarters, bridge and the rest) and has no arc, only a size. Every hull has a limited internal space, and each facility takes a share of it sized to what it is, so a design is a trade-off: a hull that carries a marine habitat and an assault bay gives up hold, hangar or magazine space, and a hull too small for a facility cannot fit it at all. Today internal bays are modelled as a hardpoint slot kind (SlotKind.InternalBay, Hardpoint.LayoutIndex -1, sockets named bay-N); move them out into the facility layout, and have the yard, the outfitting screen, the AI''s designs and the boarding interior''s compartments all read facilities from it. Builds on U.SPC-T377', 'FacilitiesTests (67a318d)', 469, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T471', 'Unity.SpaceGod', 471, '2026-10-23', 'docs', 'closed', 'Ship roster and doctrine canon (owner 2026-10-23): write docs/SHIP_ROSTER.md, linked from README and docs/VISION.md, holding the owner''s roster as the reference every ship ticket builds to: the three travel layers (jump gates as the strategic chokepoints, self-contained FTL on carriers, gate breakers and some capitals, hyper lanes inside a system with predictable routes that invite ambush and sabotage); every class with its role and how it travels (the own-FTL table); the strike craft; the weapons-by-tier table; the softened realism rules (inertial dampeners are why piloted dogfights work; bridges buried at the centre of the hull with no viewports, seen out through sensors and holo/VR; radiators a weak point on big ships but not a constant worry; full 3D combat, above all in dogfights; shields, so bombers knock shields down and then torpedo); and the two doctrines, a large but predictable gate fleet against a smaller jump strike group that can arrive anywhere', '6767e2f', 470, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T472', 'Unity.SpaceGod', 472, '2026-10-23', 'feature', 'closed', 'Who has their own FTL, per the owner''s roster (owner 2026-10-23): carriers and gate breakers always have a self-contained FTL drive; battleships and command cruisers only when the design fits one (a drive facility taking hull space); cruisers, destroyers and frigates have none and travel by gate, or docked on a carrier; corvettes never leave their home system; fighters and bombers travel inside a carrier''s hangar. Today FtlCarriage gives cruisers and destroyers their own drives and berths; take those away and move every system that relies on them (InterstellarTraffic, CruiseDrive, HelmFtl, DeepSpace, the AI''s fleet movement) onto gates or carriage', '472854c (FtlCarriageTests.TheOwnersRosterSaysWhoHasTheirOwnFtl)', 471, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T473', 'Unity.SpaceGod', 473, '2026-10-23', 'feature', 'closed', 'Carriers clamp escorts to the hull, and a lost carrier strands its wings (owner 2026-10-23): besides fighters, bombers and shuttles in its internal hangars, a carrier can clamp a few frigates or corvettes (or destroyers) to the outside of its hull and take them through its own jump, so a jump strike group is a carrier, FTL capitals and docked escorts; when a carrier is destroyed or jumps away, its fighter and bomber wings still out are stranded with nowhere to land, and must reach another friendly carrier or station or be lost', 'd7582f6 CarrierStrikeGroupTests', 472, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T474', 'Unity.SpaceGod', 474, '2026-10-23', 'feature', 'closed', 'AI fleet doctrine, gate fleets and jump strike groups (owner 2026-10-23): navies raise two kinds of force and use them differently. A gate fleet is large but has to come through a gate, so it is predictable and defended against at gate exits. A jump strike group (a carrier, FTL-capable capitals and escorts docked on the carrier) is smaller but can jump in anywhere to raid, relieve or open a second front. Strategic command picks between them by objective, and defenders station pickets at gates and keep reserves against strike groups', 'a0a523a FleetDoctrineTests', 473, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T475', 'Unity.SpaceGod', 475, '2026-10-23', 'feature', 'closed', 'Frigate class (owner 2026-10-23): a fast, lightly armoured, engine-heavy missile and torpedo boat with big magazines of long-range anti-ship missiles and antimatter or photon torpedoes; its doctrine is the alpha strike: burn in, fire a devastating volley, flip and burn back out, relying on speed and distance instead of armour. No FTL drive (gates, or docked on a carrier)', 'FrigateTests.ItBurnsInHoldingItsLaunchersLoosesOneVolleyThenFlipsAndBurnsBackOut (commit 3f5d97e)', 474, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T476', 'Unity.SpaceGod', 476, '2026-10-23', 'feature', 'closed', 'Corvette class (owner 2026-10-23): system defence with no FTL drive, saving its weight for patrol; stationed for good on the hyper lanes of its home system around a planet, moon or station, it is local law enforcement that intercepts smugglers and pirates, and it never leaves that system', 'f5632e3 (CorvetteTests)', 475, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T477', 'Unity.SpaceGod', 477, '2026-10-23', 'feature', 'closed', 'Command cruiser / battlecruiser class (owner 2026-10-23): a capital that gives up some weapons for large sensor arrays, communications and targeting computers and carries the fleet''s senior officers close to the action; ships within its reach fight better coordinated (faster and more accurate fleet targeting, a shared sensor picture), losing it degrades the fleet''s coordination, and it is a priority target. Own FTL only when the design fits a drive', '366a1cb', 476, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T478', 'Unity.SpaceGod', 478, '2026-10-23', 'feature', 'closed', 'Gate breaker siege capital (owner 2026-10-23): a heavily armoured capital built to take or destroy a jump gate, carrying siege weapons (plasma brawling batteries) and boarding and engineering teams to seize a gate intact rather than wreck it; it always has its own FTL, since it attacks the gates the rest of the fleet would use. Ties into gate forts and gate battles in InterstellarWars', 'b8a677e GateBreakerTests', 477, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T479', 'Unity.SpaceGod', 479, '2026-10-23', 'feature', 'closed', 'Lane interdictor class (owner 2026-10-23): a ship that disrupts or hijacks a hyper lane''s magnetic field to pull ships out mid-transit, the pirate''s and raider''s favourite; builds on the existing interdiction pulse and lane-side battle so the pulse comes from a dedicated hull that pirates and navies field', '754f983 LaneInterdictorTests', 478, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T480', 'Unity.SpaceGod', 480, '2026-10-23', 'feature', 'closed', 'Gate picket class (owner 2026-10-23): small, sensor-heavy ships stationed at gate exits for early warning against anything that jumps in or comes through the gate; a held gate with pickets gives its owner warning and time to react, and raiders try to kill pickets first. Distinct from today''s picket patrol wing (a destroyer leading fighters), which should be renamed or folded in', '51d68ed GatePicketTests', 479, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T481', 'Unity.SpaceGod', 481, '2026-10-23', 'feature', 'closed', 'Lane tender class and lane upkeep (owner 2026-10-23): unarmed maintenance ships that keep hyper lane accelerator rings powered and aligned; a lane without tenders slowly loses speed and reliability and eventually fails, so tenders are essential in peace and a top target in war, and raiders and navies both hunt them to cut a system''s lanes', 'f241a05 (LaneUpkeepTests)', 480, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T482', 'Unity.SpaceGod', 482, '2026-10-23', 'feature', 'closed', 'Bulk freighters as truss-and-pod ships riding the lanes (owner 2026-10-23): a freighter is a skeletal truss with an engine at one end and standardised modular cargo pods or fuel spheres clamped along it, built in space and never landing on a planet; it carries no armour and no weapons, since every kilogram goes to cargo; it rides hyper lanes cheaply instead of burning fuel, and off the lanes it takes a long time to speed up and slow down. Its cargo capacity is the pods it carries (ties to CargoHold and the hull-space facilities)', '0481fc9', 481, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T483', 'Unity.SpaceGod', 483, '2026-10-23', 'feature', 'closed', 'Ice hauler / ore tug (owner 2026-10-23): instead of carrying cargo, a tug is a big engine with claws that latches onto a harvested asteroid or a block of comet ice and pushes it slowly across a system; large loads may need dedicated heavy lanes. Feeds the asteroid-belt mining pipeline (U.SPC-T330) alongside today''s Miner', '1dc40a7 OreTugTests', 482, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T484', 'Unity.SpaceGod', 484, '2026-10-23', 'feature', 'closed', 'Strike craft roster as hulls of their own (owner 2026-10-23): interceptor (fast, agile, light guns, hunts fighters and screens bombers), space superiority fighter (the balanced all-round workhorse), bomber (slow and tough, torpedoes for anti-capital strikes, needs an escort), each its own ShipClass with its own flight model instead of today''s squadron roles on shared hulls; the heavy fighter / gunship is U.SPC-T467. Carriers launch and recover them as squadrons', '88a432c StrikeCraftTests', 483, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T485', 'Unity.SpaceGod', 485, '2026-10-23', 'feature', 'closed', 'Recon / EW fighter (owner 2026-10-23): a strike craft that scouts ahead, jams enemy targeting and paints targets for the bombers, so a painted target is easier for bombers'' torpedoes to hit and a jammed ship fires less accurately', '1c2ca1d ReconFighterTests', 484, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T486', 'Unity.SpaceGod', 486, '2026-10-23', 'feature', 'closed', 'Boarding shuttle / assault craft (owner 2026-10-23): a piloted craft that delivers marines to disabled ships and to gates by docking or latching on (slower and gentler than a fired Breacher round, U.SPC-T466), for taking prizes and seizing gates intact; carried in carrier hangars', '4c47830', 485, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T487', 'Unity.SpaceGod', 487, '2026-10-23', 'feature', 'closed', 'Tachyon lance (owner 2026-10-23): a capital-only spinal weapon that hits near-instantly at long range, ignoring light-speed delay; it would change the whole doctrine, so it is rare, expensive and power-hungry (a large power plant, long recharge) to keep kinetics and missiles relevant', 'TachyonLanceTests (8a938aa)', 486, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T488', 'Unity.SpaceGod', 488, '2026-10-23', 'feature', 'closed', 'Phaser-style beam arrays and plasma cannons (owner 2026-10-23): phaser arrays are versatile, tunable medium-range energy weapons for destroyers and cruisers; plasma cannons are devastating short-range weapons whose damage bleeds off over distance, for brawlers and gate breakers', 'c036ccd EnergyWeaponsTests', 487, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T489', 'Unity.SpaceGod', 489, '2026-10-23', 'feature', 'closed', 'Antimatter / photon torpedoes, flak and interceptor missiles (owner 2026-10-23): antimatter or photon torpedoes are heavy guided warheads at medium range for frigates and capitals; destroyers'' anti-fighter screen gains rotary flak cannons and interceptor missiles beside their point-defence lasers, forming the umbrella that shoots down missile swarms and fighters before they reach the capitals', 'ScreenWeaponsTests.ADestroyerScreenMeasurablyProtectsTheCapitalItEscorts (commit 07d9ffd)', 488, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T490', 'Unity.SpaceGod', 490, '2026-10-23', 'feature', 'closed', 'Dreadnought spinal mounts and rear-line doctrine (owner 2026-10-23): a battleship is built around one or two ship-length spinal mounts (railgun or coilgun, tachyon lance or plasma spinal cannon) on a large power plant, and its doctrine is to hold the rear and snipe from extreme range rather than close in', 'DreadnoughtTests (975e6e7)', 489, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T491', 'Unity.SpaceGod', 491, '2026-10-23', 'feature', 'closed', 'Radiators and heat on big ships (owner 2026-10-23): engines and weapons build heat that large ships shed through radiator panels mounted on the hull; radiators are a weak point, so targeting them is a real tactic, and a ship that cannot shed heat must throttle weapons and engines or its crew and systems suffer; kept a weak point to exploit, not a constant worry', '93e6d37', 490, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T492', 'Unity.SpaceGod', 492, '2026-10-23', 'feature', 'closed', 'Bridges at the centre of warships (owner 2026-10-23): a warship''s bridge is buried at the centre of the hull, protected by its full thickness, with no viewports (the crew sees out through sensors and holo/VR displays); the boarding interior puts the bridge at the centre, and only deep penetration or boarders reach it', '7fbb8b6', 491, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T493', 'Unity.SpaceGod', 493, '2026-10-23', 'fix', 'closed', 'Unity logs that it cannot parse ProjectSettings/TagManager.asset on every import (seen during U.SPC-T430''s builds, present before it): find what in the file is malformed (a merge leftover, bad indentation, a duplicate or empty layer entry) and repair it so tags and layers load as intended, checking any code that looks up tags or layers by name still finds them', '6eca11c', 492, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T494', 'Unity.SpaceGod', 494, '2026-10-23', 'feature', 'closed', 'Help becomes its own full screen under the Main menu (owner 2026-10-23): replace the help card that covers about two thirds of the lower left (Hud.DrawHelp, H/F1, ShowHelp on by default) with a Help screen reached from the Main menu (and from the Esc menu and H/F1 in game) that fills the whole screen and prints every key, control and help line the card holds today, laid out in clear groups (camera and god view, helm and flight, combat, trade, diplomacy, fleet and command, screens and panels) so it reads well; the in-game card no longer opens by default. A first step: the full sectioned in-game manual is a separate ticket', 'b8eec83', 493, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T495', 'Unity.SpaceGod', 495, '2026-10-23', 'feature', 'closed', 'The navigator starts collapsed (owner 2026-10-23): Hud.navigatorOpen defaults to false, so a new game opens with only the NAVIGATOR header bar showing and the player expands it with its [+] when wanted', '20640e7', 494, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T496', 'Unity.SpaceGod', 496, '2026-10-23', 'feature', 'closed', 'F11 clears the screen (owner 2026-10-23): pressing F11 hides the entire UI, in both the god (strategy) view and the spaceship (helm) view: HUD, navigator, help, panels, banners, toasts, labels and markers, everything except whichever reticle is in use (the helm''s aim reticle, a turret seat''s sight); pressing F11 again brings it all back as it was. The galaxy map moves off F11 to a free key (still on the navigator''s GALAXY MAP button), every label and help line is updated, and the existing U HUD toggle is folded into this or kept as a lighter toggle, whichever reads cleaner', 'a76475e', 495, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T497', 'Unity.SpaceGod', 497, '2026-10-23', 'feature', 'open', 'In-game manual (owner 2026-10-23, its own major effort): grow the Help screen into a well organised, well maintained in-game document that covers everything in the game, split into sections (getting started, the god view, flying, each ship family, combat and boarding, trade, diplomacy, fleets and command, the galaxy and travel, settings), navigable from a contents list, kept current as features land so a new feature is not done until its manual entry is', '—', 496, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T498', 'Unity.SpaceGod', 498, '2026-10-23', 'feature', 'closed', 'Every ship has a real presence in the world (owner 2026-10-23): no ship may exist only as a number inside a simulation. Ore tugs (U.SPC-T483) live only inside the belt-mining pipeline, so make each one a real Ship in the fleet: flying its haul with its load latched on (visible, rendered at its LOD), on heavy lanes when it takes one, seizable by raiders where it actually is, and embodiable so the player can take its helm; remove the skip for OreTug in the every-class-in-the-default-fleet test. Then audit the rest of the sim for other ships that exist only as counts (capture tugs, mining operations'' craft, convoy and charter freighters, carrier squadrons, fleet strength tallies, anything else) and give each a real Ship, filing a separate ticket for any too big to fold in. Add the rule to README''s design principles and docs/SHIP_ROSTER.md', 'OreTugTests.EveryOreTugIsARealHullInTheFleetThePlayerCanTakeTheHelmOf, commit 7aa919c', 497, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T499', 'Unity.SpaceGod', 499, '2026-10-23', 'feature', 'closed', 'Capital ship flight model in full 3D, Black Flag broadside handling (owner 2026-10-23: capitals fight in full 3D, like the fighters, never on a battle plane; refiles U.SPC-T442 without it; docs/FLIGHT_MODELS.md, Capital ships): a CapitalFlightModel + CapitalHandling (per-class overrides) for FlightFamily.Capital with a stepped engine telegraph that holds (Full Astern..Flank, Flank = boost), speed-dependent steerage peaking at Half with a slow pivot at Stop, keel damping so turns trace a turning circle, pitch and yaw both slow and heavy but free in every direction (no battle plane: a capital climbs, dives and rolls to bring a broadside to bear above or below), per-class come-about targets (180 deg at Half: Destroyer ~6 s, Cruiser ~10 s, Battleship ~14 s, Carrier ~18 s) checked by tests, and the Destroyer as the tighter, faster skirmisher; handling only, batteries, arcs and bracing stay with U.SPC-T425, whose broadside arcs must be checked to work above and below the hull too', 'e1cf77d', 498, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T500', 'Unity.SpaceGod', 500, '2026-10-23', 'docs', 'closed', 'Record the owner''s decision (2026-10-23) that capital ships fight in full 3D, not near a battle plane, in docs/SHIP_ROSTER.md (closing its open question) and the Broadsides.cs comment that lists a battle plane among the capital handling', '2f19a81', 499, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T501', 'Unity.SpaceGod', 501, '2026-10-23', 'feature', 'closed', 'Shields come from emitters, not facing arcs (owner 2026-10-23): since everything fights in full 3D, the facing-arc shields (Facing, Broadsides.ShieldTrim and StepShields, the bow/beam/stern split from docs/SHIELD_ARCS_SPIKE.md) go away. Instead, like turrets, ships carry shield emitters as hardpoints on the hull; each emitter projects a field over the patch of hull around it, fire that lands on a patch drains that emitter''s field, and a field shot away (or an emitter destroyed) leaves that spot of the hull unshielded while the rest stays covered, so a ship can be holed in one place and protected elsewhere. Emergency repair crews inside the ship (extending today''s damage control teams) restore shield emitters and turrets given time. Shots hit the shield of the patch they actually strike in 3D. AI gunners and the player''s aim can focus fire on a weakened patch. Every rate as a setting. Update docs (retire SHIELD_ARCS_SPIKE''s arc model, SHIP_ROSTER, README)', '8c089e7 ShieldEmitterTests', 500, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T502', 'Unity.SpaceGod', 502, '2026-10-23', 'feature', 'closed', 'Large ships roll to protect their weak spots (owner 2026-10-23): in full 3D a capital (AI captain or the player''s helm assist) rolls and turns its hull to keep damaged, unshielded or holed patches away from the heaviest incoming fire and to present fresh shields and armour instead, trading that against keeping its own batteries bearing; the AI weighs where the fire is coming from, and the player gets a clear readout of which patches are weak and an order to roll them away. Builds on shield emitters and the full-3D capital flight model (U.SPC-T499)', 'f189b6a WeakPatchTests', 501, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T503', 'Unity.SpaceGod', 503, '2026-10-23', 'fix', 'closed', 'Turning the broadside.aiVolleys setting off and back on leaves state behind, after which BroadsideTests.AnAiCaptainFiresBroadsidesFromItsBeamAndAnglesItsShieldsToTheEnemy fails (it passes on its own); find what the toggle leaves changed (a cached value, a static the setting''s setter writes, a default not restored) and make setting it back restore the original behaviour, with a test that toggles it and checks the AI still fires and angles', 'b37b467', 502, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T504', 'Unity.SpaceGod', 504, '2026-10-23', 'fix', 'closed', 'The first save in a test run can fail with ''Collection was modified'' because ObjectGraph.Statics.Ensure walks every static dictionary while fixtures running in parallel still fill or change them (seen in InterstellarCruiseTests.AGroupBetweenTheStarsSavesAndCarriesOnExactlyAsItWas and FacilitiesTests.ALoadoutWithFacilitiesSurvivesASave, each passing alone); snapshot each static collection before walking it, or retry, so a save never depends on test timing', '9ceeea2', 503, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T505', 'Unity.SpaceGod', 505, '2026-10-23', 'feature', 'closed', 'Navies and raiders fit the new weapons (owner 2026-10-23): no stock design carries phaser arrays or plasma cannons (U.SPC-T488) and AI navies never refit with them, and the tachyon lance (U.SPC-T487) is only fitted last when money is plentiful, so the new weapons appear only where a player fits them. Give the stock designs and the AI''s refit wish lists a place for each weapon in its role, per docs/SHIP_ROSTER.md''s weapons table: phaser arrays on destroyers and cruisers, plasma cannons on battleships and brawlers (and gate breakers once U.SPC-T478 adds them), the tachyon lance on a rare capital, antimatter/photon torpedoes on frigates and capitals and flak and interceptor missiles on destroyers (U.SPC-T489); navies and raiders choose by doctrine, wealth and what their yards can build, so a fleet''s mix differs by faction; tests that AI fleets field each weapon in its role', '79e4b19 FleetPatternsTests', 504, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T506', 'Unity.SpaceGod', 506, '2026-10-23', 'fix', 'closed', 'A ship''s damage figure averages over its parts, so fitting more parts makes the same hull damage read as lighter: after U.SPC-T489 added flak and interceptor launchers, a destroyer at 30% hull reads 0.27 damaged against the 0.3 repair threshold and no longer goes for repair; base the repair and retreat decisions (and anywhere else that reads it as ''how hurt is this ship'') on hull integrity, or weight parts so adding one does not dilute it, and restore ARaiderReplannedBeforeItsAmbush to its original 30% hull', 'ARaiderReplannedBeforeItsAmbushForgetsTheAmbush', 505, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T507', 'Unity.SpaceGod', 507, '2026-10-23', 'feature', 'closed', 'Lane interdictor is heavy equipment, not a ship class (owner 2026-10-23): U.SPC-T479 added ShipClass.Interdictor; instead, the interdiction field projector is a piece of heavy equipment, a facility (U.SPC-T470) fitted into the internal space of a hull big enough to carry it and its reactor load, so any suitable ship (a destroyer, a cruiser, a raider''s converted freighter) can be fitted out as an interdictor. Remove ShipClass.Interdictor and its design, hull frame and mesh (the ring projector becomes the equipment''s visible part on whatever hull carries it), keep LaneInterdictors'' rules keyed on carrying the equipment (RegisterEmitter''s per-class list becomes the fitted facility), have raider bands, the navy lane-picket wing and the Lane security build plan fit the equipment to suitable hulls instead of building the class, let yards fit and strip it, and update the tests, README and docs/SHIP_ROSTER.md (which lists Lane Interdictor as a class)', 'f3d6353 (LaneInterdictorTests)', 506, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T508', 'Unity.SpaceGod', 508, '2026-10-23', 'feature', 'closed', 'Typed hardpoints and slots, MechWarrior style (owner 2026-10-23): a hull''s hardpoints are reserved for a kind of part, as in MechWarrior: Ballistic (railguns, coilguns, autocannons, flak), Missile (missile racks, torpedo tubes, antimatter torpedoes, interceptor missiles), Energy (lasers, point-defence lasers, phaser arrays, plasma cannons, the tachyon lance), each with a size, so a design is shaped by which kinds of mount its hull has, not just how many. Spare internal space can be packed with extra armour, sensor arrays and the like (heat sinks once radiators and heat land, U.SPC-T491). Replace today''s SlotKind mounts (LightMount, HeavyMount, GunMount, UtilityMount, TorpedoTube...) with typed mounts on every hull frame and stock design, keep the effect of every existing stock design, make the yard, the outfitting screen and the AI''s refits obey the types (U.SPC-T505''s AI refits build on this), show each mount''s type and size on the outfitting screen, and document it in docs/SHIP_ROSTER.md', 'EveryHardpointIsTypedAndSizedAndEveryStockDesignKeepsItsOwnParts (bb462ff)', 507, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T509', 'Unity.SpaceGod', 509, '2026-10-23', 'chore', 'closed', 'Commit the regenerated USER_STORIES.md view for the owner''s 2026-10-23 design tickets (ship roster, boarding, typed slots, shields, help screen, F11 and the rest) filed and approved without a commit of their own', '1fe3cfb', 508, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T510', 'Unity.SpaceGod', 510, '2026-10-23', 'fix', 'closed', 'HoldingsTests.ATakenShipJoinsTheFleetWithItsCargoAsClearProfit fails on main (seen by U.SPC-T506, failing the same way without its change): find what changed (likely one of today''s landings: facilities, new classes, trade desk, damage figures) and fix the code or the test so a prize ship joins the fleet and its cargo is counted as clear profit', 'a4b8f41', 509, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T511', 'Unity.SpaceGod', 511, '2026-10-23', 'fix', 'closed', 'FightersLandBackOnTheirCarrierWhenTheShootingStops fails on main (seen by U.SPC-T465, failing without its change): likely from U.SPC-T484''s strike-craft squadrons (launched craft now hulls of their own class) or the carrier changes; find why fighters no longer land back and fix the code or the test', '7128a83', 510, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T512', 'Unity.SpaceGod', 512, '2026-10-23', 'fix', 'closed', 'EveryHeavyFighterSlotIsAGunshipAndNoneABreacher fails on main (seen by U.SPC-T465, failing without its change): a later landing (interdictor lane-picket wing U.SPC-T479, gate pickets U.SPC-T480, strike craft U.SPC-T484) put a Breacher or non-Gunship into a heavy-fighter slot, or the test''s notion of a heavy slot is stale; find which and fix it', 'EveryHeavyFighterSlotIsAGunshipAndNoneABreacher', 511, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T513', 'Unity.SpaceGod', 513, '2026-10-23', 'fix', 'closed', 'TheNewTunablesAreInTheSettingsMenu fails on main (seen by U.SPC-T465, failing without its change): a tunable the test expects is missing from the settings menu or a group was renamed (Settings > Weapons and Broadsides both gained settings today); find which and fix the registration or the test', 'TheNewTunablesAreInTheSettingsMenu', 512, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T514', 'Unity.SpaceGod', 514, '2026-10-23', 'fix', 'closed', 'EverySystemRunsAYearOfFullTrafficWithinTheBudget misses its 150 s budget on main (195 s without U.SPC-T472, 238 s with it, measured while other agents were running): profile a year of full traffic, find which of today''s landings added the cost (lane tenders'' dozen extra ships per world, gate pickets, ore tugs, command coordination, FTL roster lookups, facilities) and bring it back under budget, or show the budget is load-sensitive and make the test measure fairly', 'EverySystemRunsAYearOfFullTrafficWithinTheBudget', 513, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T515', 'Unity.SpaceGod', 515, '2026-10-23', 'fix', 'closed', 'Jump gates sit right in front of the sun instead of at the extreme edge of their solar system (owner 2026-10-23): Galaxy.GateDistanceKm is the star''s own radius plus JumpGate.RadiusKm, so GateNetwork.Build (and GateConstruction, void stations) places every gate just off the photosphere along the direction of the linked star; place each gate at the system''s outer edge instead (beyond its outermost planet and belt, e.g. past the system''s outermost body''s orbit plus a margin, in the direction of the star it links to), and move everything keyed to the gate''s position with it: gate forts and gate battles, pickets'' posts, lane spurs and on-ramps to gates, raider lie-in-wait spots, FTL drop-out points, the scene''s gate visuals and the galaxy map; travel times across a system to its gates grow accordingly, so check trade, war and patrol timings still work', 'df18a86', 514, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T516', 'Unity.SpaceGod', 516, '2026-10-23', 'fix', 'closed', 'Travelling to a system several gates away teleports straight there (owner 2026-10-23): the galaxy map''s travel (GalaxyMapScreen.Travel, UnitySpaceApp.TravelTo, Travel.Begin) jumps the view or the ship to the final destination, but the gates must actually be taken one at a time: fly to the first gate, go through it, fly across that solar system to the next gate (by lane where one runs), go through that one, and so on to the destination. Make a multi-gate trip a planned course of real legs (GateNetwork.Route) that the piloted ship, its autopilot and the god view''s followed ship actually fly, with each system crossed in real space and each gate transit played, showing the course and the next leg on the HUD and map; check AI traffic and fleets do the same rather than skipping intermediate systems', 'b1f2ac3', 515, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T517', 'Unity.SpaceGod', 517, '2026-10-23', 'feature', 'open', 'Breacher is only a round, never a ship (owner 2026-10-23): U.SPC-T466 kept the old flyable ShipClass.Breacher design (guns, shields, hull frame) for saves and tests; remove it so a Breacher exists only as the bullet-shaped armoured round fired from an assault bay, with limited steering, its own round model in the scene, and no ship class, design, yard entry or crew; rework the tests and saves that used it as a hull', '—', 516, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T518', 'Unity.SpaceGod', 518, '2026-10-23', 'feature', 'open', 'Flight decks you fly through in person (owner 2026-10-23): give carriers (and other hulls with hangars) a real flight deck in the Battlestar Galactica / Star Wars style, a through-hull bay open at both ends: a fighter, bomber or shuttle, piloted by the player or the AI, flies in one end, lands on the deck, refuels, rearms and repairs, then takes off and flies out the other end and back into the fight; replace the abstract count-based recovery of strike craft with craft actually flying the approach, landing and launching through it, with deck traffic, landing guidance on the HUD and the carrier''s bays drawn in the scene; the player can land their own fighter to restock and relaunch', '—', 517, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T519', 'Unity.SpaceGod', 519, '2026-10-23', 'feature', 'open', 'A Breacher round that fails is not an instant loss of its team (owner 2026-10-23): today (U.SPC-T466) a round that misses or glances off raised shields deletes its 70 marines; instead the round keeps flying, careening off into space or tumbling away from the shields, a derelict with the marines alive inside, and point defence can shoot rounds out of the air in flight (killing the team); after the battle, its side''s tow units can find and recover drifting rounds and bring the marines home, or pirates can salvage them first and ransom the marines back to their owner or sell them as slaves to that side''s enemy', '—', 518, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T520', 'Unity.SpaceGod', 520, '2026-10-23', 'feature', 'wont-do', 'Navy ships fit Breacher launchers too (owner 2026-10-23): U.SPC-T466 gave the Assault Bay (the firing room for Breacher rounds) only to pirate band leaders; let navies fit it as well, on warships, battleships and carriers that carry a Marine Habitat, in the stock designs where it fits the class''s role and as a yard refit, and have navy captains fire Breacher rounds at weakened hostile hulls to take them as prizes, as pirates do', 'superseded by U.SPC-T521 (Breacher Bay as an equipable facility)', 519, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T521', 'Unity.SpaceGod', 521, '2026-10-23', 'feature', 'open', 'Breacher Bay is an equipable facility any ship can fit (owner 2026-10-23): rename U.SPC-T466''s Assault Bay to the Breacher Bay and make it fittable like the interdiction facility: any hull (navy, pirate, merchant escort) can carry one if it has the free internal slots, the reactor power for it and the crew to man it, plus marines aboard to fill the rounds; it shows in the yard''s fitting screen with its slot, power and crew cost, navies fit it in the stock designs where it suits the role and as a yard refit, and AI captains of any side fire Breacher rounds at weakened hostile hulls to take them as prizes; replaces U.SPC-T520', '—', 520, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T522', 'Unity.SpaceGod', 522, '2026-10-23', 'feature', 'open', 'Capture tugs are real hulls (from U.SPC-T498''s audit: no ship exists only as a number): a belt works'' capture tugs (MiningOperation.CaptureTugs, 2 at Ceres today) are only a count and a timer in BeltMining.Capture; give the capture tug a ShipClass of its own (design, hull frame, mesh, cost, flight family) and make each one a Ship in the fleet that flies out into the field, matches a rock of 40-140 m and pushes it in to its refinery with the load latched on and drawn, using the ore tugs'' hull machinery (MiningOperation.Tugs, Ship.Tow, Ship.Homing), seizable where it is and embodiable', '—', 521, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T523', 'Unity.SpaceGod', 523, '2026-10-23', 'feature', 'open', 'Raw-material convoys are real freighters (from U.SPC-T498''s audit: no ship exists only as a number): a belt works'' MaterialConvoy from its refinery to its warehouse is a cargo array and a timetable in BeltMining.Ship/MoveConvoys, robbed by a dice roll on global pirate pressure; make each convoy real freighter hulls in the fleet, owned by the works'' faction, carrying the separated elements in their holds along the lanes to the depot, robbed only by raiders that actually reach them (the war''s boarding rules), with their escort share as real escorts', '—', 522, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T524', 'Unity.SpaceGod', 524, '2026-10-23', 'feature', 'open', 'Colony ships are real hulls (from U.SPC-T498''s audit: no ship exists only as a number): Colonisation''s ColonyShip is a record with DepartJd/ArriveJd and no hull; make each colony voyage a real Ship in the fleet (a colony ship class or a fitted freighter) that flies from its port to its site, through the gates for a voyage abroad, carrying its colonists and starter goods, attackable and boardable on the way, and founding or reinforcing the settlement only when it actually arrives', '—', 523, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T525', 'Unity.SpaceGod', 525, '2026-10-23', 'feature', 'open', 'Navy supply convoys are real tankers and colliers (from U.SPC-T498''s audit: no ship exists only as a number): MilitarySupply''s SupplyConvoy carries its propellant, munitions and spares as counts of Tankers and Colliers with a due date; make each convoy real hulls that sail from the naval base through the gates to the campaign fleet, cut off or destroyed only by what actually meets them, and deliver on arrival', '—', 524, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T526', 'Unity.SpaceGod', 526, '2026-10-23', 'feature', 'open', 'Carrier wings are real craft between battles (from U.SPC-T498''s audit: no ship exists only as a number): a carrier''s fighters, interceptors and bombers are an int (ShipCombat.Fighters, Squadrons x 6) aboard and only become BattleUnits with no Ship once a fight starts; make every craft a real hull (a Ship docked in its carrier''s hangar, carried through jumps) that launches as itself, keeps its own damage and pilot, can be embodied by the player, and is lost or recovered as itself', '—', 525, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T527', 'Unity.SpaceGod', 527, '2026-10-23', 'fix', 'closed', 'Settings tests fail when run together (seen by U.SPC-T490): with SettingsRegistryTests in the same run, the dreadnought, tachyon lance, weapons, dogfighting and drill settings tests fail though each passes alone; SettingsRegistryTests likely swaps the shared SettingsRegistry.Default without restoring it, so tests after it read a registry missing their declarations; make the registry tests restore the default (or isolate it) so the settings tests pass in any order', '6c90f3f', 526, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T528', 'Unity.SpaceGod', 528, '2026-10-23', 'chore', 'closed', 'many billions of tokens', '—', 527, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T529', 'Unity.SpaceGod', 529, '2026-10-24', 'fix', 'closed', 'tools/deploy.ps1''s ''is the project open in the Editor?'' guard (line 90) matches MainWindowTitle -like ''*UnitySpace*'', but since the Unity Fleet Rename the folder, and so the Editor title, is Unity.SpaceGod, so the guard never fires and a batch build runs against an open project; match the current folder name (Split-Path -Leaf of the repo) instead of a hard-coded name, and fix the stale ''tools\ -> UnitySpace\'' comment and the error text (found by MAT-T26 sweep)', 'b9f484e', 528, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T530', 'Unity.SpaceGod', 530, '2026-10-24', 'fix', 'closed', 'README.md line 552 says docs/USER_STORIES.md is ''generated from the MindAttic.Workflow database; change tickets with the workflow CLI''; it''s the MindAttic.Tickets database and the tickets CLI since M.TIX-T120 (found by MAT-T26 sweep)', '61f2d24', 529, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T531', 'Unity.SpaceGod', 531, '2026-10-24', 'fix', 'closed', 'Five Core.Tests fail on origin/main 259c2f8 (Tests/Core.Tests, found by MAT-T26 sweep): BomberWingmenLooseTheirTorpedoesOnTheRunToo (''only squadron leads ever fired a torpedo''), CarriersLaunchTheirSquadronsWhichFlyRunsShootAndTorpedo (''no fighter ever fired its guns''), ATakenTurretHoldsFireUntilTheTriggerAndItsCrewFiresAgainOnceHandedBack (''handed back, the crew picks its own target and fires'': enemy health unchanged), ASpurIsJoinedByFlyingThroughItsRingTheWayItRuns (GateSpurRingCrossed reports a crossing for a path that stays inside the ring) and ANavyIsOneFleetWhoseShipsAreCountedOnceAcrossSystemsAndGates (navy roster not unique: SFS Resolute, Dauntless, ... counted twice). A sixth, EverySystemRunsAYearOfFullTrafficWithinTheBudget, ran 155.5s against its 150s budget on a heavily loaded machine; watch it, but it may be load noise', 'a49b50f', 530, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T532', 'Unity.SpaceGod', 532, '2026-10-24', 'docs', 'closed', 'Update USER_STORIES.md', '—', 531, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T533', 'Unity.SpaceGod', 533, '2026-10-24', 'feature', 'closed', 'Every hardpoint weapon aims within a cone, not a facing arc (owner 2026-10-24): since everything fights in full 3D, the bow/starboard/stern/port Facing arcs that still drive broadside battery orders, a mount''s ArcCenterDeg and armour angling go away; instead each weapon hardpoint has an aiming cone, a direction on the hull (its mount''s normal) and a half-angle it can traverse within, so a gun can bear on any target inside its cone in 3D, above or below the hull as well as to the side; spinal mounts and fixed tubes get a narrow cone along the keel, turrets a wide one. Battery orders, the AI captain''s choice of which guns to bring to bear, the player''s fire control and the weak-patch rolling (U.SPC-T502) work from the cones; every cone a datum on the mount''s ModuleSpec or hull frame and every tunable a setting; update the tests, docs/SHIP_ROSTER.md and README', '2fdc1f1', 532, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T534', 'Unity.SpaceGod', 534, '2026-10-24', 'feature', 'closed', 'Armour angling rebuilt for full 3D (owner 2026-10-24): U.SPC-T533 removes the bow/beam/stern armour faces along with the facing arcs; keep armour angling but measure each hit''s obliquity against the hull surface where it actually strikes in 3D (the hull''s local surface normal at the impact point, from its real shape, not three faces), so a glancing hit is partly turned aside and the armour reads thicker the more slanted the strike (capped), as Broadsides.Angling did; keep the ''Armour angling'' strength and the obliquity cap as settings, let the AI captain and the weak-patch rolling (U.SPC-T502) weigh presenting a slanted hull, and update the tests, docs/SHIP_ROSTER.md and README', 'fd1453b', 533, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T535', 'Unity.SpaceGod', 535, '2026-10-24', 'fix', 'closed', 'A capital flying the rear-line doctrine picks its weak-patch roll (WeakPatches, U.SPC-T502) for the heading it wants rather than the one it is still turning through, so for most of the first minute of a fight it shows the incoming fire slightly more weak patch than lying level would (seen by U.SPC-T533: the battle trace in WeakPatchTests.InBattleAnAiCaptainRollsItsHolesOutOfTheFireAtItsOwnTurnRate, which T533 loosened); choose the roll for the hull''s actual heading (or blend toward the wanted one as it turns) and restore the test''s strict ''less exposed than level'' check', 'WeakPatchTests.InBattleAnAiCaptainRollsItsHolesOutOfTheFireAtItsOwnTurnRate (7cf356e)', 534, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T536', 'Unity.SpaceGod', 536, '2026-10-24', 'feature', 'closed', 'CLI-mute flag (depends on Unity.Shared''s -muted / MINDATTIC_CLI_MUTED=1 design): this game already references com.mindattic.unity.shared, so it inherits the mute-on-launch behavior automatically once Unity.Shared implements it. Verify it actually silences audio when launched with -muted or MINDATTIC_CLI_MUTED=1 set, document it in this repo''s own README, and make sure whatever script/mechanism the CLI uses to launch a playable instance of this game for development (not the batch -batchmode build/test runs in deploy.ps1) sets MINDATTIC_CLI_MUTED=1 automatically -- add or update a launch script for this if one doesn''t already cleanly support it.', '331f948 Unity batch-mode compile clean (Unity.SpaceGod.Runtime.dll built, exit 0); launch.ps1 + instant-commands.ps1 parse with 0 errors; MasterVolume now routes through SessionAudio.ListenerVolume so Profiles.SessionMuted holds AudioListener.volume at 0', 535, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T537', 'Unity.SpaceGod', 537, '2026-10-24', 'fix', 'closed', 'Route ships stall forever ''Waiting for propellant'' on a leg their full tanks can never cover: StandingOrder trade-route stops are never checked for reach (Holdings.cs CanFollow ~485, NextOnRoute ~950-974), so in a fuel port the ship re-decides the same unreachable stop every dwell (Fleet.cs ~1614-1622) while the HUD ''Next'' countdown keeps resetting (reproduced: Earth-Titan with Saturn lanes down needs 8,494 t vs a 6,000 t tank); reject or skip unreachable legs when the order is given and each leg is planned, and say why (found by bughunt)', '22e458e', 536, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T538', 'Unity.SpaceGod', 538, '2026-10-24', 'fix', 'closed', 'A loaded ship stuck waiting for propellant never says so: Fleet.cs ~1621 only sets ''Waiting for propellant'' when the hold is empty, so the right-hand card keeps showing its cargo line and a resetting ''Next'' countdown while it sits still; show the wait in its own status regardless of cargo (found by bughunt)', 'e982d05', 537, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T539', 'Unity.SpaceGod', 539, '2026-10-24', 'fix', 'closed', 'Owned ships buy cargo and propellant the house cannot afford: Economy.Load (~761) and Refuel (~928) charge the house account into the negative (probe hit -302,575), PayWages (Holdings.cs ~807-815) then skips wages and after 5 days the captain quits, leaving the ship ''Laid up, no captain''; cap purchases at what the account holds (found by bughunt)', 'AnOwnedShipNeverBuysMorePropellantThanTheHouseAccountHolds', 538, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T540', 'Unity.SpaceGod', 540, '2026-10-24', 'fix', 'closed', 'A damaged owned ship deadlocks at a shipyard it cannot pay: Holdings.cs ~913-915 holds a ship over 25% hull damage at the yard but RepairInPort (~833) silently does nothing when the bill is unaffordable, so it never repairs, earns or leaves; repair what the account can pay for, or let it trade on (found by bughunt)', 'bd1f533', 539, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T541', 'Unity.SpaceGod', 541, '2026-10-24', 'fix', 'closed', 'A trade route can be set to a planet with no port: Hud.cs NextOrders (~2668) builds the route from whatever body is selected (Saturn rather than Titan) and Holdings CanFollow (~486) does not require a market, so the ship shuttles empty forever (''Empty, on its route to Saturn''); require a tradeable market at every stop or substitute the planet''s port moon (found by bughunt)', 'e876283', 540, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T542', 'Unity.SpaceGod', 542, '2026-10-24', 'fix', 'closed', 'Owned free traders (and chartered ships) sit forever ''Free trading, looking for a cargo'' where AI merchants move on: Holdings.cs ~979-986 returns ''stay here'' when nothing is worth doing, so Fleet''s normal fallback to another port never runs; return -1 or reposition to the nearest port with trade (found by bughunt)', '6759121', 541, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T543', 'Unity.SpaceGod', 543, '2026-10-24', 'fix', 'closed', 'Cargo no stop on a route will buy is carried forever and blocks new loads: Holdings.cs ~971 only loads an empty hold and Economy.OnArrive (~514-518) keeps unsold cargo (enlisted ship''s existing hold, leftovers from free trading, a destination that lost its demand); sell it at the best reachable market or dump it, then resume the route (found by bughunt)', '69e0323', 542, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T544', 'Unity.SpaceGod', 544, '2026-10-24', 'fix', 'closed', 'The cargo label ''N t Good for X'' goes stale after X refuses it: Economy.cs ~514-518 clears the booked destination on an unsold arrival but not the cargo text, and NextOnRoute never refreshes it, hiding the stuck-cargo stall; regenerate the cargo text when the booking is cleared (found by bughunt)', 'CargoLabelDropsTheRefusingPortWhenNobodyBuys', 543, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T545', 'Unity.SpaceGod', 545, '2026-10-24', 'fix', 'closed', 'Fuel-gap stall: Economy.Refuel (~930) skips tanks at or above TopUpBelow (97%), so a ship whose next trip needs more than its current fuel but no more than a full tank, sitting at 97-100%, never tops up and waits forever (Fleet.cs ~1614); top up whenever the planned trip is short regardless of the threshold (found by bughunt)', 'd16dede', 544, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T546', 'Unity.SpaceGod', 546, '2026-10-24', 'fix', 'closed', 'A damaged ship is sent to a yard it cannot reach: Holdings.NearestYard (~1060-1075) picks by estimated days with no propellant check, unlike the fuel-port search, so it then waits forever for propellant; only consider reachable yards (found by bughunt)', '9dc25d7', 545, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T547', 'Unity.SpaceGod', 547, '2026-10-24', 'fix', 'closed', 'Ore mined at a claim on a port body can never be sold there: the miner fills its hold regardless of what its tanks can haul (Holdings.cs ~1021, contrary to its own comment) and the free-trade planner excludes the current body as a market (Economy.cs ~587), so it loops ''Idle on the ...: no market for its ore''; size the load to the tanks and sell to the claim body''s own market directly (found by bughunt)', '70e5f38', 546, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T548', 'Unity.SpaceGod', 548, '2026-10-24', 'fix', 'closed', 'A miner holding unsellable ore sits forever and never mines again: Holdings.cs ~1012-1013 returns ''stay here'' when no market is found, with no fallback; dump the ore or fall back to the fuel-port/other-port path (found by bughunt)', '77fcf0282b9aa2a9ca393b9aef7c8ab00db8df86', 547, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T549', 'Unity.SpaceGod', 549, '2026-10-24', 'fix', 'closed', 'Yard repairs crawl because they are paced by the wrong damage figure: Holdings.RepairInPort (~828-832) sizes the daily repair by the diluted Combat.Damage while the ship stays until hull damage is at or below 25%, so yard stops drag on and are under-billed; size the daily share by hull damage (found by bughunt)', '33025860746cb16dac713684d8108c5c507b56a7', 548, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T550', 'Unity.SpaceGod', 550, '2026-10-24', 'fix', 'closed', 'A route with a repeated stop loses its place: Holdings.cs ~960 re-finds the current stop with Array.IndexOf (first occurrence) on every re-plan, so a route [A,B,A,C] jumps back to B while carrying cargo bought for C; keep the stop index it was bound for (found by bughunt)', '3f702309657b8d03ed5cce53de3b3d82ee7be12e', 549, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T551', 'Unity.SpaceGod', 551, '2026-10-24', 'fix', 'closed', 'Switching a loaded trader to Patrol or Escort strands its cargo: Holdings.SetOrders (~470-479) leaves the hold and the destination market''s booked inbound tonnage in place, and non-trader roles never sell on arrival; release the booking and sell or clear the cargo when the role changes (found by bughunt)', '006f0b8', 550, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T552', 'Unity.SpaceGod', 552, '2026-10-24', 'fix', 'closed', 'An owned ship escorting the ship the player is flying follows a frozen position: Holdings.cs ~1046-1057 reads the piloted ship''s simulated orbit, which is not updated until the helm is released (UnitySpaceApp.cs PinWherePiloted ~973), so the escort sits still showing ''Escorting X''; track the piloted ship''s current frame body (found by bughunt)', '87e6ecc', 551, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T553', 'Unity.SpaceGod', 553, '2026-10-24', 'fix', 'closed', 'An owned house ship can be sent out of the system by accident and written off: following it and clicking another system on the galaxy map sends it through the gates (UnitySpaceApp.Course.cs TrySendFollowedShip ~86, InterstellarTraffic.cs SendPlotted ~1290, no ownership check), and Holdings books it lost; refuse or confirm first for house ships (found by bughunt)', 'dfd15eb', 552, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T554', 'Unity.SpaceGod', 554, '2026-10-24', 'fix', 'closed', 'Collision avoidance bogs the frame down at high time warp: Fleet.StepAvoidance (Fleet.cs ~269-287) sub-steps at most 0.002 days, so its ''long frame: settle part way'' branch (omega*d > 1) can never fire and each manoeuvrable ship runs dt/0.002 integration steps per frame (about 3,000 per ship per frame at 1 year/s); take the shortcut (or a fixed sub-step cap) when the frame is long (found by bughunt)', 'a9b2c6e', 553, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T555', 'Unity.SpaceGod', 555, '2026-10-24', 'fix', 'closed', 'At time warp the piloted hull still flies in real seconds while everything else runs warped: UnitySpaceApp.Update passes unscaled dt to UpdatePiloting (~651, model.Step ~1381) but War.Update advances the player''s own battle by warped sim seconds, so after ''.'' at the helm AI units move warp-times faster than the player''s hull, and the swept collision test (UnitySpaceApp.Collisions.cs Collide ~168) assumes others moved other.Vel * real dt so hulls tunnel through them; hold real time while piloting in a battle (or step the pilot in sim time with sub-steps) and sweep with the sim interval (found by bughunt)', '1702dd0', 554, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T556', 'Unity.SpaceGod', 556, '2026-10-24', 'fix', 'closed', 'The Explorer is flown with a capital ship''s helm keys: PilotTuning.ControlOf (PilotTuning.cs ~110) leaves ShipClass.Explorer on the default PilotControl.Helm (A/D yaw, strafe zeroed, mouse only looks) although FlightModels puts it in the Hauler family on the Newtonian model; give it PilotControl.Hauler like the other haulers (found by bughunt)', '9b3e1c5', 555, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T557', 'Unity.SpaceGod', 557, '2026-10-24', 'fix', 'closed', 'AI hulls turn with no angular inertia, so their noses snap on, off and into reversals: Battle.TurnToward (Battle.cs ~1406) and Fighters.Steer (~789-804) rotate at a fixed deg/s with no spin-up or brake, unlike the piloted hull (PilotFlight.Rotate), so an AI capital whose wanted facing flips between broadsides reverses its swing instantly; give AI turns the same angular-acceleration-limited swing as the helm (found by bughunt)', 'c1fd36e', 556, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T558', 'Unity.SpaceGod', 558, '2026-10-24', 'fix', 'closed', 'Fighter attack runs abort after a single step, so squadrons never press home: Fighters.cs ~297-298 counts a lead as ''past the target'' when its velocity points away and it is beyond R+0.8 km, which is true the moment it reaches its run entry 5-7 km out while still flying outward, so it goes straight to BreakOff (probe: all runs ended after 0.03 s, closest approach 4-5 km instead of 0.35 km, squadrons cycle Approach/BreakOff); only allow ''past'' once the run has actually closed (track the minimum distance reached) (found by bughunt)', 'AttackRunsPressHomeBeforeBreakingOff', 557, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T559', 'Unity.SpaceGod', 559, '2026-10-24', 'fix', 'closed', 'Wingmen hold station level with or ahead of their lead, not behind it in the vee, and their noses jitter: Fighters.cs ~781-782 aims at station + lead.Vel*0.6 and Steer (~808) closes that gap to zero, so the wingman sits 0.6 s of the lead''s speed ahead of its slot and then points its nose at a near-zero vector (probe: slots meant 0.1-0.16 km behind sat at -0.01..+0.12 km, nose-to-lead angle jumping 1-131 deg between samples); close on the station itself with lead.Vel as feed-forward and hold the lead''s heading inside a dead-band (found by bughunt)', 'WingmenSitBehindTheirLeadWithTheirNosesSteady', 558, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T560', 'Unity.SpaceGod', 560, '2026-10-24', 'fix', 'closed', 'AI hulls flip-flop between targets every few seconds so their heading never settles: Battle.cs ~929-933 re-picks a target every 3-10 s through PickTarget (~986) with a random +/-15% score jitter and no preference for the current one (probe: a cruiser between two equidistant enemies switched 10 times in 120 s, heading swinging -60..+6 deg); give the current target a stickiness bonus or switch only when clearly better (found by bughunt)', 'TargetStickinessTests (dae1a57)', 559, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T561', 'Unity.SpaceGod', 561, '2026-10-24', 'fix', 'closed', 'Weak-patch captains turn their holed side to the enemy: since U.SPC-T535, WeakPatches.Choose (WeakPatches.cs ~442, Transport) moves every candidate heading onto the hull''s current heading before scoring, so shield exposure and armour slant are never judged at the heading considered (probe: a cruiser with starboard emitters destroyed chose bearing 90, holed side to the enemy; without the transport it chose 270), which also leaves U.SPC-T534''s AI armour angling effectively off for hulls with two or more emitters; score each heading in its own frame and carry over only the roll finally ordered (found by bughunt)', '59488ae', 560, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T562', 'Unity.SpaceGod', 562, '2026-10-24', 'fix', 'closed', 'Hulls snap 180 deg in roll when pitching past about 78.5 deg: BattleUnit.Basis (Battle.cs ~240) and WeakPatches.LevelRoof (~329) switch their reference axis from Z to X when |Forward.Z| > 0.98 (probe: right and up vectors flip sign between sin(elevation) 0.979 and 0.981), hitting every unit without a roof (dogfighters, small hulls), RollToward-to-level and the drawn rotation (UnitySpaceApp.cs ~2399); carry the previous roof forward instead of switching at a threshold (found by bughunt)', 'PitchRollContinuityTests', 561, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T563', 'Unity.SpaceGod', 563, '2026-10-24', 'fix', 'closed', 'Drawn fighters never roll, and the player''s own fighter visibly counter-rolls in the chase view: FighterViews.cs ~78 always draws with world up (and its own 0.98 snap), and FighterAI.FlyManned (Fighters.cs ~553) keeps the roll only in stick.Up, never setting u.Up, while the seat camera (UnitySpaceApp.Embodiment.cs ~275-277) rolls with stick.Up; set u.Up = state.Up in FlyManned and draw fighters with the unit''s basis up (found by bughunt)', '1088596', 562, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T564', 'Unity.SpaceGod', 564, '2026-10-24', 'fix', 'closed', 'Taking or handing back the helm in battle snaps the hull''s roll: EnterPiloting -> SeedPilot (UnitySpaceApp.cs ~1107-1113) seeds pilot.Up from the camera''s up, ignoring the unit''s rolled Roof, and ShipHelm.HandBack (ShipHelm.cs ~113-124) leaves Roof at its value from before the player took over, so the drawn hull jumps in roll; seed pilot.Up from the unit''s basis and set unit.Roof = unit.Up on hand-back (found by bughunt)', 'ccc2da4', 563, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T565', 'Unity.SpaceGod', 565, '2026-10-24', 'fix', 'closed', 'Formation stations swing round the flagship whenever it rolls for its weak patches: Battle.StationOf (Battle.cs ~1396-1404) lays slots out in the leader''s rolled frame (l.Basis uses its Roof), so a 90-180 deg weak-patch roll moves line-abreast stations 3-4 km out from beside it to above, below or the far side and escorts charge across through the flagship; build station frames from the leader''s level roof (found by bughunt)', 'b92e02c', 564, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T566', 'Unity.SpaceGod', 566, '2026-10-24', 'fix', 'closed', 'Broadside headings are wrong for targets above or below the hull: Battle.BowFor / RotateYaw (Battle.cs ~1384-1393) rotate the 3D line to the target about world vertical without levelling it, so the bow ends up pitched and the target is not at the asked bearing despite the ''held level'' doc (probe: target 30 deg up, bearing 90 put it 75.5 deg off the bow and bearing 180 put it 120 deg off); rotate about the axis square to the target line in its vertical plane (found by bughunt)', '29fc5d6', 565, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T567', 'Unity.SpaceGod', 567, '2026-10-24', 'fix', 'closed', 'Boarding ships and shuttles always dock on the prize''s starboard side and fly straight through its hull when coming from port: Battle.Approach (Battle.cs ~3000-3001) and Fighters Dock (~697-698) place the dock point at t.Pos + right*... and fly a straight line to it, and AI-to-AI hulls never collide, so they pass visibly through; pick the side facing the boarder when the approach starts and keep it (found by bughunt)', '3b310c5', 566, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T568', 'Unity.SpaceGod', 568, '2026-10-24', 'fix', 'closed', 'A ship whose battle blend is interrupted snaps position: UnitySpaceApp.PlaceInBattles (~2381) blends from DrawnScene, which returns the raw schedule position when a ship leaves one fight and joins another within the 2 s blend, and lastBattleScene holds the unblended battle position when it leaves mid-blend-in, so it jumps; keep each ship''s last drawn (post-blend) scene position and always blend from that (found by bughunt)', '235b2bf', 567, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T569', 'Unity.SpaceGod', 569, '2026-10-24', 'fix', 'closed', 'The trade desk sizes runs for the bulk AI hold, not the hold the player actually flies: Hud.Trade.cs ~105 uses flown.CapacityTonnes (20,000 t on a freighter, and a freighter''s 20,000 t fallback on a fighter) while the player trades only through the 6x8 crate hold (~240 t of food), so suggested tonnes and profit are tens of times too high; size runs from the free PersonalHold cells when piloting (found by bughunt)', '31fe8c8', 568, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T570', 'Unity.SpaceGod', 570, '2026-10-24', 'fix', 'closed', 'ScheduleNext on a ship already in flight cuts its transit short and teleports it: the GateKm branch of Fleet.ScheduleNext (Fleet.cs ~1565) sets PhaseEndJd = now + 0.05..0.2 on a Transit or Lane ship with no phase guard, reached from Redirect (InterstellarTraffic.cs ~1364/1389), Recall (InterstellarWars.cs ~1174) and CancelVoyage (probe: a ship 2.5 days out jumped about 69.6 million km in one call); on ships under way only retarget and leave PhaseEndJd alone (found by bughunt)', '0f3484a', 569, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T571', 'Unity.SpaceGod', 571, '2026-10-24', 'fix', 'closed', 'The FTL autopilot never waits for the drive to cool though the plotted course counts the wait: FtlNavigation.cs ~179, ~236-248 and UnitySpaceApp.Ftl.cs ~565-576 spool as soon as the hull is aligned, HelmFtl.DriveRefusal refuses, and the autopilot lets go of the helm, while the plot shows ''The drive cools first'' in its ETA; add a cooling stage that holds until FtlRules.CoolUntil (found by bughunt)', 'fe3b03e', 570, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T572', 'Unity.SpaceGod', 572, '2026-10-24', 'fix', 'closed', 'A stalled lane ride is shown and treated as a lurking raider: StallRide shortens LaneEndProgress and EndLane then sets Phase = Lurk (Fleet.cs ~846-854, ~922-931), so a stalled freighter reads ''lane picket''/''Lying in wait'' (Hud.cs ~1916, ~2010-2014), a stalled armed group with a field projector pulses traffic (War.cs ~352) and a stalled pirate spawns an ambush opportunity (EventDirector.cs ~134); give a stall its own phase or flag and exclude it there (found by bughunt)', 'ARideOfAWornLaneCanStallPartWayAndPickUpAgain', 571, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T573', 'Unity.SpaceGod', 573, '2026-10-24', 'fix', 'closed', 'Warehouse store and sell ignore blockades, embargoes and war: Holdings.StoreFromMarket (~649) and SellFromStore (~674) skip the Diplomacy.CanDockAt check that BuyWarehouse makes, so the desk''s Store/Sell buttons trade at open prices with no customs risk at a port the desk calls closed; require CanDockAt and a port that has not fallen in both (found by bughunt)', 'HoldingsTests.AWarehouseCannotStoreOrSellAtAPortClosedToTheHouse (83a0946)', 572, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T574', 'Unity.SpaceGod', 574, '2026-10-24', 'fix', 'closed', 'Sol''s material depot fills with water no build uses, stalling the belt pipeline and the megastructures: Ceres'' ice depot is the same Valhalla Depot its convoys feed (World.Mining.cs ~102-106) and melted ice is never drawn down (BeltMining.cs ~958, ~795-799) (probe: depot at 50 of 50 Mt, 45 Mt water, ore convoys and ice hauls stop, Helios Swarm stuck near 22%); give the ice its own depot or count only goods some project needs against capacity (found by bughunt)', 'OreTugTests.AFullIceDepotSendsTheTugForOreInsteadOfIdlingIt', 573, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T575', 'Unity.SpaceGod', 575, '2026-10-24', 'fix', 'closed', 'Law and trade-desk notices overwrite each other in the single toast slot: UnitySpaceApp.ShowLawNotices (~1202-1208) calls ShowToast twice and ShowToast replaces Toast, so a back-door sale customs catches shows only ''Customs at X seize...'' and never the ''CRIME: smuggling'' line, and a button''s own toast is wiped at once; join both lists into one toast or queue toasts (found by bughunt)', '80d5db6', 574, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T576', 'Unity.SpaceGod', 576, '2026-10-24', 'fix', 'closed', 'Ships running out to engage their cruise drive are labelled as bound for ''a jump gate'': a cruise voyage''s GateKm is the edge of the well (InterstellarTraffic.cs ~678), not a gate, yet the ship card (Hud.cs ~1918-1926, ~2047-2049) reads ''Burning toward a jump gate''s approach'' for the whole run out (about a week for a carrier); check Voyage.ByCruise and label it the run to the edge of the well (found by bughunt)', '9df5f36', 575, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T577', 'Unity.SpaceGod', 577, '2026-10-24', 'fix', 'closed', 'The player''s own sightings give away hidden havens: Outlaws.cs ~419 records the wanted player''s sighting with (pilotBody, ''near '' + BodyName) without Hide(), so with an undiscovered haven nearby every board prints its rock and hunters fly straight to it, contrary to the doc (''the sighting names no rock''); wrap the location in Hide(...) (found by bughunt)', '9653f72', 576, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T578', 'Unity.SpaceGod', 578, '2026-10-24', 'fix', 'closed', 'A raider captain whose flagship comes home from abroad stays ''ashore'' for good: Outlaws.SettleFates (~347) sets Ashore when the hull leaves and Sync (~377) skips the returning hull because it is already in byShip, so nothing clears the flag, the captain is never sighted again, hunters drop the contract and a later Rebind strips the real flagship''s record; clear Ashore in SettleFates when the ship is present, alive and still pirate (found by bughunt)', '53c2cdb', 577, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T579', 'Unity.SpaceGod', 579, '2026-10-24', 'fix', 'closed', 'A freed captain is declared dead, bounty paid or lapsed, when the prize hull they used to command is destroyed: when a flagship is taken its byShip and Law.Captains entries are never removed (Outlaws.cs ~576-583, Hold ~725, Free ~760), so after the captain is ransomed or breaks out and the prize dies under its captor''s colours the outlaw is ''Killed''; drop those entries on capture or require the captain aboard there and in ClaimInBattle (found by bughunt)', 'df4fa6f', 578, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T580', 'Unity.SpaceGod', 580, '2026-10-24', 'fix', 'closed', 'The FTL autopilot''s out-run propellant is charged up front and never refunded: FtlAutopilot.Engage (FtlNavigation.cs ~316) deducts OutRunFuelTonnes and Disengage (~414-428) refunds nothing, so a run broken a second in by a fight or hunters loses it all and re-engaging charges it again; refund the unflown share on disengage as Fleet.RefundUnflown does for AI ships (found by bughunt)', 'a65aa4a', 579, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T581', 'Unity.SpaceGod', 581, '2026-10-24', 'fix', 'closed', 'Selling stolen goods on a lawless station''s black market creates money and earns the station a port tax: Economy.cs ~1116-1125 pays the player BlackMarket.SaleValue and credits the owner a 4% tax while debiting nothing, whereas the clans'' BlackMarket.Sell debits the owner''s treasury as the class doc says; debit the owner by the value and charge no port tax on black sales (found by bughunt)', 'a2da8e2', 580, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T582', 'Unity.SpaceGod', 582, '2026-10-24', 'fix', 'closed', 'The Buy toast says ''cargo hold is full'' for any partial purchase: Hud.cs ~2812 reports a full hold whenever fewer crates were bought than asked, even when credits or the port''s stock ran out after 4 of 10; have BuyIntoHold return why it stopped and report that (found by bughunt)', '4613c8f', 581, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T583', 'Unity.SpaceGod', 583, '2026-10-24', 'fix', 'closed', 'A warehouse can be bought at a ruin and the house loses the price the next day: Holdings.BuyWarehouse (~551) has no Fallen check, so at an abandoned colony whose owner is still lawful the price goes to that owner and the next daily round writes the warehouse off as ''lost with the abandoned ...''; refuse fallen ports there and in BuyShare (found by bughunt)', '19b626c', 582, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T584', 'Unity.SpaceGod', 584, '2026-10-24', 'fix', 'closed', 'A charter pays one more day of hire than its term: Charters.cs ~263 pays hire on every daily tick and ends on the first tick at or after EndJd, so a hull taken out between ticks (the normal case) pays 31 days on a 30-day charter (the test only covers a take exactly on a tick); end before paying once jd >= EndJd or pro-rate the first and last days (found by bughunt)', '0acc1b1', 583, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T585', 'Unity.SpaceGod', 585, '2026-10-24', 'fix', 'closed', 'A hunter whose flagship dies abroad is dropped before its heir gets home: Outlaws.PruneHunters (~1219) removes rows for hulls that are Destroyed but not GateDeparted, so OnSuccession finds nothing and the heir stops hunting, contrary to the doc (''A hunter gone through a gate keeps its row''); keep rows for hunters away on a Hunt voyage until Home resolves the succession (found by bughunt)', 'c721f0a', 584, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T586', 'Unity.SpaceGod', 586, '2026-10-24', 'fix', 'closed', 'Hunters away on a hunt do not count toward HunterCap: Outlaws.cs ~1139-1140 counts only hunters whose hull is in this system''s fleet, so in Alpha Centauri (cap 1) sending the one hunter abroad lets the guild buy a second group and there are two when it returns; count every non-retired, undestroyed hunter still under its faction wherever it is (found by bughunt)', '33bf60a', 585, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T587', 'Unity.SpaceGod', 587, '2026-10-25', 'fix', 'closed', 'CombatTests.ABattleshipWithItsForwardBatteryKnockedOutTurnsBroadsideInstead is flaky: it failed in two combined filter runs (Broadside+Combat+WeakPatch+FireCone/Fighter) after U.SPC-T557''s turn-inertia change, the battleship still bow-on (0.2 deg) when a broadside was expected, yet it passes alone and with its own class; find the shared state or ordering/seed dependency between fixtures (or a turn that now needs longer to come round) and make the test deterministic (found by bughunt follow-up)', 'b4ba0cf', 586, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.SPC-T588', 'Unity.SpaceGod', 588, '2026-10-25', 'fix', 'closed', 'A bounty hunter group wiped out abroad leaves its row Away forever: U.SPC-T585 made Outlaws.PruneHunters skip rows with BountyHunter.Away so an heir can come home and inherit, but when the whole hunt group dies abroad nobody comes home and the row is never pruned, so Outlaws.Hunters grows; clear Away wherever a Hunt voyage ends with no survivor (found by U.SPC-T585 review)', 'ABountyHunterGroupWipedOutAbroadHasItsRowPruned', 587, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.RON-T1', 'UnityRonin', 1, '2026-10-12', 'docs', 'closed', 'Start the permanent ticket log in USER_STORIES.md', '—', 0, '| U.RON-T1 | 2026-10-12 | docs | closed | Start the permanent ticket log in USER_STORIES.md | — |');
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.RON-T2', 'UnityRonin', 2, '2026-10-14', 'chore', 'closed', 'NUnit tests for DuelDirector guard rails and riposte edge cases (add to the existing xUnit Tests/Core.Tests/DuelDirectorTests.cs, Assets/UnityRonin/Core/Combat/DuelDirector.cs): Resolve throws InvalidOperationException while Phase is PlayerRiposte, ResolveRiposte throws while Phase is EnemyBeat, both throw once IsOver, constructor throws ArgumentNullException for a null Rng, PlayerWon is false when the player reaches zero health, a landed riposte with chained alternating strokes deals 1 plus bonus hits and a repeated shape breaks it, a countered riposte on the player''s last health ends the duel, and after a riposte timeout, retreat or counter Phase returns to EnemyBeat with a fresh CurrentBeat; these are the state-machine invariants RoninGameController and DuelPresenter rely on and none are asserted today', 'Tests/Core.Tests/DuelDirectorTests.cs', 1, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.RON-T3', 'UnityRonin', 3, '2026-10-14', 'chore', 'open', 'NUnit tests for GestureClassifier edge cases (add to the existing xUnit Tests/Core.Tests/GestureClassifierTests.cs, Assets/UnityRonin/Core/Combat/GestureClassifier.cs): an empty or single-point path returns no strokes (SwipeInputReader then drops the gesture silently), the angle-bucket boundaries at 22.5, 67.5, 112.5 and 157.5 degrees land in the documented shape, a three-segment zigzag yields three alternating strokes with shared corner points, a short tail under 24px after a real corner is dropped rather than turned into a Thrust, a sharp turn before 24px of travel is treated as jitter and does not split, and downward or leftward drags fold to the same shape; misclassification here silently decides parries and combo bonus hits', '—', 2, '| U.RON-T3 | 2026-10-14 | chore | open | NUnit tests for GestureClassifier edge cases (add to the existing xUnit Tests/Core.Tests/GestureClassifierTests.cs, Assets/UnityRonin/Core/Combat/GestureClassifier.cs): an empty or single-point path returns no strokes (SwipeInputReader then drops the gesture silently), the angle-bucket boundaries at 22.5, 67.5, 112.5 and 157.5 degrees land in the documented shape, a three-segment zigzag yields three alternating strokes with shared corner points, a short tail under 24px after a real corner is dropped rather than turned into a Thrust, a sharp turn before 24px of travel is treated as jitter and does not split, and downward or leftward drags fold to the same shape; misclassification here silently decides parries and combo bonus hits | — |');
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.RON-T4', 'UnityRonin', 4, '2026-10-14', 'chore', 'open', 'NUnit tests for EngageGate and StickVector boundary behavior (add to the existing xUnit Tests/Core.Tests/EngageGateTests.cs, Assets/UnityRonin/Core/Movement/EngageGate.cs and StickVector.cs): a zero or negative enterRadius throws ArgumentOutOfRangeException, a distance exactly equal to EnterRadius engages and exactly equal to ExitRadius releases, the gate can re-engage after releasing, Update returns the same value as State, and StickVector.Magnitude and StickVector.Zero behave as documented; the equality boundaries decide whether a duel triggers or releases at the edge of the enemy zone', '—', 3, '| U.RON-T4 | 2026-10-14 | chore | open | NUnit tests for EngageGate and StickVector boundary behavior (add to the existing xUnit Tests/Core.Tests/EngageGateTests.cs, Assets/UnityRonin/Core/Movement/EngageGate.cs and StickVector.cs): a zero or negative enterRadius throws ArgumentOutOfRangeException, a distance exactly equal to EnterRadius engages and exactly equal to ExitRadius releases, the gate can re-engage after releasing, Update returns the same value as State, and StickVector.Magnitude and StickVector.Zero behave as documented; the equality boundaries decide whether a duel triggers or releases at the edge of the enemy zone | — |');
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.RON-T5', 'UnityRonin', 5, '2026-10-14', 'chore', 'open', 'NUnit tests for SelfPlayInput''s scripted duel answers staying in sync with DuelDirector (Assets/UnityRonin/Runtime/Game/SelfPlayInput.cs CorrectResponse and Perpendicular, currently private in the Unity-only Runtime assembly, so either move that pure mapping into Core or cover it with a Unity EditMode test): for every DuelAction x GestureSymbol beat, the correct response really parries or strikes when fed to DuelDirector and the alwaysLose response never does; the -autoplay/-demo PASS depends on this hand-copied mirror of the scoring rules and it will silently drift if the rules change', '—', 4, '| U.RON-T5 | 2026-10-14 | chore | open | NUnit tests for SelfPlayInput''s scripted duel answers staying in sync with DuelDirector (Assets/UnityRonin/Runtime/Game/SelfPlayInput.cs CorrectResponse and Perpendicular, currently private in the Unity-only Runtime assembly, so either move that pure mapping into Core or cover it with a Unity EditMode test): for every DuelAction x GestureSymbol beat, the correct response really parries or strikes when fed to DuelDirector and the alwaysLose response never does; the -autoplay/-demo PASS depends on this hand-copied mirror of the scoring rules and it will silently drift if the rules change | — |');
