INSERT INTO ticket_events (seq, ticket_id, at, field, old, new) VALUES (11600, 'AUT-T23', '2026-10-24T06:53:59Z', 'summary', 'Publish Automata docs to GitHub Pages via the shared Toolkit DocFX pipeline: run adopt-docs-site.ps1 (README.md as home page, docs/*.md as articles, API reference only where the code builds in CI), enable Pages with build_type=workflow, set the repo homepage URL, retire tools/build-readme.ps1 and README.htm, confirm the docs Actions run is green and https://mindattic.github.io/Automata/ returns 200. Depends on MAT-T8.', 'Publish Automata docs to GitHub Pages via the shared Agency DocFX pipeline: run adopt-docs-site.ps1 (README.md as home page, docs/*.md as articles, API reference only where the code builds in CI), enable Pages with build_type=workflow, set the repo homepage URL, retire tools/build-readme.ps1 and README.htm, confirm the docs Actions run is green and https://mindattic.github.io/Automata/ returns 200. Depends on MAT-T8. (MAT-T51 -- reworded to use current project/CLI names)');
