INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('MindAttic.Capture', 0, 'raw', NULL, '---
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('MindAttic.Capture', 1, 'raw', NULL, '');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('MindAttic.Capture', 2, 'epic', 'T', '## Epic T — Tray recorder: screen, app and area capture from the system tray');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('MindAttic.Capture', 3, 'story', '1097', '- **M.CAPT-US-T1 🟡** As a user, I have a Capture icon in the system tray whose menu offers Record Screen, Record App, Record Area, Screenshot (screen / app / area), my saved regions, Stop and Settings, so I can capture without a terminal.');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('MindAttic.Capture', 4, 'story', '1098', '- **M.CAPT-US-T2 🟡** As a user, I can choose Record App and pick a running app''s window from a list, so only that window is recorded (lossless, at its native resolution).');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('MindAttic.Capture', 5, 'story', '1099', '- **M.CAPT-US-T3 🟡** As a user, when I choose Record Area the whole screen (every monitor) dims under a gray semi-transparent overlay and I drag out a rectangle that shows as a light-blue outlined, fully clear cut-out, so I can see exactly what will be recorded.');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('MindAttic.Capture', 6, 'story', '1100', '- **M.CAPT-US-T4 🟡** As a user, after drawing the area I can move it by dragging its upper-left grab handle and resize it from its edges and corners, so I can fine-tune the region before recording.');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('MindAttic.Capture', 7, 'story', '1101', '- **M.CAPT-US-T5 🟡** As a user, buttons beside the selection let me snap it to an aspect ratio (Free, 16:9, 9:16, 1:1, 4:3, 4:5, 21:9, ...), resizing to the rectangle of that ratio closest in size to my current cut-out, so a 1:1 is a square and a 9:16 is a tall vertical frame.');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('MindAttic.Capture', 8, 'story', '1102', '- **M.CAPT-US-T6 🟡** As a user, the area toolbar also lets me pick the output format (video: MP4 H.264 / lossless MKV / GIF, screenshot: PNG / JPG) and start Record or take a Screenshot, so I decide what is produced before capturing.');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('MindAttic.Capture', 9, 'story', '1103', '- **M.CAPT-US-T7 🟡** As a user, I can save the current region''s size and position under a name like ''YouTube Short'', and later pick it from the tray or the overlay, so I can record the same frame again without redrawing it.');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('MindAttic.Capture', 10, 'story', '1104', '- **M.CAPT-US-T8 🟡** As a user, once a region is armed, a global hotkey starts recording it and pressing it again stops, and a separate hotkey takes a screenshot of it; a thin border marks the region while it records and is never in the recording, so I can capture hands-free.');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('MindAttic.Capture', 11, 'story', '1105', '- **M.CAPT-US-T9 🟡** As a user, when a recording stops the lossless master is written and a lossy copy is written next to it, so I have both an editing master and a small file ready to upload.');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('MindAttic.Capture', 12, 'story', '1106', '- **M.CAPT-US-T10 🟡** As a user, I can open Settings from the tray to assign the record and screenshot hotkeys, choose the output folder and default format, and set Capture to start with Windows, so the tray app fits my setup.');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('MindAttic.Capture', 13, 'raw', NULL, '');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('MindAttic.Capture', 14, 'tickets', NULL, '## Tickets
