INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Chain', 0, 'raw', NULL, '---
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Chain', 1, 'raw', NULL, '');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Chain', 2, 'epic', 'A', '## Epic A — Art, audio and look');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Chain', 3, 'story', '1236', '- **U.CHN-US-A1 ✅** As a player, I see the original''s art (angel with 4 flap frames per facing, chain link, mace and grappling mace, the seven Shadow enemy frames, the heart), so that the game looks like the original');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Chain', 4, 'story', '1238', '- **U.CHN-US-A2 ✅** As a player, I hear the original''s sound effects and music, so that the game sounds like the original');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Chain', 5, 'story', '1241', '- **U.CHN-US-A3 ✅** As a player, the arena has the original''s background and I can switch between the beach and the utopia areas, so that the scenery matches');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Chain', 6, 'story', '1246', '- **U.CHN-US-A4 ✅** As a player, I can change the chain''s links to coloured gems, so that I can dress the chain as the original allowed');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Chain', 7, 'story', '1249', '- **U.CHN-US-A5 ✅** As a player, the mace can be dressed as a magnet, so that the README''s promised magnet mace exists');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Chain', 8, 'raw', NULL, '');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Chain', 9, 'raw', NULL, '');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Chain', 10, 'epic', 'G', '## Epic G — Gameplay parity');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Chain', 11, 'story', '1253', '- **U.CHN-US-G1 ✅** As a player, the chain and combat feel the same as the original, with each deliberate deviation recorded and chosen on purpose, so that gameplay is kept exactly');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Chain', 12, 'story', '1256', '- **U.CHN-US-G2 ✅** As a player, 14 enemies come at me from the corners of the arena and return on restart, so that the fight matches the original');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Chain', 13, 'story', '1264', '- **U.CHN-US-G3 ✅** As a player, enemies that overlap push each other apart instead of stacking into one blob, so that a crowd spreads out as in the original');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Chain', 14, 'story', '1271', '- **U.CHN-US-G4 ✅** As a player, a heart floats down the screen and heals me when I touch it, so that I can recover as in the original');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Chain', 15, 'story', '1278', '- **U.CHN-US-G5 ✅** As a player, when I die the light fades and the game restarts by itself, so that game over matches the original');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Chain', 16, 'story', '1286', '- **U.CHN-US-G6 ✅** As a player, the arena light fades and the day cycle tints the scene, so that the lighting matches the original');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Chain', 17, 'story', '1295', '- **U.CHN-US-G7 ✅** As a player, I can toggle the chain''s follow-the-mouse force, so that I can watch it fall free as the original allowed');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Chain', 18, 'story', '1303', '- **U.CHN-US-G8 ✅** As a player, I can reset the game with a key and the music restarts at a random point, so that a new round starts as in the original');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Chain', 19, 'story', '1312', '- **U.CHN-US-G9 ✅** As a player, I can shake the screen, so that the original''s shake key works');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Chain', 20, 'raw', NULL, '');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Chain', 21, 'raw', NULL, '');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Chain', 22, 'epic', 'D', '## Epic D — Display, controls and debug tools');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Chain', 23, 'story', '1316', '- **U.CHN-US-D1 ✅** As a player, the HUD shows what the original showed in the same places, so that the screen reads the same');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Chain', 24, 'story', '1318', '- **U.CHN-US-D2 ✅** As a player, I can tune resistance, gravity and spring live and see them, so that the chain''s feel can be changed as the original allowed');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Chain', 25, 'story', '1319', '- **U.CHN-US-D3 ✅** As a player, I can speed up and slow down the game, so that the original''s speed keys work');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Chain', 26, 'story', '1320', '- **U.CHN-US-D4 ✅** As a player, the screen shows how long this round has lasted, so that the original''s clock is there');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Chain', 27, 'story', '1321', '- **U.CHN-US-D5 ✅** As a player, pause and quit work as in the original');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Chain', 28, 'story', '1322', '- **U.CHN-US-D6 ✅** As a player, Tab opens the in-game menu panel, so that the original''s menu is there');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Chain', 29, 'story', '1323', '- **U.CHN-US-D7 ✅** As a developer, I can show the hit boxes and the render debug toggles, so that the original''s debug views exist');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Chain', 30, 'story', '1324', '- **U.CHN-US-D8 ✅** As a developer, I can move the camera with the numpad, so that the original''s debug camera works');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Chain', 31, 'story', '1325', '- **U.CHN-US-D9 ✅** As a player, a random loading picture shows while the game starts, so that start-up matches the original');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Chain', 32, 'story', '1326', '- **U.CHN-US-D10 ✅** As a player, I can change resolution, window mode and the volumes in a settings screen, so that the original''s configuration window exists');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Chain', 33, 'raw', NULL, '');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Chain', 34, 'raw', NULL, '');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Chain', 35, 'epic', 'C', '## Epic C — Scripter console');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Chain', 36, 'story', '1327', '- **U.CHN-US-C1 ✅** As a player, I can type scripts that change the game, so that the original''s scripting language exists');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Chain', 37, 'story', '1328', '- **U.CHN-US-C2 ✅** As a player, I can open the scripter console and type commands into it, so that scripts can be entered as in the original');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Chain', 38, 'raw', NULL, '');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Chain', 39, 'raw', NULL, '');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Chain', 40, 'epic', 'V', '## Epic V — Verify and finish');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Chain', 41, 'story', '1329', '- **U.CHN-US-V1 ✅** As a player, I can host or join an online game on the shared Unity.Multiplayer kit, so that the game can be played online while local play is unchanged');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Chain', 42, 'story', '1330', '- **U.CHN-US-V2 ✅** As the owner, I can see the finished game working end to end, so that done is verified by play');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Chain', 43, 'story', '1331', '- **U.CHN-US-V3 ✅** As the owner, I can trust that nothing from the original is missing, so that the repo is a finished proof of concept');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Chain', 44, 'raw', NULL, '');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Chain', 45, 'raw', NULL, '');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Chain', 46, 'epic', 'F', '## Epic F — Foundations and standards');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Chain', 47, 'story', '1171', '- **U.CHN-US-F1 ✅** As a maintainer, I can read docs/BIBLE.md and the README to learn the game''s rules, the architecture and every deliberate deviation from the original, so that the repo matches the shared standard');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Chain', 48, 'story', '1172', '- **U.CHN-US-F2 ✅** As a maintainer, the game rules live in an engine-free Core assembly apart from the MonoBehaviour layer, so that they can be tested without Unity');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Chain', 49, 'story', '1173', '- **U.CHN-US-F3 ✅** As a maintainer, I can run the Core tests with dotnet test outside Unity, so that rules are checked in seconds without opening the editor');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Chain', 50, 'story', '1174', '- **U.CHN-US-F4 ✅** As a maintainer, game state changes only through commands that produce events, so that presentation only reads state and plays events and local play is the same path an online game will use');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Chain', 51, 'story', '1175', '- **U.CHN-US-F5 ✅** As a designer, every tuning number and the level content come from data files validated on load, so that nothing is hard-coded in behaviour');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Chain', 52, 'story', '1177', '- **U.CHN-US-F6 ✅** As a player, I steer and act through the Input System with rebindable actions and gamepad support, so that input is not hard-coded to device polling');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Chain', 53, 'story', '1222', '- **U.CHN-US-F7 ✅** As a player, the game renders through URP 2D with committed pipeline settings, so that a fresh checkout looks the same and Unity does not rewrite the graphics settings on every import');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Chain', 54, 'story', '1226', '- **U.CHN-US-F8 ✅** As a player, my volumes, mutes and display name persist in my profile, so that settings follow the shared MindAttic profile model');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Chain', 55, 'story', '1232', '- **U.CHN-US-F9 ✅** As a player, the HUD and menus are built with UI Toolkit (or the shared MindAttic components) instead of IMGUI, so that the UI follows the modern Unity standard');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Chain', 56, 'story', '1234', '- **U.CHN-US-F10 ✅** As a player, the game opens like the original: titled window, icon, 4:3 default size, hidden cursor, project metadata');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Chain', 57, 'story', '1235', '- **U.CHN-US-F11 ✅** As a maintainer, I can build, test and deploy with one command each, so that done means verified from a script');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Chain', 58, 'raw', NULL, '');
