INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Hare', 44, 'raw', NULL, '');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Hare', 45, 'epic', 'H', '## Epic H — Pickups, Economy & Upgrades');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Hare', 46, 'story', '1133', '- **U.HARE-US-H1 ⬜** As a player, I collect carrots, coins, chips and cartridges dropped by enemies/rocks (random_pickup, spawn_chips, obj_drop*) as the game''s currency/ammo pickups');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Hare', 47, 'story', '1134', '- **U.HARE-US-H2 ⬜** As a player, I spend currency in the upgrade/garage screen (room_upgrade, obj_upgrade, obj_upgrade_vulcan1, obj_upgrade_shotgun1, obj_upgrade_missle1, obj_rabbit_schematic, obj_booster_schematic, obj_brake_schematic) to improve my ship');
