INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Hare', 51, 'story', '1135', '- **U.HARE-US-I1 ⬜** As a player, I see a HUD with health bar, energy bar, weapon GUI and speedometer during gameplay (obj_healthbar, obj_energybar, obj_weapon_gui, obj_speedometer)');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Hare', 52, 'story', '1136', '- **U.HARE-US-I2 ⬜** As a player, I navigate title and quit/confirm menus (obj_title, obj_btn_quickstart, obj_btn_campaign, obj_btn_quit, obj_yesno_dialog) with the same flow as the original');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Hare', 53, 'story', '1137', '- **U.HARE-US-I3 ⬜** As a player, I see floating damage/pickup text and tips (obj_float_text, obj_tip, obj_alert) during play');
