INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Hare', 61, 'story', '1139', '- **U.HARE-US-K1 ⬜** As a player, I hear the original''s music tracks with random selection between levels (play_random_music, obj_jukebox)');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Hare', 62, 'story', '1140', '- **U.HARE-US-K2 ⬜** As a player, I hear weapon and UI sound effects ported from the gmlHARE/gmlRabbit sound libraries (102-152 original sound assets)');
