INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Hare', 66, 'story', '1141', '- **U.HARE-US-L1 ⬜** As a player, I see muzzle flashes, explosions (oval_explosion, tinyexplosion, rocket_explosion, grenade_explosion) and trail/swirl effects (rail_swirl) matching each weapon');
